/// Shares the existing range string binding so saved schemes and engine parsing stay unchanged.
private struct ConditionRangePickers: View {
    let title: String
    let fallback: String
    @Binding var text: String
    @State private var isSelectingEndpoint = false
    @State private var selectedEndpoint = 0

    private var endpoints: [Double] {
        let parts = text.replacingOccurrences(of: "–", with: "-")
            .split(separator: "-").compactMap { Double($0.trimmingCharacters(in: .whitespaces)) }
        if parts.count == 2, parts.allSatisfy({ $0.isFinite && $0 >= 0 }) { return parts }
        return fallback.split(separator: "-").compactMap { Double($0) }
    }

    private var options: [Double] {
        let maximum: Int
        let step: Double
        if title == "前5场彩果断点" {
            maximum = 4; step = 1
        } else if title == "六场判定值和值S" {
            maximum = 24; step = 1
        } else if title == "六场判定值R" {
            maximum = 16; step = 1
        } else if title == "六场实际顺序M" {
            maximum = 10; step = 1
        } else if title == "前5场实际顺序M" {
            maximum = 8; step = 1
        } else if title == "平局个数范围" || title == "第三选个数范围" {
            maximum = 6; step = 1
        } else if title == "前5场负个数" || title == "前5场胜个数" {
            maximum = 5; step = 1
        } else if title.contains("综合评分") {
            maximum = 20; step = 0.1
        } else if title.contains("概率") {
            maximum = 100; step = 0.1
        } else if title.contains("乘积") || title.contains("奖金") {
            maximum = 10000; step = 10
        } else if title.contains("断点") {
            maximum = 1500; step = 1
        } else if title.contains("容错") {
            maximum = 3; step = 1
        } else if title.contains("不满足") {
            maximum = 30; step = 1
        } else if title.contains("连续") || title.contains("连胜") || title.contains("连平") || title.contains("连负") || title.contains("第二档三项") || title.contains("场次数") {
            maximum = 7; step = 1
        } else {
            maximum = 100; step = 1
        }
        let values = (0...Int(Double(maximum) / step)).map { Double($0) * step }
        return Array(Set(values + endpoints)).sorted()
    }

    private func label(_ value: Double) -> String {
        value.formatted(.number.grouping(.never).precision(.fractionLength(0...8)).locale(Locale(identifier: "en_US_POSIX")))
    }

    private func endpoint(_ index: Int) -> Binding<Double> {
        Binding(get: { endpoints[index] }, set: { value in
            var updated = endpoints
            updated[index] = value
            if updated[0] > updated[1] { updated[1 - index] = value }
            text = "\(label(updated[0]))-\(label(updated[1]))"
        })
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 6) {
            Text(title).font(.subheadline)
            TextField("输入范围，例如\(fallback)", text: $text)
                .keyboardType(.numbersAndPunctuation)
                .font(.system(.subheadline, design: .monospaced))
            endpointRow("起始", index: 0)
            endpointRow("结束", index: 1)
        }
        .sheet(isPresented: $isSelectingEndpoint) {
            NavigationStack {
                // Only materialize the selected endpoint's choices when opened.
                // List creates visible rows lazily, rather than two eager 1,501-item menus.
                let values = options
                List {
                    ForEach(values, id: \.self) { value in
                        Button {
                            endpoint(selectedEndpoint).wrappedValue = value
                            isSelectingEndpoint = false
                        } label: {
                            HStack {
                                Text(label(value))
                                Spacer()
                                if value == endpoints[selectedEndpoint] {
                                    Image(systemName: "checkmark")
                                }
                            }
                            .contentShape(Rectangle())
                        }
                    }
                }
                .navigationTitle("\(title) · \(selectedEndpoint == 0 ? "起始" : "结束")")
                .navigationBarTitleDisplayMode(.inline)
                .toolbar {
                    ToolbarItem(placement: .confirmationAction) {
                        Button("完成") { isSelectingEndpoint = false }
                    }
                }
            }
        }
    }

    private func endpointRow(_ name: String, index: Int) -> some View {
        Button {
            selectedEndpoint = index
            isSelectingEndpoint = true
        } label: {
            HStack {
                Text(name).foregroundStyle(.primary)
                Spacer()
                Text(label(endpoints[index]))
                Image(systemName: "chevron.up.chevron.down").font(.caption)
            }
            .padding(.vertical, 5)
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .accessibilityLabel("\(title)\(name)，\(label(endpoints[index]))")
    }

}

private struct ExplicitBackButtonContainer<Content: View>: View {
    private let content: Content

    init(@ViewBuilder content: () -> Content) {
        self.content = content()
    }

    var body: some View {
        content
            .navigationBarBackButtonHidden(false)
