private struct BeijingSingleScoreRow: View {
    let match: BeijingSingleMatch
    let oddsRecommendation: OddsConfidenceRecommendation?
    let isCalculatingOddsConfidence: Bool

    private var displayedABCD: String? {
        HandicapOddsComparisonTableMatrix.logic(matchNumbers: [match.matchNumber], matches: [match.resultBlindCopy])
    }

    private var scoreText: String {
        guard let home = match.homeScore, let away = match.awayScore else { return "-- : --" }
        return "\(home) : \(away)"
    }

    private var recommendationColor: Color {
        guard let oddsRecommendation else { return SequenceFilterTheme.textSecondary }
        switch oddsRecommendation.decision {
        case .bet: return .green
        case .observe: return .orange
        case .skip: return .red
        }
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack(alignment: .firstTextBaseline) {
                Text("北单\(match.matchNumber)")
                    .font(.headline.monospacedDigit())
                Text(match.league)
                    .font(.caption)
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
                Spacer()
                Text(match.status.isEmpty ? "状态未知" : match.status)
                    .font(.caption.bold())
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
            }
            Text(displayedABCD.map { "ABCD：" + $0 } ?? "ABCD：待补普通欧赔或让球")
                .font(.system(.subheadline, design: .monospaced).weight(.semibold))
                .foregroundStyle(displayedABCD == nil ? SequenceFilterTheme.textSecondary : SequenceFilterTheme.scoreAccent)
                .accessibilityIdentifier("score.abcd.\(match.matchNumber)")
            HStack(alignment: .center, spacing: 10) {
                Text(match.homeTeam)
                    .frame(maxWidth: .infinity, alignment: .trailing)
                Text(scoreText)
                    .font(.system(.title3, design: .monospaced).bold())
                    .foregroundStyle(SequenceFilterTheme.accent)
                    .monospacedDigit()
                    .fixedSize()
                Text(match.awayTeam)
                    .frame(maxWidth: .infinity, alignment: .leading)
            }
            .font(.subheadline.weight(.semibold))
            HStack {
                Text(match.matchTime)
                Spacer()
                if let handicap = match.handicap {
                    Text("让球\(handicap >= 0 ? "+" : "")\(handicap)")
                }
                if let outcome = match.handicapOutcome {
                    Text("让球赛果 \(outcome)")
                        .fontWeight(.bold)
                }
            }
            .font(.caption.monospacedDigit())
            .foregroundStyle(SequenceFilterTheme.textSecondary)
            if let oddsRecommendation {
                HStack(spacing: 6) {
                    Text(oddsRecommendation.decision.rawValue)
                        .font(.caption.bold())
                        .foregroundStyle(recommendationColor)
                    Text("单选\(oddsRecommendation.outcome) · \(String(format: "%.1f", oddsRecommendation.outcomeProbability * 100))% · 信心\(oddsRecommendation.modelConfidenceIndex)")
                        .font(.system(.caption2, design: .monospaced))
                        .foregroundStyle(SequenceFilterTheme.textSecondary)
                }
            } else if isCalculatingOddsConfidence, !match.hasStarted {
                Label("正在计算赔率置信度…", systemImage: "hourglass")
                    .font(.caption2)
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
            } else if match.hasStarted {
                Text("已开赛，不参与赛前投注推荐")
                    .font(.caption2)
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
            } else {
                Text("缺少完整普通欧赔或让球数，不推荐")
                    .font(.caption2)
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
            }
        }
        .padding(.vertical, 5)
    }
}

/// 将生成后才出现的大段结果 UI 隔离成独立视图。
/// iPhone XS 上直接把这些 Section 嵌在已经很大的输入页中，会在 result 从 nil
/// 切换为有值时触发 SwiftUI 深层类型元数据展开，表现为“点全局生成就退出”。
private struct GeneratedBetAmountSummary: View {
    let multiplier: Int
    let totalAmount: Int
    let splitCounts: [Int]

    var body: some View {
        Group {
            LabeledContent("总金额") {
                Text("¥\(totalAmount)")
                    .font(.headline.monospacedDigit())
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
            }
            ForEach(Array(splitCounts.enumerated()), id: \.offset) { index, count in
                LabeledContent("\(["A", "B", "C"][index]) TXT") {
                    Text("\(count)注 · ¥\(count * 2 * multiplier)")
                        .font(.subheadline.monospacedDigit())
                }
            }
            Text("TXT已去重；A/B/C按去重后实际注数尽量均分，因此金额基本一致；A优先压至约5–6行，B约10行，C放其余组合。以上金额均按 \(multiplier) 倍计算。")
                .font(.caption)
                .foregroundStyle(SequenceFilterTheme.textSecondary)
        }
    }
}

private struct GeneratedInputResultSections: View {
    let result: FilterResult
    let estimatedHitProbability: Double?
    let hitProbabilityExplanation: String?
    let methodDescription: String
    let txtBetCount: Int
    let multiplier: Int
    let totalAmount: Int
    let txtDisplaysSeventhMatch: Bool
    @Binding var showAllFilteredResultLines: Bool

    var body: some View {
        Group {
            Section("本次选场") {
                LabeledContent("参与条件判断") {
                    Text(result.config.matchNumbers.joined(separator: "、"))
                        .font(.system(.body, design: .monospaced).bold())
                        .textSelection(.enabled)
                }
                LabeledContent("A/B/C/D") {
                    Text(result.config.logic.map(\.displayName).joined())
                        .font(.system(.body, design: .monospaced).bold())
                }
                if let maximum = result.config.frontThreeMaximumFourCount {
                    LabeledContent("前三场判定值4") {
                        Text("最多\(maximum)个")
                            .font(.subheadline.bold())
                    }
                }
                if result.config.matchNumbers.count == 6 {
                    Text(result.config.calculationMatchCount == 5
                         ? "VIP10只以前5场计算全部条件；第6场固定全包310，不参与S、M、方差、判定值个数、转移率、波动、断点或禁4。"
                         : "以上6场全部进入S、M、方差、判定值个数、转移率、波动、断点和禁4计算；不是“前5场计算＋第6场外置全包”。")
                        .font(.caption.bold())
                        .foregroundStyle(SequenceFilterTheme.textSecondary)
                }
            }

            Section("本次概率分析") {
                LabeledContent("主场模型覆盖率") {
                    if let estimatedHitProbability {
                        Text("\(String(format: "%.2f", estimatedHitProbability * 100))%")
                            .font(.title3.bold())
                            .foregroundStyle(SequenceFilterTheme.textSecondary)
                    } else {
                        Text("暂无").foregroundStyle(SequenceFilterTheme.textSecondary)
                    }
                }
                if let hitProbabilityExplanation {
                    Text(hitProbabilityExplanation)
                        .font(.caption)
                        .foregroundStyle(SequenceFilterTheme.textSecondary)
                } else {
                    Text("需先成功获取当前\(result.config.matchNumbers.count)个过滤场次的赔率；若数据不全，仍可生成过滤结果，但不会虚构命中概率。")
                        .font(.caption)
                        .foregroundStyle(SequenceFilterTheme.textSecondary)
                }
                if let estimatedHitProbability {
                    LabeledContent("模型覆盖≥95%") {
                        Text(estimatedHitProbability >= 0.95 ? "已达到" : "未达到")
                            .fontWeight(.bold)
                            .foregroundStyle(SequenceFilterTheme.textSecondary)
                    }
                }
                LabeledContent("策略信心指数") {
                    Text("\(result.strategyConfidenceIndex)/100")
                        .font(.title3.bold())
                        .foregroundStyle(SequenceFilterTheme.textSecondary)
                }
                Text(methodDescription)
                    .font(.caption)
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
                Text("理由：\(result.strategyConfidenceReason)该指数衡量策略稳定度，不代表真实中奖率。")
                    .font(.caption)
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
                Text("采用领域：\(result.knowledgeFields)。")
                    .font(.caption)
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
            }

            Section("最终注数与TXT行数") {
                HStack {
                    Spacer()
                    VStack(spacing: 4) {
                        Text("\(txtBetCount)注")
                            .font(.system(size: 34, weight: .bold, design: .rounded))
                            .foregroundStyle(SequenceFilterTheme.textSecondary)
                        Text("TXT合并后共\(result.displayResultLines.count)行")
                            .font(.headline.monospacedDigit())
                        Text("\(multiplier)倍 · 总金额 ¥\(totalAmount)")
                            .font(.headline.monospacedDigit())
                            .foregroundStyle(SequenceFilterTheme.textSecondary)
                        Text("完整注展开 \(result.rawExpandedBetCount) · 删除重复 \(result.duplicateExpandedBetCount) · 去重后 \(txtBetCount)")
                            .font(.caption.monospacedDigit())
                            .foregroundStyle(SequenceFilterTheme.inputAccent)
                    }
                    Spacer()
                }
                .padding(.vertical, 8)
            }

            Section("各条件过滤注数（按执行顺序）") {
                if result.config.finalReduction != .off {
                    Text(result.finalReductionBasis).font(.caption).foregroundStyle(SequenceFilterTheme.textSecondary)
                }
                ForEach(Array(result.filterStageSummaries.enumerated()), id: \.offset) { _, line in
                    Text(line).font(.system(.subheadline, design: .monospaced))
                }
                ForEach(result.manualTXTExclusions.map(\.summary), id: \.self) { note in
                    Text(note).font(.subheadline).foregroundStyle(.orange)
                }
                Text("按完整7场的实际注数统计。乘积删除或最终减半可能只保留部分固定场选项，TXT不会补回已删注。")
                    .font(.caption)
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
            }

            Section("\(result.config.matchNumbers.count)场过滤结果（合并后\(result.filteredDisplayResultLines.count)行）") {
                let previewLimit = 60
                let visibleLines = showAllFilteredResultLines
                    ? result.filteredDisplayResultLines
                    : Array(result.filteredDisplayResultLines.prefix(previewLimit))
                ForEach(Array(visibleLines.enumerated()), id: \.offset) { index, line in
                    Text("\(String(format: "%02d", index + 1)). \(line)")
                        .font(.system(.subheadline, design: .monospaced))
                        .textSelection(.enabled)
                }
                if result.filteredDisplayResultLines.count > previewLimit {
                    Button(showAllFilteredResultLines
                           ? "收起完整结果"
                           : "展开全部\(result.filteredDisplayResultLines.count)行") {
                        showAllFilteredResultLines.toggle()
                    }
                    .font(.subheadline.bold())
                    Text(showAllFilteredResultLines
                         ? "已展开全部结果。"
                         : "为保持输入页流畅，默认只渲染前\(previewLimit)行；总 TXT 仍包含全部投注。")
                        .font(.caption)
                        .foregroundStyle(SequenceFilterTheme.textSecondary)
                }
                Text("首页是主场组合预览，部分固定场选项可能已被删除；TXT共\(result.displayResultLines.count)行，\(txtDisplaysSeventhMatch ? "投注行显示完整7场" : "投注行已隐藏第7场")，内部注数仍按完整整注计算。")
                    .font(.caption)
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
            }
        }
    }
}

