private enum AdvancedFilterDataError: LocalizedError {
    case spUnavailable
    case probabilityUnavailable

    var errorDescription: String? {
        switch self {
        case .spUnavailable: return "已开启SP相关过滤，但当前5个主场没有完整的胜/平/负SP，请刷新ABCD或关闭对应开关。"
        case .probabilityUnavailable: return "已开启概率过滤，但当前5个主场的模型概率不完整，请刷新ABCD或关闭对应开关。"
        }
    }
}

private struct PrizeQueryRecord: Codable, Identifiable {
    let id: Int
    let queriedAt: Date
    let issue: String
    let matchNumbers: [String]
    let handicaps: [Int?]?
    let isSettled: Bool
    let amount: Double
    let calculationLabel: String?
    let runSummary: PrizeRunSummary?
