    @State private var isBuildingProtectedHistoryProfile = false
    @State private var historicalToleranceStatistics: HistoricalGlobalToleranceStatistics?
    @State private var isBackfillingPrizeHistory = false
    @State private var prizeHistoryBackfillMessage: String?
    @State private var isBackfillingHandicapOutcomes = false
    @State private var handicapOutcomeBackfillMessage: String?
    @State private var sharedTXTQueryHistory: [SharedTXTQueryRecord] = []
    @State private var recentTXTQueryHistory: [SharedTXTQueryRecord] = []
    @State private var explicitTXTShareHistory: [SharedTXTQueryRecord] = []
    @State private var legacyTXTArchive: [SharedTXTQueryRecord] = []
    @State private var previewShareableReport: ShareableReport?
    @State private var hasLoadedRecentTXTQueryHistory = false
    @State private var recentTXTHistoryPersistenceTask: Task<Void, Never>?
    @State private var verifyingRecentTXTRecordIDs: Set<UUID> = []
    @State private var isVerifyingRecentTXTRecords = false
    @State private var verifyingSharedTXTRecordIDs: Set<UUID> = []
    @State private var refreshingSharedTXTRecordIDs: Set<UUID> = []
    @State private var isVerifyingAllSharedTXTRecords = false
    @State private var sharedTXTBulkVerificationMessage: String?
    @State private var isImportingTXT = false
    @State private var txtImportMessage: String?
    @State private var txtQueryStatisticsMessage: String?
    @State private var isRefreshingQueryConditions = false
    @State private var queryConditionsRefreshMessage: String?
    private let historicalBatchIssues = ["26091", "26092", "26093"]
    private let historicalMergedIssues = (26091...26098).map(String.init)
    private let historicalBatchCombinedSelection = "26091—26098合并"
    @State private var historicalBatchSnapshots: [String: Issue26094BatchSnapshot] = [:]
    @State private var calculatingHistoricalBatchIssue: String?
    @State private var historicalBatchProgressMessages: [String: String] = [:]
    @State private var selectedHistoricalBatchIssue = "26091"
    @State private var isShowingHistoricalBatchResults = false
    @State private var isRegeneratingGlobalPrizeAnswers = false
    @State private var globalPrizeAnswerMessage: String?
    @State private var isShowingGlobalPrizeAnswers = false
    @State private var globalABCDByPrizeRecordID: [Int: String] = [:]
    @State private var globalFilterCountsByRecordID: [Int: GlobalPrizeFilterCounts] = [:]
    @State private var globalFilterCacheConditionSignature: String?
    @State private var calculationVersionHistory: [CalculationVersionSummary] = []
    @State private var protectedPrizeOutcomePrefixesCache: Set<[Int]> = []
    @State private var showAllFilteredResultLines = false
    @State private var historicalStatisticsRefreshTask: Task<Void, Never>?
    @State private var prizeHistoryPersistenceTask: Task<Void, Never>?
    @State private var sharedTXTHistoryPersistenceTask: Task<Void, Never>?
    @State private var prizeDerivedStatisticsRefreshTask: Task<Void, Never>?
    @State private var protectedPrizePrefixRefreshTask: Task<Void, Never>?
    @State private var cachedPrizeRunStatistics = PrizeRunStatisticsSnapshot.empty
    @State private var inputDefaultsSaveTask: Task<Void, Never>?
    @State private var durableBackupTask: Task<Void, Never>?
    @State private var inputExperienceMode = "v1"
    @State private var vip1StartInput = ""
    @State private var vip1EndInput = ""
    @State private var vip1Selection: VIP1SevenSelection?
    @State private var vipSeventhNumber = "1"
    @State private var vipSeventhOutcome = "3"
    @State private var vipPrizeMessage = ""
    @State private var vipResultMatches: [BeijingSingleMatch] = []
    @State private var vip1SelectionMessage: String?
    @State private var isSelectingVIP1 = false
    @State private var vip1SelectionTask: Task<Void, Never>?
    @State private var vip1SelectionToken = UUID()
    @State private var selectedRootTab = 0

    @ViewBuilder
    private var selectedRootPage: some View {
        switch selectedRootTab {
        case 1:
            scorePage.sequenceFilterModulePalette(SequenceFilterTheme.scoreAccent)
        case 2:
            conditionsPage.sequenceFilterModulePalette(SequenceFilterTheme.conditionsAccent)
        case 3:
            historyPage.sequenceFilterModulePalette(SequenceFilterTheme.queryAccent)
        case 4:
            prizePage.sequenceFilterModulePalette(SequenceFilterTheme.prizeAccent)
        default:
            inputPage.sequenceFilterModulePalette(SequenceFilterTheme.inputAccent)
        }
    }

    private var rootTabBar: some View {
        let items = [
            ("输入", "square.and.pencil"),
            ("比分", "sportscourt.fill"),
            ("条件", "slider.horizontal.3"),
            ("查询", "clock.arrow.circlepath"),
            ("奖金", "yensign.circle")
        ]
        return HStack(spacing: 0) {
            ForEach(items.indices, id: \.self) { index in
                Button {
                    selectedRootTab = index
                    if index == 0,
                       usesVIP6AutomaticMatchSelection,
                       (!hasValidMainNumbers || currentABCDForGeneration == nil) {
                        scheduleVIP6AutomaticMatchSelection()
                    } else if index == 0,
                              usesVIP6AutomaticMatchSelection,
                              vip6SelectedMatchesWithResults.isEmpty {
                        Task { await loadVIP6CompletedResultVerification() }
                    } else if index == 1 {
                        refreshScoreTab()
                    }
                } label: {
                    VStack(spacing: 3) {
                        Image(systemName: items[index].1)
                            .font(.system(size: 20, weight: selectedRootTab == index ? .semibold : .regular))
                        Text(items[index].0)
                            .font(.caption2)
                    }
                    .foregroundStyle(selectedRootTab == index ? SequenceFilterTheme.accent : Color.secondary)
                    .frame(maxWidth: .infinity, minHeight: 46)
                    .contentShape(Rectangle())
                }
                .buttonStyle(.plain)
            }
        }
        .padding(.horizontal, 4)
        .padding(.top, 3)
        .background(.ultraThinMaterial)
        .overlay(alignment: .top) { Divider() }
    }

    var body: some View {
        VStack(spacing: 0) {
            selectedRootPage
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .clipped()
            // 底栏直接参与布局，所有NavigationStack内的列表都只占用上方
            // 剩余高度，不依赖子页面继续传递外层safeAreaInset。
            VStack(spacing: 0) {
                if selectedRootTab == 0 {
                    inputActionBar
                }
                rootTabBar
            }
            .fixedSize(horizontal: false, vertical: true)
            .background(.ultraThinMaterial)
        }
        .foregroundStyle(SequenceFilterTheme.textPrimary)
        .tint(SequenceFilterTheme.accent)
        .background(SequenceFilterTheme.background.ignoresSafeArea())
        .preferredColorScheme(.light)
        .background(KeyboardDismissTapInstaller())
        .sheet(item: $shareableReport) { report in
            AppleShareSheet(items: [report.url])
                .onAppear { recordExplicitTXTShare(report.txtSnapshot) }
        }
        .sheet(isPresented: $isShowingGlobalPrizeAnswers) {
            globalPrizeAnswersPage
        }
        .sheet(isPresented: $isShowingTXTTools, onDismiss: {
            if let part = pendingTXTPreviewPart {
                pendingTXTPreviewPart = nil
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.15) {
                    previewGeneratedTXTReport(part)
                }
            } else if let part = pendingTXTSharePart {
                pendingTXTSharePart = nil
                // 等工具sheet完成退场后再呈现系统分享页，避免同一更新周期
                // 同时切换两个UIViewController。
                DispatchQueue.main.asyncAfter(deadline: .now() + 0.15) {
                    shareTXTReport(part)
                }
            }
        }) {
            txtToolsSheet
        }
        .sheet(isPresented: $isShowingCurrentTXTQueryResult) {
            currentTXTQueryResultSheet
        }
        .sheet(isPresented: $isShowingHistoricalBatchResults) {
            historicalBatchResultsPage(issue: selectedHistoricalBatchIssue)
        }
        .sheet(item: $txtPreview) { preview in
            NavigationStack {
                ScrollView {
                    LazyVStack(alignment: .leading, spacing: 2) {
                        ForEach(
                            Array(preview.content.components(separatedBy: .newlines).enumerated()),
                            id: \.offset
                        ) { index, line in
                            let isHitLine = preview.highlightedLineIndices.contains(index)
                            Text(line.isEmpty ? " " : line)
                                .font(.system(.caption, design: .monospaced))
                                .foregroundStyle(isHitLine ? Color.red : SequenceFilterTheme.textPrimary)
                                .fontWeight(isHitLine ? .bold : .regular)
                                .textSelection(.enabled)
                                .frame(maxWidth: .infinity, alignment: .leading)
                                .padding(.horizontal, isHitLine ? 6 : 0)
                                .padding(.vertical, isHitLine ? 4 : 0)
                                .background(
                                    isHitLine ? Color.red.opacity(0.18) : Color.clear,
                                    in: RoundedRectangle(cornerRadius: 6)
                                )
                        }
                    }
                    .padding()
                }
                .background(SequenceFilterTheme.background.ignoresSafeArea())
                .safeAreaInset(edge: .bottom) { txtPreviewActions(preview) }
                .navigationTitle(preview.title)
                .navigationBarTitleDisplayMode(.inline)
                .toolbar(.visible, for: .navigationBar)
                .toolbar {
                    ToolbarItem(placement: .topBarLeading) {
                        Button {
                            txtPreview = nil
                        } label: {
                            Label("返回", systemImage: "chevron.left")
                        }
                    }
                    ToolbarItem(placement: .topBarTrailing) {
                        Button {
                            sharePreviewTXT(preview)
                        } label: {
                            Label("分享", systemImage: "square.and.arrow.up")
                        }
                        .accessibilityIdentifier("txt.preview.share")
                    }
                }
            }
            .sheet(isPresented: $isShowingTXTExclusionEditor) {
                txtExclusionEditorSheet(preview)
            }
            .sheet(item: $previewShareableReport) { report in
                AppleShareSheet(items: [report.url])
                    .onAppear { recordExplicitTXTShare(report.txtSnapshot) }
            }
        }
        .onAppear {
            let restoredAfterReinstall = DurableAppBackup.restoreAfterReinstallIfNeeded()
            // Admission/history loading must also run if settings were already
            // restored; it cannot depend on the form's loaded-state guard.
            ExplicitTXTShareArchive.preserveLegacyHistoryOnce(defaults: .standard)
            loadExplicitTXTShareHistory()
            let computerConditionValues = computerConditionDefaultsForMaintenance()
                .map(FilterInputDefaults.removingFixed105Limit)
                .map(FilterInputDefaults.currentDirectionalDoubleSettings)
            if let computerConditionValues {
                UserDefaults.standard.set(computerConditionValues, forKey: inputDefaultsStorageKey)
                UserDefaults.standard.synchronize()
            }
            applyCurrentSelectionSettings()
            installSVVVPackageIfNeeded()
            installSVVVHighPassConditionsIfNeeded()
            installSVVVHighPass93ConditionsIfNeeded()
            installSVVVHighPass98PackagesIfNeeded()
            installSVVVP11RevisionIfNeeded()
            // 必须在 restoreInputDefaults() 之前抓取。SwiftUI 回填 @State
            // 可能触发旧内存值落盘，但本次维护/导入必须只认启动时的条件Tab。
            let launchPersistedConditionValues = computerConditionValues
                ?? UserDefaults.standard.dictionary(forKey: inputDefaultsStorageKey) as? [String: String]
            let launchConditionInput = persistedCurrentConditionInputForMaintenance(
                persistedValues: launchPersistedConditionValues
            )
            let launchConditionSignature = globalFilterConditionsSignature(
                for: launchConditionInput,
                persistedValues: launchPersistedConditionValues
            )
            let launchRun2Token = launchConditionInput.split(separator: "|")
                .first { $0.uppercased().hasPrefix("RUN2ON=") }
                .map(String.init) ?? "RUN2ON=?"
            NSLog(
                "LAUNCH-CONDITION-SNAPSHOT savedRUN2=%@ input=%@",
                launchPersistedConditionValues?["secondaryConsecutiveRunsEnabled"] ?? "nil",
                launchRun2Token
            )
            // 电脑下发的条件快照只能用一次。导入完成后立即删除，
            // 否则下次普通启动会再次覆盖用户在条件 Tab 的新修改。
            if computerConditionValues != nil {
                try? FileManager.default.removeItem(at: computerConditionDefaultsURL)
            }
            guard !hasLoadedInputDefaults else { return }
            isRestoringInputDefaults = true
            loadCalculationVersionHistory()
            restoreInputDefaults()
            purgeLegacyComputedCachesIfNeeded()
            loadPreviousRunSnapshot()
            syncPrizeMatchInputsFromFirst()
            syncSequentialMatchInputs()
            loadPrizeQueryHistory()
            refreshProtectedPrizeOutcomePrefixesCache()
            loadSavedFilterSchemes()
            let recentTXTLegacyData = UserDefaults.standard.data(forKey: sharedTXTQueryHistoryStorageKey)
            Task { await loadRecentTXTQueryHistory(legacyData: recentTXTLegacyData) }
            loadSharedTXTQueryHistory()
            schedulePrizeDerivedStatisticsRefresh()
            loadHistoricalBatchSnapshots()
            loadGlobalABCDCache()
            importComputerRefreshedGlobalDataIfPresent(
                expectedConditionSignature: launchConditionSignature
            )
            loadGlobalFilterCountCache()
            logicInput = ""
            abcdAttemptedKey = nil
            automaticallyFetchedABCDKey = nil
            // 启动时只读本地缓存，避免输入页被网络请求和重复状态刷新卡住。
            // 需要最新数据时由用户点击“获取ABCD”。
            restoreCurrentABCDFromCache()
            if ProcessInfo.processInfo.arguments.contains("--disable-sp-product-filter") {
                spProductFilterEnabled = false
                var values = UserDefaults.standard.dictionary(forKey: inputDefaultsStorageKey) as? [String: String] ?? [:]
                values["spProductFilterEnabled"] = "0"
                UserDefaults.standard.set(values, forKey: inputDefaultsStorageKey)
                UserDefaults.standard.synchronize()
            }
            DispatchQueue.main.async {
                refreshHistoricalToleranceStatistics()
            }
            let isSeedingGlobalAnswerCache = ProcessInfo.processInfo.arguments.contains("--seed-global-answer-cache")
                || ProcessInfo.processInfo.environment["SEED_GLOBAL_ANSWER_CACHE"] == "1"
            if ProcessInfo.processInfo.arguments.contains("--activate-svvvp11-recommended") {
                DispatchQueue.main.async { activateSVVVP11Package(reset: true) }
            } else if ProcessInfo.processInfo.arguments.contains("--calculate-historical-batch")
                || ProcessInfo.processInfo.arguments.contains("--calculate-26094-batch") {
                DispatchQueue.main.async {
                    Task { @MainActor in
                        let requestedIssue = ProcessInfo.processInfo.arguments.first {
                            $0.hasPrefix("--batch-issue=")
                        }?.replacingOccurrences(of: "--batch-issue=", with: "") ?? "26091"
                        await calculateHistoricalBatch(issue: requestedIssue)
                        // 批量记录使用运行时实际条件签名。启动前从文件读取的签名可能
                        // 尚未提交到 @State，不能拿它过滤刚生成的TXT。
                        exportCurrentComputerMaintenancePayload()
                        NSLog("HISTORICAL-BATCH %@ maintenance export finished", requestedIssue)
                    }
                }
            } else if ProcessInfo.processInfo.arguments.contains("--apply-big-compression-tolerance-0-3") {
                applyVerifiedBigCompressionToleranceForMaintenance()
            } else if ProcessInfo.processInfo.arguments.contains("--apply-generic-big-compression") {
                Task { await applyVerifiedGenericBigCompressionForMaintenance() }
            } else if ProcessInfo.processInfo.arguments.contains("--recompute-vip1-206") {
                // 本次电脑维护仅重算26091—26098的VIP 1有效单：
                // 值2个数≥4的冻结单不进入计算，26101也不混入这批结果。
                DispatchQueue.main.async {
                    Task { @MainActor in
                        let defaults = UserDefaults.standard
                        let statusKey = "sequenceFilter.vip1Bulk.status.v1"
                        let summaryKey = "sequenceFilter.vip1Bulk.summary.v1"
                        defaults.set("running", forKey: statusKey)
                        defaults.removeObject(forKey: summaryKey)
                        defaults.synchronize()

                        let targets = mergedHistoricalPrizeRecords.filter { !isVIP1FrozenRecord($0) }
                        await recomputeAllTXTAndGlobalFromCurrentRulesForMaintenance(
                            currentConditionInput: launchConditionInput,
                            currentConditionSignature: launchConditionSignature,
                            targetRecords: targets
                        )
                        // VIP 1的29个冻结单只保留在“冻结”列表，不能让旧TXT
                        // 混入查询页的通过/未通过及注数统计。奖金原始记录不删除。
                        let targetKeys = Set(targets.map {
                            TXTQueryStatisticsCalculator.ticketKey(
                                issue: $0.issue,
                                matchNumbers: $0.matchNumbers
                            )
                        })
                        sharedTXTQueryHistory.removeAll { record in
                            historicalMergedIssues.contains(record.issue)
                                && !targetKeys.contains(
                                    TXTQueryStatisticsCalculator.ticketKey(
                                        issue: record.issue,
                                        matchNumbers: record.matchNumbers
                                    )
                                )
                        }
                        saveSharedTXTQueryHistory()
                        let calculated = targets.filter { globalFilterCountsByRecordID[$0.id] != nil }.count
                        let passed = targets.filter {
                            globalFilterCountsByRecordID[$0.id]?.targetCoveredByFinalTXT == true
                        }.count
                        let failed = targets.filter {
                            globalFilterCountsByRecordID[$0.id]?.targetCoveredByFinalTXT == false
                        }.count
                        let summary = "VIP 1已用电脑重算\(calculated)/\(targets.count)单；通过\(passed)单，未通过\(failed)单。"
                        sharedTXTBulkVerificationMessage = summary
                        defaults.set(calculated == targets.count ? "completed" : "incomplete", forKey: statusKey)
                        defaults.set(summary, forKey: summaryKey)
                        defaults.set(Date(), forKey: "sequenceFilter.vip1Bulk.completedAt.v1")
                        defaults.synchronize()
                        NSLog("VIP1-206-RECOMPUTE %@", summary)
                    }
                }
            } else if ProcessInfo.processInfo.arguments.contains("--recompute-txt-global-current-rules") {
                // 维护命令直接从 UserDefaults 制作不可变的条件快照，
                // 不依赖 SwiftUI @State 在 onAppear 当前事务内是否已提交。
                DispatchQueue.main.async {
                    Task { @MainActor in
                        await recomputeAllTXTAndGlobalFromCurrentRulesForMaintenance(
                            currentConditionInput: launchConditionInput,
                            currentConditionSignature: launchConditionSignature
                        )
                        diagnoseGlobalStatisticsForMaintenance()
                    }
                }
            } else if isSeedingGlobalAnswerCache {
                Task { await seedAllGlobalAnswerCacheForDeviceInstall() }
            } else if ProcessInfo.processInfo.arguments.contains("--refresh-missing-global-data") {
                Task { await refreshMissingGlobalDataForMaintenance() }
            } else if ProcessInfo.processInfo.arguments.contains("--regenerate-current-global-txt") {
                Task { await regenerateCurrentGlobalTXTForMaintenance() }
            } else if ProcessInfo.processInfo.arguments.contains("--diagnose-global-statistics") {
                diagnoseGlobalStatisticsForMaintenance()
            } else if ProcessInfo.processInfo.arguments.contains("--diagnose-batch-failures") {
                diagnoseBatchFailureReasonsForMaintenance(
                    currentConditionInput: launchConditionInput
                )
            } else if ProcessInfo.processInfo.arguments.contains("--diagnose-big-compression-tolerance") {
                Task { await diagnoseBigCompressionToleranceForMaintenance() }
            } else if ProcessInfo.processInfo.arguments.contains("--test-current-global-generation") {
                Task {
                    let passes = ProcessInfo.processInfo.arguments.contains("--repeat-global-generation") ? 2 : 1
                    for pass in 1...passes {
                        let beforeCount = uniqueTXTQueryRecords.count
                        // 维护测试必须和真实按钮走完全相同的路径：
                        // ABCD校验、赔率补取、引擎计算、结果渲染和查询落库。
                        await calculateAfterEnsuringRequiredMatchTimes()
                        for _ in 0..<120 where isCalculating {
                            try? await Task.sleep(nanoseconds: 250_000_000)
                        }
                        let afterCount = uniqueTXTQueryRecords.count
                        NSLog(
                            "Global generation UI test final: %d; query before=%ld after=%ld; autoSaved=%@",
                            result.map { expandedSharedTXTBets($0).count } ?? -1,
                            beforeCount,
                            afterCount,
                            txtImportMessage?.contains("全局生成已保存本机存档") == true ? "YES" : "NO"
                        )
                        NSLog("Global generation search test: pass=%d start=%@ selected=%@", pass,
                            automaticMatchSearchStart, currentCalculationMatchNumbers.joined(separator: ","))
                    }
                }
            } else if ProcessInfo.processInfo.arguments.contains("--test-last-run-ui") {
                Task { await diagnoseLastRunForMaintenance() }
            } else if ProcessInfo.processInfo.arguments.contains("--diagnose-last-run") {
                Task { await diagnoseLastRunForMaintenance() }
            } else if ProcessInfo.processInfo.environment["IMPORT_GLOBAL_ANSWER_CACHE"] == "1"
                || FileManager.default.fileExists(atPath: computerGlobalAnswerCacheURL.path) {
                importComputerGeneratedGlobalAnswerCache(
                    expectedConditionSignature: launchConditionSignature,
                    conditionValues: launchPersistedConditionValues
                )
            }
            if ProcessInfo.processInfo.arguments.contains("--rebuild-protected-history-profile") {
                Task { await rebuildProtectedHistoryMaxCompressionProfile() }
            }
            // 全局答案的批量复核只在 Mac 上计算后导入。普通启动不在手机上
            // 自动重算 41 条大压缩，避免占用大量内存或覆盖电脑已校验的缓存。
            scheduleDurableBackup()
            if restoredAfterReinstall {
                globalPrizeAnswerMessage = "已从耐久备份自动召回卸载前的全部数据。"
            }
            DispatchQueue.main.async {
                isRestoringInputDefaults = false
            }
        }
        .task(id: finalOutcomeRecommendationRefreshKey) {
            refreshFinalOutcomeRecommendation()
        }
        .task(id: automaticDoubleMarketPollingKey) {
            guard scenePhase == .active, hasLoadedInputDefaults, usesSVIP10AutomaticDoublePair,
                  inputExperienceMode == "v1" else { return }
            while !Task.isCancelled {
                do { try await Task.sleep(nanoseconds: 60_000_000_000) }
                catch { return }
                await refreshDoubleMarketSelection(forceApply: false)
            }
        }
        .onChange(of: manualMatchSelectionKey) { key in
            if manualMatchSelectionScope != key { manualMatchSelectionScope = "" }
        }
        .onChange(of: automaticDoubleSelectionSettingsKey) { _ in
            guard hasLoadedInputDefaults, !isRestoringInputDefaults, selectedConditionVersionID == "svip10-frozen-160" else { return }
            scheduleVIP6AutomaticMatchSelection()
        }
        .onChange(of: inputPersistenceSignature) { _ in
            scheduleInputDefaultsSave()
        }
        .onChange(of: globalFilterConditionsSignature) { _ in
            guard !isRestoringInputDefaults else { return }
            // 条件 Tab 任意一项变更后，内存与持久化的旧计算结果同时删除。
            // TXT 本身作为历史保留，但由条件签名保证绝不会被当前奖金/查询复用。
            invalidateComputedResultsAfterConditionChange()
        }
        .onChange(of: generatedInput) { input in
            let current = try? FilterConfig.parse(input)
            historicalStatisticsRefreshTask?.cancel()
            if current == nil {
                historicalToleranceStatistics = nil
                protectedPrizeOutcomePrefixesCache = []
            }
            guard let result,
                  let current,
                  !result.matchesGenerationRequest(current) else {
                scheduleHistoricalStatisticsRefresh(for: current)
                return
            }
            self.result = nil
            showAllFilteredResultLines = false
            scheduleHistoricalStatisticsRefresh(for: current)
        }
        .onChange(of: match1Input) { value in
            if programmaticallySelectedFirstMatch == value {
                programmaticallySelectedFirstMatch = nil
                return
            }
            guard !usesAutomaticSearchOrigin else { return }
            if usesVIP6AutomaticMatchSelection {
                scheduleVIP6AutomaticMatchSelection()
            } else {
                syncSequentialMatchInputs()
            }
        }
        .onChange(of:inputExperienceMode) { mode in
            vip6AutoSelectionTask?.cancel()
            invalidateVIP1Selection()
            isCalculatingVIP6Matches=false
            isSelectingVIP1=false
            if mode == "vip1", !["3","0"].contains(vipSeventhOutcome) { vipSeventhOutcome="3" }
            if mode != "v1" {
                if vip1StartInput.isEmpty { vip1StartInput=match1Input }
                if vip1EndInput.isEmpty { vip1EndInput=singleMatchInput }
            } else if hasLoadedInputDefaults { scheduleVIP6AutomaticMatchSelection() }
        }
        .onChange(of: vipSeventhNumber) { _ in invalidateVIP1Selection() }
        .onChange(of: vipSeventhOutcome) { _ in invalidateVIP1Selection() }
        .onChange(of: vip1StartInput) { _ in invalidateVIP1Selection() }
        .onChange(of: vip1EndInput) { _ in invalidateVIP1Selection() }
        .onChange(of: beijingSingleIssueInput) { _ in
            invalidateVIP1Selection()
            if usesVIP6AutomaticMatchSelection {
                scheduleVIP6AutomaticMatchSelection()
            }
        }
        .onChange(of: abcdInputKey) { _ in
            guard hasLoadedInputDefaults else { return }
            // VIP6/VIP7自动选场会在同一次主线程事务中同时写入6个场次和ABCD。
            // onChange可能在写入完成后才回调；如果新key已有完整ABCD，不能反过来
            // 把刚自动生成的结果清空。
            if abcdAttemptedKey == abcdInputKey,
               normalizedCurrentABCD(logicInput) != nil {
                return
            }
            // 期号、场次或数据源变化后，旧ABCD绝不能继续参与新一轮计算。
            // 只尝试同步恢复本地缓存；不在启动/编辑时自动联网。
            logicInput = ""
            abcdAttemptedKey = nil
            automaticallyFetchedABCDKey = nil
            goalModelAnalyses = []
            goalModelErrorMessage = nil
            result = nil
            restoreCurrentABCDFromCache()
        }
        .onChange(of: scenePhase) { phase in
            if phase == .inactive || phase == .background {
                prizeHistoryPersistenceTask?.cancel()
                sharedTXTHistoryPersistenceTask?.cancel()
                recentTXTHistoryPersistenceTask?.cancel()
                persistPrizeHistoryImmediately()
                persistSharedTXTHistoryImmediately()
                persistRecentTXTHistoryImmediately()
                // 分享面板和键盘状态变化都会触发scene更新。钥匙串写入绝不能
                // 同步占用主线程，否则旧XS会在10秒后被系统看门狗终止。
                scheduleDurableBackup(delayNanoseconds: 0)
            }
        }
    }


