    private var scoreMatchPages: [[BeijingSingleMatch]] {
        let ordered = scoreMatches.sorted {
            (Int($0.matchNumber) ?? Int.max) < (Int($1.matchNumber) ?? Int.max)
        }
        return ScoreMatchPagination.pageRanges(totalCount: ordered.count).map { range in
            Array(ordered[range])
        }
    }

    private var visibleScoreMatches: [BeijingSingleMatch] {
        let pages = scoreMatchPages
        guard !pages.isEmpty else { return [] }
        return pages[min(max(scoreSelectedPage, 0), pages.count - 1)]
    }

    private func scorePageButtonTitle(_ page: [BeijingSingleMatch]) -> String {
        guard let first = page.first?.matchNumber, let last = page.last?.matchNumber else { return "空" }
        return first == last ? "第\(first)场" : "\(first)–\(last)"
    }

    private var scorePageSectionTitle: String {
        let page = visibleScoreMatches
        guard let first = page.first?.matchNumber, let last = page.last?.matchNumber else {
            return "0场"
        }
        return "\(first)–\(last) · \(page.count)场"
    }

