    private func invalidateVIP1Selection() {
        vip1SelectionTask?.cancel()
        vip1SelectionToken=UUID()
        isSelectingVIP1=false
        vip1Selection=nil
        vip1SelectionMessage=nil
        vipPrizeMessage=""
        vipResultMatches=[]
    }

    private func generateVIP1Selection() {
        invalidateVIP1Selection()
        guard let start=Int(vip1StartInput.trimmingCharacters(in:.whitespacesAndNewlines)),
              let end=Int(vip1EndInput.trimmingCharacters(in:.whitespacesAndNewlines)),start>0,end>start else {
            vip1SelectionMessage="请输入有效起点和终点，终点须大于起点。";return
        }
        guard let seventh=Int(vipSeventhNumber),seventh>0,(inputExperienceMode == "vip1" ? ["3","0"] : ["3","1","0"]).contains(vipSeventhOutcome) else {
            vip1SelectionMessage="请填写第7场有效场次和单选赛果。";return
        }
        let token=vip1SelectionToken
        let mode=inputExperienceMode
        let doubleCount=mode == "vip2" ? 2 : 1
        isSelectingVIP1=true
        vip1SelectionTask=Task { @MainActor in
            defer { if vip1SelectionToken==token { isSelectingVIP1=false } }
            do {
                let issue=try await resolveCurrentIssue()
                try Task.checkCancellation()
                let matches=try await FiveHundredBeijingSingleClient.fetchAllIssueMatches(issue:issue)
                try Task.checkCancellation()
                let chosen=try await Task.detached(priority:.userInitiated) {
                    try VIP1SevenMatchSelector.select(start:start,end:end,matches:matches.filter{Int($0.matchNumber) != seventh},doubleCount:doubleCount)
                }.value
                try Task.checkCancellation()
                guard vip1SelectionToken==token,inputExperienceMode==mode else { return }
                let bets = chosen.legs.reduce([[]]) { partial, leg in
                    partial.flatMap { prefix in leg.options.map { prefix + [$0] } }
                }
                if overallOddsForecastGateEnabled,
                   let forecast = SequenceFilterEngine.overallOddsForecast(
                    bets: bets,
                    customOdds: chosen.legs.map(\.customOdds)
                ), forecast.isLow {
                    let weakLeg = chosen.legs[forecast.weakestPosition - 1]
                    vip1Selection = nil
                    vip1SelectionMessage = "整体赔率预测偏低：六场自定义赔率乘积中位数\(String(format: "%.2f", forecast.medianProduct))，低于500，本次未生成。建议更换场次\(weakLeg.number)（当前选中赔率中位数\(String(format: "%.2f", forecast.weakestMedianSelectedOdd))），优先选择让球后胜平负三项赔率更均衡的比赛。"
                    return
                }
                vip1Selection=chosen
                vipResultMatches=matches
                updateVIPPrizeMessage()
                archiveVIPTXT(chosen)
            } catch is CancellationError { return }
            catch { if vip1SelectionToken==token { vip1SelectionMessage=error.localizedDescription } }
        }
    }

    private func vipPlainTXT(_ selection: VIP1SevenSelection) -> String {
        let numbers=selection.legs.map{String($0.number)}+[vipSeventhNumber]
        let seventhOptions=[[Int(vipSeventhOutcome) ?? 1]]
        return selection.txtPartitions.map { partition in
            let body=zip(numbers,partition.options+seventhOptions).map { number,values in
                let choice=values.count==1 ? String(values[0]) : "(\(values.map(String.init).joined()))"
                return "\(number)→\(choice)"
            }.joined(separator:"，")
            return partition.label.map { "\($0)：\(body)" } ?? body
        }.joined(separator:"\n")
    }

    private func vipTXTRecord(_ selection: VIP1SevenSelection) -> SharedTXTQueryRecord {
        let firstSix = selection.legs.compactMap { leg in
            vipResultMatches.first { $0.issue == selection.issue && Int($0.matchNumber) == leg.number }
        }
        let final = QueryFinalityGate.permitsResult(matches: firstSix, expectedCount: 6)
        let outcomes = final ? firstSix.map(QueryFinalityGate.resolvedOutcome) : nil
        let seventh = Int(vipSeventhOutcome) ?? 1
        let bets = selection.legs.reduce([[Int]]([[]])) { prefixes, leg in
            prefixes.flatMap { prefix in leg.options.map { prefix + [$0] } }
        }.map { $0 + [seventh] }
        return SharedTXTQueryRecord(
            id: UUID(), sharedAt: Date(), issue: selection.issue,
            filename: "\(inputExperienceMode.uppercased())-\(selection.issue)-\(selection.start)-\(selection.end).txt",
            txtContent: vipPlainTXT(selection), normalizedInput: "",
            matchNumbers: selection.legs.map { String($0.number) } + [vipSeventhNumber],
            betOutcomes: bets, finalBetCount: bets.count, conditionSignature: nil,
            lastCheckedAt: final ? Date() : nil, observedOutcomes: outcomes,
            observedHandicaps: firstSix.map(\.handicap), verificationMessage: nil,
            isFinalResult: final, isHit: nil, prizeAmount: nil, prizeSPValues: nil,
            generationCustomOdds: selection.legs.map(\.customOdds)
        )
    }

    private func archiveVIPTXT(_ selection: VIP1SevenSelection) {
        archiveRecentTXTRecord(vipTXTRecord(selection))
    }

    private func updateVIPPrizeMessage() {
        guard let selection=vip1Selection else { return }
        let selected=selection.legs.compactMap { leg in vipResultMatches.first { $0.issue==selection.issue && Int($0.matchNumber)==leg.number } }
        guard QueryFinalityGate.permitsResult(matches:selected,expectedCount:6) else {
            vipPrizeMessage="前六场尚未全部开奖，暂不判断命中。"; return
        }
        let outcomes=selected.compactMap { QueryFinalityGate.resolvedOutcome($0) }
        let reasons=selection.missReasons(outcomes:outcomes)
        guard reasons.isEmpty else {
            vipPrizeMessage="前六场未命中；奖金0元。\n未中原因（按实际让球赛果）：\n"+reasons.joined(separator:"\n")
                + "\n第7场不参与前六场命中判断。"
            return
        }
        let report=TXTQueryPrizeCalculator.calculate(issue:selection.issue,matchNumbers:selection.legs.map{String($0.number)}+[vipSeventhNumber],firstSixOutcomes:outcomes,seventhOptions:[Int(vipSeventhOutcome) ?? 1],matches:vipResultMatches,snapshots:[],isSimulation:false,multiplier:1)
        vipPrizeMessage="前六场已命中。\n"+report.displayText
    }

    private func refreshVIPPrize() {
        guard let selection=vip1Selection else { return }
        let token=vip1SelectionToken
        vip1SelectionTask?.cancel()
        vip1SelectionTask=Task { @MainActor in
            do {
                let matches=try await FiveHundredBeijingSingleClient.fetchAllIssueMatches(issue:selection.issue)
                try Task.checkCancellation()
                guard token==vip1SelectionToken else { return }
                vipResultMatches=matches; updateVIPPrizeMessage()
            } catch is CancellationError { return }
            catch { if token==vip1SelectionToken { vipPrizeMessage="开奖查询失败：\(error.localizedDescription)" } }
        }
    }

    private func vipTXTFile(_ selection: VIP1SevenSelection) throws -> URL {
        try writeShareFile(
            filename: "\(inputExperienceMode.uppercased())-\(selection.issue)-\(selection.start)-\(selection.end).txt",
            text: vipPlainTXT(selection)
        )
    }

    private func previewVIPTXT() {
        guard let selection=vip1Selection else { return }
        do {
            txtPreview=TXTPreview(id:UUID(),title:"\(inputExperienceMode.uppercased()) · E/F · 1倍",content:vipPlainTXT(selection),highlightedLineIndices:[],shareURL:try vipTXTFile(selection),sharingRecord:vipTXTRecord(selection))
        } catch { vip1SelectionMessage="TXT生成失败：\(error.localizedDescription)" }
    }

    private func shareVIP1TXT() {
        guard let selection=vip1Selection else { return }
        do { shareableReport=ShareableReport(url:try vipTXTFile(selection)) }
        catch { vip1SelectionMessage="TXT生成失败：\(error.localizedDescription)" }
    }

    private var manualMatchSelectionKey: String {
        beijingSingleIssueInput.trimmingCharacters(in: .whitespacesAndNewlines) + "|" + selectedConditionVersionID + "|" + inputExperienceMode
    }
    private var hasManualMatchSelection: Bool {
        inputExperienceMode == "v1" && manualMatchSelectionScope == manualMatchSelectionKey
    }
    private var inputMatchReplacementSection: some View {
        Section("替换已选场号") {
            HStack {
                TextField("原场号，如3", text: $replacementOldMatchInput)
                    .keyboardType(.numberPad).accessibilityIdentifier("input.replaceMatch.from")
                Image(systemName: "arrow.right")
                TextField("新场号，如20", text: $replacementNewMatchInput)
                    .keyboardType(.numberPad).accessibilityIdentifier("input.replaceMatch.to")
            }
            Button("替换场号") { replaceSelectedMatchNumber() }
                .frame(minHeight: 44)
                .disabled(isCalculating || globalGenerationPhase != nil || isCalculatingVIP6Matches || isLoadingGoalModel)
                .accessibilityIdentifier("input.replaceMatch.apply")
            Text("可替换前六场或第7场的场号；其它已选比赛及顺序保留。新场号不能与已选比赛重复。")
                .font(.caption).foregroundStyle(SequenceFilterTheme.textSecondary)
            if let replacementMatchMessage {
                Text(replacementMatchMessage).font(.caption)
                    .accessibilityIdentifier("input.replaceMatch.status")
            }
            if hasManualMatchSelection {
                Text("当前保留替换后的场次，不再自动改回连续选场。")
                    .font(.caption).foregroundStyle(SequenceFilterTheme.textSecondary)
                Button("恢复自动选场") {
                    manualMatchSelectionScope = ""
                    replacementMatchMessage = nil
                    if usesVIP6AutomaticMatchSelection { scheduleVIP6AutomaticMatchSelection() }
                    else { syncSequentialMatchInputs(); loadGoalModelRecommendations() }
                }.accessibilityIdentifier("input.replaceMatch.reset")
            }
        }
    }
    private func replaceSelectedMatchNumber() {
        let issue = beijingSingleIssueInput.trimmingCharacters(in: .whitespacesAndNewlines)
        guard issue.count == 5, issue.allSatisfy(\.isNumber) else {
            replacementMatchMessage = "请先按日期匹配成5位期号后替换场号。"
            return
        }
        let six = currentFilteredMatchNumbers + [effectiveFixedFullMatchInput]
        let selected = six + [singleMatchInput.trimmingCharacters(in: .whitespacesAndNewlines)]
        do {
            let updated = try MatchNumberReplacement.replacing(selected, from: replacementOldMatchInput, to: replacementNewMatchInput)
            vip6AutoSelectionTask?.cancel()
            vip6AutoSelectionTask = nil
            isCalculatingVIP6Matches = false
            manualMatchSelectionScope = manualMatchSelectionKey
            if match1Input != updated[0] { programmaticallySelectedFirstMatch = updated[0] }
            match1Input = updated[0]; match2Input = updated[1]; match3Input = updated[2]
            match4Input = updated[3]; match5Input = updated[4]; fixedFullMatchInput = updated[5]
            singleMatchInput = updated[6]
            logicInput = ""; abcdAttemptedKey = nil; automaticallyFetchedABCDKey = nil
            goalModelAnalyses = []; vip6SelectedMatchesWithResults = []; conditionHandicaps = [:]
            result = nil; currentTXTQueryMessage = nil; currentTXTQueryIsHit = nil
            errorMessage = nil
            replacementMatchMessage = "已替换，当前前六场：" + updated.prefix(6).joined(separator: "、") + "；第7场：" + updated[6] + "。正在重新获取ABCD和赔率，请重新生成TXT。"
            UserDefaults.standard.set(persistedInputValues, forKey: inputDefaultsStorageKey)
            Task { @MainActor in
                await fetchABCDForCurrentInput(debounce: false)
                guard hasManualMatchSelection, currentCalculationMatchNumbers == Array(updated.prefix(6)) else { return }
                replacementMatchMessage = currentABCDForGeneration != nil
                    ? "场号已替换，ABCD已更新；请重新生成TXT。"
                    : "场号已替换并保留；ABCD暂未取全，请检查期号和场号后重试获取。"
            }
        } catch {
            replacementMatchMessage = error.localizedDescription
        }
    }

