                           let odds=outcomeSPMatrix(for:config,analyses:goalModelAnalyses),
                           let range=SequenceFilterEngine.oddsAdaptiveSRange(logic:config.logic,customOdds:odds) {
                            Text("推荐六场S：\(range.lowerBound)–\(range.upperBound)").font(.headline)
                        } else { Text("请先获取当前六场ABCD和自定义赔率，数据齐全后显示推荐范围。") }
                        Text("依据六场自定义赔率倒数归一化后的判定值总波动，沿用赔率自适应规则推荐14–17、15–18或14–19。打开后替代手动S范围；关闭后恢复手动范围。估计模型不保证历史或未来命中率。")
                            .font(.caption)
                    }
                }
                Section("本期场次与ABCD") {
                    if !selectedConditionVersionID.hasPrefix("svip") {
                        Text("非SVIP：从首场起连续6场；第7场场次、单选结果和倍数均在上方手动输入。")
                            .font(.caption)
                    }
                    Text("参与过滤：\(currentCalculationMatchNumbers.joined(separator: "、"))")
                        .font(.system(.subheadline, design: .monospaced))
                    if isCalculatingVIP6Matches {
                        ProgressView("正在获取场次和ABCD…")
                    }
                    if let vip6AutoSelectionMessage, usesVIP6AutomaticMatchSelection {
                        Text(vip6AutoSelectionMessage)
                            .font(.caption)
                            .foregroundStyle(SequenceFilterTheme.textSecondary)
                    }
                    if let noFour = currentLowestOddsNoFourDescription {
                        Label(noFour, systemImage: "nosign")
                            .font(.subheadline.bold())
                            .foregroundStyle(SequenceFilterTheme.conditionsAccent)
                    }
                    if isVIPConditionEnabled,
                       usesSVIPPermutationVersion,
                       noFourPositionFilterEnabled {
                        svip4NoFourSelectionPicker
                    }
                    LabeledContent("A/B/C/D") {
                        TextField("请输入\(currentCalculationLogicCount)位", text: $logicInput)
                            .disabled(isLoadingGoalModel)
                            .multilineTextAlignment(.trailing)
                            .font(.system(.body, design: .monospaced))
                            .textInputAutocapitalization(.characters)
                            .autocorrectionDisabled()
                            .onChange(of: logicInput) { value in
                                guard !isLoadingGoalModel, normalizedCurrentABCD(value) != nil else { return }
                                abcdAttemptedKey = abcdInputKey
                            }
                    }
                    Picker("ABCD数据源", selection: $abcdSource) {
                        ForEach(ABCDDataSource.allCases, id: \.self) { source in
                            Text(source.rawValue).tag(source)
                        }
                    }
                    Button(isLoadingGoalModel ? "获取中…" : "重新获取当前ABCD") {
                        loadGoalModelRecommendations()
                    }
                    .disabled(isLoadingGoalModel || !hasValidMainNumbers)
                    if let goalModelErrorMessage {
                        Text(goalModelErrorMessage)
                            .font(.caption)
                            .foregroundStyle(.orange)
                    } else {
                        Text(abcdSourceMessage)
                            .font(.caption)
                            .foregroundStyle(SequenceFilterTheme.textSecondary)
                    }
                }


                if let errorMessage {
                    Section("输入错误") {
                        Text(errorMessage).foregroundStyle(SequenceFilterTheme.textSecondary)
                    }
                }

                Section("当前TXT查询与未过关原因") {
                    TextField("可选：输入前6场赛果，如310130", text: $currentTXTManualOutcomes)
                        .font(.system(.body, design: .monospaced))
                        .keyboardType(.numberPad)
                        .onChange(of: currentTXTManualOutcomes) { _ in
                            currentTXTQueryMessage = nil
                            currentTXTQueryIsHit = nil
                        }
                    if let message = currentTXTQueryMessage {
                        Text(message)
                            .font(.callout)
                            .foregroundStyle(SequenceFilterTheme.textPrimary)
                            .textSelection(.enabled)
                            .accessibilityIdentifier("input.queryTXT.status")
                    }
                    Text(currentTXTManualOutcomes.isEmpty
                        ? "留空时从比分网核对已结束的赛果；未结束不判中奖。"
                        : "填写后按模拟赛果核对当前TXT，不当作官方开奖结果。")
                        .font(.caption)
                        .foregroundStyle(SequenceFilterTheme.textSecondary)
                    inputFailureReasonsButton
                }

            }
            .scrollContentBackground(.hidden)
            .background(SequenceFilterTheme.inputAccent.opacity(0.045))
            .scrollDismissesKeyboard(.interactively)
            .navigationTitle("输入与生成")
            .toolbar(.hidden, for: .navigationBar)
        }
    }

