    private func previewTXTRevision(_ context: TXTEditingContext, part: TXTSharePart, previewID: UUID? = nil) {
        let record = context.record
        txtPreview = makeTXTPreview(title: "第\(record.issue)期-\(record.id.uuidString.prefix(8))-\(part.label)",
            content: queryTXTContent(record: record, part: part),
            observedOutcomes: record.isFinalResult ? record.observedOutcomes : nil,
            editingRecord: record, part: part, generationID: context.generationID,
            displayedMatchNumbers: context.displayedMatchNumbers, previewID: previewID)
    }

    @MainActor
    private func applyTXTOutcomeExclusion() async {
        guard !isApplyingTXTExclusion, let preview = txtPreview, let context = preview.editingContext else { return }
        let source = context.record
        let generated: FilterResult?
        if let generationID = context.generationID {
            guard let current = result, current.generationID == generationID else {
                txtExclusionError = "当前已重新生成其他TXT，请关闭预览后打开最新的总TXT。"
                return
            }
            generated = current
        } else { generated = nil }
        let number = txtExclusionMatchInput, outcome = txtExclusionOutcomeInput
        let multiplier = txtMultiplier(from: source.txtContent) ?? 1
        isApplyingTXTExclusion = true
        txtExclusionError = nil
        defer { isApplyingTXTExclusion = false }
        do {
            let edited = try await Task.detached(priority: .userInitiated) {
                let revision = try TXTBetEditor.excluding(bets: source.betOutcomes,
                    matchNumbers: source.matchNumbers, matchNumber: number, outcome: outcome)
                let export = try TXTBetExport(matchNumbers: source.matchNumbers,
                    displayedMatchNumbers: context.displayedMatchNumbers, bets: revision.bets, multiplier: multiplier)
                let updated = try generated?.excludingTXTOutcome(matchNumber: number, outcome: outcome)
                return (revision, export, updated)
            }.value
            guard txtPreview?.id == preview.id else { return }
            if let generationID = context.generationID, result?.generationID != generationID {
                throw NSError(domain: "TXTRevision", code: 1,
                    userInfo: [NSLocalizedDescriptionKey: "当前TXT已改变，请重新打开最新总TXT后操作。"])
            }
            var rules = source.manualTXTExclusions ?? []
            if !rules.contains(edited.0.rule) { rules.append(edited.0.rule) }
            let startLines = (source.txtContent ?? "").components(separatedBy: .newlines).filter {
                ($0.hasPrefix("第一场（") || $0.hasPrefix("第七场（")) && $0.contains("开始时间：")
            }
            let export = edited.1
            let texts = TXTBetExportPart.allCases.map { part in
                export.text(issue: source.issue, part: part, notes: rules.map(\.summary), startTimeLines: startLines)
            }
            let filename = "mustwin-\(source.issue)-\(source.matchNumbers.joined(separator: "-"))-剔除"
            // Write every file before committing the revision to UI/history.
            let urls = try zip(TXTBetExportPart.allCases, texts).map { part, text in
                try writeShareFile(filename: "\(filename)-\(part.label).txt", text: text)
            }
            let record = SharedTXTQueryRecord(id: UUID(), sharedAt: Date(), issue: source.issue,
                filename: "\(filename)-总量.txt", txtContent: texts[0], normalizedInput: source.normalizedInput,
                matchNumbers: source.matchNumbers, betOutcomes: export.bets, finalBetCount: export.bets.count,
                conditionSignature: nil, lastCheckedAt: nil, observedOutcomes: source.observedOutcomes,
                observedHandicaps: source.observedHandicaps, verificationMessage: nil,
                isFinalResult: source.isFinalResult,
                isHit: RecentTXTQueryArchive.hit(bets: export.bets, outcomes: source.observedOutcomes ?? [], isFinal: source.isFinalResult),
                prizeAmount: nil, prizeSPValues: source.prizeSPValues,
                generationCustomOdds: source.generationCustomOdds, manualTXTExclusions: rules,
                displayedMatchNumbers: context.displayedMatchNumbers)
            if let updated = edited.2 {
                result = updated
                currentTXTPrizeGenerationID = updated.generationID
                currentTXTQueryMessage = nil
                currentTXTQueryIsHit = nil
                estimatedHitProbability = nil
                hitProbabilityExplanation = nil
            }
            archiveRecentTXTRecord(record)
            txtExclusionMessage = "已剔除\(edited.0.removedCount)注：\(source.finalBetCount)→\(export.bets.count)注，\(export.amount(.total))元；E \(export.betCount(.e))注/\(export.amount(.e))元，F \(export.betCount(.f))注/\(export.amount(.f))元。"
            txtPreview = TXTPreview(id: preview.id, title: "第\(record.issue)期-剔除后-总TXT", content: texts[0],
                highlightedLineIndices: highlightedTXTLineIndices(content: texts[0], observedOutcomes: record.isFinalResult ? record.observedOutcomes : nil),
                shareURL: urls[0], editingContext: TXTEditingContext(record: record,
                    generationID: edited.2?.generationID, displayedMatchNumbers: context.displayedMatchNumbers), part: .total, sharingRecord: record)
            isShowingTXTExclusionEditor = false
        } catch { txtExclusionError = error.localizedDescription }
    }

