    private var finalOutcomeSelectionKey: String {
        beijingSingleIssueInput.trimmingCharacters(in: .whitespacesAndNewlines) + "|" + currentCalculationMatchNumbers.joined(separator: ",")
    }
    private var usesAutomaticFinalOutcomeRecommendation: Bool {
        FinalOutcomeCutRecommender.shouldApply(enabled: automaticFinalOutcomeExclusions,
            selectionKey: finalOutcomeSelectionKey, manualSelectionKey: finalOutcomeManualSelectionKey)
    }
    private var finalOutcomeLiveRecommendationOdds: [[Double]]? {
        let issue = beijingSingleIssueInput.trimmingCharacters(in: .whitespacesAndNewlines)
        guard currentCalculationMatchNumbers.count == 6 else { return nil }
        return HandicapOddsComparisonTableMatrix.rows(matchNumbers: currentCalculationMatchNumbers,
            matches: goalModelAnalyses.filter { $0.match.issue == issue }.map(\.match))
    }
    private var finalOutcomeRecommendationOdds: [[Double]]? {
        if let live = finalOutcomeLiveRecommendationOdds { return live }
        let issue = beijingSingleIssueInput.trimmingCharacters(in: .whitespacesAndNewlines)
        // Only frozen generation odds for this exact issue and ordered six fixtures.
        // Never read observed results or settlement SP to fill a recommendation.
        return recentTXTQueryHistory.filter {
            $0.issue == issue && Array($0.matchNumbers.prefix(6)) == currentCalculationMatchNumbers
                && $0.generationCustomOdds.map { FinalOutcomeCutRecommender.recommend(odds: $0) != nil } == true
        }.sorted { $0.sharedAt > $1.sharedAt }.first?.generationCustomOdds
    }
    private var finalOutcomeRecommendationRefreshKey: String {
        let oddsText = finalOutcomeRecommendationOdds?.flatMap { $0 }.map { String($0) }.joined(separator: ",") ?? "missing"
        return [selectedConditionVersionID, finalOutcomeSelectionKey, String(hasLoadedInputDefaults), String(automaticFinalOutcomeExclusions), oddsText].joined(separator: "|")
    }
    private func refreshFinalOutcomeRecommendation() {
        guard hasLoadedInputDefaults, selectedConditionVersionID == "svip10-frozen-160" else { return }
        guard automaticFinalOutcomeExclusions else {
            finalOutcomeRecommendationMessage = "自动推荐已关闭；使用手动场次和彩果。"
            return
        }
        guard usesAutomaticFinalOutcomeRecommendation else {
            finalOutcomeRecommendationMessage = "本组选场已手动修改，刷新赔率不会覆盖；换选场后恢复自动推荐。"
            return
        }
        guard let odds = finalOutcomeRecommendationOdds,
              let recommendation = FinalOutcomeCutRecommender.recommend(odds: odds) else {
            finalOutcomeRecommendationMessage = "等待当前六场完整赛前赔率；未齐时不会把旧值当作本次自动推荐。"
            return
        }
        finalOutcomeExclusion1Position = recommendation.rules[0].position
        finalOutcomeExclusion1Outcome = recommendation.rules[0].outcome
        finalOutcomeExclusion2Position = recommendation.rules[1].position
        finalOutcomeExclusion2Outcome = recommendation.rules[1].outcome
        let sourceText = finalOutcomeLiveRecommendationOdds == nil ? "参考本组上次生成保存的赔率；生成时会用当前赛前赔率重算。" : ""
        finalOutcomeRecommendationMessage = sourceText + recommendation.rules.enumerated().map { i, rule in
            "剔除\(rule.slot)：第\(rule.position)场（\(currentCalculationMatchNumbers[rule.position - 1])）彩果\(rule.outcome)，赛前估算\(String(format: "%.1f", recommendation.removedProbabilities[i] * 100))%"
        }.joined(separator: "；") + "。可手动改；两组开关自行控制，估算不代表中奖率或180注保证。"
    }
    private func markFinalOutcomeRecommendationManual() {
        finalOutcomeManualSelectionKey = finalOutcomeSelectionKey
        finalOutcomeRecommendationMessage = "本组选场已手动修改，刷新赔率不会覆盖；换选场后恢复自动推荐。"
    }

    private var finalResultFilterInputValues: [String: String] {
        var values = ["finalResultInverted": finalResultInverted ? "1" : "0",
         "finalOutcomeExclusion1Enabled": finalOutcomeExclusion1Enabled ? "1" : "0",
         "finalOutcomeExclusion1Position": String(finalOutcomeExclusion1Position),
         "finalOutcomeExclusion1Outcome": String(finalOutcomeExclusion1Outcome),
         "finalOutcomeExclusion2Enabled": finalOutcomeExclusion2Enabled ? "1" : "0",
         "finalOutcomeExclusion2Position": String(finalOutcomeExclusion2Position),
         "finalOutcomeExclusion2Outcome": String(finalOutcomeExclusion2Outcome)]
        values["automaticFinalOutcomeExclusionsEnabled"] = automaticFinalOutcomeExclusions ? "1" : "0"
        values["finalOutcomeManualSelectionKey"] = finalOutcomeManualSelectionKey
        values["automaticFinalOutcomeExclusions"] = usesAutomaticFinalOutcomeRecommendation ? "1" : "0"
        for n in [50, 100, 150, 200] { values["historyWindow\(n)Enabled"] = historicalOutcomeWindows.contains(n) ? "1" : "0" }
        values["historyWindowBeforeIssue"] = beijingSingleIssueInput.trimmingCharacters(in: .whitespacesAndNewlines)
        return values
    }

    private var hasFinalResultFilters: Bool {
        finalResultInverted || finalOutcomeExclusion1Enabled || finalOutcomeExclusion2Enabled || !historicalOutcomeWindows.isEmpty
    }

    private var finalResultFiltersSection: some View {
        Section("反选与独立剔除") {
            Toggle("反（729注减去原条件结果）", isOn: $finalResultInverted)
                .accessibilityIdentifier("conditions.resultInvert")
            Text("先按其它已开条件生成，再用六场全部729注减去该结果。第7场和投注倍数沿用当前设置。")
                .font(.caption).foregroundStyle(SequenceFilterTheme.textSecondary)
            Toggle("换选场自动推荐两组剔除", isOn: $automaticFinalOutcomeExclusions)
                .accessibilityIdentifier("conditions.resultCut.auto")
            Text(finalOutcomeRecommendationMessage)
                .font(.caption).foregroundStyle(SequenceFilterTheme.textSecondary)
            Button("重新推荐并填入") {
                automaticFinalOutcomeExclusions = true
                finalOutcomeManualSelectionKey = ""
                refreshFinalOutcomeRecommendation()
            }.accessibilityIdentifier("conditions.resultCut.recommend")
            independentOutcomeExclusionControls(slot: 1, enabled: $finalOutcomeExclusion1Enabled,
                position: $finalOutcomeExclusion1Position, outcome: $finalOutcomeExclusion1Outcome)
            independentOutcomeExclusionControls(slot: 2, enabled: $finalOutcomeExclusion2Enabled,
                position: $finalOutcomeExclusion2Position, outcome: $finalOutcomeExclusion2Outcome)
            ForEach([50, 100, 150, 200], id: \.self) { n in
                Toggle("最近\(n)组彩果去重", isOn: Binding(
                    get: { historicalOutcomeWindows.contains(n) },
                    set: { if $0 { historicalOutcomeWindows.insert(n) } else { historicalOutcomeWindows.remove(n) } }))
                    .accessibilityIdentifier("conditions.historyWindow\(n)")
            }
            Text("按六场彩果3/1/0的顺序，剔除已在历史窗口出现的组合。只使用已归档且早于输入期号的完整期次；同期开赛结果不用。多个开关取并集，只扣一次。最后归档期：\(HistoricalOutcomeWindows.rows.last?.issue ?? "无")。")
                .font(.caption).foregroundStyle(SequenceFilterTheme.textSecondary)
            Text("独立剔除和历史去重在原条件及反选之后执行，不受原有条件总开关、容错或补回影响。按当前选场顺序选择第1–6场，去掉指定彩果的整注；关闭开关保留选择。")
                .font(.caption).foregroundStyle(SequenceFilterTheme.textSecondary)
        }
    }

    private func independentOutcomeExclusionControls(
        slot: Int, enabled: Binding<Bool>, position: Binding<Int>, outcome: Binding<Int>
    ) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            Toggle("独立剔除\(slot)", isOn: enabled)
                .accessibilityIdentifier("conditions.resultCut\(slot).enabled")
            Picker("剔除\(slot)场次", selection: Binding(get: { position.wrappedValue }, set: {
                position.wrappedValue = $0
                markFinalOutcomeRecommendationManual()
            })) {
                ForEach(1...6, id: \.self) { number in Text("第\(number)场").tag(number) }
            }
            .frame(minHeight: 44)
            .disabled(!enabled.wrappedValue)
            .accessibilityIdentifier("conditions.resultCut\(slot).position")
            Picker("剔除\(slot)彩果", selection: Binding(get: { outcome.wrappedValue }, set: {
                outcome.wrappedValue = $0
                markFinalOutcomeRecommendationManual()
            })) {
                Text("3（胜）").tag(3)
                Text("1（平）").tag(1)
                Text("0（负）").tag(0)
            }
            .frame(minHeight: 44)
            .disabled(!enabled.wrappedValue)
            .accessibilityIdentifier("conditions.resultCut\(slot).outcome")
        }
        .padding(.vertical, 4)
    }

    @ViewBuilder private var currentConditionRateView: some View {
