                        ForEach([true, false], id: \.self) { enabled in
                            let group = rows.filter { $0.enabled.wrappedValue == enabled }
                            Text("\(enabled ? "已开启" : "已关闭")（\(group.count)项）")
                                .font(.subheadline.bold()).padding(.top, 8)
                            ForEach(group) { row in conditionSettingRowView(row) }
