                    }
                    .accessibilityIdentifier("svvvPackageDetails")
                }
                Section("单项93%以上 · 40条条件") {
                    Toggle("40条条件总开关", isOn: $svvvHighPass40Enabled)
                        .accessibilityIdentifier("svvvHighPass40Switch")
                        .onChange(of: svvvHighPass40Enabled) { _ in
                            result = nil
                            currentTXTQueryMessage = nil
                            currentTXTQueryIsHit = nil
                            scheduleInputDefaultsSave()
                        }
                    Text("共40条，已开\(highPassEnabledCount)条；独立控制，不受原有条件总开关影响。单项历史率不等于全部共同过关率。")
                        .font(.caption).foregroundStyle(SequenceFilterTheme.textSecondary)
                    DisclosureGroup("40条明细（已开\(highPassEnabledCount)条）", isExpanded: $svvvHighPass40DetailsExpanded) {
                        ForEach(highPassRows) { row in conditionSettingRowView(row) }
                    }
                    .accessibilityIdentifier("svvvHighPass40Details")
                }
                Section("第三组 · 单项98%以上条件") {
                    Toggle("第三组条件总开关", isOn: $svvvHighPass100Enabled)
                        .accessibilityIdentifier("svvvHighPass100Switch")
                        .onChange(of: svvvHighPass100Enabled) { _ in
                            result = nil
                            currentTXTQueryMessage = nil
                            currentTXTQueryIsHit = nil
                            scheduleInputDefaultsSave()
                        }
                    Text("共\(hundredRows.count)条，已开\(hundredEnabledCount)条；已移除相对位置条件。单项98%是两年历史参考，不是共同过关率。")
                        .font(.caption).foregroundStyle(SequenceFilterTheme.textSecondary)
