    private var svip10ConditionRows: [ConditionSettingRow] {
        let fields = conditionEditorFields
        func editor(_ field: ConditionEditorField) -> ConditionSettingRow {
            let placeholder: String
            switch field.id {
            case "sum": placeholder = "15-20"
            case "displacement": placeholder = "3-7"
            case "roughness": placeholder = "0-15"
            case "valueTwo": placeholder = "4"
            case "valueThree": placeholder = "5"
            case "score": placeholder = "5.8-6.8"
            default: placeholder = "0-\(Int(field.maximum))"
            }
            let metric = field.id.hasPrefix("OC_") ? OutcomeCondition(rawValue: String(field.id.dropFirst(3))) : nil
            return ConditionSettingRow(id: field.id, title: field.title, enabled: field.enabled,
                value: field.value, placeholder: placeholder,
                keyboard: field.format == .integerMaximum ? .numberPad : .numbersAndPunctuation,
                help: metric.map { condition in
                    [condition.help, condition.highPassHistoricalReference(rangeText: field.value.wrappedValue)]
                        .compactMap { $0 }.joined(separator: "\n")
                })
        }
        var rows = fields.filter { !$0.id.hasPrefix("OC_") }.map(editor)
        rows += [
            ConditionSettingRow(id: "extra.0", title: "六场自定义赔率第三选个数", enabled: $svip10ColdCountEnabled,
                value: $svip10ColdCountRangeInput, placeholder: "0-2",
                help: "每场赔率从低到高的第三项称为第三选；并列按胜、平、负排序。"),
            ConditionSettingRow(id: "extra.2", title: "前5场胜负直接切换0–2次", enabled: $svip10WinLossSwitchEnabled,
                help: "只统计前5场相邻的3→0或0→3；经过平局不计，第6场和第7场不参与。"),
            ConditionSettingRow(id: "extra.4", title: "前5场实际顺序M", enabled: $svip10FiveMatchMEnabled,
                value: $svip10FiveMatchMRangeInput, placeholder: "2-6",
                help: "前5场按ABCD映射为2、3、4，M为相邻值绝对差之和，含范围边界。"),
            ConditionSettingRow(id: "extra.5", title: "前5场同彩果最长连续≤2场", enabled: $svip10FrontFiveSameOutcomeRunMaximum2Enabled,
                help: "逐注检查前5场的3、1、0；任意同一彩果连续3场或以上时淘汰。"),
            ConditionSettingRow(id: "extra.6", title: "前5场隔场回返0–2次", enabled: $svip10FrontFiveReturnMaximum2Enabled,
                help: "回返指A-B-A；前5场出现3次时淘汰。"),
            ConditionSettingRow(id: "extra.7", title: "前5场不出现连续平局", enabled: $svip10FrontFiveNoConsecutiveDrawEnabled,
                help: "只检查前5场原始彩果；出现相邻的1、1即淘汰。"),
            ConditionSettingRow(id: "extra.8", title: "前5场判定值3最多2个", enabled: $svip10FrontFiveValueThreeMaximum2Enabled,
                help: "逐注按当期ABCD映射，前5场判定值3出现3个或以上时淘汰。"),
            ConditionSettingRow(id: "extra.15", title: "六场自定义赔率第一选1–4个", enabled: $svip10SixMatchFavoriteCount1To4Enabled,
                help: "每场自定义赔率最低项为第一选；每注六场必须有1–4个第一选。"),
            ConditionSettingRow(id: "extra.10", title: "前六场自定义赔率乘积下限", enabled: $svip10SixMatchMinimumOddsProductEnabled,
                value: $svip10SixMatchMinimumOddsProductInput, placeholder: "380", keyboard: .decimalPad,
                help: "前六场所选项目自定义赔率直接连乘，低于下限的组合淘汰。"),
            ConditionSettingRow(id: "extra.12", title: "六场彩果断点数 B", enabled: $svip10SixMatchBreakpoint3To5Enabled,
                value: $svip10SixMatchBreakpointRangeInput, placeholder: "2-5",
                help: "相邻两场彩果不同计1个断点，前六场共有5处相邻位置。保留范围内的断点数，含边界；第7场不参与。"),
            ConditionSettingRow(id: "recovery100", title: "联合概率优先补回最多100注", enabled: $svip10TopThreeProbabilityRecovery100Enabled,
                help: "保留原过关注；仅对因前5场M或六场第一选个数被删、其余条件全部通过的组合，按联合概率补回最多100注。"),
            ConditionSettingRow(id: "overallOddsGate", title: "整体赔率低于500不生成", enabled: $overallOddsForecastGateEnabled,
                help: "按最终投注的六场自定义赔率乘积中位数判断；低于500只给调整建议。"),
            ConditionSettingRow(id: "lineBudget50", title: "市场统计优选，最多50行", enabled: Binding(
                get: { svip10StatisticalLineBudgetEnabled }, set: { enabled in
                    svip10StatisticalLineBudgetEnabled = enabled
                    if enabled { svip10ProbabilityMass60Enabled = false }
                }), help: "保留为可选开关。历史回测过关率下降较多，按需要开启；与60行优选互斥。"),
            ConditionSettingRow(id: "probabilityMass60", title: "概率质量优先，最多60行", enabled: Binding(
                get: { svip10ProbabilityMass60Enabled }, set: { enabled in
                    svip10ProbabilityMass60Enabled = enabled
                    if enabled { svip10StatisticalLineBudgetEnabled = false }
                }), help: "按完整合并行的联合概率总量排序，不拆行、不补注；与50行优选互斥。")
        ]
        rows += fields.filter { $0.id.hasPrefix("OC_") }.map(editor)
        return rows
    }

    private func conditionSettingRowView(_ row: ConditionSettingRow) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            Toggle(row.title, isOn: Binding(get: { row.enabled.wrappedValue }, set: { enabled in
                row.enabled.wrappedValue = enabled
                result = nil
                currentTXTQueryMessage = nil
                currentTXTQueryIsHit = nil
            }))
            .accessibilityIdentifier("conditionSwitch_" + row.id)
            if let value = row.value {
                rawConditionField(row.title, row.placeholder, text: value, keyboard: row.keyboard)
                    .disabled(!row.enabled.wrappedValue)
            }
            if let help = row.help {
                Text(help).font(.caption).foregroundStyle(SequenceFilterTheme.textSecondary)
            }
        }
    }

