    private func basicConditionBinding(_ rule: BasicCondition) -> Binding<Bool> {
        Binding(get: { !disabledBasicConditions.contains(rule) }, set: { enabled in
            if enabled { disabledBasicConditions.remove(rule) }
            else { disabledBasicConditions.insert(rule) }
            result = nil
        })
    }

    private var conditionEditorFields: [ConditionEditorField] {
        let isSVIP11 = selectedConditionVersionID == "svip11-breakpoint-selection"
        let isSVIP10 = selectedConditionVersionID == "svip10-frozen-160"
        let usesRelationship = !isSVIP11 && (isSVIP10
            || (selectedConditionVersionID == "svip5-current-snapshot" && six250RelationshipEnabled))
        let count = usesVIP6AutomaticMatchSelection ? 6 : 5
        var fields: [ConditionEditorField] = []
        func basic(_ rule: BasicCondition, _ title: String, _ aliases: [String], _ value: Binding<String>,
                   _ format: ConditionEditorField.Format, _ maximum: Double) {
            fields.append(ConditionEditorField(id: rule.rawValue, title: title, aliases: aliases,
                value: value, enabled: basicConditionBinding(rule), format: format, maximum: maximum))
        }
        if selectedConditionVersionID != "svip7-odds-rank-280" {
            basic(.sum, "判定值和值 S", ["和值", "判定和值", "判定总和", "总和值", "总和", "和值S", "S和值", "S"],
                  isSVIP10 || isSVIP11 ? $svip10SumRangeInput : (usesRelationship ? $six250SumRangeInput : $sumInput), .integerRange, Double(count * 4))
            basic(.displacement, "位移 M", ["位移", "实际M", "顺序M", "六场M", "M"],
                  isSVIP10 || isSVIP11 ? $svip10MRangeInput : (usesRelationship ? $six250MRangeInput : $displacementInput), .integerRange, 100)
            if isSVIP11 {
                basic(.breakpoints, "前5场彩果断点", ["断点", "彩果断点", "B"], $svip11BreakpointRangeInput, .integerRange, 4)
            } else if usesRelationship {
                basic(.roughness, "六场 R 范围", ["二阶波动", "波动", "R"], isSVIP10 ? $svip10RRangeInput : $six250RRangeInput, .integerRange, 16)
                if isSVIP10 {
                    basic(.valueTwo, "判定值2最多", ["判定值2最多", "判定值2", "值2最多"], $svip10ValueTwoMaximumInput, .integerMaximum, 6)
                }
                basic(.valueThree, "判定值3最多", ["判定值3最多", "判定值3", "值3最多"], $valueThreeMaximumInput, .integerMaximum, 6)
                basic(.score, "自定义综合评分", ["自定义综合评分", "综合评分", "综合分", "评分", "分数"],
                      isSVIP10 ? $svip10ScoreRangeInput : $six250ScoreUpperInput,
                      isSVIP10 ? .decimalRange : .decimalMaximum, 100)
            } else {
                basic(.variance, "稳定性方差上限", ["稳定性", "方差", "σ²"], $varianceInput, .decimalMaximum, 100)
                basic(.valueTwo, "判定值2最多", ["判定值2最多", "判定值2", "值2最多"], $valueTwoMaximumInput, .integerMaximum, Double(count))
                basic(.transition, "转移率下限（%）", ["转移率", "P_tr"], $transitionMinimumInput, .decimalMinimum, 100)
                basic(.roughness, "二阶波动 R 上限", ["二阶波动", "波动", "R"], $roughnessMaximumInput, .integerMaximum, 100)
                basic(.breakpoints, "彩果断点 B", ["断点", "彩果断点", "B"], $breakpointInput, .integerRange, Double(count - 1))
            }
        }
        for condition in OutcomeCondition.editorCases {
            let aliases: [String]
            switch condition {
            case .draws: aliases = ["平局", "平局个数", "平局数", "平局场数", "平的场数", "平的总场数", "平局数量"]
            case .losses: aliases = ["负场", "负个数", "负的总场数", "负场数", "输球场数", "输的场数"]
            case .winRun: aliases = ["连胜", "最长连续胜", "最长连胜", "连续胜", "连赢"]
            case .drawRun: aliases = ["连平", "最长连续平", "最长连平", "连续平局"]
            case .lossRun: aliases = ["连负", "最长连续负", "最长连负", "连续负", "连输"]
            case .diversity: aliases = ["彩果种类", "彩果种类数"]
            case .outcomeSum: aliases = ["彩果和值", "原始彩果和值", "原始和值", "彩果总和", "310和值"]
            case .returns: aliases = ["隔场回返", "隔场回返次数", "回返次数", "回返"]
            case .winLossSwitches: aliases = ["胜负切换", "胜负直接切换次数"]
            case .adjacentDrawPairs: aliases = ["连续平局相邻对数", "相邻平局对数", "连平对数", "平局对数"]
            case .nonDrawRun: aliases = ["最长连续不平", "连续不平最长", "不平连续长度"]
            case .winDrawSwitches: aliases = ["胜平切换", "胜平直接切换次数"]
            case .drawLossSwitches: aliases = ["平负切换", "平负直接切换次数"]
            case .drawSegments: aliases = ["平局段数", "平局段", "连平段数"]
            case .adjacentWinPairs: aliases = ["连续胜相邻对数", "连胜对数", "相邻胜对数"]
            case .adjacentLossPairs: aliases = ["连续负相邻对数", "连负对数", "相邻负对数"]
            case .differentTriples: aliases = ["连续三场彩果全异次数", "三场全异次数", "三场全异"]
            case .isolatedWins: aliases = ["孤立胜场数", "孤立胜", "单独胜场数"]
            case .lossSegments: aliases = ["负局段数", "连负段数", "负局段"]
            case .wins: aliases = []
            default: aliases = [condition.title]
            }
            if isSVIP10 && condition == .draws {
                fields.append(ConditionEditorField(id: "OC_DRAWS", title: "六场平局个数", aliases: aliases,
                    value: $svip10DrawCountRangeInput, enabled: $svip10DrawCountEnabled,
                    format: .integerRange, maximum: 6))
            } else {
                fields.append(ConditionEditorField(id: "OC_" + condition.rawValue, title: condition.title, aliases: aliases,
                    value: Binding(get: { outcomeConditionInputs[condition] ?? defaultOutcomeConditionRange(condition) },
                                   set: { outcomeConditionInputs[condition] = $0 }),
                    enabled: Binding(get: { outcomeConditionEnabled[condition] == true }, set: { enabled in
                        outcomeConditionEnabled[condition] = enabled
                        if enabled && (outcomeConditionInputs[condition] ?? "").isEmpty {
                            outcomeConditionInputs[condition] = defaultOutcomeConditionRange(condition)
                        }
                    }), format: .integerRange, maximum: Double(condition.maximum(matchCount: isSVIP11 ? 5 : count))))
            }
        }
        return fields
    }

    private var conditionInputFields: [ConditionEditorField] {
        var fields = conditionEditorFields
        if selectedConditionVersionID == "svip10-frozen-160" {
            fields += [
                ConditionEditorField(id: "extra.0", title: "六场自定义赔率第三选个数",
                    aliases: ["第三选", "第三选个数", "六场第三选", "冷门个数", "冷门数量"],
                    value: $svip10ColdCountRangeInput, enabled: $svip10ColdCountEnabled, format: .integerRange, maximum: 6),
                ConditionEditorField(id: "extra.4", title: "前5场实际顺序M",
                    aliases: ["前5场M", "前5场实际M", "前5场位移", "前5场实际顺序M"],
                    value: $svip10FiveMatchMRangeInput, enabled: $svip10FiveMatchMEnabled, format: .integerRange, maximum: 8),
                ConditionEditorField(id: "extra.10", title: "前六场自定义赔率乘积下限",
                    aliases: ["赔率乘积", "赔率积", "六场赔率乘积", "六场自定义赔率乘积", "赔率乘积下限"],
                    value: $svip10SixMatchMinimumOddsProductInput, enabled: $svip10SixMatchMinimumOddsProductEnabled,
                    format: .decimalMinimum, maximum: 1_000_000_000),
                ConditionEditorField(id: "extra.12", title: "六场彩果断点数 B",
                    aliases: ["断点数", "断点", "彩果断点", "六场断点数", "六场断点", "六场彩果断点", "B"],
                    value: $svip10SixMatchBreakpointRangeInput, enabled: $svip10SixMatchBreakpoint3To5Enabled,
                    format: .integerRange, maximum: 5)
            ]
        }
        return fields
    }

    private var conditionInputRules: [ConditionTextRule] {
        let fields = conditionInputFields
        var rules = fields.map { ConditionTextRule(id: $0.id, title: $0.title, aliases: $0.aliases,
            format: $0.format, maximum: $0.maximum) }
        guard selectedConditionVersionID == "svip10-frozen-160" else { return rules }
        let aliases: [String: [String]] = [
            "extra.13": ["第一双选", "第一个双选", "第一处双选", "双选一", "第一双选保留前两项", "第一个双选保留前两项"],
            "extra.14": ["第二双选", "第二个双选", "第二处双选", "双选二", "第二个双选去掉最低概率项"],
            "automaticDoublePair": ["连续六场自动双选", "六场自动双选", "自动双选", "双选组合自动选择"],
            "doubleCalibration": ["概率校正", "双选校正", "校正双选"],
            "extra.2": ["前5场胜负切换", "前5场胜负直接切换"],
            "extra.5": ["前5场同彩果最长连续", "前5场同彩果连续", "前5场最长同彩果连续"],
            "extra.6": ["前5场回返", "前5场隔场回返"],
            "extra.7": ["前5场不连续平局", "前5场不要连平", "前5场禁止连平", "前5场连续平局过滤"],
            "extra.8": ["前5场判定值3", "前5场判定值3最多", "前5场值3最多"],
            "extra.15": ["第一选", "六场第一选", "首选个数", "六场首选个数"],
            "extra.12": ["断点", "彩果断点", "六场断点", "六场彩果断点", "B"],
            "recovery100": ["补回", "补注", "概率补回", "联合概率补回", "补回100注"],
            "overallOddsGate": ["整体赔率门槛", "整体赔率门禁", "低赔率门禁"],
            "lineBudget50": ["50行", "50行优选", "最多50行", "市场统计优选"],
            "probabilityMass60": ["60行", "60行优选", "最多60行", "概率质量优先"]
        ]
        let fixedRanges = ["extra.2": "0-2", "extra.15": "1-4"]
        let fixedMaximums = ["extra.5": "2", "extra.6": "2", "extra.8": "2", "recovery100": "100"]
        for row in svip10ConditionRows where !fields.contains(where: { $0.id == row.id }) {
            let factor = row.id.hasPrefix("doubleFactor.") ? DoubleJudgmentFactor(rawValue: String(row.id.dropFirst(13))) : nil
            var rule = ConditionTextRule(id: row.id, title: row.title, aliases: aliases[row.id] ?? factor?.aliases ?? [])
            if let fixed = fixedRanges[row.id] { rule.format = .integerRange; rule.maximum = 6; rule.fixedValue = fixed }
            if let fixed = fixedMaximums[row.id] { rule.format = .integerMaximum; rule.maximum = 100; rule.fixedValue = fixed }
            if ["lineBudget50", "probabilityMass60"].contains(row.id) { rule.exclusionGroup = "svip10LineBudget" }
            rules.append(rule)
        }
        return rules
    }

    private var conditionInputPreview: (commands: [ConditionTextCommand], error: String?) {
        guard !conditionTextInput.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return ([], nil) }
        do { return (try ConditionTextParser.interpret(conditionTextInput, rules: conditionInputRules), nil) }
        catch { return ([], error.localizedDescription) }
    }

    private func interpretedConditionLabel(_ command: ConditionTextCommand) -> String {
        guard let rule = conditionInputRules.first(where: { $0.id == command.id }) else { return command.id }
        let state = command.enabled ? "开启" : "关闭"
        guard let value = command.value else { return state + "“" + rule.title + "”" }
        let prefix: String
        switch rule.format {
        case .integerMinimum?, .decimalMinimum?: prefix = "≥"
        case .integerMaximum?, .decimalMaximum?: prefix = "≤"
        default: prefix = ""
        }
        return "\(state)“\(rule.title)”：\(prefix)\(value.replacingOccurrences(of: "-", with: "–"))"
    }

    private var conditionTextInputSection: some View {
        let preview = conditionInputPreview
        return Section("输入条件") {
            NavigationLink {
                ConditionEffectAnalysisPage(input: generatedInput,
                    existingEditorIDs: Set(enteredConditionIDs).union(enteredConditionIDs.contains("extra.1") ? ["OC_DRAWS"] : []),
                    onAdd: addAnalyzedConditions)
            } label: {
                Label("条件效果分析", systemImage: "chart.bar.xaxis")
            }
            .accessibilityIdentifier("conditionEffectAnalysisLink")
            TextField("例如：和值十五到二十，平局最多两场，关闭第二双选", text: $conditionTextInput, axis: .vertical)
                .lineLimit(2...4)
                .textInputAutocapitalization(.never)
                .autocorrectionDisabled()
                .accessibilityIdentifier("conditionTextInput")
            if !preview.commands.isEmpty {
                VStack(alignment: .leading, spacing: 5) {
                    Text("我理解为：").fontWeight(.semibold)
                    ForEach(preview.commands, id: \.id) { command in Text(interpretedConditionLabel(command)) }
                }.font(.caption).accessibilityIdentifier("conditionInterpretationPreview")
            }
            if let error = preview.error {
                Text("待明确：" + error).font(.caption).foregroundStyle(.orange)
                    .accessibilityIdentifier("conditionInterpretationError")
            }
            Button("应用到条件列表", action: applyConditionTextInput)
                .disabled(preview.commands.isEmpty)
                .accessibilityIdentifier("applyConditionTextInput")
            Text("支持中文数字、日常说法和多项条件；先核对识别结果，再点应用。范围含糊时会提示补充，修改后请重新生成。")
                .font(.caption).foregroundStyle(SequenceFilterTheme.textSecondary)
            if let conditionTextMessage {
                Text(conditionTextMessage).font(.caption).accessibilityIdentifier("conditionTextMessage")
            }
            DisclosureGroup("支持输入的条件") {
                Text(conditionInputRules.map { $0.aliases.first ?? $0.title }.joined(separator: "、"))
                    .font(.caption).foregroundStyle(SequenceFilterTheme.textSecondary)
            }
        }
    }

    @ViewBuilder
    private var enteredConditionsSection: some View {
        let fields = conditionEditorFields.filter { enteredConditionIDs.contains($0.id) }
        let additions = analyzedConditionSwitches.filter { enteredConditionIDs.contains($0.id) }
        if !fields.isEmpty || !additions.isEmpty {
            Section("已输入条件 · 逐项开关") {
                ForEach([true, false], id: \.self) { enabled in
                    ForEach(fields.filter { $0.enabled.wrappedValue == enabled }) { field in
                        VStack(alignment: .leading, spacing: 8) {
                            Toggle(field.title, isOn: field.enabled)
                                .accessibilityIdentifier("conditionSwitch_" + field.id)
                            TextField("输入数值或范围", text: field.value)
                                .keyboardType(.numbersAndPunctuation)
                                .font(.system(.subheadline, design: .monospaced))
                                .disabled(!field.enabled.wrappedValue)
                        }
                    }
                    ForEach(additions.filter { $0.enabled.wrappedValue == enabled }) { field in
                        Toggle(field.title, isOn: field.enabled)
                            .accessibilityIdentifier("conditionSwitch_" + field.id)
                    }
                }
            }
        }
    }

    private var analyzedConditionSwitches: [AnalyzedConditionSwitch] {
        guard selectedConditionVersionID == "svip10-frozen-160" else { return [] }
        return [
            AnalyzedConditionSwitch(id: "extra.0", title: "第三选\(svip10ColdCountRangeInput)个", enabled: $svip10ColdCountEnabled),
            AnalyzedConditionSwitch(id: "extra.1", title: "平局\(svip10DrawCountRangeInput)个", enabled: $svip10DrawCountEnabled),
            AnalyzedConditionSwitch(id: "extra.2", title: "前5场胜负切换0–2次", enabled: $svip10WinLossSwitchEnabled),
            AnalyzedConditionSwitch(id: "extra.4", title: "前5场实际M \(svip10FiveMatchMRangeInput)", enabled: $svip10FiveMatchMEnabled),
            AnalyzedConditionSwitch(id: "extra.5", title: "前5场同彩果连续≤2", enabled: $svip10FrontFiveSameOutcomeRunMaximum2Enabled),
            AnalyzedConditionSwitch(id: "extra.6", title: "前5场隔场回返≤2", enabled: $svip10FrontFiveReturnMaximum2Enabled),
            AnalyzedConditionSwitch(id: "extra.7", title: "前5场不连续平局", enabled: $svip10FrontFiveNoConsecutiveDrawEnabled),
            AnalyzedConditionSwitch(id: "extra.8", title: "前5场判定值3≤2个", enabled: $svip10FrontFiveValueThreeMaximum2Enabled),
            AnalyzedConditionSwitch(id: "extra.15", title: "六场第一选1–4个", enabled: $svip10SixMatchFavoriteCount1To4Enabled),
            AnalyzedConditionSwitch(id: "extra.10", title: "六场自定义赔率乘积≥\(svip10SixMatchMinimumOddsProductInput)", enabled: $svip10SixMatchMinimumOddsProductEnabled),
            AnalyzedConditionSwitch(id: "extra.12", title: "六场彩果断点B=\(svip10SixMatchBreakpointRangeInput)", enabled: $svip10SixMatchBreakpoint3To5Enabled),
        ]
    }

    private func addAnalyzedConditions(_ selectedIDs: Set<String>, suggestion: ConditionEffectSuggestion?) {
        guard selectedConditionVersionID == "svip10-frozen-160" else { return }
        var ids = selectedIDs
        if let suggestion {
            guard let field = conditionEditorFields.first(where: { $0.id == suggestion.editorID }),
                  let value = try? field.validated("\(suggestion.range.lowerBound)-\(suggestion.range.upperBound)") else {
                conditionTextMessage = "新增条件范围无效，请重新计算。"
                return
            }
            field.value.wrappedValue = value
            ids.insert("outcome." + suggestion.condition.rawValue)
        }
        let coreIDs = ["core.0": "sum", "core.1": "displacement", "core.2": "roughness",
                       "core.3": "valueThree", "core.4": "score", "core.6": "valueTwo"]
        var added = 0
        for id in ids.sorted() {
            let editorID = coreIDs[id] ?? (id.hasPrefix("outcome.") ? "OC_" + String(id.dropFirst(8)) : id)
            if let field = conditionEditorFields.first(where: { $0.id == editorID }) {
                field.enabled.wrappedValue = true
                if !enteredConditionIDs.contains(editorID) { enteredConditionIDs.append(editorID) }
                added += 1
            } else if let field = analyzedConditionSwitches.first(where: { $0.id == id }) {
                field.enabled.wrappedValue = true
                if !enteredConditionIDs.contains(id) { enteredConditionIDs.append(id) }
                added += 1
            }
        }
        result = nil
        currentTXTQueryMessage = nil
        currentTXTQueryIsHit = nil
        conditionTextMessage = "已添加并开启\(added)项条件；原有条件保持。请重新生成以应用更改。"
        DispatchQueue.main.async {
            UserDefaults.standard.set(persistedInputValues, forKey: inputDefaultsStorageKey)
            UserDefaults.standard.synchronize()
            scheduleDurableBackup()
        }
    }

    private func applyConditionTextInput() {
        let fields = conditionInputFields
        let switches = selectedConditionVersionID == "svip10-frozen-160" ? svip10ConditionRows : []
        do {
            let commands = try ConditionTextParser.interpret(conditionTextInput, rules: conditionInputRules)
            // Resolve and validate the complete batch before touching live settings.
            let updates = try commands.map { command -> (ConditionTextCommand, Binding<String>?, Binding<Bool>) in
                if let field = fields.first(where: { $0.id == command.id }) {
                    return (command, field.value, field.enabled)
                }
                if let row = switches.first(where: { $0.id == command.id }), command.value == nil {
                    return (command, nil, row.enabled)
                }
                throw FilterConfigError.invalidRange("无法应用该条件，请重新输入")
            }
            let labels = commands.map(interpretedConditionLabel)
            for (command, value, enabled) in updates {
                if command.id == BasicCondition.sum.rawValue {
                    v1RecommendedSEnabled = false
                    oddsAdaptiveSEnabled = false
                    svip6SumEnabled = command.enabled
                }
                if let text = command.value { value?.wrappedValue = text }
                enabled.wrappedValue = command.enabled
                if !enteredConditionIDs.contains(command.id) { enteredConditionIDs.append(command.id) }
            }
            result = nil
            currentTXTQueryMessage = nil
            currentTXTQueryIsHit = nil
            conditionTextMessage = "已理解并应用\(updates.count)项：" + labels.joined(separator: "；") + "。请重新生成。"
            conditionTextInput = ""
            DispatchQueue.main.async {
                UserDefaults.standard.set(persistedInputValues, forKey: inputDefaultsStorageKey)
                UserDefaults.standard.synchronize()
                scheduleDurableBackup()
            }
        } catch {
            conditionTextMessage = error.localizedDescription
        }
    }

    private func basicCondition(for title: String) -> BasicCondition? {
        if title.contains("判定值3最多") { return .valueThree }
        if title.contains("判定值2最多") { return .valueTwo }
        if title.contains("稳定性") { return .variance }
        if title.hasPrefix("P_tr") { return .transition }
        if title.contains("综合评分") { return .score }
        if title == "前5场彩果断点" || title.hasPrefix("最终彩果断点") { return .breakpoints }
        if title.contains("二阶波动 R") || title == "六场判定值R" || title == "六场R范围" { return .roughness }
        if title == "判定总和 S" || title.contains("判定值和值S") || title.contains("判定值和值 S")
            || title.contains("欧赔和值 S") { return .sum }
        if title == "六场实际顺序M" || title == "前5场实际顺序M" || title.contains("位移 M") { return .displacement }
        return nil
    }

