                    showsAllLegacyV1Conditions.toggle()
                }
            }.font(.subheadline).padding(.horizontal,14).padding(.vertical,10).background(.regularMaterial)
            if showsAllLegacyV1Conditions { legacyAllConditionsPage }
            else { selectedConditionsPage }
        }.sheet(isPresented:$showsConditionVersionPicker) {
            NavigationStack {
                Form { conditionVersionSection }
                    .navigationTitle("条件版本")
                    .toolbar { ToolbarItem(placement:.topBarTrailing) { Button("完成") { showsConditionVersionPicker=false; showsAllLegacyV1Conditions=false } } }
            }
        })
    }

    private var selectedConditionsPage: AnyView {
        if svvvp11Selected { return svvvp11ConditionsPage }
        if svvvSelected { return svvvConditionsPage }
        if isVIPConditionEnabled && selectedConditionVersionID == "svip11-breakpoint-selection" { return svip11ConditionsPage }
        if isVIPConditionEnabled && selectedConditionVersionID == "svip10-frozen-160" { return svip10ConditionsPage }
        if isVIPConditionEnabled && selectedConditionVersionID == "svip9-dual-s" { return svip9ConditionsPage }
        if isVIPConditionEnabled && ["svip11-breakpoint-selection", "svip10-frozen-160", "svip9-dual-s", "svip8-current-three", "svip6-three-condition"].contains(selectedConditionVersionID) { return svip6ConditionsPage }
        if isVIPConditionEnabled && selectedConditionVersionID == "svip7-odds-rank-280" {
            return svip7ConditionsPage
        }
        if usesVIP7EnabledOnlyConditionsPage {
            return vip7EnabledOnlyConditionsPage
        }
        return legacyAllConditionsPage
    }

