                    conditionField("P_tr ≥ (%)", "0.15", text: $transitionMinimumInput, keyboard: .decimalPad)
                    conditionField("二阶波动 R≤", "9", text: $roughnessMaximumInput, keyboard: .numberPad)
                    conditionField("最终彩果断点 B", "2-6", text: $breakpointInput)
                    Divider()
                    Toggle("第8项：前三场判定值4最多1个", isOn: $noFourPositionFilterEnabled)
