                    }
                }
                enabledConditionPinnedSection
                conditionVersionSection
                customHandicapOddsProductSection
                customHandicapOddsSumSection
                universal247ToleranceSection
                universal150CompressionSection
                historicalToleranceSection
                allConditionsToleranceSection
                comprehensiveAnalysisSection
                protectedHistoryMaxCompressionSection
                Section("连续彩果条件") {
                    Toggle("启用连续彩果过滤", isOn: $consecutiveRunsEnabled)
                        .onChange(of: consecutiveRunsEnabled) { _ in result = nil }
                    if consecutiveRunsEnabled {
                        conditionField("连续不败", "3-7", text: $nonLossRunInput)
                        conditionField("连续不平", "3-7", text: $nonDrawRunInput)
                        conditionField("连续不胜", "3-7", text: $nonWinRunInput)
                        conditionField("容错空间", "0-1", text: $consecutiveRunToleranceInput)
