                        .font(.caption)
                        .foregroundStyle(SequenceFilterTheme.textSecondary)
                    DisclosureGroup(six250RelationshipEnabled ? "旧总包明细（当前不参与过滤）" : "查看或调整总包明细", isExpanded: $isConditionPackageExpanded) {
                    conditionField(
                        usesVIP11FrontFiveMappedSum
                            ? "234判定值和值 S（6场）"
                            : (selectedConditionVersionID == "vip10-front-five-real-sum" ? "真实让球欧赔和值 S（六场）" : "判定总和 S"),
                        ["svip11-breakpoint-selection", "svip10-frozen-160", "svip9-dual-s", "svip8-current-three", "svip6-three-condition", "svip5-current-snapshot", "svip4-permutation-lowest-odds", "svip1-xs-current", "svip2-all-basic", "svip3-current-no-four", "vip10-front-five-real-sum", "vip11-front-five-mapped-sum", "vip12-probability-bottom20", "vip14-s15-18", "vip15-s15-20-single-no-four", "vip16-probability-top200"].contains(selectedConditionVersionID) ? (["svip11-breakpoint-selection", "svip10-frozen-160", "svip9-dual-s", "svip8-current-three", "svip6-three-condition", "svip5-current-snapshot", "svip4-permutation-lowest-odds", "svip2-all-basic", "svip3-current-no-four"].contains(selectedConditionVersionID) ? "14-20" : (["svip1-xs-current", "vip15-s15-20-single-no-four", "vip16-probability-top200"].contains(selectedConditionVersionID) ? "15-20" : (selectedConditionVersionID == "vip14-s15-18" ? "15-18" : "13-17"))) : (["vip18-calibrated-upset-top200", "vip19-custom-odds-constitution-top200"].contains(selectedConditionVersionID) ? "12-24" : "12-19"),
                        text: inherited ? $svip9BaseSumRangeInput : $sumInput
