                    if ["svip11-breakpoint-selection", "svip10-frozen-160", "svip9-dual-s", "svip8-current-three", "svip6-three-condition", "svip5-current-snapshot", "svip4-permutation-lowest-odds", "svip1-xs-current", "svip2-all-basic", "svip3-current-no-four", "vip12-probability-bottom20"].contains(selectedConditionVersionID) {
                        Divider()
                        Toggle("自定义赔率乘积（前6场）", isOn: $customHandicapOddsProductFilterEnabled)
                            .font(.subheadline.bold())
                            .tint(SequenceFilterTheme.conditionsAccent)
                            .onChange(of: customHandicapOddsProductFilterEnabled) { _ in result = nil }
                        if customHandicapOddsProductFilterEnabled {
