                        usesSVIPPermutationVersion ? "4-6" : (usesFrontFiveMVersion ? (["svip2-all-basic", "svip3-current-no-four"].contains(selectedConditionVersionID) ? "2-6" : "3-6") : (["vip18-calibrated-upset-top200", "vip19-custom-odds-constitution-top200"].contains(selectedConditionVersionID) ? "0-100" : "4-8")),
                        text: $displacementInput
