    /// 连续条件使用每单前6场实际彩果；有第7场固定单选时追加该单选，
    /// 与过滤引擎处理最终6/7场组合的口径保持一致。
    private var consecutiveRunHistoricalOutcomes: [[Int]] {
        uniquePrizeQueryRecords.compactMap { record in
            guard let outcomes = record.outcomes, outcomes.count >= 6 else { return nil }
            var sequence = Array(outcomes.prefix(6))
            guard record.matchNumbers.count >= 7 else { return sequence }
            let key = TXTQueryStatisticsCalculator.ticketKey(
                issue: record.issue,
                matchNumbers: record.matchNumbers
            )
            let seventh = sharedTXTQueryHistory
                .filter {
                    TXTQueryStatisticsCalculator.ticketKey(
                        issue: $0.issue,
                        matchNumbers: $0.matchNumbers
                    ) == key
                }
                .sorted { $0.sharedAt > $1.sharedAt }
                .compactMap(savedSeventhSingleOutcome)
                .first
            if let seventh { sequence.append(seventh) }
            return sequence
        }
    }

    private var consecutiveRunHistoryStatistics: [ConsecutiveRunHistoryStatistic] {
        let samples = consecutiveRunHistoricalOutcomes
        return [3, 4, 5].map { minimum in
            let failures = samples.map { outcomes in
                [
                    ConsecutiveRunCondition.nonLoss.longestRun(in: outcomes),
                    ConsecutiveRunCondition.nonDraw.longestRun(in: outcomes),
                    ConsecutiveRunCondition.nonWin.longestRun(in: outcomes)
                ].filter { $0 < minimum }.count
            }
            return ConsecutiveRunHistoryStatistic(
                minimum: minimum,
                sampleCount: samples.count,
                nonLossCount: samples.filter {
                    ConsecutiveRunCondition.nonLoss.longestRun(in: $0) >= minimum
                }.count,
                nonDrawCount: samples.filter {
                    ConsecutiveRunCondition.nonDraw.longestRun(in: $0) >= minimum
                }.count,
                nonWinCount: samples.filter {
                    ConsecutiveRunCondition.nonWin.longestRun(in: $0) >= minimum
                }.count,
                strictCount: failures.filter { $0 == 0 }.count,
                allowOneFailureCount: failures.filter { $0 <= 1 }.count,
                allowTwoFailuresCount: failures.filter { $0 <= 2 }.count,
                requireOneToThreeFailuresCount: failures.filter { (1...3).contains($0) }.count,
                requireTwoToThreeFailuresCount: failures.filter { (2...3).contains($0) }.count
            )
        }
    }

    /// 从33条去重历史彩果中分别给出连胜/连平/连负范围。
    /// 下限固定为2（才构成“连续”），上限覆盖历史中约90%的实际连续事件。
    private var sameResultRunHistoryRecommendations: [SameResultRunHistoryRecommendation] {
        let samples = consecutiveRunHistoricalOutcomes
        let definitions: [(id: String, title: String, condition: ConsecutiveRunCondition)] = [
            ("win", "连胜3", .win),
            ("draw", "连平1", .draw),
            ("loss", "连负0", .loss)
        ]
        return definitions.map { definition in
            let allLengths = samples.map { definition.condition.longestRun(in: $0) }
            let repeatedLengths = allLengths.filter { $0 >= 2 }.sorted()
            let recommendedUpper: Int
            if repeatedLengths.isEmpty {
                recommendedUpper = 7
            } else {
                let percentileIndex = min(
                    repeatedLengths.count - 1,
                    max(0, Int(ceil(Double(repeatedLengths.count) * 0.90)) - 1)
                )
                recommendedUpper = max(2, min(7, repeatedLengths[percentileIndex]))
            }
            let recommendedRange = 2...recommendedUpper
            return SameResultRunHistoryRecommendation(
                id: definition.id,
                title: definition.title,
                inputRange: "2-\(recommendedUpper)",
                passCount: allLengths.filter(recommendedRange.contains).count,
                repeatedRunCount: repeatedLengths.count,
                sampleCount: samples.count
            )
        }
    }

    private func applySameResultRunHistoryRecommendation(
        _ recommendation: SameResultRunHistoryRecommendation
    ) {
        switch recommendation.id {
        case "win": winRunInput = recommendation.inputRange
        case "draw": drawRunInput = recommendation.inputRange
        case "loss": lossRunInput = recommendation.inputRange
        default: return
        }
        sameResultRunsEnabled = true
        result = nil
    }

    private var sameResultRunHistoryRecommendationView: AnyView {
        AnyView(
            VStack(alignment: .leading, spacing: 7) {
                Text("历史33条独立推荐")
                    .font(.caption.bold())
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
                ForEach(sameResultRunHistoryRecommendations) { recommendation in
                    HStack(spacing: 8) {
                        Text(recommendation.title)
                            .frame(width: 52, alignment: .leading)
                        Text("推荐 \(recommendation.inputRange)")
                            .font(.system(.caption, design: .monospaced).bold())
                        Spacer()
                        Text("命中\(recommendation.passCount)/\(recommendation.sampleCount)")
                            .font(.caption2.monospacedDigit())
                            .foregroundStyle(SequenceFilterTheme.textSecondary)
                        Button("套用") {
                            applySameResultRunHistoryRecommendation(recommendation)
                        }
                        .buttonStyle(.bordered)
                        .tint(SequenceFilterTheme.conditionsAccent)
                    }
                }
                Text("推荐下限为2；上限覆盖历史中约90%的实际连续事件。命中数是在全部历史样本中落入推荐范围的条数。")
                    .font(.caption2)
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
            }
            .padding(9)
