    private func applyConsecutiveRunHistoryPreset(minimum: Int) {
        let range = "\(minimum)-7"
        nonLossRunInput = range
        nonDrawRunInput = range
        nonWinRunInput = range
        consecutiveRunToleranceInput = minimum == 3 ? "0-1" : (minimum == 5 ? "2-3" : "0-2")
        consecutiveRunsEnabled = true
        result = nil
    }

    private var currentConsecutiveRunRangeRecommendation: ConsecutiveRunRangeRecommendation? {
        guard let normalized = normalizedABCD(logicInput) else { return nil }
        let logic = normalized.lowercased().compactMap { LogicMapping(rawValue: String($0)) }
        guard logic.count == 5 else { return nil }
        let requested = currentFilteredMatchNumbers.compactMap(Int.init)
        let matching = requested.compactMap { number in
            goalModelAnalyses.first { Int($0.match.matchNumber) == number }
        }
        let spRows: [[Double]]? = matching.count == 5 ? matching.compactMap { analysis in
            let match = analysis.match
            if match.referenceSP.count == 3,
               match.referenceSP.allSatisfy({ $0.isFinite && $0 > 0 }) {
                return match.referenceSP
            }
            if match.marketOdds.count == 3,
               match.marketOdds.allSatisfy({ $0.isFinite && $0 > 0 }) {
                return match.marketOdds
            }
            return nil
        } : nil
        let completeSPRows = spRows?.count == 5 ? spRows : nil
        return ConsecutiveRunRangeAdvisor.recommend(
            spRows: completeSPRows,
            logic: logic,
            seventhOutcome: Int(singleOutcomeInput) ?? 3
        )
    }

    private func applyConsecutiveRunRecommendation(_ recommendation: ConsecutiveRunRangeRecommendation) {
        guard let assessment = recommendation.recommendedAssessment else { return }
        let range = "\(assessment.minimum)-7"
        nonLossRunInput = range
        nonDrawRunInput = range
        nonWinRunInput = range
        consecutiveRunToleranceInput = "\(assessment.tolerance.lowerBound)-\(assessment.tolerance.upperBound)"
        consecutiveRunsEnabled = true
        secondaryConsecutiveRunsEnabled = false
        result = nil
    }

