    private var automaticMatchSearchStart: String {
        (usesAutomaticSearchOrigin ? matchSearchStartInput : match1Input)
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private var usesSVIP10AutomaticDoublePair: Bool { false }

    private var usesAllABCDSelection: Bool { false }

    private var usesFrontTwoADSelection: Bool { false }

    private var usesStructuredMatchSelection: Bool { usesAllABCDSelection || usesFrontTwoADSelection || usesADDoublesWithinSix }

    private var currentSelectionPatternIsValid: Bool {
        guard let logic = currentABCDForGeneration else { return false }
        if usesADDoublesWithinSix {
            return logic.count == 6 && logic.filter { "AD".contains($0) }.count >= 1
        }
        return (!usesAllABCDSelection || Set(logic) == Set("ABCD"))
            && (!usesFrontTwoADSelection || (logic.count == 6 && logic.prefix(2).allSatisfy { "AD".contains($0) }))
    }

