    @MainActor
    private func refreshDoubleMarketSelection(forceApply: Bool) async {
        guard scenePhase == .active, hasLoadedInputDefaults, !isRestoringInputDefaults,
              usesSVIP10AutomaticDoublePair, inputExperienceMode == "v1",
              !hasManualMatchSelection, !isRefreshingDoubleMarket,
              !isCalculatingVIP6Matches, !isCalculating, globalGenerationPhase == nil,
              let first = Int(automaticMatchSearchStart), first > 0 else { return }
        let kickoffs = vip6SelectedMatchesWithResults.compactMap { DoubleMarketDataClient.kickoff(issue: $0.issue, matchTime: $0.matchTime) }
        if !forceApply, kickoffs.count != 6 || kickoffs.min().map({ $0.addingTimeInterval(-DoubleMarketDataClient.decisionLeadTime) <= Date() }) != false {
            svip10MarketRefreshMessage = "当前组未就绪或已到首场赛前2小时锁定点；仅使用此窗口内已有归档。"
            return
        }
        isRefreshingDoubleMarket = true
        defer { isRefreshingDoubleMarket = false }
        await calculateVIP6AutomaticMatchSelection(firstMatchNumber: first, preserveGeneratedResult: !forceApply)
    }

