    @MainActor
    private func setVIPConditionEnabled(_ enabled: Bool) {
        if enabled {
            if svvvSelected || svvvp11Selected {
                vipConditionsEnabled = true
                scheduleInputDefaultsSave()
                return
            }
            let saved = UserDefaults.standard.string(forKey: lastVIPConditionVersionStorageKey)
            selectedConditionVersionID = saved.flatMap { vipConditionVersionIDs.contains($0) ? $0 : nil }
                ?? "vip19-custom-odds-constitution-top200"
            vipConditionsEnabled = true
            applySelectedConditionVersion()
        } else {
            if hasSelectedVIPConditionVersion {
                UserDefaults.standard.set(selectedConditionVersionID, forKey: lastVIPConditionVersionStorageKey)
            }
            vipConditionsEnabled = false
            result = nil
            conditionVersionMessage = "已关闭全部VIP：未载入V1或任何默认值，当前数值与普通条件保持不变。"
            UserDefaults.standard.set(persistedInputValues, forKey: inputDefaultsStorageKey)
            UserDefaults.standard.synchronize()
            invalidateComputedResultsAfterConditionChange()
            scheduleDurableBackup()
        }
    }

