    private func legacyConditionVersionButton(_ title: String, id: String) -> some View {
        Button {
            saveSVVVP11PackageIfSelected()
            svvvp11Selected = false
            inputExperienceMode = "v1"
            selectedConditionVersionID = id
            applySelectedConditionVersion()
        } label: {
            HStack {
                Text(title)
                    .foregroundStyle(SequenceFilterTheme.textPrimary)
                Spacer()
                if selectedConditionVersionID == id {
                    Image(systemName: "checkmark.circle.fill")
                        .foregroundStyle(SequenceFilterTheme.accent)
                }
            }
        }
    }

