    @MainActor
    private func applySelectedConditionVersion() {
        svvvp11Selected = false
        if !selectedConditionVersionID.hasPrefix("svip") { syncSequentialMatchInputs() }
        isRestoringInputDefaults = true
        if !["svip11-breakpoint-selection", "svip10-frozen-160", "svip9-dual-s"].contains(selectedConditionVersionID) {
            universal247ToleranceEnabled = true
            secondNoFourPositionFilterEnabled = false
            secondNoFourPositionInput = "2"
        }
        if ["svip10-frozen-160", "svip11-breakpoint-selection"].contains(selectedConditionVersionID) {
            vipConditionsEnabled = true
            svip10Enabled = true
            UserDefaults.standard.set(selectedConditionVersionID, forKey: lastVIPConditionVersionStorageKey)
            conditionVersionMessage = selectedConditionVersionID == "svip11-breakpoint-selection" ? "SVIP11已启用断点概率非连续选场，沿用当前六场过滤；需重新选场生成。" : "SVIP10连续选场已启用，评分范围\(svip10ScoreRangeInput)、不补注。"
        } else if selectedConditionVersionID == "svip9-dual-s" {
            vipConditionsEnabled = true
            UserDefaults.standard.set(selectedConditionVersionID, forKey: lastVIPConditionVersionStorageKey)
            conditionVersionMessage = "SVIP9已载入SVIP5完整条件，保留原范围及开关状态。"
        } else if selectedConditionVersionID == "svip8-current-three" {
            vipConditionsEnabled = true
            comprehensiveAnalysisFilterEnabled = false
            protectedHistoryMaxCompressionEnabled = false
            protectedHistoryToleranceEnabled = false
            protectedHistoryBetCapEnabled = false
            let snapshot = UserDefaults.standard.dictionary(forKey: "sequenceFilter.svip8Snapshot.v1") as? [String: String] ?? [:]
            sumInput = snapshot["sumInput"] ?? "15-18"
            svip6SumEnabled = snapshot["svip6SumEnabled"] != "0"
            noFourPositionFilterEnabled = snapshot["noFourPositionFilterEnabled"] != "0"
            svip4NoFourSelection = snapshot["svip4NoFourSelection"] ?? "1"
            currentConditionPackageEnabled = snapshot["currentConditionPackageEnabled"] != "0"
            universal247ToleranceEnabled = false
