        } else if selectedConditionVersionID == "manual-confirmed-v7" {
            applyManualConfirmedV7Configuration()
            conditionVersionMessage = "已载入V7手动确认版：指定位置≠4默认为第3场，可手动改为第1–5场。请重新全局生成。"
        } else if selectedConditionVersionID == "phone-current-v6"
            || selectedConditionVersionID == "whole-issue-405-v5" {
            // V5是一个可复现的完整条件版本。其他过滤若与405模型取交集，
            // 会使整期留出覆盖率低于验收线，因此这里明确关闭而不继承旧开关。
            sumInput = "10-20"
            displacementInput = "0-8"
            varianceInput = "1"
            valueTwoMaximumInput = "5"
            transitionMinimumInput = "0"
            roughnessMaximumInput = "12"
            breakpointInput = "0-4"
            productRemovalCountInput = "0"
            finalReduction = .off
            outcomeConditionToleranceEnabled = false
            allConditionsToleranceEnabled = false
            for condition in OutcomeCondition.editorCases {
                outcomeConditionEnabled[condition] = false
                outcomeConditionInputs[condition] = ""
            }
            consecutiveRunsEnabled = false
            secondaryConsecutiveRunsEnabled = false
            sameResultRunsEnabled = false
            protectConsecutiveDrawPair = false
            spProductFilterEnabled = false
            prizeRangeFilterEnabled = false
            spRiskFilterEnabled = false
            minimumProbabilityFilterEnabled = false
            jointProbabilityFilterEnabled = false
            groupFilterEnabled = false
            prizeStatisticalConditionEnabled = false
            prizeStatisticalCountPatternEnabled = false
            comprehensiveAnalysisFilterEnabled = false
            protectedHistoryMaxCompressionEnabled = false
            protectedHistoryBetCapEnabled = false
            universal150CompressionEnabled = false
            universal247ToleranceThresholdInput = "9.405"
            frontThreeMaximumFourFilterEnabled = false
            noFourPositionFilterEnabled = false
            noFourPositionInput = "1"
            conditionVersionMessage = selectedConditionVersionID == "phone-current-v6"
                ? "已载入V6手机当前版：169/235（71.91%），405注。新增的指定场次不是4开关默认关闭。"
                : "已载入V5整期留出405版：验证143/203（70.44%）。请重新全局生成。"
        } else if selectedConditionVersionID == "general-u247-v4" {
            consecutiveRunsEnabled = false
            secondaryConsecutiveRunsEnabled = false
            sameResultRunsEnabled = false
            displacementInput = "3-7"
            transitionMinimumInput = "0.15"
            universal247ToleranceThresholdInput = "9.247"
            conditionVersionMessage = "已载入V4通用247统计版。请重新全局生成，查询与奖金将只认V4新TXT。"
        } else if selectedConditionVersionID == "relaxed-runs-v3" {
            consecutiveRunsEnabled = false
            secondaryConsecutiveRunsEnabled = false
            sameResultRunsEnabled = false
            displacementInput = "3-7"
            transitionMinimumInput = "0.15"
            universal247ToleranceThresholdInput = "-0.050756"
            conditionVersionMessage = "已载入V3双连续关闭版。请重新全局生成，查询与奖金将只认V3新TXT。"
        } else if selectedConditionVersionID == "recommended-v2" {
            consecutiveRunsEnabled = true
            sameResultRunsEnabled = true
            consecutiveRunToleranceInput = "0-2"
            sameResultRunToleranceInput = "1-3"
            universal247ToleranceThresholdInput = "-0.37"
            conditionVersionMessage = "已载入V2推荐版。请重新全局生成，查询与奖金将只认V2新TXT。"
        } else {
            consecutiveRunsEnabled = true
            sameResultRunsEnabled = true
            consecutiveRunToleranceInput = "0-1"
            sameResultRunToleranceInput = "2-3"
            universal247ToleranceThresholdInput = "-0.050756"
            conditionVersionMessage = "已载入V1当前版。请重新全局生成，查询与奖金将只认V1新TXT。"
        }
        result = nil
        UserDefaults.standard.set(persistedInputValues, forKey: inputDefaultsStorageKey)
        UserDefaults.standard.synchronize()
        invalidateComputedResultsAfterConditionChange()
        scheduleDurableBackup()
        DispatchQueue.main.async {
            isRestoringInputDefaults = false
            if selectedConditionVersionID == "svip11-breakpoint-selection" {
                // Cached ABCD from the old consecutive set must never bypass new selection.
                scheduleVIP6AutomaticMatchSelection()
            } else if selectedConditionVersionID == "svip3-current-no-four",
               (noFourPositionFilterEnabled || secondNoFourPositionFilterEnabled) {
                scheduleVIP6AutomaticMatchSelection()
            }
        }
    }

