    private func recentTXTQueryRecordRow(_ record: SharedTXTQueryRecord, canVerify: Bool = true) -> some View {
        let checking = verifyingRecentTXTRecordIDs.contains(record.id)
        let hit = record.isFinalResult ? record.isHit : nil
        return VStack(alignment: .leading, spacing: 8) {
            HStack {
                Text("第\(record.issue)期").font(.headline)
                Spacer()
                Label(hit == true ? "已命中" : (hit == false ? "未命中" : "待开奖"),
                      systemImage: hit == true ? "checkmark.circle.fill" : (hit == false ? "xmark.circle.fill" : "clock"))
                    .font(.subheadline.bold())
                    .foregroundStyle(hit == true ? Color.green : (hit == false ? Color.red : Color.orange))
            }
            Text(record.sharedAt.formatted(date: .numeric, time: .shortened))
                .font(.caption)
                .foregroundStyle(SequenceFilterTheme.textSecondary)
            Text("场次：" + record.matchNumbers.joined(separator: "、"))
                .font(.system(.caption, design: .monospaced))
            Text("\(record.finalBetCount)注 · \(record.finalBetCount * 2 * (txtMultiplier(from: record.txtContent) ?? 1))元（\(txtMultiplier(from: record.txtContent) ?? 1)倍） · \(record.filename)")
                .font(.caption)
                .foregroundStyle(SequenceFilterTheme.textSecondary)
            if let outcomes = record.observedOutcomes {
                Text("前六场赛果：" + outcomes.prefix(6).map { $0.map(String.init) ?? "?" }.joined())
                    .font(.system(.caption, design: .monospaced))
            }
            if let message = record.verificationMessage {
                Text(message)
                    .font(.caption)
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
            }
            HStack(spacing: 8) {
                ForEach([TXTSharePart.total, .e, .f], id: \.label) { part in
                    Button("\(part.label)TXT") {
                        txtPreview = makeTXTPreview(
                            title: "第\(record.issue)期-\(record.id.uuidString.prefix(8))-\(part.label)",
                            content: queryTXTContent(record: record, part: part),
                            observedOutcomes: record.isFinalResult ? record.observedOutcomes : nil,
                            editingRecord: record, part: part
                        )
                    }
                    .frame(maxWidth: .infinity)
                }
            }
            .buttonStyle(ColorfulOutlineButtonStyle())
            if canVerify {
            Button {
                Task { await verifyRecentTXTRecord(record.id) }
            } label: {
                HStack {
                    if checking { ProgressView() }
                    Text(checking ? "正在核对…" : "查询是否命中")
                }
                .frame(maxWidth: .infinity)
            }
            .buttonStyle(PatternedActionButtonStyle())
            .disabled(checking)
            }
        }
        .padding(.vertical, 6)
    }

