    private var sharedTXTQueryResultsPage: some View {
        let records = uniqueTXTQueryRecords
        let staleRecords = records.filter { !isCurrentConditionTXT($0) }
        // 每条记录只计算一次状态，同时供汇总与可见 Cell 使用。
        // 以前汇总、待定列表和 Cell 会分别重放条件，206 单时卡顿明显。
        let conditionResults = records.map { ($0, sharedTXTUnderlyingConditionStatus(for: $0)) }
        let finalConditionResults = conditionResults.filter(\.0.isFinalResult)
        let conditionPassedCount = finalConditionResults.filter { $0.1.passes == true }.count
        // 查询页的“TXT结果”和“条件结果”强制使用同一个端到端结论。
        // TXT精确存在性仍在失败原因中展示，但不能形成第二套通过数字。
        let txtPassedRecords = finalConditionResults.filter { $0.1.passes == true }.map(\.0)
        let txtFailedRecords = finalConditionResults.filter { $0.1.passes == false }.map(\.0)
        let txtPendingRecords = conditionResults.filter {
            !$0.0.isFinalResult || $0.1.passes == nil
        }.map(\.0)
        // 八期合并必须以奖金历史的全部去重单据为数据源，
        // 不能只统计已经生成过TXT的那一部分 Cell。
        let mergedRecords = mergedHistoricalPrizeRecords
        // VIP 1 冻结单有独立本地归档，不依赖 206 条有效 TXT 列表。
        let mergedFrozenRecords = locallySavedVIP1FrozenRecords.filter {
            historicalMergedIssues.contains($0.issue)
        }
        let mergedEffectiveRecords = mergedRecords.filter { !isCurrentFrozenV11Record($0) }
        let frozenTicketKeys = Set(mergedFrozenRecords.map {
            TXTQueryStatisticsCalculator.ticketKey(issue: $0.issue, matchNumbers: $0.matchNumbers)
        })
        // 通过/未通过详情必须使用原始 TXT 查询记录，才能保留手动输入赛果、
        // 重新查询、查看总量/A/B/C/E/F 等完整功能。
        let effectiveTXTResults = finalConditionResults.filter { evaluation in
            let record = evaluation.0
            let key = TXTQueryStatisticsCalculator.ticketKey(
                issue: record.issue,
                matchNumbers: record.matchNumbers
            )
            return historicalMergedIssues.contains(record.issue) && !frozenTicketKeys.contains(key)
        }
        let mergedPassedTXTRecords = effectiveTXTResults.filter { $0.1.passes == true }.map(\.0)
        let mergedFailedTXTRecords = effectiveTXTResults.filter { $0.1.passes == false }.map(\.0)
        let mergedCalculatedCount = mergedRecords.filter { globalFilterCounts(for: $0) != nil }.count
        return List {
            Section("全部更新") {
                Button {
                    Task { await verifyAllSharedTXTRecordsUsingCurrentConditions() }
                } label: {
                    HStack {
                        if isVerifyingAllSharedTXTRecords {
                            ProgressView()
                                .padding(.trailing, 6)
                        }
                        Label(
                            isVerifyingAllSharedTXTRecords
                                ? "正在计算分析所有 Cell…"
                                : "按当前全部条件计算分析所有 Cell",
                            systemImage: "arrow.triangle.2.circlepath.circle.fill"
                        )
                        Spacer()
                    }
                    .frame(maxWidth: .infinity, minHeight: 38)
                }
                .buttonStyle(PatternedActionButtonStyle())
                // 规则升级后页面里可能暂时全是旧签名记录。此时仍允许点击，
                // 由批量流程升级可安全迁移的TXT并明确提示其余记录，不能静默失效。
                .disabled(isVerifyingAllSharedTXTRecords)
                if let sharedTXTBulkVerificationMessage {
                    Text(sharedTXTBulkVerificationMessage)
                        .font(.caption.weight(.semibold))
                        .foregroundStyle(SequenceFilterTheme.textSecondary)
                        .fixedSize(horizontal: false, vertical: true)
                }
                Text("按去重后顺序逐条获取赛果并计算分析，与在每个 Cell 点“按全部条件确认是否命中”的口径完全一致；同时更新通过状态、未通过原因、奖金和奖金Tab。")
                    .font(.caption2)
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
                if !staleRecords.isEmpty {
                    Text("将在本按钮内自动把\(staleRecords.count)条旧条件TXT按条件Tab最新设置重新生成，无需再去输入页逐条操作。")
                        .font(.caption2.bold())
                        .foregroundStyle(.orange)
                }
            }
            Section("结果导航（26091—26098）") {
                NavigationLink {
                    ExplicitBackButtonContainer {
                        sharedTXTMergedStatusPage(
                            title: "26091—26098 · 通过",
                            records: mergedPassedTXTRecords,
                            showsFailureReasons: false
                        )
                    }
                } label: {
                    HStack {
                        Label("通过", systemImage: "checkmark.circle.fill")
                        Spacer()
                        Text("\(mergedPassedTXTRecords.count)单")
                            .font(.headline.monospacedDigit())
                    }
                    .frame(maxWidth: .infinity, minHeight: 38)
                }
                .buttonStyle(PatternedActionButtonStyle())

                NavigationLink {
                    ExplicitBackButtonContainer {
                        sharedTXTMergedStatusPage(
                            title: "26091—26098 · 未通过",
                            records: mergedFailedTXTRecords,
                            showsFailureReasons: true
                        )
                    }
                } label: {
                    HStack {
                        Label("未通过", systemImage: "xmark.circle.fill")
                        Spacer()
                        Text("\(mergedFailedTXTRecords.count)单")
                            .font(.headline.monospacedDigit())
                    }
                    .frame(maxWidth: .infinity, minHeight: 38)
                }
                .buttonStyle(PatternedActionButtonStyle())

                if !mergedFrozenRecords.isEmpty {
                    NavigationLink {
                        ExplicitBackButtonContainer {
                            locallySavedFrozenRecordsPage(records: mergedFrozenRecords)
                        }
                    } label: {
                        HStack {
                            Label("冻结（判定值2≥4个）", systemImage: "snowflake")
                            Spacer()
                            Text("\(mergedFrozenRecords.count)单")
                                .font(.headline.monospacedDigit())
                        }
                        .frame(maxWidth: .infinity, minHeight: 38)
                    }
                    .buttonStyle(ColorfulOutlineButtonStyle())
                }

                Text(mergedFrozenRecords.isEmpty
                    ? "共合并\(mergedRecords.count)单，按期号＋场次去重。已按当前版本完整计算\(mergedCalculatedCount)单；若小于总数，请先点上方“按当前全部条件计算分析所有 Cell”。"
                    : "共合并\(mergedRecords.count)单；V11冻结\(mergedFrozenRecords.count)单已另外保存在手机本地，只在本页进入的三级页面展示。有效分母\(mergedEffectiveRecords.count)单，冻结单不列入通过、未通过或注数统计。")
                    .font(.caption)
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
                    .fixedSize(horizontal: false, vertical: true)
            }
            Section("统计（期号＋场次去重）") {
                HStack(spacing: 12) {
                    queryStatisticTile(
                        title: "TXT通过",
                        value: "\(txtPassedRecords.count)条",
                        color: .green
                    )
                    queryStatisticTile(
                        title: "条件通过",
