    private func sharedTXTMergedStatusPage(
        title: String,
        records: [SharedTXTQueryRecord],
        showsFailureReasons: Bool
    ) -> some View {
        let statusColor: Color = showsFailureReasons ? .red : .green
        let needle = sharedTXTResultSearchText
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
        let filteredRecords = records.filter { record in
            guard !needle.isEmpty else { return true }
            let outcomeText = record.observedOutcomes?
                .map { $0.map(String.init) ?? "?" }
                .joined() ?? ""
            return record.issue.lowercased().contains(needle)
                || record.matchNumbers.joined(separator: ",").lowercased().contains(needle)
                || record.filename.lowercased().contains(needle)
                || outcomeText.contains(needle)
        }
        // 用户要求的唯一展示特例：最近保存的5单独立置顶，
        // 不再在下方按期号分组里重复。
        let latestRecords = Array(records.sorted { $0.sharedAt > $1.sharedAt }.prefix(5))
        let latestRecordIDs = Set(latestRecords.map(\.id))
        let visibleLatestRecords = latestRecords.filter {
            sharedTXTRecord($0, matchesSearch: needle)
        }
        let categorizedRecords = filteredRecords.filter { !latestRecordIDs.contains($0.id) }
        return List {
            Section("汇总") {
                LabeledContent(showsFailureReasons ? "未通过" : "通过", value: "\(records.count)单")
                    .foregroundStyle(statusColor)
                if !needle.isEmpty {
                    LabeledContent("搜索结果", value: "\(filteredRecords.count)单")
                        .foregroundStyle(statusColor)
                }
                Text("范围：26091—26098；按期号＋前6场去重。可搜索期号、场次号、彩果或TXT文件名。")
                    .font(.caption)
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
            }
            if filteredRecords.isEmpty {
                Section {
                    Label(
                        needle.isEmpty
                            ? (showsFailureReasons ? "当前没有未通过单据" : "当前没有通过单据")
                            : "没有符合搜索条件的单据",
                        systemImage: needle.isEmpty
                            ? (showsFailureReasons ? "checkmark.circle" : "tray")
                            : "magnifyingglass"
                    )
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
                }
            } else {
                if !visibleLatestRecords.isEmpty {
                    Section("最新5单·单独置顶") {
                        ForEach(visibleLatestRecords) { record in
                            NavigationLink {
                                ExplicitBackButtonContainer {
                                    sharedTXTStatusIssuePage(
                                        issue: record.issue,
                                        records: [record],
                                        showsFailureReasons: showsFailureReasons
                                    )
                                }
                            } label: {
                                VStack(alignment: .leading, spacing: 4) {
                                    HStack {
                                        Text("第\(record.issue)期")
                                            .font(.headline.monospacedDigit())
                                        Spacer()
                                        Text("\(record.finalBetCount)注")
                                            .font(.subheadline.bold().monospacedDigit())
                                    }
                                    Text("场次 \(record.matchNumbers.prefix(6).joined(separator: ","))")
                                        .font(.system(.caption, design: .monospaced))
                                    Text(record.sharedAt.formatted(date: .numeric, time: .shortened))
                                        .font(.caption2)
                                }
                                .foregroundStyle(statusColor)
                            }
                        }
                    }
                }
                Section("按期号归类") {
                    ForEach(historicalMergedIssues, id: \.self) { issue in
                        let issueRecords = categorizedRecords
                            .filter {
                                $0.issue.trimmingCharacters(in: .whitespacesAndNewlines) == issue
                            }
                            .sorted(by: sharedTXTQueryRecordOrdered)
                        if !issueRecords.isEmpty {
                            NavigationLink {
                                ExplicitBackButtonContainer {
                                    sharedTXTStatusIssuePage(
                                        issue: issue,
                                        records: issueRecords,
                                        showsFailureReasons: showsFailureReasons
                                    )
                                }
                            } label: {
                                HStack {
                                    VStack(alignment: .leading, spacing: 3) {
                                        Text("第\(issue)期")
                                            .font(.headline.monospacedDigit())
                                            .foregroundStyle(statusColor)
                                        if let first = issueRecords.first,
                                           let last = issueRecords.last {
                                            Text("场次 \(first.matchNumbers.first ?? "-") — \(last.matchNumbers.first ?? "-")")
                                                .font(.caption.monospacedDigit())
                                                .foregroundStyle(SequenceFilterTheme.textSecondary)
                                        }
                                    }
                                    Spacer()
                                    Text("\(issueRecords.count)单")
                                        .font(.headline.monospacedDigit())
                                        .foregroundStyle(statusColor)
                                }
                                .frame(maxWidth: .infinity, minHeight: 42)
                            }
                        }
                    }
                }
            }
        }
        .scrollContentBackground(.hidden)
        .background(SequenceFilterTheme.queryAccent.opacity(0.05))
        .navigationTitle(title)
        .navigationBarTitleDisplayMode(.inline)
        .toolbar(.visible, for: .navigationBar)
        .searchable(
            text: $sharedTXTResultSearchText,
            placement: .navigationBarDrawer(displayMode: .always),
            prompt: "搜索期号、场次号、彩果或TXT"
        )
    }

