    private func sharedTXTRecord(
        _ record: SharedTXTQueryRecord,
        matchesSearch needle: String
    ) -> Bool {
        guard !needle.isEmpty else { return true }
        let outcomeText = record.observedOutcomes?
            .map { $0.map(String.init) ?? "?" }
            .joined() ?? ""
        return record.issue.lowercased().contains(needle)
            || record.matchNumbers.joined(separator: ",").lowercased().contains(needle)
            || record.filename.lowercased().contains(needle)
            || outcomeText.contains(needle)
    }

    private func sharedTXTQueryRecordOrdered(
        _ lhs: SharedTXTQueryRecord,
        _ rhs: SharedTXTQueryRecord
    ) -> Bool {
        let leftIssue = Int(lhs.issue.trimmingCharacters(in: .whitespacesAndNewlines)) ?? Int.max
        let rightIssue = Int(rhs.issue.trimmingCharacters(in: .whitespacesAndNewlines)) ?? Int.max
        if leftIssue != rightIssue { return leftIssue < rightIssue }
        let leftMatches = lhs.matchNumbers.map {
            Int($0.trimmingCharacters(in: .whitespacesAndNewlines)) ?? Int.max
        }
        let rightMatches = rhs.matchNumbers.map {
            Int($0.trimmingCharacters(in: .whitespacesAndNewlines)) ?? Int.max
        }
        if leftMatches != rightMatches {
            return leftMatches.lexicographicallyPrecedes(rightMatches)
        }
        return lhs.sharedAt < rhs.sharedAt
    }

