    private func historicalSingleBatchResultsPage(issue: String) -> some View {
        NavigationStack {
            Group {
                if let snapshot = historicalBatchSnapshots[issue] {
                    let passedItems = snapshot.items.filter(\.isTXTPassed)
                    let totalBefore = snapshot.expectedGroupCount * 729
                    let totalAfter = snapshot.items.reduce(0) { $0 + $1.finalBetCount }
                    let totalPrize = passedItems.compactMap(\.prizeAmount).reduce(0, +)
                    List {
                        Section("\(issue)汇总") {
                            LabeledContent("计划分组", value: "\(snapshot.expectedGroupCount)组")
                            LabeledContent("已计算", value: "\(snapshot.items.count)组")
                            LabeledContent("TXT过关", value: "\(passedItems.count)组")
                            LabeledContent("TXT未过", value: "\(snapshot.items.count - passedItems.count)组")
                            LabeledContent("计算失败", value: "\(snapshot.failures.count)组")
                            Divider()
                            LabeledContent("过滤前总注数", value: "\(totalBefore)注")
                            LabeledContent("过滤后TXT总注数", value: "\(totalAfter)注")
                            LabeledContent("共过滤掉", value: "\(max(0, totalBefore - totalAfter))注")
                            LabeledContent("过关奖金合计") {
                                Text("¥\(String(format: "%.2f", totalPrize))")
                                    .font(.headline.monospacedDigit())
                                    .foregroundStyle(SequenceFilterTheme.prizeAccent)
                            }
                            Text("分组从2–7开始，每次后移6场，直到当期剩余场次不足6场；每组固定追加“场次1→赛果1”。TXT命中和奖金只按前6场实际赛果核对。")
                                .font(.caption)
                                .foregroundStyle(SequenceFilterTheme.textSecondary)
                            if snapshot.conditionSignature != globalFilterConditionsSignature {
                                Label("这是旧条件结果；请回到查询Tab点“按当前条件重算\(issue)”。", systemImage: "exclamationmark.triangle.fill")
                                    .font(.caption.weight(.semibold))
                                    .foregroundStyle(.orange)
                            }
                        }

                        Section("分组明细（\(snapshot.items.count)）") {
                            ForEach(snapshot.items.sorted { $0.firstMatchNumber < $1.firstMatchNumber }) { item in
                                DisclosureGroup {
                                    Text("ABCD：\(item.logic)")
                                        .font(.system(.caption, design: .monospaced))
                                    Text("500赛果：" + zip(item.matchNumbers.prefix(6), item.actualOutcomes).map { number, outcome in
                                        item.autoPassedMatchNumbers?.contains(number) == true
                                            ? "\(number)=全对(SP 1.00)"
                                            : "\(number)=\(outcome)"
                                    }.joined(separator: "、"))
                                        .font(.system(.caption, design: .monospaced))
                                    Text("注数：\(item.beforeBetCount) → \(item.finalBetCount)，过滤\(max(0, item.beforeBetCount - item.finalBetCount))注")
                                        .font(.caption)
                                    Text(item.isTXTPassed
                                        ? "TXT精确命中：通过"
                                        : "TXT精确命中：未通过")
                                        .font(.subheadline.bold())
                                        .foregroundStyle(item.isTXTPassed ? .green : .red)
                                    Text("奖金：" + (item.isTXTPassed
                                        ? item.prizeAmount.map { "¥" + String(format: "%.2f", $0) } ?? "SP不足，暂无法计算"
                                        : "¥0.00（TXT未过）"))
                                        .font(.headline.monospacedDigit())
                                    NavigationLink("查看该组总TXT") {
                                        historicalBatchTXTDetailPage(issue: issue, item: item)
                                    }
                                    DisclosureGroup("查看过滤明细") {
                                        Text(item.conditionSummary)
                                            .font(.system(.caption2, design: .monospaced))
                                            .textSelection(.enabled)
                                            .fixedSize(horizontal: false, vertical: true)
                                    }
                                } label: {
                                    HStack {
                                        VStack(alignment: .leading, spacing: 3) {
                                            Text("场次\(item.matchNumbers.prefix(6).joined(separator: ","))")
                                                .font(.headline.monospacedDigit())
                                            Text("第7场：1→1 · TXT \(item.finalBetCount)注")
                                                .font(.caption)
                                                .foregroundStyle(SequenceFilterTheme.textSecondary)
                                        }
                                        Spacer()
                                        Text(item.isTXTPassed ? "过关" : "未过")
                                            .font(.caption.bold())
                                            .foregroundStyle(item.isTXTPassed ? .green : .red)
                                    }
                                }
                            }
                        }

                        if !snapshot.failures.isEmpty {
                            Section("未计算成功（\(snapshot.failures.count)）") {
                                ForEach(snapshot.failures.sorted { $0.firstMatchNumber < $1.firstMatchNumber }) { failure in
                                    VStack(alignment: .leading, spacing: 4) {
                                        Text("场次\(failure.matchNumbers.joined(separator: ","))")
                                            .font(.headline.monospacedDigit())
                                        Text(failure.reason)
                                            .font(.caption)
                                            .foregroundStyle(.red)
                                    }
                                }
                            }
                        }
                    }
                } else {
                    VStack(spacing: 12) {
                        Image(systemName: "sum")
                            .font(.largeTitle)
                            .foregroundStyle(SequenceFilterTheme.textSecondary)
                        Text("尚未同步\(issue)结果")
                            .font(.headline)
                        Text("请先在Mac端完成计算并同步到手机。")
                            .font(.caption)
                            .foregroundStyle(SequenceFilterTheme.textSecondary)
                    }
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                }
            }
            .navigationTitle("\(issue)结果与奖金")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar {
                ToolbarItem(placement: .topBarTrailing) {
                    Button("完成") { isShowingHistoricalBatchResults = false }
                }
            }
        }
    }

