    private func historicalBatchTXTDetailPage(issue: String, item: Issue26094BatchItem) -> some View {
        let key = TXTQueryStatisticsCalculator.ticketKey(issue: issue, matchNumbers: item.matchNumbers)
        let content = sharedTXTQueryHistory.first {
            TXTQueryStatisticsCalculator.ticketKey(issue: $0.issue, matchNumbers: $0.matchNumbers) == key
        }?.txtContent ?? "TXT内容暂不可用，请重新计算\(issue)。"
        return ScrollView {
            Text(content)
                .font(.system(.caption, design: .monospaced))
                .frame(maxWidth: .infinity, alignment: .leading)
                .textSelection(.enabled)
                .padding()
