        .navigationTitle("场次\(item.matchNumbers.prefix(6).joined(separator: ","))")
        .navigationBarTitleDisplayMode(.inline)
    }
    private func historicalBatchStorageKey(for issue: String) -> String {
        "sequenceFilter.historicalBatch.\(issue).v2"
    }

    private func loadHistoricalBatchSnapshots() {
        for issue in historicalBatchIssues {
            guard let data = UserDefaults.standard.data(forKey: historicalBatchStorageKey(for: issue)),
                  let snapshot = try? JSONDecoder().decode(Issue26094BatchSnapshot.self, from: data),
                  snapshot.issue == issue else { continue }
            historicalBatchSnapshots[issue] = snapshot
            historicalBatchProgressMessages[issue] = snapshot.items.count == snapshot.expectedGroupCount
                && snapshot.failures.isEmpty
                ? "已载入完整结果：TXT过关\(snapshot.items.filter(\.isTXTPassed).count)/\(snapshot.expectedGroupCount)组。"
                : "已载入进度：成功\(snapshot.items.count)组，失败\(snapshot.failures.count)组。"
        }
    }

    private func persistHistoricalBatchSnapshot(_ snapshot: Issue26094BatchSnapshot) {
        historicalBatchSnapshots[snapshot.issue] = snapshot
        guard let data = try? JSONEncoder().encode(snapshot) else { return }
        UserDefaults.standard.set(data, forKey: historicalBatchStorageKey(for: snapshot.issue))
        UserDefaults.standard.synchronize()
        scheduleDurableBackup()
    }

    /// 保留条件Tab全部开关与范围，仅将本专项的固定场定义为：
    /// 第6场全包310，第7场场次号1、单选赛果1。
    private func historicalBatchConditionTemplateInput() -> String? {
        guard (try? FilterConfig.parse(generatedInput)) != nil else { return nil }
        var fields = generatedInput
            .split(separator: "|", omittingEmptySubsequences: false)
            .map(String.init)
        fields.removeAll { $0.contains(":") }
        let mergeIndex = fields.firstIndex {
            $0.uppercased().hasPrefix("MERGE")
        } ?? fields.endIndex
        fields.insert(contentsOf: ["999998:310", "999999:1"], at: mergeIndex)
        return fields.joined(separator: "|")
    }

    private func upsertHistoricalBatchHistories(
        sharedRecord: SharedTXTQueryRecord,
        prizeRecord: PrizeQueryRecord,
        counts: GlobalPrizeFilterCounts
    ) {
        let key = TXTQueryStatisticsCalculator.ticketKey(
            issue: sharedRecord.issue,
            matchNumbers: sharedRecord.matchNumbers
        )
        sharedTXTQueryHistory.removeAll {
            TXTQueryStatisticsCalculator.ticketKey(issue: $0.issue, matchNumbers: $0.matchNumbers) == key
        }
        sharedTXTQueryHistory.append(sharedRecord)

        if let index = prizeQueryHistory.firstIndex(where: {
            TXTQueryStatisticsCalculator.ticketKey(issue: $0.issue, matchNumbers: $0.matchNumbers) == key
        }) {
            prizeQueryHistory[index] = prizeRecord
        } else {
            prizeQueryHistory.append(prizeRecord)
        }
        globalFilterCountsByRecordID[prizeRecord.id] = counts
    }

    private func persistHistoricalBatchHistories() {
        if let data = try? JSONEncoder().encode(sharedTXTQueryHistory) {
            UserDefaults.standard.set(data, forKey: sharedTXTQueryHistoryStorageKey)
        }
        if let data = try? JSONEncoder().encode(prizeQueryHistory) {
            UserDefaults.standard.set(data, forKey: prizeQueryHistoryStorageKey)
        }
        globalFilterCacheConditionSignature = globalFilterConditionsSignature
        persistGlobalFilterCountCache()
        UserDefaults.standard.synchronize()
        scheduleDurableBackup()
    }

    @MainActor
    private func calculateHistoricalBatch(issue: String) async {
        guard historicalBatchIssues.contains(issue), calculatingHistoricalBatchIssue == nil else { return }
        #if !targetEnvironment(simulator)
        if historicalBatchSnapshots[issue] != nil {
            historicalBatchProgressMessages[issue] = "已载入电脑完成的\(issue)整批计算，手机不重算。"
            selectedHistoricalBatchIssue = issue
            isShowingHistoricalBatchResults = true
        } else {
            historicalBatchProgressMessages[issue] = "电脑计算结果尚未同步，请先在Mac完成计算并安装同步包。"
        }
        return
        #endif
        guard let templateInput = historicalBatchConditionTemplateInput() else {
            historicalBatchProgressMessages[issue] = "条件Tab当前配置无法解析，请先修正红色提示的条件。"
            return
        }

        calculatingHistoricalBatchIssue = issue
        defer { calculatingHistoricalBatchIssue = nil }
        let shardArgument = ProcessInfo.processInfo.arguments.first {
            $0.hasPrefix("--26094-shard=")
        }?.replacingOccurrences(of: "--26094-shard=", with: "")
        let shardParts = shardArgument?.split(separator: "/").compactMap { Int($0) }
        let shardIndex = shardParts?.count == 2 ? shardParts?[0] : nil
        let shardCount = shardParts?.count == 2 ? shardParts?[1] : nil
        let conditionSignature = globalFilterConditionsSignature
        let startedAt = Date()
        historicalBatchProgressMessages[issue] = "正在从500获取第\(issue)期全部场次…"

        var allMatches: [BeijingSingleMatch]?
        var downloadErrors: [String] = []
        for attempt in 1...3 where allMatches == nil {
            do {
                allMatches = try await FiveHundredBeijingSingleClient.fetchAllIssueMatches(issue: issue)
            } catch {
                downloadErrors.append("第\(attempt)次：\(error.localizedDescription)")
                if attempt < 3 {
                    historicalBatchProgressMessages[issue] = "整期数据第\(attempt)次获取失败，正在自动重试…"
                }
            }
        }
        guard let allMatches else {
            historicalBatchProgressMessages[issue] = "\(issue)整期数据获取失败：" + downloadErrors.joined(separator: "；")
            return
        }

        var matchesByNumber: [Int: BeijingSingleMatch] = [:]
        for match in allMatches {
            if let number = Int(match.matchNumber) { matchesByNumber[number] = match }
        }
        let maximumMatchNumber = matchesByNumber.keys.max() ?? 0
        let allStarts = HistoricalBatchPlanner.groupStarts(
            maximumMatchNumber: maximumMatchNumber
        )
        let starts: [Int]
        if let shardIndex, let shardCount,
           shardCount > 0, (0..<shardCount).contains(shardIndex) {
            starts = allStarts.enumerated().compactMap { index, start in
                index % shardCount == shardIndex ? start : nil
            }
        } else {
            starts = allStarts
        }
        let expectedGroupCount = allStarts.count
        let missingRequired = maximumMatchNumber > 0
            ? (1...maximumMatchNumber).filter { matchesByNumber[$0] == nil }
            : []
        guard missingRequired.isEmpty else {
            historicalBatchProgressMessages[issue] = "\(issue)整期数据不完整，缺少场次：\(missingRequired.map(String.init).joined(separator: "、"))。未开始过滤，不会留下半套结果。"
            return
        }

        let comprehensive = comprehensiveAnalysisFilterEnabled ? comprehensiveAnalysisProfile : nil
        let comprehensiveTolerance = comprehensiveAnalysisFilterEnabled
            ? (parsedComprehensiveAnalysisToleranceRange ?? 0...0)
            : 0...0
        let protectedProfile = protectedHistoryMaxCompressionEnabled
            ? protectedHistoryMaxCompressionProfile
            : nil
        let protectedTolerance = effectiveProtectedHistoryToleranceRange
        let protectedCap = effectiveProtectedHistoryBetCap
        let protectedPrefixes = protectedPrizeOutcomePrefixes
        let multiplier = validBetMultiplier ?? 1
        // 电脑维护计算可能因模拟器重启中断；条件签名一致时从已逐组
        // 落盘的快照续算，不重复消耗算力，也不会把半套结果下发到手机。
        let resumableItems: [Issue26094BatchItem]
        if let saved = historicalBatchSnapshots[issue],
           saved.issue == issue,
           saved.conditionSignature == conditionSignature,
           saved.expectedGroupCount == expectedGroupCount {
            resumableItems = saved.items.filter { starts.contains($0.firstMatchNumber) }
        } else {
            resumableItems = []
        }
        var items = resumableItems
        var failures: [Issue26094BatchFailure] = []
        var persistedABCD = UserDefaults.standard.dictionary(forKey: globalABCDCacheStorageKey)
            as? [String: String] ?? [:]
        // 并行电脑分片使用不重叠的ID区间，合并后计数缓存不会相互覆盖。
        var nextPrizeID = (prizeQueryHistory.map(\.id).max() ?? 0)
            + 1
            + (shardIndex ?? 0) * 1_000
        let completedStarts = Set(resumableItems.map(\.firstMatchNumber))

        for (offset, start) in starts.enumerated() {
            if completedStarts.contains(start) { continue }
            let sixNumbers = Array(start...(start + 5))
            let sixNumberStrings = sixNumbers.map(String.init)
            let sevenMatchNumbers = HistoricalBatchPlanner.ticketMatchNumbers(start: start)
            historicalBatchProgressMessages[issue] = "正在计算 \(offset + 1)/\(expectedGroupCount)：场次\(sixNumberStrings.joined(separator: ","))…"

            do {
                let groupMatches = try sixNumbers.map { number -> BeijingSingleMatch in
                    guard let match = matchesByNumber[number] else {
                        throw GoalModelError.matchNotFound(String(number))
                    }
                    return match
                }
                let mainMatches = Array(groupMatches.prefix(5))
                let analyses = try mainMatches.map(PoissonGoalModel.analyze)
                guard analyses.count == 5 else { throw GoalModelError.invalidResponse }
                let logic = analyses.map(\.recommendedLogic.displayName).joined()
                guard let config = CurrentConditionConfigFactory.make(
                    currentInput: templateInput,
                    historicalMatchNumbers: sevenMatchNumbers,
                    historicalABCD: logic
                ) else {
                    throw NSError(
                        domain: "Issue26094",
                        code: 1,
                        userInfo: [NSLocalizedDescriptionKey: "无法用条件Tab当前条件构建该组配置"]
                    )
                }
                guard QueryFinalityGate.permitsResult(matches: groupMatches, expectedCount: 6) else {
                    let blocked = groupMatches.filter {
                        !QueryFinalityGate.isFinallyEnded($0) && !$0.isPostponedOver12Hours
                    }.map(\.matchNumber)
                    throw NSError(
                        domain: "Issue26094",
                        code: 2,
                        userInfo: [NSLocalizedDescriptionKey: "比赛未最终结束，不允许查询出结果：\(blocked.joined(separator: "、"))"]
                    )
                }
                let publishedOutcomes = groupMatches.compactMap(QueryFinalityGate.resolvedOutcome)
                let autoPassedNumbers = groupMatches.filter(\.isPostponedOver12Hours).map(\.matchNumber)
                let probabilities = outcomeProbabilityMatrix(for: config, analyses: analyses)
                let spMatrix = outcomeSPMatrix(for: config, analyses: analyses)
                let marketShares = config.matchNumbers.map { number in
                    analyses.first { Int($0.match.matchNumber) == Int(number) }?
                        .match.marketBettingShares ?? []
                }
                let applyRelationships = shouldApplyRelationshipCondition(
                    for: config,
                    analyses: analyses
                )
                let generated = await Task.detached(priority: .userInitiated) {
                    SequenceFilterEngine.calculate(
                        config,
                        previousContext: nil,
                        currentOutcomeProbabilities: probabilities,
                        currentOutcomeSPs: spMatrix,
                        currentMarketBettingShares: marketShares,
                        applyPoissonRelationshipCondition: applyRelationships,
                        comprehensiveAnalysisProfile: comprehensive,
                        comprehensiveAnalysisToleranceRange: comprehensiveTolerance,
                        protectedHistoryProfile: protectedProfile,
                        protectedHistoryToleranceRange: protectedTolerance,
                        protectedHistoryBetCap: protectedCap,
                        protectedPrizeOutcomePrefixes: protectedPrefixes
                    )
                }.value
                let bets = deduplicatedTXTBets(generated.uniqueExpandedBets)
                let winningBet = bets.first { bet in
                    guard bet.count >= 6 else { return false }
                    return publishedOutcomes.enumerated().allSatisfy { index, outcome in
                        bet[index] == outcome
                    }
                }
                let passed = winningBet != nil
                let actualOutcomes = publishedOutcomes
                let prizeSP = groupMatches.map { match -> Double? in
                    if match.isPostponedOver12Hours { return 1.0 }
                    if let value = PrizeCalculator.selectedSP(for: match) { return value }
                    return nil
                }.compactMap { $0 }
                let calculatedPrize = prizeSP.count == 6
                    ? prizeSP.reduce(1.3, *)
                    : nil
                let rows = compressedTXTRows(matchNumbers: sevenMatchNumbers, bets: bets)
                let txtContent = [
                    "期号：\(issue)",
                    "TXT分组：总量",
                    "生成方式：\(issue)全场批量计算",
                    "过滤场次：\(sixNumberStrings.joined(separator: ","))",
                    "固定第7场：场次1→赛果1",
                    "投注倍数：\(multiplier)倍",
                    sharedTXTBody(rows: rows, multiplier: multiplier)
                ].joined(separator: "\n")
                let ticketKey = TXTQueryStatisticsCalculator.ticketKey(
                    issue: issue,
                    matchNumbers: sevenMatchNumbers
                )
                let existingShared = sharedTXTQueryHistory.first {
                    TXTQueryStatisticsCalculator.ticketKey(issue: $0.issue, matchNumbers: $0.matchNumbers) == ticketKey
                }
                let observed = publishedOutcomes.map(Optional.some)
                let sharedRecord = SharedTXTQueryRecord(
                    id: existingShared?.id ?? UUID(),
                    sharedAt: Date(),
                    issue: issue,
                    filename: "\(issue)-\(start)-\(start + 5)-total.txt",
                    txtContent: txtContent,
                    normalizedInput: generated.config.normalizedInput,
                    matchNumbers: sevenMatchNumbers,
                    betOutcomes: bets,
                    finalBetCount: bets.count,
                    conditionSignature: conditionSignature,
                    lastCheckedAt: Date(),
                    observedOutcomes: observed,
                    observedHandicaps: groupMatches.map(\.handicap),
                    verificationMessage: passed
                        ? "\(issue)批量计算已通过；延期超过12小时的场次\(autoPassedNumbers.joined(separator: "、"))按1、SP 1.00处理。"
                        : "\(issue)批量计算的TXT未匹配终局赛果；延期超过12小时的场次\(autoPassedNumbers.joined(separator: "、"))已按1处理。",
                    isFinalResult: true,
                    isHit: passed,
                    prizeAmount: passed ? calculatedPrize : nil,
                    prizeSPValues: prizeSP.count == 6 ? prizeSP : nil
                )
                let existingPrize = prizeQueryHistory.first {
                    TXTQueryStatisticsCalculator.ticketKey(issue: $0.issue, matchNumbers: $0.matchNumbers) == ticketKey
                }
                let prizeID = existingPrize?.id ?? nextPrizeID
                if existingPrize == nil { nextPrizeID += 1 }
                let conditionSnapshot = prizeSP.count == 6
                    ? makePrizeConditionSnapshot(
                        matches: groupMatches,
                        outcomes: actualOutcomes,
                        spValues: prizeSP,
                        label: "\(issue)批量计算·前6场实际赛果"
                    )
                    : makeStoredPrizeConditionSnapshot(
                        outcomes: actualOutcomes,
                        spValues: nil,
                        logicText: logic,
                        estimatedPrize: calculatedPrize,
                        label: "\(issue)批量计算·前6场实际赛果"
                    )
                let sevenOutcomes = actualOutcomes + [1]
                let prizeRecord = PrizeQueryRecord(
                    id: prizeID,
                    queriedAt: Date(),
                    issue: issue,
                    matchNumbers: sevenMatchNumbers,
                    handicaps: groupMatches.map(\.handicap) + [matchesByNumber[1]?.handicap],
                    isSettled: true,
                    amount: calculatedPrize ?? 0,
                    calculationLabel: "\(issue)批量计算·前6场奖金",
                    runSummary: PrizeCalculator.outcomeSummary(for: sevenOutcomes),
                    outcomes: sevenOutcomes,
                    seventhEstimates: nil,
                    seventhRunSummaries: nil,
                    conditionSnapshots: conditionSnapshot.map { [$0] }
                )
                let counts = GlobalPrizeFilterCounts(
                    before: 729,
                    removed: max(0, 729 - bets.count),
                    after: bets.count,
                    stageSummaries: generated.majorFilterStageSummaries,
                    outcomeSignature: actualOutcomes.map(String.init).joined(),
                    targetCoveredByFinalTXT: passed,
                    targetCoverageDetail: passed
                        ? nil
                        : "\(issue)批量生成的终局TXT未找到前6场实际赛果。"
                )
                upsertHistoricalBatchHistories(
                    sharedRecord: sharedRecord,
                    prizeRecord: prizeRecord,
                    counts: counts
                )
                let abcdKey = TXTQueryStatisticsCalculator.uniqueKey(
                    issue: issue,
                    matchNumbers: Array(sixNumberStrings.prefix(5))
                )
                persistedABCD[abcdKey] = logic
                let item = Issue26094BatchItem(
                    firstMatchNumber: start,
                    matchNumbers: sevenMatchNumbers,
                    logic: logic,
                    beforeBetCount: 729,
                    finalBetCount: bets.count,
                    actualOutcomes: actualOutcomes,
                    autoPassedMatchNumbers: autoPassedNumbers.isEmpty ? nil : autoPassedNumbers,
                    isTXTPassed: passed,
                    prizeAmount: calculatedPrize,
                    conditionSummary: generated.majorFilterStageSummaries.joined(separator: "\n"),
                    calculatedAt: Date()
                )
                items.append(item)
            } catch {
                failures.append(Issue26094BatchFailure(
                    firstMatchNumber: start,
                    matchNumbers: sixNumberStrings + ["1"],
                    reason: error.localizedDescription
                ))
            }

            let partial = Issue26094BatchSnapshot(
                issue: issue,
                conditionSignature: conditionSignature,
                fixedSeventhMatchNumber: "1",
                fixedSeventhOutcome: 1,
                expectedGroupCount: expectedGroupCount,
                generatedAt: startedAt,
                items: items,
                failures: failures
            )
            persistHistoricalBatchSnapshot(partial)
            UserDefaults.standard.set(persistedABCD, forKey: globalABCDCacheStorageKey)
            // 每5组保存一次完整TXT/奖金历史，兼顾断点保护和真机速度。
            if (offset + 1).isMultiple(of: 5) || offset + 1 == expectedGroupCount {
                persistHistoricalBatchHistories()
            }
            await Task.yield()
        }

        deduplicateSharedTXTQueryHistory()
        deduplicatePrizeQueryHistory()
        persistHistoricalBatchHistories()
        refreshHistoricalToleranceStatistics()
        refreshProtectedPrizeOutcomePrefixesCache()
        let finalSnapshot = Issue26094BatchSnapshot(
            issue: issue,
            conditionSignature: conditionSignature,
            fixedSeventhMatchNumber: "1",
            fixedSeventhOutcome: 1,
            expectedGroupCount: expectedGroupCount,
            generatedAt: startedAt,
            items: items,
            failures: failures
        )
        persistHistoricalBatchSnapshot(finalSnapshot)
        let passed = items.filter(\.isTXTPassed)
        historicalBatchProgressMessages[issue] = failures.isEmpty && items.count == expectedGroupCount
            ? "\(issue)全部\(expectedGroupCount)组已计算完成：TXT过关\(passed.count)组，过滤后总注数\(items.reduce(0) { $0 + $1.finalBetCount })注，结果已复制到奖金Tab。"
            : "\(issue)已计算\(items.count)/\(expectedGroupCount)组，其中\(failures.count)组数据不足；再次点击会重试整批。"
        archiveCurrentCalculationVersion(source: "\(issue)全场批量计算")
        selectedHistoricalBatchIssue = issue
        isShowingHistoricalBatchResults = true
    }

    private var uniqueTXTQueryRecords: [SharedTXTQueryRecord] {
        // 载入、导入和每次写入均通过 deduplicatedSharedTXTRecords，
        // 因此列表刷新时不必再重建 206 条字典并反复扫描投注。
        sharedTXTQueryHistory
    }

    private var txtQueryStatistics: TXTQueryStatistics {
        let currentRecords = uniqueTXTQueryRecords.filter { isCurrentConditionTXT($0) }
        let sevenOutcomeRows = currentRecords.compactMap(statisticSevenOutcomes)
        return TXTQueryStatistics(
            uniqueOrderCount: currentRecords.count,
            completedSevenOrderCount: sevenOutcomeRows.count,
            twoRunsAtLeastTwoCount: sevenOutcomeRows.filter {
                TXTQueryStatisticsCalculator.hasTwoSameResultRunsAtLeastTwo(sevenOutcomes: $0)
            }.count
        )
    }

    private func savedSeventhSingleOutcome(_ record: SharedTXTQueryRecord) -> Int? {
        guard record.matchNumbers.count == 7 else { return nil }
        let selections = Set(record.betOutcomes.compactMap { bet in
            bet.count == 7 ? bet[6] : nil
        })
        return selections.count == 1 ? selections.first : nil
    }

    /// 前6位取已查到的实际彩果，第7位取TXT内所有投注共用的单选。
    private func statisticSevenOutcomes(_ record: SharedTXTQueryRecord) -> [Int]? {
        guard record.matchNumbers.count == 7,
              let observed = record.observedOutcomes,
              observed.count >= 6 else { return nil }
        let firstSix = Array(observed.prefix(6))
        guard firstSix.allSatisfy({ $0 != nil }) else { return nil }
        guard let seventhSelection = savedSeventhSingleOutcome(record) else { return nil }
        return firstSix.compactMap { $0 } + [seventhSelection]
    }

    private func analyzeAllTXTQueryRecords() {
        let records = uniqueTXTQueryRecords.filter { isCurrentConditionTXT($0) }
        let sevenOutcomes = records.compactMap(statisticSevenOutcomes)
        let summaries = sevenOutcomes.compactMap { PrizeCalculator.outcomeSummary(for: $0) }
        let singles = records.compactMap(savedSeventhSingleOutcome)
        let singleCounts = Dictionary(grouping: singles, by: { $0 }).mapValues(\.count)
        let finalRecords = records.filter(\.isFinalResult)
        let finalEvaluations = finalRecords.map { ($0, sharedTXTUnderlyingConditionStatus(for: $0)) }
        let hitRecords = finalEvaluations.filter { $0.1.passes == true }.map(\.0)
        let missedRecords = finalEvaluations.filter { $0.1.passes == false }.map(\.0)
        let pendingConditionCount = finalEvaluations.filter { $0.1.passes == nil }.count
        let prizeAmounts = hitRecords.compactMap(\.prizeAmount).filter(\.isFinite)
        let duplicateCount = max(0, sharedTXTQueryHistory.count - records.count)
        let totalBets = records.reduce(0) {
            $0 + deduplicatedTXTBets($1.betOutcomes).count
        }
        let twoRunsCount = sevenOutcomes.filter {
            TXTQueryStatisticsCalculator.hasTwoSameResultRunsAtLeastTwo(sevenOutcomes: $0)
        }.count
        var lines = [
            "【TXT查询记录总览】",
            "全部保存：\(sharedTXTQueryHistory.count)条；按期号＋场次去重：\(records.count)单；重复保留：\(duplicateCount)条。",
            "去重后总注数：\(totalBets)注。",
            "已最终确认：\(finalRecords.count)单；统一通过：\(hitRecords.count)单；统一未通过：\(missedRecords.count)单；待判定：\(records.count - finalRecords.count + pendingConditionCount)单。",
            "第7场已保存单选：\(singles.count)单；胜3 \(singleCounts[3, default: 0])次；平1 \(singleCounts[1, default: 0])次；负0 \(singleCounts[0, default: 0])次。",
            "可统计完整7场：\(sevenOutcomes.count)单；数据不足：\(records.count - sevenOutcomes.count)单。",
            "连续胜/平/负中至少两项≥2：\(twoRunsCount)次。",
            "已命中且奖金完整：\(prizeAmounts.count)单；奖金合计 ¥\(decimal(prizeAmounts.reduce(0, +)))；平均 ¥\(decimal(prizeAmounts.isEmpty ? 0 : prizeAmounts.reduce(0, +) / Double(prizeAmounts.count)))。",
            "",
            "【7场彩果与连续条件】"
        ]
        if summaries.isEmpty {
            lines += ["尚无完整样本。点击各条记录的“确认是否命中”后会自动补全。"]
        } else {
            let allOutcomes = sevenOutcomes.flatMap { $0 }
            let outcomeCounts = Dictionary(grouping: allOutcomes, by: { $0 }).mapValues(\.count)
            lines += [
                "彩果总计：胜3 \(outcomeCounts[3, default: 0])场；平1 \(outcomeCounts[1, default: 0])场；负0 \(outcomeCounts[0, default: 0])场。",
                commonIntLine("胜总数", summaries.map(\.winCount)),
                commonIntLine("平总数", summaries.map(\.drawCount)),
                commonIntLine("负总数", summaries.map(\.lossCount)),
                commonIntLine("彩果种类", summaries.map(\.diversity)),
                commonIntLine("彩果和值", summaries.map(\.outcomeSum)),
                commonIntLine("隔场回返", summaries.map(\.returns)),
                commonIntLine("胜负直接切换", summaries.map(\.winLossSwitches)),
                commonIntLine("连续不败", summaries.map(\.nonLoss)),
                commonIntLine("连续不平", summaries.map(\.nonDraw)),
                commonIntLine("连续不胜", summaries.map(\.nonWin)),
                commonIntLine("连续胜", summaries.map(\.win)),
                commonIntLine("连续平", summaries.map(\.draw)),
                commonIntLine("连续负", summaries.map(\.loss))
            ]
        }
        lines += ["", "【每单明细（去重后）】"]
        lines += records.reversed().map { record in
            let single = savedSeventhSingleOutcome(record).map(String.init) ?? "?"
            let outcomes = statisticSevenOutcomes(record)?.map(String.init).joined() ?? "待补全"
            let finalStatus = sharedTXTUnderlyingConditionStatus(for: record).passes
            let state = record.isFinalResult
                ? (finalStatus == true ? "TXT/条件统一通过" : (finalStatus == false ? "TXT/条件统一未通过" : "待判定"))
                : "待确认"
            let prize = record.prizeAmount.map { "，奖金¥\(decimal($0))" } ?? ""
            return "第\(record.issue)期｜场次\(record.matchNumbers.joined(separator: ","))｜第7场单选\(single)｜7场彩果\(outcomes)｜\(state)\(prize)"
        }
        txtQueryStatisticsMessage = lines.joined(separator: "\n")
    }

