    private var conditionHandicapMatchNumbers: [String] {
        let numbers = currentFilteredMatchNumbers + [effectiveFixedFullMatchInput, singleMatchInput]
        var seen = Set<String>()
        return numbers.map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty && $0.allSatisfy(\.isNumber) && seen.insert($0).inserted }
    }

    private var conditionHandicapRequestKey: String {
        beijingSingleIssueInput + "|" + conditionHandicapMatchNumbers.joined(separator: ",")
    }

    @MainActor
    private func loadConditionHandicaps() async {
        let numbers = conditionHandicapMatchNumbers
        guard !numbers.isEmpty else { return }
        do {
            let input = beijingSingleIssueInput.trimmingCharacters(in: .whitespacesAndNewlines)
            let anchor = UserDefaults.standard.string(forKey: goalModelIssueStorageKey)
                ?? (input.allSatisfy(\.isNumber) ? input : "26092")
            let issue = try await FiveHundredBeijingSingleClient.resolveIssue(input: input, anchorIssue: anchor)
            let matches = try await FiveHundredBeijingSingleClient.fetchLiveMatches(
                issue: issue,
                matchNumbers: numbers
            )
            conditionHandicaps = Dictionary(uniqueKeysWithValues: matches.compactMap { match in
                match.handicap.map { (match.matchNumber, $0) }
            })
        } catch {
            // 浮层保留已获取的主场让球，不打断条件编辑。
        }
    }

    private func sharedTXTQueryRecordRow(
        _ record: SharedTXTQueryRecord,
        precomputedConditionStatus: (passes: Bool?, reasons: [String])? = nil
    ) -> some View {
        let cachedStatus = precomputedConditionStatus
        let fullStatus = cachedStatus.map { status in
            (
                text: status.passes == true
                    ? "TXT结果：通过；条件结果：同步通过。"
                    : (status.passes == false
                        ? "TXT结果：未通过；条件结果：同步未通过。"
                        : "TXT/条件统一结果：等待完整前6场赛果。"),
                passes: status.passes,
                failedDetails: status.reasons
            )
        }
        let conditionStatus = fullStatus ?? sharedTXTConditionStatus(for: record)
        let currentTXT = isCurrentConditionTXT(record)
        let manualInput = Binding<String>(
            get: {
                if let input = manualOutcomeInputsByRecordID[record.id] {
                    return input
                }
                let stored = record.observedOutcomes?
                    .prefix(6)
                    .compactMap { $0 }
                    .map(String.init)
                    .joined() ?? ""
                return stored.count == 6 ? stored : ""
            },
            set: { newValue in
                let filtered = newValue.filter { character in
                    character == "3" || character == "1" || character == "0"
                }
                manualOutcomeInputsByRecordID[record.id] = String(filtered.prefix(6))
            }
        )
        return VStack(alignment: .leading, spacing: 8) {
            HStack(alignment: .firstTextBaseline) {
                Text("第\(record.issue)期")
                    .font(.headline)
                Spacer()
                Text(record.sharedAt.formatted(date: .numeric, time: .shortened))
                    .font(.caption2)
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
            }
            Text("场次：" + displayedMatches(record.matchNumbers, handicaps: record.observedHandicaps))
                .font(.system(.caption, design: .monospaced))
            Text("\(record.finalBetCount)注 · \(record.filename)")
                .font(.caption)
                .foregroundStyle(SequenceFilterTheme.textSecondary)
            if record.matchNumbers.count > 6 {
                Text("命中判定只核对前6场，第7场不参与判定。")
                    .font(.caption.bold())
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
            }
            if let outcomes = record.observedOutcomes {
                let text = outcomes.map { $0.map(String.init) ?? "?" }.joined(separator: "、")
                Text("\(record.matchNumbers.count > 6 ? "当前前6场让球彩果" : "当前让球彩果")：\(text)")
                    .font(.system(.caption, design: .monospaced))
            }
            if !currentTXT {
                Label("旧条件TXT已失效：不再使用其命中、奖金或过关结论，请按当前条件重新生成/导入。", systemImage: "arrow.triangle.2.circlepath.circle.fill")
                    .font(.caption.bold())
                    .foregroundStyle(.orange)
                    .fixedSize(horizontal: false, vertical: true)
            } else if let message = record.verificationMessage {
                Label {
                    Text("TXT精确核对：" + message)
                        .font(.caption)
                        .fixedSize(horizontal: false, vertical: true)
                } icon: {
                    Image(systemName: record.isFinalResult
                        ? (conditionStatus.passes == true ? "checkmark.circle.fill" : (conditionStatus.passes == false ? "xmark.circle.fill" : "clock.badge.questionmark"))
                        : "clock.badge.questionmark")
                }
                .foregroundStyle(SequenceFilterTheme.textSecondary)
            }
            if currentTXT && record.isFinalResult {
                Text("说明：最终以当前这一份TXT为准；TXT有该赛果时两边同时通过，没有时两边同时未通过。")
                    .font(.caption2)
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
                    .fixedSize(horizontal: false, vertical: true)
            }
            Label {
                Text(conditionStatus.text)
                    .font(.caption.weight(.semibold))
                    .fixedSize(horizontal: false, vertical: true)
            } icon: {
                Image(systemName: conditionStatus.passes == true
                    ? "checkmark.seal.fill"
                    : (conditionStatus.passes == false ? "xmark.seal.fill" : "exclamationmark.triangle.fill"))
            }
            .foregroundStyle(SequenceFilterTheme.textSecondary)
            if !conditionStatus.failedDetails.isEmpty {
                DisclosureGroup("查看未通过原因（\(conditionStatus.failedDetails.count)项）") {
                    ForEach(Array(conditionStatus.failedDetails.enumerated()), id: \.offset) { _, detail in
                        Text(detail)
                            .font(.system(.caption, design: .monospaced))
                            .foregroundStyle(SequenceFilterTheme.textSecondary)
                            .fixedSize(horizontal: false, vertical: true)
                    }
                }
                .tint(SequenceFilterTheme.accent)
            }
            if currentTXT && record.isFinalResult, conditionStatus.passes == true {
                if let amount = record.prizeAmount {
                    VStack(alignment: .leading, spacing: 3) {
                        Text("命中奖金合计：¥\(String(format: "%.2f", amount))")
                            .font(.headline)
                            .foregroundStyle(SequenceFilterTheme.textSecondary)
                        if let values = record.prizeSPValues, values.count == 6 {
                            Text(values.map { String(format: "%.2f", $0) }.joined(separator: " × ") + " × 1.3")
                                .font(.system(.caption2, design: .monospaced))
                                .foregroundStyle(SequenceFilterTheme.textSecondary)
                                .fixedSize(horizontal: false, vertical: true)
                        } else {
                            Text("按每个选项命中，已按中几个 × 每个组合奖金逐注合计")
                                .font(.caption)
                                .foregroundStyle(SequenceFilterTheme.textSecondary)
                        }
                    }
                } else {
                    Text("已命中，但当前赔率不完整，暂无法计算金额；稍后再点“确认是否命中”即可补算。")
                        .font(.caption)
                        .foregroundStyle(SequenceFilterTheme.textSecondary)
                        .fixedSize(horizontal: false, vertical: true)
                }
            }
            VStack(alignment: .leading, spacing: 6) {
                Text("手动输入前6场赛果")
                    .font(.caption.bold())
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
                HStack(spacing: 8) {
                    TextField("连续6位，例如310130", text: manualInput)
                        .font(.system(.body, design: .monospaced).weight(.semibold))
                        .keyboardType(.numberPad)
                        .textInputAutocapitalization(.never)
                    Button("判断命中") {
                        Task {
                            await applyManualSharedTXTQueryResult(
                                manualOutcomeInputsByRecordID[record.id] ?? manualInput.wrappedValue,
                                to: record.id
                            )
                        }
                    }
                    .buttonStyle(PatternedActionButtonStyle())
                    .disabled(!currentTXT || manualInput.wrappedValue.count != 6)
                }
                if !currentTXT {
                    Text("手动命中已禁用：该TXT不属于条件Tab当前版本。")
                        .font(.caption2)
                        .foregroundStyle(.orange)
                }
                Text("只接受3/1/0。点击后会先联网确认六场已最终结束，再以官方终局赛果核对TXT；明确延期超过12小时的场次按1计算。")
                    .font(.caption2)
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
            }
            .padding(10)
            .background(SequenceFilterTheme.accent.opacity(0.12), in: RoundedRectangle(cornerRadius: 10))
            Button {
                Task { await refreshSharedTXTRecordUsingCurrentConditions(record.id) }
            } label: {
                HStack {
                    Spacer()
                    if verifyingSharedTXTRecordIDs.contains(record.id)
                        || refreshingSharedTXTRecordIDs.contains(record.id) {
                        ProgressView().padding(.trailing, 6)
                    }
                    Text(
                        verifyingSharedTXTRecordIDs.contains(record.id)
                            || refreshingSharedTXTRecordIDs.contains(record.id)
                            ? "正在按最新条件重建并查询…"
                            : "按全部最新条件重新生成并确认"
                    )
                    Spacer()
                }
            }
            .buttonStyle(PatternedActionButtonStyle())
            .disabled(
                verifyingSharedTXTRecordIDs.contains(record.id)
                    || refreshingSharedTXTRecordIDs.contains(record.id)
            )
            if record.txtContent != nil {
                HStack(spacing: 6) {
                    ForEach([TXTSharePart.total, .a, .b, .c], id: \.label) { part in
                        Button {
                            let partContent = queryTXTContent(record: record, part: part)
                            txtPreview = makeTXTPreview(
                                title: "\(record.filename)-\(part.label)",
                                content: partContent,
                                observedOutcomes: record.observedOutcomes,
                                editingRecord: record, part: part
                            )
                        } label: {
                            Text("\(part.label)查看")
                                .frame(maxWidth: .infinity)
                        }
                    }
                }
                .buttonStyle(ColorfulOutlineButtonStyle())

                HStack(spacing: 6) {
                    ForEach([TXTSharePart.e, .f], id: \.label) { part in
                        Button {
                            let partContent = queryTXTContent(record: record, part: part)
                            txtPreview = makeTXTPreview(
                                title: "\(record.filename)-\(part.label)",
                                content: partContent,
                                observedOutcomes: record.observedOutcomes,
                                editingRecord: record, part: part
                            )
                        } label: {
                            Text("\(part.label)查看")
                                .frame(maxWidth: .infinity)
                        }
                    }
                }
                .buttonStyle(ColorfulOutlineButtonStyle())
                .accessibilityHint("E最多\(SequenceFilterEngine.eTXTMaximumRows)条投注行，其余完整投注行放入F，与输入页使用相同分配")
            }
        }
        .padding(.vertical, 5)
    }

    private func deleteSharedTXTRecord(_ id: UUID) {
        sharedTXTQueryHistory.removeAll { $0.id == id }
        verifyingSharedTXTRecordIDs.remove(id)
        refreshingSharedTXTRecordIDs.remove(id)
        manualOutcomeInputsByRecordID.removeValue(forKey: id)
        saveSharedTXTQueryHistory()
    }

    private var prizeFirstScreenConditionSummary: String {
        if usesVIP11FrontFiveMappedSum {
            let probabilityLine = usesVIP12ProbabilityReduction
                ? "\n\(vip11FamilyVersionLabel)联合概率减注：\(vip12ProbabilityReductionEnabled ? "开（至少10%）" : "关")"
                : ""
            return "\(vip11FamilyVersionLabel)：只有234判定值和值S=\(sumInput)计算6场\nM与其余VIP9条件只计算前5场；第6场保留310\(probabilityLine)\n奖金按六场项目换算SP连乘×1.3"
        }
        let outcome = OutcomeCondition.editorCases.compactMap { condition -> String? in
            guard outcomeConditionEnabled[condition] == true else { return nil }
            return "\(condition.title)\(outcomeConditionInputs[condition] ?? "-")"
        }.joined(separator: "、")
        return [
            "基础：S \(sumInput)，M \(displacementInput)，σ²≤\(varianceInput)，值2≤\(valueTwoMaximumInput)，P_tr≥\(transitionMinimumInput)%，B \(breakpointInput)",
            "奖金R：\(prizeRoughnessRangeInput)；SP和值/乘积：\(prizeSPRangeFilterEnabled ? prizeSPSumRangeInput + " / " + prizeSPProductRangeInput : "关")",
            "彩果：\(outcome.isEmpty ? "未开启" : outcome)",
            "连续彩果：\(consecutiveRunsEnabled ? "不败\(nonLossRunInput)、不平\(nonDrawRunInput)、不胜\(nonWinRunInput)，容错\(consecutiveRunToleranceInput)" : "关")",
            "奖金分析总容错：\(prizeConditionToleranceInput)项（只影响奖金模块）"
        ].joined(separator: "\n")
    }

