    /// 直接核对当前查询Cell自己的TXT。不能借用同期其他第7场记录的TXT，
    /// 从而保证页面显示“条件通过”时，用户正在查看的这份TXT内一定有赛果。
    private func directTXTCoverageAssessment(
        for sharedRecord: SharedTXTQueryRecord,
        fallbackOutcomes: [Int]? = nil
    ) -> (passes: Bool?, detail: String) {
        guard isCurrentConditionTXT(sharedRecord) else {
            return (false, "TXT覆盖=待重算（当前记录属于旧条件）")
        }
        guard sharedRecord.isFinalResult else {
            return (nil, "TXT覆盖=比赛未全部最终结束，禁止返回结果")
        }
        let stored = Array((sharedRecord.observedOutcomes ?? []).prefix(6))
        let target: [Int]?
        if stored.count == 6, stored.allSatisfy({ $0 != nil }) {
            target = stored.compactMap { $0 }
        } else if let fallbackOutcomes, fallbackOutcomes.count >= 6 {
            target = Array(fallbackOutcomes.prefix(6))
        } else {
            target = nil
        }
        guard let target else {
            return (nil, "TXT覆盖=等待完整前6场赛果")
        }
        let covered = sharedRecord.betOutcomes.contains { bet in
            bet.count >= 6 && Array(bet.prefix(6)) == target
        }
        return covered
            ? (true, "TXT覆盖=通过（当前TXT已找到赛果\(target.map(String.init).joined())）")
            : (false, "TXT覆盖=未通过（当前TXT找不到赛果\(target.map(String.init).joined())）")
    }

    /// 查询页以当前Cell自己的TXT精确覆盖为唯一最终结果。
    /// 条件结果同步镜像TXT结果，不再产生第二套通过/未通过。
    private func sharedTXTConditionStatus(
        for sharedRecord: SharedTXTQueryRecord
    ) -> (text: String, passes: Bool?, failedDetails: [String]) {
        // 最终核对结果已经与这份 TXT 一起持久化。列表滚动时直接使用，
        // 避免每个 Cell 再扫描全部奖金历史、数百注以及重放全套条件。
        if isCurrentConditionTXT(sharedRecord),
           sharedRecord.isFinalResult,
           let storedResult = sharedRecord.isHit {
            if storedResult {
                return ("TXT结果：通过；条件结果：同步通过。", true, [])
            }
            let savedReason = sharedRecord.verificationMessage?
                .trimmingCharacters(in: .whitespacesAndNewlines)
            return (
                "TXT结果：未通过；条件结果：同步未通过。",
                false,
                savedReason.map { [$0] } ?? ["已保存的TXT精确核对结果为未通过。"]
            )
        }
        guard sharedRecord.isFinalResult else {
            return ("TXT/条件统一结果：比赛未全部最终结束，暂不判定。", nil, [])
        }
        let key = TXTQueryStatisticsCalculator.ticketKey(
            issue: sharedRecord.issue,
            matchNumbers: sharedRecord.matchNumbers
        )
        let record = uniquePrizeQueryRecords.filter({
            TXTQueryStatisticsCalculator.ticketKey(issue: $0.issue, matchNumbers: $0.matchNumbers) == key
        }).max(by: {
            let leftScore = prizeRecordCompletenessScore($0)
            let rightScore = prizeRecordCompletenessScore($1)
            return leftScore == rightScore ? $0.queriedAt < $1.queriedAt : leftScore < rightScore
        })
        let directCoverage = directTXTCoverageAssessment(
            for: sharedRecord,
            fallbackOutcomes: record?.outcomes
        )
        if directCoverage.passes == nil {
            return ("TXT/条件统一结果：等待完整前6场赛果。", nil, [])
        }
        guard directCoverage.passes == true else {
            let rootReasons = sharedTXTRootFailureReasons(for: sharedRecord)
            return (
                "TXT结果：未通过；条件结果：同步未通过。",
                false,
                rootReasons
            )
        }
        return ("TXT结果：通过；条件结果：同步通过。", true, [])
    }

    /// 查询页统计与Cell使用完全相同的端到端口径，禁止出现
    /// “条件通过，但当前TXT未通过”的两个数字。
    private func sharedTXTUnderlyingConditionStatus(
        for sharedRecord: SharedTXTQueryRecord
    ) -> (passes: Bool?, reasons: [String]) {
        let status = sharedTXTConditionStatus(for: sharedRecord)
        return (status.passes, status.failedDetails)
    }

    /// TXT未通过时重放当前条件，只返回真正拦截该组合的根因。
    /// “TXT里没找到”只是核对现象，不得冒充失败原因。
    private func sharedTXTRootFailureReasons(for record: SharedTXTQueryRecord) -> [String] {
        guard isCurrentConditionTXT(record) else {
            return ["根因暂不可判定：该TXT属于旧条件，须按条件Tab当前版本重新生成"]
        }
        guard let config = try? FilterConfig.parse(record.normalizedInput) else {
            return ["根因暂不可判定：该TXT缺少可重放的完整条件"]
        }
        let outcomes = record.observedOutcomes.map {
            Array($0.prefix(6)).compactMap { $0 }
        }
        var reasons = maintenanceFinalOutcomeFailureReasons(
            storedOutcomes: outcomes,
            matchNumbers: record.matchNumbers,
            config: config,
            protectedProfile: protectedHistoryMaxCompressionEnabled
                ? protectedHistoryMaxCompressionProfile
                : nil,
            protectedTolerance: effectiveProtectedHistoryToleranceRange
        )
        if reasons.isEmpty {
            reasons = ["未保存该TXT的逐阶段生成记录，须重新生成后核对实际淘汰阶段"]
        }
        return reasons
    }

    private func sharedTXTFailureDetails(for record: SharedTXTQueryRecord) -> [String] {
        sharedTXTRootFailureReasons(for: record).map { reason in
            reason.hasPrefix("根因") ? reason : "根因：" + reason
        }
    }

    private func prizeTXTFailureDetails(for record: PrizeQueryRecord) -> [String] {
        prizeRootFailureReasons(for: record).map { reason in
            reason.hasPrefix("根因") ? reason : "根因：" + reason
        }
    }

