    private var globalPrizeAnswersPage: some View {
        let records = uniquePrizeQueryRecords
        let passedRecords = records.filter(globalPrizeRecordPasses)
        let failedRecords = records.filter { !globalPrizeRecordPasses($0) }
        // 两组统计引用同一套最终判定，数量和逐条结果必须完全一致。
        let txtPassedRecords = passedRecords
        let txtFailedRecords = failedRecords
        let conditionResults = records.map { ($0, prizeUnderlyingConditionStatus(for: $0)) }
        let conditionPassedCount = conditionResults.filter { $0.1.passes }.count
        let conditionFailedResults = conditionResults.filter { !$0.1.passes }
        let conditionSummaries = globalConditionFilterSummaries(for: records)
        let totalPrize = passedRecords.compactMap(sixMatchPrizeAmount).reduce(0, +)
        let cachedFilterCounts = records.compactMap(globalFilterCounts)
        let averageOneTimesBetCount = cachedFilterCounts.isEmpty
            ? nil
            : Double(cachedFilterCounts.reduce(0) { $0 + $1.after }) / Double(cachedFilterCounts.count)
        return NavigationStack {
            List {
                Section("全局汇总") {
                    if let averageOneTimesBetCount {
                        LabeledContent("平均\(prizeDisplayMultiplier)倍") {
                            Text("\(String(format: "%.1f", averageOneTimesBetCount))注 · ¥\(String(format: "%.2f", prizeDisplayedAmount(averageOneTimesBetCount * 2)))")
                                .font(.headline.monospacedDigit())
                                .foregroundStyle(SequenceFilterTheme.textSecondary)
                        }
                        Text("按\(cachedFilterCounts.count)个已有过滤结果的Cell取平均；每注2元，再乘\(prizeDisplayMultiplier)倍。")
                            .font(.caption2)
                            .foregroundStyle(SequenceFilterTheme.textSecondary)
                    } else {
                        LabeledContent("平均\(prizeDisplayMultiplier)倍", value: "待生成过滤结果")
                    }
                    LabeledContent("过滤前总注数", value: "\(records.count)注")
                    LabeledContent("过滤掉", value: "\(failedRecords.count)注")
                    LabeledContent("过滤后总注数", value: "\(passedRecords.count)注")
                    LabeledContent("未通过/数据不足", value: "\(failedRecords.count)注")
                    Divider()
                    LabeledContent("TXT通过总数", value: "\(txtPassedRecords.count)条")
                    LabeledContent("条件通过总数", value: "\(conditionPassedCount)条")
                    LabeledContent("TXT未通过总数", value: "\(txtFailedRecords.count)条")
                    LabeledContent("条件未通过总数", value: "\(conditionFailedResults.count)条")
                    LabeledContent("奖金合计（\(prizeDisplayMultiplier)倍）", value: "¥\(String(format: "%.2f", prizeDisplayedAmount(totalPrize)))")
                    Text("最终以当前版本TXT为唯一结果：实际前6场赛果在TXT中，TXT通过与条件通过同时成立；不在则同时未通过。第7场不参与精确赛果核对。")
                        .font(.caption)
                        .foregroundStyle(SequenceFilterTheme.textSecondary)
                }
                if !conditionSummaries.isEmpty {
                    Section("最新条件逐项过滤统计") {
                        ForEach(conditionSummaries) { summary in
                            VStack(alignment: .leading, spacing: 3) {
                                Text(summary.name)
                                    .font(.subheadline.weight(.semibold))
                                HStack(spacing: 10) {
                                    Text("过滤\(summary.filtered)条")
                                        .foregroundStyle(SequenceFilterTheme.textSecondary)
                                    Text("通过\(summary.passed)条")
                                        .foregroundStyle(SequenceFilterTheme.textSecondary)
                                    if summary.unavailable > 0 {
                                        Text("数据不足\(summary.unavailable)条")
                                            .foregroundStyle(SequenceFilterTheme.textSecondary)
                                    }
                                }
                                .font(.system(.caption, design: .monospaced).weight(.semibold))
                            }
                            .padding(.vertical, 2)
                        }
                        Text("普通条件按同一批去重记录逐项独立统计；历史综合分析和大压缩也使用当前开关、当前范围及每条记录自己的ABCD。“TXT精确覆盖”是最终必过项，不参与容错；未覆盖的记录绝不进入通过分组。")
                            .font(.caption2)
                            .foregroundStyle(SequenceFilterTheme.textSecondary)
                    }
                }
                if !txtFailedRecords.isEmpty {
                    Section("TXT未通过原因（\(txtFailedRecords.count)条）") {
                        ForEach(txtFailedRecords.reversed()) { record in
                            DisclosureGroup("第\(record.issue)期 · \(record.matchNumbers.prefix(6).joined(separator: ","))") {
                                ForEach(Array(prizeTXTFailureDetails(for: record).enumerated()), id: \.offset) { _, reason in
                                    Text(reason)
                                        .font(.system(.caption, design: .monospaced))
                                        .foregroundStyle(SequenceFilterTheme.textSecondary)
                                        .fixedSize(horizontal: false, vertical: true)
                                }
                            }
                            .tint(SequenceFilterTheme.accent)
                        }
                    }
                }
                if !conditionFailedResults.isEmpty {
                    Section("条件未通过原因（\(conditionFailedResults.count)条）") {
                        ForEach(conditionFailedResults.reversed(), id: \.0.id) { record, status in
                            DisclosureGroup("第\(record.issue)期 · \(record.matchNumbers.prefix(6).joined(separator: ","))") {
                                ForEach(Array(status.reasons.enumerated()), id: \.offset) { _, reason in
                                    Text(reason)
                                        .font(.system(.caption, design: .monospaced))
                                        .foregroundStyle(SequenceFilterTheme.textSecondary)
                                        .fixedSize(horizontal: false, vertical: true)
                                }
                            }
                            .tint(SequenceFilterTheme.accent)
                        }
                    }
                }
                Section("TXT命中（\(passedRecords.count)）") {
                    ForEach(passedRecords.reversed()) { record in
                        prizeTwoRunsAtLeastTwoRow(record, showGlobalFilterStats: true)
                    }
                }
                if !failedRecords.isEmpty {
                    Section("TXT未命中或数据不足（\(failedRecords.count)）") {
                        ForEach(failedRecords.reversed()) { record in
                            prizeTwoRunsAtLeastTwoRow(record, showGlobalFilterStats: true)
                        }
                    }
                }
            }
            .navigationTitle("全局答案")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar(.visible, for: .navigationBar)
            .toolbar {
                ToolbarItem(placement: .topBarLeading) {
                    Button {
                        isShowingGlobalPrizeAnswers = false
                    } label: {
                        Label("返回", systemImage: "chevron.left")
                    }
                }
            }
        }
    }

    private func globalConditionFilterSummaries(
        for records: [PrizeQueryRecord]
    ) -> [GlobalConditionFilterSummary] {
        var orderedNames: [String] = []
        var values: [String: (filtered: Int, passed: Int, evaluated: Int)] = [:]
        for record in records {
            guard let snapshot = record.conditionSnapshots?.first,
                  let config = globalFilterConfig(for: record) else { continue }
            let evaluations = globalConditionEvaluations(
                snapshot,
                config: config,
                usesPrizeOverrides: false,
                mergeMainFilterConditions: false
            )
            for (name, passes) in evaluations {
                if values[name] == nil { orderedNames.append(name) }
                var counts = values[name] ?? (0, 0, 0)
                counts.evaluated += 1
                if passes { counts.passed += 1 } else { counts.filtered += 1 }
                values[name] = counts
            }
        }
        var summaries = orderedNames.compactMap { name -> GlobalConditionFilterSummary? in
            guard let counts = values[name] else { return nil }
            return GlobalConditionFilterSummary(
                name: name,
                filtered: counts.filtered,
                passed: counts.passed,
                unavailable: max(0, records.count - counts.evaluated)
            )
        }
        if comprehensiveAnalysisFilterEnabled {
            var filtered = 0
            var passed = 0
            var evaluated = 0
            for record in records {
                guard let snapshot = record.conditionSnapshots?.first,
                      let config = globalFilterConfig(for: record),
                      comprehensiveAnalysisFailureCount(snapshot, config: config) != nil,
                      parsedComprehensiveAnalysisToleranceRange != nil else { continue }
                evaluated += 1
                if comprehensiveAnalysisPasses(snapshot, config: config) {
                    passed += 1
                } else {
                    filtered += 1
                }
            }
            summaries.append(GlobalConditionFilterSummary(
                name: "历史综合分析",
                filtered: filtered,
                passed: passed,
                unavailable: max(0, records.count - evaluated)
            ))
        }
        if protectedHistoryMaxCompressionEnabled,
           let profile = protectedHistoryMaxCompressionProfile {
            let evaluatedRecords = records.filter {
                ($0.conditionSnapshots?.first?.outcomes.count ?? 0) >= 6
                    && globalFilterConfig(for: $0) != nil
            }
            let passed = evaluatedRecords.filter {
                protectedHistoryProfilePasses($0, profile: profile)
            }.count
            summaries.append(GlobalConditionFilterSummary(
                name: "大压缩（\(profile.rules.count)项通用范围）",
                filtered: evaluatedRecords.count - passed,
                passed: passed,
                unavailable: records.count - evaluatedRecords.count
            ))
        }
        if universal150CompressionEnabled {
            let evaluatedRecords = records.filter {
                ($0.conditionSnapshots?.first?.outcomes.count ?? 0) >= 6
                    && globalFilterConfig(for: $0) != nil
            }
            let passed = evaluatedRecords.filter { record in
                guard let snapshot = record.conditionSnapshots?.first,
                      let config = globalFilterConfig(for: record) else { return false }
                return SequenceFilterEngine.passesUniversal150Compression(
                    fullOutcomes: Array(snapshot.outcomes.prefix(6)),
                    config: config
                )
            }.count
            summaries.append(GlobalConditionFilterSummary(
                name: "通用150注统计压缩",
                filtered: evaluatedRecords.count - passed,
                passed: passed,
                unavailable: records.count - evaluatedRecords.count
            ))
        }
        if effectiveUniversal247ToleranceEnabled {
            let evaluatedRecords = records.filter {
                ($0.conditionSnapshots?.first?.outcomes.count ?? 0) >= 6
            }
            let passed = evaluatedRecords.filter { record in
                guard let outcomes = record.conditionSnapshots?.first?.outcomes,
                      let config = globalFilterConfig(for: record) else { return false }
                if SequenceFilterEngine.usesVIP4Model(
                    threshold: config.universal247ToleranceThreshold
                ) || SequenceFilterEngine.usesVIP3Model(
                    threshold: config.universal247ToleranceThreshold
                ) || SequenceFilterEngine.usesVIP2Model(
                    threshold: config.universal247ToleranceThreshold
                ) {
                    // VIP2/VIP3必须带当期让球对照表赔率重放；历史Cell缺少该上下文时，
                    // 直接以同期同场次的最终TXT精确覆盖为准。
                    return txtCoverageAssessment(for: record).passes
                }
                return SequenceFilterEngine.passesUniversal247Tolerance(
                    fullOutcomes: Array(outcomes.prefix(6)),
                    threshold: config.universal247ToleranceThreshold,
                    logic: config.logic,
                    productSumV10Top150Enabled: config.productSumV10Top150Enabled
                )
            }.count
            summaries.append(GlobalConditionFilterSummary(
                name: SequenceFilterEngine.universalCompressionStageName(
                    threshold: Double(universal247ToleranceThresholdInput)
                ),
                filtered: evaluatedRecords.count - passed,
                passed: passed,
                unavailable: records.count - evaluatedRecords.count
            ))
        }
        let txtEvaluatedRecords = records.filter { ($0.outcomes?.count ?? 0) >= 6 }
        let txtPassed = txtEvaluatedRecords.filter { txtCoverageAssessment(for: $0).passes }.count
        summaries.append(GlobalConditionFilterSummary(
            name: "TXT精确覆盖（最终必过项）",
            filtered: txtEvaluatedRecords.count - txtPassed,
            passed: txtPassed,
            unavailable: records.count - txtEvaluatedRecords.count
        ))
        return summaries
    }

    private func globalPrizeRecordPasses(_ record: PrizeQueryRecord) -> Bool {
        // 奖金页与查询页只保留一套最终结论：以当前TXT精确覆盖为准。
        prizeUnderlyingConditionStatus(for: record).passes
    }

    /// 全局答案的“条件结果”镜像当前TXT精确覆盖结果。
    private func prizeUnderlyingConditionStatus(
        for record: PrizeQueryRecord
    ) -> (passes: Bool, reasons: [String]) {
        let txtCoverage = txtCoverageAssessment(for: record)
        return txtCoverage.passes ? (true, []) : (false, prizeRootFailureReasons(for: record))
    }

    private func prizeRootFailureReasons(for record: PrizeQueryRecord) -> [String] {
        guard let config = globalFilterConfig(for: record) else {
            return ["根因暂不可判定：缺少可重放的完整条件"]
        }
        var reasons = maintenanceFinalOutcomeFailureReasons(
            storedOutcomes: record.outcomes,
            matchNumbers: record.matchNumbers,
            config: config,
            protectedProfile: protectedHistoryMaxCompressionEnabled
                ? protectedHistoryMaxCompressionProfile
                : nil,
            protectedTolerance: effectiveProtectedHistoryToleranceRange
        )
        if reasons.isEmpty {
            reasons = ["未保存该TXT的逐阶段生成记录，须重新生成后核对实际淘汰阶段"]
        }
        return reasons
    }

    /// 最终“通过”必须是端到端的：同期号、同场次的TXT中确实包含该前6场赛果。
    private func txtCoverageAssessment(
        for record: PrizeQueryRecord
    ) -> (passes: Bool, detail: String) {
        guard let outcomes = record.outcomes, outcomes.count >= 6 else {
            return (false, "TXT覆盖=无法核对（缺少完整前6场赛果）")
        }
        let key = TXTQueryStatisticsCalculator.ticketKey(
            issue: record.issue,
            matchNumbers: Array(record.matchNumbers.prefix(6))
        )
        let matchingRecords = uniqueTXTQueryRecords.filter {
            TXTQueryStatisticsCalculator.ticketKey(
                issue: $0.issue,
                matchNumbers: Array($0.matchNumbers.prefix(6))
            ) == key
        }
        guard let shared = matchingRecords
            .filter({ isCurrentConditionTXT($0) })
            .max(by: { $0.sharedAt < $1.sharedAt }) else {
            if !matchingRecords.isEmpty {
                return (false, "TXT覆盖=待重算（同期同场TXT属于旧条件，已禁止复用）")
            }
            return (false, "TXT覆盖=未通过（找不到同期号＋相同前6场TXT）")
        }
        let target = Array(outcomes.prefix(6))
        let covered = shared.betOutcomes.contains { bet in
            bet.count >= 6 && Array(bet.prefix(6)) == target
        }
        return covered
            ? (true, "TXT覆盖=通过（已找到赛果\(target.map(String.init).joined())）")
            : (false, "TXT覆盖=未通过（TXT中找不到赛果\(target.map(String.init).joined())）")
    }

    private func prizeRecordPasses(
        _ record: PrizeQueryRecord,
        excludesHistoricalPairing: Bool
    ) -> Bool {
        guard baselinePrizeRecordPasses(
            record,
            excludesHistoricalPairing: excludesHistoricalPairing
        ) else { return false }
        guard protectedHistoryMaxCompressionEnabled,
              let profile = protectedHistoryMaxCompressionProfile else { return true }
        return protectedHistoryProfilePasses(record, profile: profile)
    }

    private func baselineGlobalPrizeRecordPasses(_ record: PrizeQueryRecord) -> Bool {
        baselinePrizeRecordPasses(record, excludesHistoricalPairing: true)
    }

    private func baselinePrizeRecordPasses(
        _ record: PrizeQueryRecord,
        excludesHistoricalPairing: Bool
    ) -> Bool {
        guard let snapshot = record.conditionSnapshots?.first,
              let config = globalFilterConfig(
                for: record,
                excludesHistoricalPairing: excludesHistoricalPairing
              ) else { return false }
        let failureCount = globalConditionEvaluations(
            snapshot,
            config: config,
            usesPrizeOverrides: false,
            mergeMainFilterConditions: true
        ).filter { !$0.1 }.count
        let basePasses = config.allConditionsToleranceEnabled
            ? config.allConditionsToleranceRange.contains(failureCount)
            : failureCount == 0
        let universal150Passes = !config.universal150CompressionEnabled
            || SequenceFilterEngine.passesUniversal150Compression(
                fullOutcomes: Array(snapshot.outcomes.prefix(6)),
                config: config
            )
        let universal247Passes = !config.universal247ToleranceEnabled
            || SequenceFilterEngine.usesVIP4Model(
                threshold: config.universal247ToleranceThreshold
            )
            || SequenceFilterEngine.usesVIP3Model(
                threshold: config.universal247ToleranceThreshold
            )
            || SequenceFilterEngine.usesVIP2Model(
                threshold: config.universal247ToleranceThreshold
            )
            || SequenceFilterEngine.passesUniversal247Tolerance(
                fullOutcomes: Array(snapshot.outcomes.prefix(6)),
                threshold: config.universal247ToleranceThreshold,
                logic: config.logic,
                productSumV10Top150Enabled: config.productSumV10Top150Enabled
            )
        return basePasses
            && comprehensiveAnalysisPasses(snapshot, config: config)
            && universal247Passes
            && universal150Passes
    }

    @MainActor
    private func openCachedGlobalPrizeAnswers() async {
        let synced = syncStoredQueryResultsToGlobalAnswersFromCache()
        loadGlobalABCDCache()
        loadGlobalFilterCountCache()
        globalPrizeAnswerMessage = synced > 0
            ? "已即时同步查询Tab最新\(synced)条记录，正在校验最新ABCD…"
            : "已同步查询Tab，正在校验最新ABCD…"
        isShowingGlobalPrizeAnswers = !uniquePrizeQueryRecords.isEmpty
        guard isShowingGlobalPrizeAnswers else { return }
        let refreshMessage = await refreshLatestQueryRecordForGlobalAnswers()
        let records = uniquePrizeQueryRecords
        let needsStageRefresh = globalFilterCacheConditionSignature != globalFilterConditionsSignature
            || records.contains { globalFilterCounts(for: $0)?.stageSummaries?.isEmpty != false }
        if needsStageRefresh {
            globalPrizeAnswerMessage = "\(refreshMessage) 正在按最新条件生成每个Cell的分段过滤注数…"
            await rebuildGlobalFilterCountCache(
                for: records,
                replacingExisting: true,
                markSignatureCurrent: true
            )
            globalPrizeAnswerMessage = "已按最新全部条件更新\(records.count)个Cell，并写入各大条件过滤注数。"
        } else {
            globalPrizeAnswerMessage = refreshMessage
        }
    }

    /// 每次从奖金Tab进入全局答案时，都对查询Tab最近更新的一条做增量校验。
    /// 只允许“期号＋完整场次”键一致的数据覆盖全局答案。
    @MainActor
    private func refreshLatestQueryRecordForGlobalAnswers() async -> String {
        guard let source = uniqueTXTQueryRecords.max(by: {
            ($0.lastCheckedAt ?? $0.sharedAt) < ($1.lastCheckedAt ?? $1.sharedAt)
        }), source.matchNumbers.count >= 6 else {
            return "已同步：查询Tab暂无可用记录，已保留现有全局答案。"
        }
        let uniqueKey = TXTQueryStatisticsCalculator.ticketKey(
            issue: source.issue,
            matchNumbers: source.matchNumbers
        )
        guard let existing = uniquePrizeQueryRecords.filter({
            TXTQueryStatisticsCalculator.ticketKey(issue: $0.issue, matchNumbers: $0.matchNumbers) == uniqueKey
        }).max(by: {
            let leftScore = prizeRecordCompletenessScore($0)
            let rightScore = prizeRecordCompletenessScore($1)
            return leftScore == rightScore ? $0.queriedAt < $1.queriedAt : leftScore < rightScore
        }) else {
            return "同步失败：最新查询记录未写入全局答案。"
        }

        let issue = source.issue.trimmingCharacters(in: .whitespacesAndNewlines)
        let mainNumbers = Array(source.matchNumbers.prefix(5))
        let exactCachedLogic = cachedABCD(for: source)
        let logic: String
        let sourceLabel: String
        do {
            logic = try await fetchHistoricalABCD(issue: issue, matchNumbers: mainNumbers)
            sourceLabel = "500/澳客最新数据"
        } catch {
            guard let exactCachedLogic else {
                return "同步完成，但最新记录的ABCD网络校验失败，且无严格匹配缓存：\(error.localizedDescription)"
            }
            logic = exactCachedLogic
            sourceLabel = "期号＋场次严格匹配缓存（网络暂不可用）"
        }
        guard normalizedABCD(logic) != nil else {
            return "同步失败：最新记录ABCD格式无效。"
        }
        storeGlobalABCD(logic, for: existing)

        let firstSix = Array((source.observedOutcomes ?? []).prefix(6))
        let completeOutcomes = firstSix.count == 6 && firstSix.allSatisfy { $0 != nil }
            ? firstSix.compactMap { $0 }
            : existing.outcomes
        let latestSnapshot = completeOutcomes.flatMap { outcomes in
            makeStoredPrizeConditionSnapshot(
                outcomes: outcomes,
                spValues: source.prizeSPValues.map { Array($0.prefix(6)) },
                logicText: logic,
                estimatedPrize: source.prizeAmount,
                label: "查询Tab最新同步"
            )
        }
        let updated = PrizeQueryRecord(
            id: existing.id,
            queriedAt: max(existing.queriedAt, source.lastCheckedAt ?? source.sharedAt),
            issue: source.issue,
            matchNumbers: source.matchNumbers,
            handicaps: source.observedHandicaps ?? existing.handicaps,
            isSettled: source.isFinalResult || existing.isSettled,
            amount: source.prizeAmount ?? existing.amount,
            calculationLabel: "查询Tab最新同步",
            runSummary: completeOutcomes.flatMap(PrizeCalculator.outcomeSummary(for:)) ?? existing.runSummary,
            outcomes: completeOutcomes,
            seventhEstimates: existing.seventhEstimates,
            seventhRunSummaries: existing.seventhRunSummaries,
            conditionSnapshots: latestSnapshot.map { [$0] } ?? existing.conditionSnapshots
        )
        if let index = prizeQueryHistory.firstIndex(where: { $0.id == existing.id }) {
            prizeQueryHistory[index] = updated
        } else {
            prizeQueryHistory.append(updated)
        }
        deduplicatePrizeQueryHistory()
        savePrizeQueryHistory()
        await rebuildGlobalFilterCountCache(for: [updated], replacingExisting: false)
        return "已同步查询Tab最新记录：第\(issue)期·场次\(mainNumbers.joined(separator: ","))·ABCD \(logic)·\(sourceLabel)。"
    }

    /// 维护命令把 Mac 按当前条件计算好的结果导入 UserDefaults；
    /// 签名必须与条件 Tab 当前内容完全一致，禁止用旧结果冒充最新判定。
    private var computerGlobalAnswerCacheURL: URL {
        FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("global-answer-cache.json")
    }

    private var computerPrizeHistoryURL: URL {
        FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("computer-prize-history.json")
    }

    private var computerABCDCacheURL: URL {
        FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("computer-abcd-cache.json")
    }

    private var computerSharedTXTQueryHistoryURL: URL {
        FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("computer-shared-txt-history.json")
    }

    private func computerHistoricalBatchURL(for issue: String) -> URL {
        FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("computer-\(issue)-batch.json")
    }

    private var computerConditionDefaultsURL: URL {
        FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("computer-condition-defaults.plist")
    }

    /// simctl/devicectl 的 defaults 工具可能与 App 进程使用不同的
    /// CFPreferences 缓存。电脑批量计算时同时放入真机导出的 plist，
    /// App 从文件中精确读取条件Tab，避免又被旧进程缓存覆盖。
    private func computerConditionDefaultsForMaintenance() -> [String: String]? {
        guard let data = try? Data(contentsOf: computerConditionDefaultsURL),
              let propertyList = try? PropertyListSerialization.propertyList(
                from: data,
                options: [],
                format: nil
              ),
              let root = propertyList as? [String: Any],
              let values = root[inputDefaultsStorageKey] as? [String: String],
              !values.isEmpty else { return nil }
        return values
    }

    /// 将电脑端按当前条件完整重算的数据覆盖回真机。
    /// 这些文件是全量负载，不得再和旧条件记录合并，否则统计会超过34条。
    private func importComputerRefreshedGlobalDataIfPresent(
        expectedConditionSignature: String? = nil
    ) {
        let decoder = JSONDecoder()
        var importedTXT = false
        if let data = try? Data(contentsOf: computerSharedTXTQueryHistoryURL),
           let records = try? decoder.decode([SharedTXTQueryRecord].self, from: data),
           !records.isEmpty {
            // 电脑负载是全量、已去重的查询历史；保留旧条件签名记录供用户
            // 回看，统计时仍由 isCurrentConditionTXT 严格区分当前条件。
            let normalized = deduplicatedSharedTXTRecords(records)
            if !normalized.isEmpty {
                sharedTXTQueryHistory = normalized
                if let encoded = try? JSONEncoder().encode(normalized) {
                    UserDefaults.standard.set(encoded, forKey: sharedTXTQueryHistoryStorageKey)
                }
                importedTXT = true
            }
            try? FileManager.default.removeItem(at: computerSharedTXTQueryHistoryURL)
        }

        var importedHistory = false
        if let data = try? Data(contentsOf: computerPrizeHistoryURL),
           let records = try? decoder.decode([PrizeQueryRecord].self, from: data),
           !records.isEmpty {
            let normalized = deduplicatedPrizeRecords(records)
            prizeQueryHistory = normalized
            loadVIP1FrozenPrizeRecords(merging: normalized)
            if let encoded = try? JSONEncoder().encode(normalized) {
                UserDefaults.standard.set(encoded, forKey: prizeQueryHistoryStorageKey)
            }
            importedHistory = true
            try? FileManager.default.removeItem(at: computerPrizeHistoryURL)
        }

        var importedABCD = false
        if let data = try? Data(contentsOf: computerABCDCacheURL),
           let cache = try? decoder.decode([String: String].self, from: data),
           !cache.isEmpty {
            var merged = UserDefaults.standard.dictionary(forKey: globalABCDCacheStorageKey) as? [String: String] ?? [:]
            for (key, value) in cache where normalizedABCD(value) != nil {
                merged[key] = value
            }
            UserDefaults.standard.set(merged, forKey: globalABCDCacheStorageKey)
            globalABCDByPrizeRecordID.removeAll()
            loadGlobalABCDCache()
            importedABCD = true
            try? FileManager.default.removeItem(at: computerABCDCacheURL)
        }

        var importedBatchCount = 0
        let expectedSignature = expectedConditionSignature ?? globalFilterConditionsSignature
        for issue in historicalBatchIssues {
            let url = computerHistoricalBatchURL(for: issue)
            if let data = try? Data(contentsOf: url),
               let snapshot = try? decoder.decode(Issue26094BatchSnapshot.self, from: data),
               snapshot.issue == issue,
               snapshot.conditionSignature == expectedSignature,
               snapshot.expectedGroupCount > 0,
               snapshot.items.count == snapshot.expectedGroupCount,
               snapshot.failures.isEmpty {
                historicalBatchSnapshots[issue] = snapshot
                historicalBatchProgressMessages[issue] = "已同步电脑完整计算：TXT过关\(snapshot.items.filter(\.isTXTPassed).count)/\(snapshot.expectedGroupCount)组。"
                UserDefaults.standard.set(data, forKey: historicalBatchStorageKey(for: issue))
                importedBatchCount += 1
            }
            try? FileManager.default.removeItem(at: url)
        }

        if importedTXT || importedHistory || importedABCD || importedBatchCount > 0 {
            UserDefaults.standard.synchronize()
            NSLog(
                "Computer-refreshed global data imported: txt=%@ history=%@ abcd=%@ historicalBatches=%ld records=%ld",
                importedTXT ? "YES" : "NO",
                importedHistory ? "YES" : "NO",
                importedABCD ? "YES" : "NO",
                importedBatchCount,
                prizeQueryHistory.count
            )
        }
    }

    private func importComputerGeneratedGlobalAnswerCache(
        expectedConditionSignature: String? = nil,
        conditionValues: [String: String]? = nil
    ) {
        let url = computerGlobalAnswerCacheURL
        guard let data = try? Data(contentsOf: url),
              let envelope = try? JSONDecoder().decode(GlobalPrizeFilterCacheEnvelope.self, from: data),
              !envelope.countsByRecordID.isEmpty else {
            NSLog("Global answer cache import failed")
            return
        }
        let expectedSignature = expectedConditionSignature ?? globalFilterConditionsSignature
        guard envelope.conditionSignature == expectedSignature else {
            globalFilterCountsByRecordID = [:]
            globalFilterCacheConditionSignature = nil
            let defaults = UserDefaults.standard
            defaults.removeObject(forKey: globalFilterCountsCacheStorageKey)
            defaults.removeObject(forKey: globalFilterConditionsSignatureStorageKey)
            defaults.synchronize()
            try? FileManager.default.removeItem(at: url)
            globalPrizeAnswerMessage = "已拒绝旧条件计算结果；请在电脑按条件Tab最新内容重算。"
            NSLog("Rejected stale global answer result: condition signature mismatch")
            return
        }
        let validCounts = currentOutcomeMatchingFilterCounts(envelope.countsByRecordID)
        guard !validCounts.isEmpty else {
            let defaults = UserDefaults.standard
            defaults.removeObject(forKey: globalFilterCountsCacheStorageKey)
            defaults.removeObject(forKey: globalFilterConditionsSignatureStorageKey)
            defaults.synchronize()
            try? FileManager.default.removeItem(at: url)
            globalPrizeAnswerMessage = "已拒绝旧赛果的电脑计算结果；请按当前赛果重算。"
            return
        }
        globalFilterCountsByRecordID = validCounts
        globalFilterCacheConditionSignature = envelope.conditionSignature
        let defaults = UserDefaults.standard
        if let countsData = try? JSONEncoder().encode(validCounts) {
            defaults.set(countsData, forKey: globalFilterCountsCacheStorageKey)
        }
        defaults.set(envelope.conditionSignature, forKey: globalFilterConditionsSignatureStorageKey)
        defaults.set(Date(), forKey: "sequenceFilter.globalAnswerCacheSeedCompleted.v1")
        defaults.synchronize()
        try? FileManager.default.removeItem(at: url)
        archiveCurrentCalculationVersion(
            source: "电脑按条件Tab全量重算",
            conditionSignature: envelope.conditionSignature,
            conditionValues: conditionValues
        )
        NSLog("Latest-condition and outcome-matched global answer result imported: %ld", validCounts.count)
    }

    private var calculationVersionIndexStorageKey: String {
        "sequenceFilter.calculationVersionIndex.v1"
    }

    private var calculationVersionDirectoryURL: URL {
        FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("CalculationVersions", isDirectory: true)
    }

    private func loadCalculationVersionHistory() {
        guard let data = UserDefaults.standard.data(forKey: calculationVersionIndexStorageKey),
              let values = try? JSONDecoder().decode([CalculationVersionSummary].self, from: data) else {
            calculationVersionHistory = []
            return
        }
        calculationVersionHistory = values.sorted { $0.version > $1.version }
    }

    private func calculationConditionSummary(_ values: [String: String]) -> String {
        let flag: (String) -> String = { values[$0] == "1" ? "开" : "关" }
        return [
            "S \(values["sumInput"] ?? "-")",
            "M \(values["displacementInput"] ?? "-")",
            "σ²≤\(values["varianceInput"] ?? "-")",
            "2值≤\(values["valueTwoMaximumInput"] ?? "-")",
            "P_tr≥\(values["transitionMinimumInput"] ?? "-")%",
            "R≤\(values["roughnessMaximumInput"] ?? "-")",
            "B \(values["breakpointInput"] ?? "-")",
            "前三场4最多1个 \(values["noFourPositionFilterEnabled"] == "1" ? "开" : "关")",
            "连续彩果\(flag("consecutiveRunsEnabled"))",
            "连胜平负\(flag("sameResultRunsEnabled"))",
            "大压缩\(flag("protectedHistoryMaxCompressionEnabled"))",
            "247\(flag("universal247ToleranceEnabled"))≥\(values["universal247ToleranceThresholdInput"] ?? "-0.050756")"
        ].joined(separator: "｜")
    }

    /// 版本文件是完整快照；UserDefaults 只存轻量索引，
    /// 避免多次更新后把大量 TXT 塞进偏好设置导致启动变慢。
    @MainActor
    private func archiveCurrentCalculationVersion(
        source: String,
        conditionSignature: String? = nil,
        conditionValues: [String: String]? = nil
    ) {
        let queryRecords = uniqueTXTQueryRecords
        let prizeRecords = uniquePrizeQueryRecords
        guard !queryRecords.isEmpty || !prizeRecords.isEmpty else { return }

        let values = conditionValues
            ?? UserDefaults.standard.dictionary(forKey: inputDefaultsStorageKey) as? [String: String]
            ?? [:]
        let signature = conditionSignature ?? globalFilterConditionsSignature
        let version = (calculationVersionHistory.map(\.version).max() ?? 0) + 1
        let id = UUID()
        let createdAt = Date()

        let queryPassed = queryRecords.filter { $0.isFinalResult && $0.isHit == true }.count
        let queryFailed = queryRecords.filter { $0.isFinalResult && $0.isHit == false }.count
        let queryPending = max(0, queryRecords.count - queryPassed - queryFailed)
        let globalPassed = prizeRecords.filter {
            globalFilterCountsByRecordID[$0.id]?.targetCoveredByFinalTXT == true
        }.count
        let globalFailed = prizeRecords.filter {
            globalFilterCountsByRecordID[$0.id]?.targetCoveredByFinalTXT == false
        }.count
        let globalPending = max(0, prizeRecords.count - globalPassed - globalFailed)
        let betCounts = queryRecords.map(\.finalBetCount)
        let average = betCounts.isEmpty
            ? 0
            : Double(betCounts.reduce(0, +)) / Double(betCounts.count)

        let snapshot = CalculationVersionSnapshot(
            id: id,
            version: version,
            createdAt: createdAt,
            source: source,
            conditionSignature: signature,
            conditionValues: values,
            queryRecords: queryRecords,
            prizeRecords: prizeRecords,
            globalCountsByRecordID: globalFilterCountsByRecordID
        )
        do {
            try FileManager.default.createDirectory(
                at: calculationVersionDirectoryURL,
                withIntermediateDirectories: true
            )
            let url = calculationVersionDirectoryURL
                .appendingPathComponent(String(format: "version-%04d-%@.json", version, id.uuidString))
            let data = try JSONEncoder().encode(snapshot)
            try data.write(to: url, options: .atomic)
        } catch {
            NSLog("Calculation version archive failed: %@", error.localizedDescription)
            return
        }

        let summary = CalculationVersionSummary(
            id: id,
            version: version,
            createdAt: createdAt,
            source: source,
            conditionSignature: signature,
            conditionSummary: calculationConditionSummary(values),
            queryTotal: queryRecords.count,
            queryPassed: queryPassed,
            queryFailed: queryFailed,
            queryPending: queryPending,
            globalTotal: prizeRecords.count,
            globalPassed: globalPassed,
            globalFailed: globalFailed,
            globalPending: globalPending,
            minimumBetCount: betCounts.min() ?? 0,
            maximumBetCount: betCounts.max() ?? 0,
            averageBetCount: average
        )
        calculationVersionHistory.insert(summary, at: 0)
        calculationVersionHistory.sort { $0.version > $1.version }
        if let indexData = try? JSONEncoder().encode(calculationVersionHistory) {
            UserDefaults.standard.set(indexData, forKey: calculationVersionIndexStorageKey)
            UserDefaults.standard.synchronize()
        }
    }

    /// 仅供安装维护命令显式调用；用户正常启动绝不会执行。
    @MainActor
    private func seedAllGlobalAnswerCacheForDeviceInstall() async {
        let records = uniquePrizeQueryRecords
        guard !records.isEmpty else { return }
        NSLog("Global answer cache seed started: %ld records", records.count)
        await rebuildGlobalFilterCountCache(for: records, replacingExisting: true)
        let defaults = UserDefaults.standard
        defaults.set(
            Date(),
            forKey: "sequenceFilter.globalAnswerCacheSeedCompleted.v1"
        )
        defaults.synchronize()
        NSLog("Global answer cache seeded: %ld/%ld", globalFilterCountsByRecordID.count, records.count)
    }

    /// Mac 维护时复核首页最近一次生成的逐层注数，不在手机正常流程中运行。
    @MainActor
    private func diagnoseLastRunForMaintenance() async {
        guard let input = lastRunSnapshot?.normalizedInput,
              let config = try? FilterConfig.parse(input) else {
            NSLog("Last-run diagnosis unavailable")
            return
        }
        let profile = protectedHistoryMaxCompressionEnabled ? protectedHistoryMaxCompressionProfile : nil
        let comprehensive = comprehensiveAnalysisFilterEnabled ? comprehensiveAnalysisProfile : nil
        let tolerance = comprehensiveAnalysisFilterEnabled
            ? (parsedComprehensiveAnalysisToleranceRange ?? 0...0)
            : 0...0
        let protectedTolerance = effectiveProtectedHistoryToleranceRange
        let protectedCap = effectiveProtectedHistoryBetCap
        let prefixes = protectedPrizeOutcomePrefixes
        let calculated = await Task.detached(priority: .userInitiated) {
            SequenceFilterEngine.calculate(
                config,
                previousContext: nil,
                comprehensiveAnalysisProfile: comprehensive,
                comprehensiveAnalysisToleranceRange: tolerance,
                protectedHistoryProfile: profile,
                protectedHistoryToleranceRange: protectedTolerance,
                protectedHistoryBetCap: protectedCap,
                protectedPrizeOutcomePrefixes: prefixes,
                captureQueryStages: true
            )
        }.value
        NSLog("Last-run diagnosis input: %@", config.normalizedInput)
        NSLog("Last-run diagnosis stages: %@", calculated.majorFilterStageSummaries.joined(separator: " || "))
        NSLog("Last-run diagnosis final: %ld", calculated.finalBetCount)
        if ProcessInfo.processInfo.arguments.contains("--test-last-run-ui") {
            result = calculated
            try? await Task.sleep(nanoseconds: 2_000_000_000)
            NSLog("Last-run result UI remained alive: %ld", expandedSharedTXTBets(calculated).count)
            shareTXTReport(.total)
            try? await Task.sleep(nanoseconds: 2_000_000_000)
            NSLog("TXT share UI test presented: %@", shareableReport == nil ? "NO" : "YES")
        }
    }

    /// Mac维护用：验证全局答案的TXT结果与条件结果使用同一最终集合。
    @MainActor
    private func diagnoseGlobalStatisticsForMaintenance() {
        let records = uniquePrizeQueryRecords
        let txtEvaluated = records.filter { ($0.outcomes?.count ?? 0) >= 6 }
        let rawTXTCovered = txtEvaluated.filter { txtCoverageAssessment(for: $0).passes }
        let txtPassed = txtEvaluated.filter(globalPrizeRecordPasses)
        let conditionResults = records.map { ($0, prizeUnderlyingConditionStatus(for: $0)) }
        let conditionPassed = conditionResults.filter { $0.1.passes }.count
        let conditionFailed = conditionResults.filter { !$0.1.passes }
        let conditionPassedRecords = conditionResults.filter { $0.1.passes }.map(\.0)
        let conditionAndTXTPassed = conditionPassedRecords.filter { txtCoverageAssessment(for: $0).passes }.count
        let conditionPassedIDs = Set(conditionPassedRecords.map(\.id))
        let txtPassedIDs = Set(txtPassed.map(\.id))
        let conditionOnlyIDs = conditionPassedIDs.subtracting(txtPassedIDs).sorted()
        let txtOnlyIDs = txtPassedIDs.subtracting(conditionPassedIDs).sorted()
        let conditionPassedWithoutTXT = conditionPassedRecords.filter {
            txtCoverageAssessment(for: $0).detail.contains("找不到同期号＋相同前6场TXT")
        }.count
        let conditionPassedButOutcomeAbsent = conditionPassedRecords.filter {
            txtCoverageAssessment(for: $0).detail.contains("TXT中找不到赛果")
        }.count
        NSLog(
            "GLOBAL-STATS total=%ld txtEvaluated=%ld txtPassed=%ld txtFailed=%ld conditionPassed=%ld conditionFailed=%ld",
            records.count,
            txtEvaluated.count,
            txtPassed.count,
            txtEvaluated.count - txtPassed.count,
            conditionPassed,
            conditionFailed.count
        )
        NSLog(
            "GLOBAL-STATS rawTXTExactCoverage=%ld finalUnifiedPass=%ld",
            rawTXTCovered.count,
            txtPassed.count
        )
        NSLog(
            "GLOBAL-STATS conditionAndTXTPassed=%ld conditionPassedWithoutTXT=%ld conditionPassedButOutcomeAbsent=%ld",
            conditionAndTXTPassed,
            conditionPassedWithoutTXT,
            conditionPassedButOutcomeAbsent
        )
        NSLog(
            "GLOBAL-STATS-ID-SETS conditionIDs=%ld txtIDs=%ld conditionOnly=%@ txtOnly=%@ exactMatch=%@",
            conditionPassedIDs.count,
            txtPassedIDs.count,
            conditionOnlyIDs.map(String.init).joined(separator: ","),
            txtOnlyIDs.map(String.init).joined(separator: ","),
            conditionPassedIDs == txtPassedIDs ? "YES" : "NO"
        )
        for item in conditionFailed {
            NSLog(
                "GLOBAL-CONDITION-FAIL issue=%@ matches=%@ reasons=%@",
                item.0.issue,
                item.0.matchNumbers.prefix(6).joined(separator: ","),
                item.1.reasons.joined(separator: "；")
            )
        }
    }

