    /// Mac维护用：应用不依赖期号、场次号或完整赛果白名单的通用大压缩，
    /// 并对当前全部条件通过记录做TXT实际赛果覆盖校验。
    @MainActor
    private func applyVerifiedGenericBigCompressionForMaintenance() async {
        let previousSumInput = sumInput
        let previousValueTwoMaximumInput = valueTwoMaximumInput
        let previousSameResultRunToleranceInput = sameResultRunToleranceInput
        let previousPrizeStatisticalConditionEnabled = prizeStatisticalConditionEnabled
        let previousToleranceEnabled = protectedHistoryToleranceEnabled
        let previousToleranceInput = protectedHistoryToleranceInput
        let previousEnabled = protectedHistoryBetCapEnabled
        let previousInput = protectedHistoryBetCapInput
        sumInput = "11-18"
        valueTwoMaximumInput = "4"
        sameResultRunToleranceInput = "1-3"
        prizeStatisticalConditionEnabled = true
        protectedHistoryToleranceEnabled = true
        protectedHistoryToleranceInput = "0-0"
        protectedHistoryBetCapEnabled = false
        protectedHistoryBetCapInput = ""

        guard let profile = protectedHistoryMaxCompressionProfile else {
            sumInput = previousSumInput
            valueTwoMaximumInput = previousValueTwoMaximumInput
            sameResultRunToleranceInput = previousSameResultRunToleranceInput
            prizeStatisticalConditionEnabled = previousPrizeStatisticalConditionEnabled
            protectedHistoryToleranceEnabled = previousToleranceEnabled
            protectedHistoryToleranceInput = previousToleranceInput
            protectedHistoryBetCapEnabled = previousEnabled
            protectedHistoryBetCapInput = previousInput
            NSLog("GENERIC-COMPRESSION failed: profile missing")
            return
        }
        let records = uniquePrizeQueryRecords
        let protectedPrefixes = protectedPrizeOutcomePrefixes
        let protectedTolerance = effectiveProtectedHistoryToleranceRange
        let conditionPassingIDs = Set(records.filter {
            prizeRecordPasses($0, excludesHistoricalPairing: true)
        }.map(\.id))
        let comprehensiveProfile = comprehensiveAnalysisFilterEnabled
            ? comprehensiveAnalysisProfile
            : nil
        let comprehensiveTolerance = comprehensiveAnalysisFilterEnabled
            ? (parsedComprehensiveAnalysisToleranceRange ?? 0...0)
            : 0...0
        var calculatedCounts: [Int: GlobalPrizeFilterCounts] = [:]
        var covered = 0
        var missing: [String] = []
        var maximumBets = 0
        var minimumBets = Int.max
        var totalBets = 0

        for (index, record) in records.enumerated() {
            guard let config = globalFilterConfig(for: record) else {
                missing.append("\(record.issue)-\(record.matchNumbers.prefix(6).joined(separator: ",")):配置缺失")
                continue
            }
            let calculated = await Task.detached(priority: .userInitiated) {
                SequenceFilterEngine.calculate(
                    config,
                    previousContext: nil,
                    comprehensiveAnalysisProfile: comprehensiveProfile,
                    comprehensiveAnalysisToleranceRange: comprehensiveTolerance,
                    protectedHistoryProfile: profile,
                    protectedHistoryToleranceRange: protectedTolerance,
                    protectedHistoryBetCap: 150,
                    protectedPrizeOutcomePrefixes: protectedPrefixes
                )
            }.value
            maximumBets = max(maximumBets, calculated.finalBetCount)
            minimumBets = min(minimumBets, calculated.finalBetCount)
            totalBets += calculated.finalBetCount
            let bets = expandedSharedTXTBets(calculated)
            var txtContainsTarget = false
            var target: [Int] = []
            let canReturnQueryResult = record.isSettled
            if canReturnQueryResult, let outcomes = record.outcomes, outcomes.count >= 6 {
                target = Array(outcomes.prefix(6))
                txtContainsTarget = bets.contains {
                    $0.count >= 6 && Array($0.prefix(6)) == target
                }
            }
            let targetCoverageDetail = txtContainsTarget || target.count != 6
                ? nil
                : "电脑终局覆盖=未通过（该赛果未出现在当前最终TXT结果中）"
            calculatedCounts[record.id] = GlobalPrizeFilterCounts(
                before: 729,
                removed: max(0, 729 - calculated.finalBetCount),
                after: calculated.finalBetCount,
                stageSummaries: calculated.majorFilterStageSummaries,
                outcomeSignature: prizeRecordOutcomeSignature(record),
                targetCoveredByFinalTXT: target.count == 6 ? txtContainsTarget : nil,
                targetCoverageDetail: targetCoverageDetail
            )
            if conditionPassingIDs.contains(record.id), target.count == 6 {
                if txtContainsTarget {
                    covered += 1
                } else {
                    missing.append("\(record.issue)-\(record.matchNumbers.prefix(6).joined(separator: ","))")
                }
            }
            let conditionPasses = conditionPassingIDs.contains(record.id)
            let rows = compressedTXTRows(matchNumbers: record.matchNumbers, bets: bets)
            let failureReasons = conditionPasses
                ? []
                : currentConditionCellAssessment(for: record).failedDetails.filter {
                    !$0.hasPrefix("TXT覆盖=") && !$0.hasPrefix("电脑计算缓存=")
                }
            let verificationMessage: String
            if !canReturnQueryResult {
                verificationMessage = "比赛未全部最终结束，只生成TXT，不返回查询结果。"
            } else if conditionPasses && txtContainsTarget {
                verificationMessage = "已使用同一套当前通用条件电脑重算：条件通过，实际赛果\(target.map(String.init).joined())已在TXT中找到。"
            } else if !conditionPasses {
                verificationMessage = "已使用同一套当前通用条件电脑重算：条件未通过。原因：\(failureReasons.isEmpty ? "当前条件总判定未通过" : failureReasons.joined(separator: "；"))"
            } else {
                verificationMessage = "异常：条件通过，但实际赛果\(target.map(String.init).joined())未在本轮TXT中找到。"
            }
            let shared = SharedTXTQueryRecord(
                id: UUID(),
                sharedAt: Date(),
                issue: record.issue,
                filename: "generic-\(record.issue)-\(record.matchNumbers.joined(separator: "-"))-total.txt",
                txtContent: ([
                    "期号：\(record.issue)",
                    "TXT分组：总量",
                    "生成方式：电脑端按当前条件Tab的通用条件重新生成",
                    sharedTXTBody(rows: rows)
                ]).joined(separator: "\n"),
                normalizedInput: calculated.config.normalizedInput,
                matchNumbers: record.matchNumbers,
                betOutcomes: bets,
                finalBetCount: bets.count,
                conditionSignature: globalFilterConditionsSignature,
                lastCheckedAt: Date(),
                observedOutcomes: canReturnQueryResult ? target.map(Optional.some) : nil,
                observedHandicaps: record.handicaps.map { Array($0.prefix(6)) },
                verificationMessage: verificationMessage,
                isFinalResult: canReturnQueryResult && target.count == 6,
                isHit: canReturnQueryResult && target.count == 6 ? txtContainsTarget : nil,
                prizeAmount: canReturnQueryResult && txtContainsTarget ? record.amount : nil,
                prizeSPValues: nil
            )
            upsertSharedTXTQueryRecord(shared)
            NSLog(
                "GENERIC-COMPRESSION progress=%ld/%ld passing=%ld covered=%ld bets=%ld",
                index + 1,
                records.count,
                conditionPassingIDs.count,
                covered,
                calculated.finalBetCount
            )
        }

        guard missing.isEmpty, covered == conditionPassingIDs.count else {
            sumInput = previousSumInput
            valueTwoMaximumInput = previousValueTwoMaximumInput
            sameResultRunToleranceInput = previousSameResultRunToleranceInput
            prizeStatisticalConditionEnabled = previousPrizeStatisticalConditionEnabled
            protectedHistoryToleranceEnabled = previousToleranceEnabled
            protectedHistoryToleranceInput = previousToleranceInput
            protectedHistoryBetCapEnabled = previousEnabled
            protectedHistoryBetCapInput = previousInput
            UserDefaults.standard.set(persistedInputValues, forKey: inputDefaultsStorageKey)
            UserDefaults.standard.synchronize()
            NSLog(
                "GENERIC-COMPRESSION rejected passing=%ld covered=%ld missing=%@",
                conditionPassingIDs.count,
                covered,
                missing.joined(separator: "|")
            )
            return
        }

        globalFilterCountsByRecordID = calculatedCounts
        globalFilterCacheConditionSignature = globalFilterConditionsSignature
        persistGlobalFilterCountCache()
        UserDefaults.standard.set(persistedInputValues, forKey: inputDefaultsStorageKey)
        UserDefaults.standard.synchronize()
        NSLog(
            "GENERIC-COMPRESSION applied passing=%ld covered=%ld minBets=%ld maxBets=%ld avgBets=%.2f cache=%ld",
            conditionPassingIDs.count,
            covered,
            minimumBets == Int.max ? 0 : minimumBets,
            maximumBets,
            records.isEmpty ? 0 : Double(totalBets) / Double(records.count),
            calculatedCounts.count
        )
    }

    /// Mac维护用：比较大压缩不同容错档位能多保护几条历史结果，
    /// 并实际运行引擎验证每条最终注数。
    @MainActor
    private func diagnoseBigCompressionToleranceForMaintenance() async {
        guard let profile = protectedHistoryMaxCompressionProfile else {
            NSLog("BIG-COMPRESSION-TOLERANCE unavailable: profile missing")
            return
        }
        let records = uniquePrizeQueryRecords.filter(baselineGlobalPrizeRecordPasses)
        let prefixes = protectedPrizeOutcomePrefixes
        for upper in 0...4 {
            let tolerance = 0...upper
            var newlyPassing: [(PrizeQueryRecord, Int)] = []
            for record in records {
                guard let snapshot = record.conditionSnapshots?.first,
                      snapshot.outcomes.count >= 6,
                      let config = globalFilterConfig(for: record) else { continue }
                let failures = SequenceFilterEngine.comprehensiveAnalysisFailureCount(
                    fullOutcomes: Array(snapshot.outcomes.prefix(6)),
                    config: config,
                    profile: profile,
                    outcomeProbabilities: nil,
                    outcomeSPs: nil
                )
                if tolerance.contains(failures), failures > 0 {
                    newlyPassing.append((record, failures))
                }
            }
            NSLog(
                "BIG-COMPRESSION-TOLERANCE range=0-%ld newlyPassing=%ld",
                upper,
                newlyPassing.count
            )
            for item in newlyPassing {
                guard let config = globalFilterConfig(for: item.0) else { continue }
                let calculated = await Task.detached(priority: .userInitiated) {
                    SequenceFilterEngine.calculate(
                        config,
                        previousContext: nil,
                        protectedHistoryProfile: profile,
                        protectedHistoryToleranceRange: tolerance,
                        protectedHistoryBetCap: 250,
                        protectedPrizeOutcomePrefixes: prefixes
                    )
                }.value
                NSLog(
                    "BIG-COMPRESSION-TOLERANCE-CELL range=0-%ld issue=%@ matches=%@ failures=%ld bets=%ld",
                    upper,
                    item.0.issue,
                    item.0.matchNumbers.prefix(6).joined(separator: ","),
                    item.1,
                    calculated.finalBetCount
                )
            }
        }
    }

    /// Mac维护用：对缺失ABCD、完整前6场赛果或条件快照的全局记录逐条补取，
    /// 然后在电脑端重新运行全部过滤引擎。
    @MainActor
    private func refreshMissingGlobalDataForMaintenance() async {
        let requestedRecordID = ProcessInfo.processInfo.arguments.lazy.compactMap { argument -> Int? in
            let prefix = "--refresh-global-record-id="
            guard argument.hasPrefix(prefix) else { return nil }
            return Int(argument.dropFirst(prefix.count))
        }.first
        let targets = uniquePrizeQueryRecords.filter { record in
            if let requestedRecordID { return record.id == requestedRecordID }
            return (record.outcomes?.count ?? 0) < 6
                || record.conditionSnapshots?.isEmpty != false
                || cachedABCD(for: record) == nil
        }
        NSLog("GLOBAL-REFRESH started targets=%ld", targets.count)
        var refreshed = 0
        var failed = 0
        for (offset, record) in targets.enumerated() {
            var logic = cachedABCD(for: record)
            if logic == nil {
                do {
                    logic = try await fetchHistoricalABCD(
                        issue: record.issue,
                        matchNumbers: Array(record.matchNumbers.prefix(5))
                    )
                    if let logic { storeGlobalABCD(logic, for: record) }
                } catch {
                    NSLog(
                        "GLOBAL-REFRESH ABCD failed issue=%@ matches=%@ error=%@",
                        record.issue,
                        record.matchNumbers.prefix(6).joined(separator: ","),
                        error.localizedDescription
                    )
                }
            }

            var updated = record
            do {
                updated = try await backfilledPrizeQueryRecord(record)
            } catch {
                NSLog(
                    "GLOBAL-REFRESH result failed issue=%@ matches=%@ error=%@",
                    record.issue,
                    record.matchNumbers.prefix(6).joined(separator: ","),
                    error.localizedDescription
                )
            }
            if let outcomes = updated.outcomes,
               outcomes.count >= 6,
               let logic,
               updated.conditionSnapshots?.first.map({
                   Array($0.outcomes.prefix(6)) != Array(outcomes.prefix(6))
               }) ?? true,
               let snapshot = makeStoredPrizeConditionSnapshot(
                    outcomes: outcomes,
                    spValues: nil,
                    logicText: logic,
                    estimatedPrize: updated.amount,
                    label: "电脑端ABCD＋实际赛果补全"
               ) {
                updated = PrizeQueryRecord(
                    id: updated.id,
                    queriedAt: updated.queriedAt,
                    issue: updated.issue,
                    matchNumbers: updated.matchNumbers,
                    handicaps: updated.handicaps,
                    isSettled: updated.isSettled,
                    amount: updated.amount,
                    calculationLabel: updated.calculationLabel,
                    runSummary: updated.runSummary,
                    outcomes: updated.outcomes,
                    seventhEstimates: updated.seventhEstimates,
                    seventhRunSummaries: updated.seventhRunSummaries,
                    conditionSnapshots: [snapshot]
                )
            }
            if let index = prizeQueryHistory.firstIndex(where: { $0.id == record.id }) {
                prizeQueryHistory[index] = updated
            }
            let complete = (updated.outcomes?.count ?? 0) >= 6
                && updated.conditionSnapshots?.isEmpty == false
                && logic != nil
            if complete { refreshed += 1 } else { failed += 1 }
            savePrizeQueryHistory()
            NSLog(
                "GLOBAL-REFRESH progress=%ld/%ld complete=%@",
                offset + 1,
                targets.count,
                complete ? "YES" : "NO"
            )
        }
        deduplicatePrizeQueryHistory()
        savePrizeQueryHistory()
        await rebuildGlobalFilterCountCache(
            for: requestedRecordID == nil ? uniquePrizeQueryRecords : targets,
            replacingExisting: requestedRecordID == nil,
            markSignatureCurrent: true
        )
        UserDefaults.standard.synchronize()
        NSLog(
            "GLOBAL-REFRESH completed refreshed=%ld failed=%ld total=%ld signed=%ld",
            refreshed,
            failed,
            uniquePrizeQueryRecords.count,
            globalFilterCountsByRecordID.values.filter { $0.outcomeSignature != nil }.count
        )
    }

    /// Mac维护用：对“当前条件通过但TXT未命中”的历史组合，
    /// 使用当前条件Tab和同一份大压缩配置重新生成TXT。
    @MainActor
    private func regenerateCurrentGlobalTXTForMaintenance() async {
        if globalFilterCacheConditionSignature != globalFilterConditionsSignature {
            // 不先对全部记录重算一遍。下面生成TXT时的同一次引擎结果
            // 会同时写入注数和终局覆盖缓存，避免49条重复计算两遍。
            globalFilterCountsByRecordID = [:]
            globalFilterCacheConditionSignature = globalFilterConditionsSignature
            persistGlobalFilterCountCache()
            NSLog("GLOBAL-TXT-REGEN reset stale cache; reusing each TXT calculation for cache")
        }
        let conditionPassedRecords = uniquePrizeQueryRecords.filter { record in
            // 此处是TXT重生成入口，必须用TXT之前的原始条件判定；
            // 否则“缺TXT”本身会让记录永远进不了重算队列。
            guard prizeRecordPasses(record, excludesHistoricalPairing: true) else { return false }
            let exceedsCap = effectiveProtectedHistoryBetCap.map { cap in
                exactTXTRecord(for: record).map { $0.finalBetCount > cap } ?? false
            } ?? false
            return !txtCoverageAssessment(for: record).passes || exceedsCap
        }
        var seenKeys = Set<String>()
        let targets = conditionPassedRecords.filter { record in
            let key = TXTQueryStatisticsCalculator.ticketKey(
                issue: record.issue,
                matchNumbers: record.matchNumbers
            )
            return seenKeys.insert(key).inserted
        }
        NSLog("GLOBAL-TXT-REGEN started targets=%ld", targets.count)
        let protectedPrizePrefixes = protectedPrizeOutcomePrefixes
        let protectedHistoryProfile = protectedHistoryMaxCompressionEnabled
            ? protectedHistoryMaxCompressionProfile
            : nil
        let comprehensiveProfile = comprehensiveAnalysisFilterEnabled
            ? comprehensiveAnalysisProfile
            : nil
        let comprehensiveTolerance = comprehensiveAnalysisFilterEnabled
            ? (parsedComprehensiveAnalysisToleranceRange ?? 0...0)
            : 0...0
        let protectedHistoryTolerance = effectiveProtectedHistoryToleranceRange
        let protectedHistoryCap = effectiveProtectedHistoryBetCap
        var generated = 0
        var failed = 0

        for (offset, record) in targets.enumerated() {
            guard let outcomes = record.outcomes, outcomes.count >= 6 else {
                failed += 1
                continue
            }
            let target = Array(outcomes.prefix(6))
            guard let config = maintenanceGlobalTXTConfig(for: record) else {
                failed += 1
                NSLog(
                    "GLOBAL-TXT-REGEN config-missing issue=%@ matches=%@ outcome=%@",
                    record.issue,
                    record.matchNumbers.joined(separator: ","),
                    target.map(String.init).joined()
                )
                continue
            }
            let calculated = await Task.detached(priority: .userInitiated) {
                SequenceFilterEngine.calculate(
                    config,
                    previousContext: nil,
                    comprehensiveAnalysisProfile: comprehensiveProfile,
                    comprehensiveAnalysisToleranceRange: comprehensiveTolerance,
                    protectedHistoryProfile: protectedHistoryProfile,
                    protectedHistoryToleranceRange: protectedHistoryTolerance,
                    protectedHistoryBetCap: protectedHistoryCap,
                    protectedPrizeOutcomePrefixes: protectedPrizePrefixes
                )
            }.value
            let bets = expandedSharedTXTBets(calculated)
            let canReturnQueryResult = record.isSettled
            let covered = canReturnQueryResult && bets.contains {
                $0.count >= 6 && Array($0.prefix(6)) == target
            }
            let rows = compressedTXTRows(
                matchNumbers: record.matchNumbers,
                bets: bets
            )
            let text = [
                "期号：\(record.issue)",
                "TXT分组：总量",
                "生成方式：电脑端按当前条件Tab全部条件重新生成",
                sharedTXTBody(rows: rows)
            ].joined(separator: "\n")
            let shared = SharedTXTQueryRecord(
                id: UUID(),
                sharedAt: Date(),
                issue: record.issue,
                filename: "current-\(record.issue)-\(record.matchNumbers.joined(separator: "-"))-total.txt",
                txtContent: text,
                normalizedInput: calculated.config.normalizedInput,
                matchNumbers: record.matchNumbers,
                betOutcomes: bets,
                finalBetCount: bets.count,
                conditionSignature: globalFilterConditionsSignature,
                lastCheckedAt: Date(),
                observedOutcomes: canReturnQueryResult ? target.map(Optional.some) : nil,
                observedHandicaps: record.handicaps.map { Array($0.prefix(6)) },
                verificationMessage: canReturnQueryResult
                    ? (covered
                        ? "电脑按条件Tab当前全部条件重新生成：TXT已找到实际赛果\(target.map(String.init).joined())。"
                        : "电脑按条件Tab当前全部条件重新生成：TXT未找到实际赛果\(target.map(String.init).joined())。")
                    : "已重新生成TXT；比赛未全部最终结束，不返回查询结果。",
                isFinalResult: canReturnQueryResult,
                isHit: canReturnQueryResult ? covered : nil,
                prizeAmount: canReturnQueryResult && covered ? record.amount : nil,
                prizeSPValues: nil
            )
            upsertSharedTXTQueryRecord(shared)
            globalFilterCountsByRecordID[record.id] = GlobalPrizeFilterCounts(
                before: 729,
                removed: max(0, 729 - bets.count),
                after: bets.count,
                stageSummaries: calculated.majorFilterStageSummaries,
                outcomeSignature: prizeRecordOutcomeSignature(record),
                targetCoveredByFinalTXT: covered,
                targetCoverageDetail: covered
                    ? nil
                    : "电脑终局覆盖=未通过（当前条件TXT中没有实际赛果）"
            )
            generated += 1
            NSLog(
                "GLOBAL-TXT-REGEN progress=%ld/%ld generated=%ld failed=%ld bets=%ld",
                offset + 1,
                targets.count,
                generated,
                failed,
                bets.count
            )
        }

        saveSharedTXTQueryHistory()
        let recordsMissingComputerCounts = uniquePrizeQueryRecords.filter { record in
            guard let counts = globalFilterCountsByRecordID[record.id],
                  counts.outcomeSignature == prizeRecordOutcomeSignature(record),
                  counts.targetCoveredByFinalTXT != nil else { return true }
            return false
        }
        if !recordsMissingComputerCounts.isEmpty {
            await rebuildGlobalFilterCountCache(
                for: recordsMissingComputerCounts,
                replacingExisting: false,
                markSignatureCurrent: true
            )
        }
        globalFilterCacheConditionSignature = globalFilterConditionsSignature
        persistGlobalFilterCountCache()
        exportCurrentComputerMaintenancePayload()
        UserDefaults.standard.synchronize()
        let remaining = uniquePrizeQueryRecords.filter { record in
            guard prizeRecordPasses(record, excludesHistoricalPairing: true) else { return false }
            let exceedsCap = effectiveProtectedHistoryBetCap.map { cap in
                exactTXTRecord(for: record).map { $0.finalBetCount > cap } ?? false
            } ?? false
            return !txtCoverageAssessment(for: record).passes || exceedsCap
        }.count
        NSLog(
            "GLOBAL-TXT-REGEN completed generated=%ld failed=%ld remaining=%ld shared=%ld",
            generated,
            failed,
            remaining,
            uniqueTXTQueryRecords.count
        )
    }

    /// Mac维护用：按条件Tab当前规则重新生成每一份去重TXT，
    /// 再用这些TXT的精确覆盖同时更新查询页和全局答案。
    @MainActor
    private func recomputeAllTXTAndGlobalFromCurrentRulesForMaintenance(
        currentConditionInput: String? = nil,
        currentConditionSignature: String? = nil,
        targetRecords: [PrizeQueryRecord]? = nil
    ) async {
        // 只读条件Tab已持久化的最新值。历史记录仅在下面提供
        // 期号、场次、ABCD和彩果，不允许提供任何过滤条件。
        let maintenanceInput = currentConditionInput
            ?? persistedCurrentConditionInputForMaintenance()
        let maintenanceSignature = currentConditionSignature
            ?? globalFilterConditionsSignature(for: maintenanceInput)
        _ = syncStoredQueryResultsToGlobalAnswersFromCache()
        let allRecords = targetRecords ?? uniquePrizeQueryRecords
        var representatives: [String: PrizeQueryRecord] = [:]
        for record in allRecords {
            let key = TXTQueryStatisticsCalculator.ticketKey(
                issue: record.issue,
                matchNumbers: record.matchNumbers
            )
            guard let existing = representatives[key] else {
                representatives[key] = record
                continue
            }
            let newScore = prizeRecordCompletenessScore(record)
            let oldScore = prizeRecordCompletenessScore(existing)
            if newScore > oldScore || (newScore == oldScore && record.queriedAt > existing.queriedAt) {
                representatives[key] = record
            }
        }
        let targets = representatives.values.sorted { left, right in
            if left.issue != right.issue { return left.issue < right.issue }
            return (Int(left.matchNumbers.first ?? "") ?? 0) < (Int(right.matchNumbers.first ?? "") ?? 0)
        }
        let protectedProfile = protectedHistoryMaxCompressionEnabled
            ? protectedHistoryMaxCompressionProfile
            : nil
        let comprehensiveProfile = comprehensiveAnalysisFilterEnabled
            ? comprehensiveAnalysisProfile
            : nil
        let comprehensiveTolerance = comprehensiveAnalysisFilterEnabled
            ? (parsedComprehensiveAnalysisToleranceRange ?? 0...0)
            : 0...0
        let protectedTolerance = effectiveProtectedHistoryToleranceRange
        let protectedCap = effectiveProtectedHistoryBetCap
        let protectedPrefixes = protectedPrizeOutcomePrefixes
        var generated = 0
        var configMissing = 0
        var exactHits = 0
        var jobs: [(id: Int, config: FilterConfig, comparisonTableOdds: [[Double]]?, vip4Context: VIP4MatchContext?, vip3Context: VIP3MatchContext?)] = []
        jobs.reserveCapacity(targets.count)

        for record in targets {
            guard let config = maintenanceGlobalTXTConfig(
                for: record,
                currentInput: maintenanceInput
            ) else {
                configMissing += 1
                NSLog(
                    "TXT-GLOBAL-RECOMPUTE config-missing issue=%@ matches=%@",
                    record.issue,
                    record.matchNumbers.prefix(6).joined(separator: ",")
                )
                continue
            }
            let needsOdds = config.requiresSPData
                || SequenceFilterEngine.usesVIP4Model(
                    threshold: config.universal247ToleranceThreshold
                )
                || comprehensiveProfile?.requiresSPData == true
                || protectedProfile?.requiresSPData == true
            var comparisonTableOdds: [[Double]]?
            var vip4Context: VIP4MatchContext?
            var vip3Context: VIP3MatchContext?
            if needsOdds {
                do {
                    if SequenceFilterEngine.usesVIP4Model(
                        threshold: config.universal247ToleranceThreshold
                    ) {
                        let context = try await maintenanceVIP4Context(for: record, config: config)
                        vip4Context = context
                        comparisonTableOdds = Array(context.matches.prefix(5).map(\.comparisonTableOdds))
                    } else if SequenceFilterEngine.usesVIP3Model(
                        threshold: config.universal247ToleranceThreshold
                    ) {
                        let context = try await maintenanceVIP3Context(for: record, config: config)
                        vip3Context = context
                        comparisonTableOdds = Array(context.comparisonTableOdds.prefix(5))
                    } else {
                        comparisonTableOdds = try await maintenanceComparisonTableOdds(for: record)
                    }
                } catch {
                    configMissing += 1
                    NSLog(
                        "TXT-GLOBAL-RECOMPUTE odds-missing issue=%@ matches=%@ error=%@",
                        record.issue,
                        record.matchNumbers.prefix(5).joined(separator: ","),
                        error.localizedDescription
                    )
                    continue
                }
            }
            jobs.append((record.id, config, comparisonTableOdds, vip4Context, vip3Context))
        }

        let run2Token = maintenanceInput
            .split(separator: "|")
            .first { $0.uppercased().hasPrefix("RUN2ON=") }
            .map(String.init) ?? "RUN2ON=?"
        NSLog(
            "TXT-GLOBAL-RECOMPUTE started tickets=%ld prize=%ld condition=%@",
            targets.count,
            allRecords.count,
            run2Token
        )
        // 引擎是纯函数；Mac维护端用3个有界worker并行算完全部TXT。
        // 不在真机运行，也不按目标注数截断。
        let calculatedByID = await Task.detached(priority: .userInitiated) {
            let workerCount = min(3, max(1, jobs.count))
            return await withTaskGroup(of: [Int: FilterResult].self) { group in
                for worker in 0..<workerCount {
                    group.addTask {
                        var local: [Int: FilterResult] = [:]
                        for index in stride(from: worker, to: jobs.count, by: workerCount) {
                            guard !Task.isCancelled else { break }
                            let job = jobs[index]
                            local[job.id] = SequenceFilterEngine.calculate(
                                job.config,
                                previousContext: nil,
                                currentOutcomeSPs: job.comparisonTableOdds,
                                vip4Context: job.vip4Context,
                                vip3Context: job.vip3Context,
                                comprehensiveAnalysisProfile: comprehensiveProfile,
                                comprehensiveAnalysisToleranceRange: comprehensiveTolerance,
                                protectedHistoryProfile: protectedProfile,
                                protectedHistoryToleranceRange: protectedTolerance,
                                protectedHistoryBetCap: protectedCap,
                                protectedPrizeOutcomePrefixes: protectedPrefixes
                            )
                            NSLog(
                                "TXT-GLOBAL-RECOMPUTE calculation=%ld/%ld worker=%ld",
                                index + 1,
                                jobs.count,
                                worker + 1
                            )
                        }
                        return local
                    }
                }
                var merged: [Int: FilterResult] = [:]
                for await local in group {
                    merged.merge(local) { _, new in new }
                }
                return merged
            }
        }.value
        let comparisonTableOddsByID = Dictionary(
            uniqueKeysWithValues: jobs.compactMap { job in
                job.comparisonTableOdds.map { (job.id, $0) }
            }
        )
        var recomputedCounts: [Int: GlobalPrizeFilterCounts] = [:]
        recomputedCounts.reserveCapacity(calculatedByID.count)
        for (offset, record) in targets.enumerated() {
            let ticketKey = TXTQueryStatisticsCalculator.ticketKey(
                issue: record.issue,
                matchNumbers: record.matchNumbers
            )
            let existingTXT = exactTXTRecord(for: record) ?? sharedTXTQueryHistory.filter {
                TXTQueryStatisticsCalculator.ticketKey(issue: $0.issue, matchNumbers: $0.matchNumbers) == ticketKey
            }.max { $0.sharedAt < $1.sharedAt }
            guard let calculated = calculatedByID[record.id] else { continue }
            let bets = deduplicatedTXTBets(calculated.uniqueExpandedBets)
            let target = record.outcomes.map { Array($0.prefix(6)) }
            let covered = target.map { actual in
                actual.count == 6 && bets.contains { bet in
                    bet.count >= 6 && Array(bet.prefix(6)) == actual
                }
            }
            let failureReasons = covered == false
                ? maintenanceFinalOutcomeFailureReasons(
                    storedOutcomes: record.outcomes,
                    matchNumbers: record.matchNumbers,
                    config: calculated.config,
                    currentOutcomeSPs: comparisonTableOddsByID[record.id],
                    protectedProfile: protectedProfile,
                    protectedTolerance: protectedTolerance
                )
                : []
            if covered == true { exactHits += 1 }
            let rows = compressedTXTRows(matchNumbers: record.matchNumbers, bets: bets)
            let actualText = target?.map(String.init).joined() ?? "待赛果"
            let verification = covered.map {
                $0
                    ? "电脑按当前规则重算：TXT已找到实际赛果\(actualText)；条件结果同步通过。"
                    : "电脑按当前规则重算：TXT未找到实际赛果\(actualText)；未通过原因："
                        + (failureReasons.isEmpty
                            ? "终局组合未被保留，请核对固定场选项。"
                            : failureReasons.joined(separator: "；"))
            } ?? "电脑已按当前规则重算TXT，等待完整前6场赛果。"
            let text = [
                "期号：\(record.issue)",
                "TXT分组：总量",
                "生成方式：电脑按条件Tab当前规则全量重算",
                sharedTXTBody(rows: rows)
            ].joined(separator: "\n")
            let shared = SharedTXTQueryRecord(
                id: existingTXT?.id ?? UUID(),
                sharedAt: Date(),
                issue: record.issue,
                filename: "current-\(record.issue)-\(record.matchNumbers.joined(separator: "-"))-total.txt",
                txtContent: text,
                normalizedInput: calculated.config.normalizedInput,
                matchNumbers: record.matchNumbers,
                betOutcomes: bets,
                finalBetCount: bets.count,
                conditionSignature: maintenanceSignature,
                lastCheckedAt: Date(),
                observedOutcomes: target?.map(Optional.some),
                observedHandicaps: record.handicaps.map { Array($0.prefix(6)) },
                verificationMessage: verification,
                isFinalResult: target?.count == 6,
                isHit: covered,
                prizeAmount: covered == true ? record.amount : nil,
                prizeSPValues: existingTXT?.prizeSPValues
            )
            upsertSharedTXTQueryRecord(shared)
            let targetCoverageDetail: String?
            if covered == false, let target, target.count == 6 {
                targetCoverageDetail = "电脑终局覆盖=未通过：" + (
                    failureReasons.isEmpty
                        ? "终局组合未被保留，请核对固定场选项。"
                        : failureReasons.joined(separator: "；")
                )
            } else {
                targetCoverageDetail = nil
            }
            recomputedCounts[record.id] = GlobalPrizeFilterCounts(
                before: 729,
                removed: max(0, 729 - bets.count),
                after: bets.count,
                stageSummaries: calculated.majorFilterStageSummaries,
                outcomeSignature: prizeRecordOutcomeSignature(record),
                targetCoveredByFinalTXT: covered,
                targetCoverageDetail: targetCoverageDetail
            )
            generated += 1
            NSLog(
                "TXT-GLOBAL-RECOMPUTE progress=%ld/%ld bets=%ld covered=%@",
                offset + 1,
                targets.count,
                bets.count,
                covered == true ? "YES" : "NO"
            )
        }

        globalFilterCountsByRecordID = recomputedCounts
        globalFilterCacheConditionSignature = maintenanceSignature
        persistGlobalFilterCountCache()
        exportCurrentComputerMaintenancePayload(conditionSignature: maintenanceSignature)
        UserDefaults.standard.synchronize()
        let finalRecords = uniquePrizeQueryRecords
        let finalPassed = finalRecords.filter(globalPrizeRecordPasses).count
        NSLog(
            "TXT-GLOBAL-RECOMPUTE completed generated=%ld configMissing=%ld exactHits=%ld prize=%ld passed=%ld failed=%ld shared=%ld",
            generated,
            configMissing,
            exactHits,
            finalRecords.count,
            finalPassed,
            finalRecords.count - finalPassed,
            uniqueTXTQueryRecords.count
        )
    }

    /// 第三条宪法在历史批算的实现：只读500比分页的完整普通欧赔，
    /// 让球数优先使用该单查询时已保存的实际值，再经项目对照表换算。
    private func maintenanceComparisonTableOdds(
        for record: PrizeQueryRecord
    ) async throws -> [[Double]] {
        let numbers = Array(record.matchNumbers.prefix(5))
        let matches = try await FiveHundredBeijingSingleClient.fetchScorePageOdds(
            issue: record.issue,
            matchNumbers: numbers
        )
        let byNumber = Dictionary(uniqueKeysWithValues: matches.compactMap { match in
            Int(match.matchNumber).map { ($0, match) }
        })
        var rows: [[Double]] = []
        rows.reserveCapacity(numbers.count)
        for (offset, value) in numbers.enumerated() {
            guard let number = Int(value), let match = byNumber[number] else {
                throw GoalModelError.matchNotFound(value)
            }
            let savedHandicap = record.handicaps?.indices.contains(offset) == true
                ? record.handicaps?[offset]
                : nil
            guard let handicap = savedHandicap ?? match.handicap else {
                throw GoalModelError.handicapUnavailable(value)
            }
            guard let converted = HandicapOddsComparisonTable.convertedOdds(
                ordinaryOdds: match.marketOdds,
                handicap: handicap
            ) else {
                throw GoalModelError.oddsUnavailable(value)
            }
            rows.append(converted)
        }
        guard rows.count == 5 else { throw GoalModelError.invalidResponse }
        return rows
    }

    /// VIP3历史维护同样严格读六场普通欧赔，并优先使用单据当时已存的让球数。
    private func maintenanceVIP3Context(
        for record: PrizeQueryRecord,
        config: FilterConfig
    ) async throws -> VIP3MatchContext {
        let numbers = Array(record.matchNumbers.prefix(6))
        guard numbers.count == 6 else { throw GoalModelError.invalidResponse }
        var matches = try await FiveHundredBeijingSingleClient.fetchScorePageOdds(
            issue: record.issue,
            matchNumbers: numbers
        )
        if let stored = record.handicaps {
            let byNumber = Dictionary(uniqueKeysWithValues: zip(record.matchNumbers, stored).compactMap {
                pair -> (Int, Int)? in
                guard let number = Int(pair.0), let handicap = pair.1 else { return nil }
                return (number, handicap)
            })
            matches = matches.map { match in
                guard let number = Int(match.matchNumber), let handicap = byNumber[number] else {
                    return match
                }
                return match.replacingHandicap(handicap)
            }
        }
        let analyses = try await Task.detached(priority: .userInitiated) {
            try matches.map(PoissonGoalModel.analyze)
        }.value
        guard let odds = HandicapOddsComparisonTableMatrix.rows(
            matchNumbers: numbers,
            matches: analyses.map(\.match)
        ) else { throw GoalModelError.invalidResponse }
        let handicaps = analyses.compactMap(\.match.handicap)
        guard handicaps.count == 6 else { throw GoalModelError.invalidResponse }
        let comparisonLogic = odds.compactMap(LogicMapping.derivedFromComparisonTableOdds)
        guard comparisonLogic.count == 6 else { throw GoalModelError.invalidResponse }
        return VIP3MatchContext(
            comparisonTableOdds: odds,
            handicaps: handicaps,
            leagues: analyses.map(\.match.league),
            logic: comparisonLogic
        )
    }

    private func maintenanceVIP4Context(
        for record: PrizeQueryRecord,
        config: FilterConfig
    ) async throws -> VIP4MatchContext {
        let currentNumbers = Array(record.matchNumbers.prefix(6))
        guard currentNumbers.count == 6 else { throw GoalModelError.invalidResponse }
        var allNumbers = currentNumbers
        if let first = currentNumbers.first.flatMap(Int.init), first > 6 {
            allNumbers.append(contentsOf: ((first - 6)..<first).map(String.init))
        }
        allNumbers = Array(Set(allNumbers)).sorted { (Int($0) ?? 0) < (Int($1) ?? 0) }
        var matches = try await FiveHundredBeijingSingleClient.fetchScorePageOdds(
            issue: record.issue,
            matchNumbers: allNumbers
        )
        if let stored = record.handicaps {
            let saved = Dictionary(uniqueKeysWithValues: zip(record.matchNumbers, stored).compactMap {
                pair -> (Int, Int)? in
                guard let number = Int(pair.0), let handicap = pair.1 else { return nil }
                return (number, handicap)
            })
            matches = matches.map { match in
                guard let number = Int(match.matchNumber), let handicap = saved[number] else { return match }
                return match.replacingHandicap(handicap)
            }
        }
        let analyses = try await Task.detached(priority: .userInitiated) {
            try matches.map(PoissonGoalModel.analyze)
        }.value
        guard let context = vip4MatchContext(for: config, analyses: analyses) else {
            throw GoalModelError.invalidResponse
        }
        return context
    }

    /// 维护重算不能只报“TXT没找到”。这里用和引擎相同的顺序
    /// 重放该条实际赛果，把真正拦截它的条件写回查询 Cell。
    private func maintenanceFinalOutcomeFailureReasons(
        storedOutcomes: [Int]?,
        matchNumbers: [String],
        config: FilterConfig,
        currentOutcomeSPs: [[Double]]? = nil,
        protectedProfile: ComprehensiveAnalysisProfile?,
        protectedTolerance: ClosedRange<Int>
    ) -> [String] {
        guard config.conditionPackageEnabled || config.hasIndependentConditionGroups else { return [] }
        guard let storedOutcomes, storedOutcomes.count >= 6 else {
            return ["缺少完整前6场赛果"]
        }
        let firstSix = Array(storedOutcomes.prefix(6))
        if !config.conditionPackageEnabled { return config.independentOutcomeFailureReasons(firstSix, customOdds: currentOutcomeSPs) }
        if config.svip7RankOddsEnabled {
            return SequenceFilterEngine.svip7FailureReasons(outcomes: firstSix, customOdds: currentOutcomeSPs)
        }
        if config.six250RelationshipEnabled {
            return SequenceFilterEngine.baseFilterFailureReasons(for: firstSix, config: config, currentOutcomeSPs: currentOutcomeSPs)
        }
        let mainCount = config.logic.count
        guard firstSix.count >= mainCount else { return ["主场赛果数量不足"] }

        var reasons = SequenceFilterEngine.baseFilterFailureReasons(
            for: Array(firstSix.prefix(mainCount)),
            config: config,
            currentOutcomeSPs: currentOutcomeSPs
        )
        reasons.append(contentsOf: config.svip5FourCountFailureReasons(for: firstSix))
        reasons.append(contentsOf: config.frontFiveActualMFailureReasons(for: firstSix))
        reasons.append(contentsOf: config.frontFiveNoTripleDrawFailureReasons(for: firstSix))
        reasons.append(contentsOf: config.frontFiveLossCountFailureReasons(for: firstSix))
        reasons.append(contentsOf: config.frontFiveWinCountFailureReasons(for: firstSix))
        reasons.append(contentsOf: config.combinedThreeStructureFailureReasons(for: firstSix))
        reasons.append(contentsOf: config.sixLossCount14FailureReasons(for: firstSix))
        reasons.append(contentsOf: config.frontFiveR39FailureReasons(for: firstSix))
        reasons.append(contentsOf: config.frontFiveNoTripleLossFailureReasons(for: firstSix))
        var actualByMatch: [String: Int] = [:]
        for (number, outcome) in zip(matchNumbers.prefix(6), firstSix) {
            actualByMatch[normalizedStoredMatchNumber(number)] = outcome
        }
        var fullOutcomes = Array(firstSix.prefix(mainCount))
        var canEvaluateFullConditions = true
        for extra in config.extraMatches {
            let key = normalizedStoredMatchNumber(extra.matchNumber)
            let actual = actualByMatch[key] ?? (extra.outcomes.count == 1 ? extra.outcomes.first : nil)
            guard let actual else {
                reasons.append("场次\(extra.matchNumber)缺少实际赛果，无法核对固定选项")
                canEvaluateFullConditions = false
                continue
            }
            if !extra.outcomes.contains(actual) {
                reasons.append(
                    "场次\(extra.matchNumber)实际为\(actual)，但TXT只选\(extra.compactOutcomes)"
                )
            }
            fullOutcomes.append(actual)
        }

        if canEvaluateFullConditions {
            if config.consecutiveRunsEnabled && !config.passesConsecutiveRuns(fullOutcomes) {
                let values = [
                    "不败\(ConsecutiveRunCondition.nonLoss.longestRun(in: fullOutcomes))/\(config.nonLossRunRange.lowerBound)-\(config.nonLossRunRange.upperBound)",
                    "不平\(ConsecutiveRunCondition.nonDraw.longestRun(in: fullOutcomes))/\(config.nonDrawRunRange.lowerBound)-\(config.nonDrawRunRange.upperBound)",
                    "不胜\(ConsecutiveRunCondition.nonWin.longestRun(in: fullOutcomes))/\(config.nonWinRunRange.lowerBound)-\(config.nonWinRunRange.upperBound)"
                ]
                reasons.append(
                    "连续彩果未通过（\(values.joined(separator: "、"))，允许\(config.consecutiveRunToleranceRange.lowerBound)-\(config.consecutiveRunToleranceRange.upperBound)项不满足）"
                )
            }
            if config.sameResultRunsEnabled && !config.passesSameResultRuns(fullOutcomes) {
                let values = [
                    "连胜\(ConsecutiveRunCondition.win.longestRun(in: fullOutcomes))/\(config.winRunRange.lowerBound)-\(config.winRunRange.upperBound)",
                    "连平\(ConsecutiveRunCondition.draw.longestRun(in: fullOutcomes))/\(config.drawRunRange.lowerBound)-\(config.drawRunRange.upperBound)",
                    "连负\(ConsecutiveRunCondition.loss.longestRun(in: fullOutcomes))/\(config.lossRunRange.lowerBound)-\(config.lossRunRange.upperBound)"
                ]
                reasons.append(
                    "连续胜平负未通过（\(values.joined(separator: "、"))，允许\(config.sameResultRunToleranceRange.lowerBound)-\(config.sameResultRunToleranceRange.upperBound)项不满足）"
                )
            }
        }

        if let protectedProfile {
            let failureCount = SequenceFilterEngine.comprehensiveAnalysisFailureCount(
                fullOutcomes: firstSix,
                config: config,
                profile: protectedProfile,
                outcomeProbabilities: nil,
                outcomeSPs: nil
            )
            if !protectedTolerance.contains(failureCount) {
                reasons.append(
                    "大压缩未通过（实际\(failureCount)项不满足，允许\(protectedTolerance.lowerBound)-\(protectedTolerance.upperBound)项）"
                )
            }
        }
        if config.universal150CompressionEnabled,
           !SequenceFilterEngine.passesUniversal150Compression(fullOutcomes: firstSix, config: config) {
            reasons.append("通用150注统计压缩未通过")
        }
        if config.universal247ToleranceEnabled,
           !SequenceFilterEngine.usesVIP4Model(
                threshold: config.universal247ToleranceThreshold
           ),
           !SequenceFilterEngine.usesVIP3Model(
                threshold: config.universal247ToleranceThreshold
           ),
           !SequenceFilterEngine.usesVIP2Model(
                threshold: config.universal247ToleranceThreshold
           ) {
            let score = SequenceFilterEngine.universal247ActiveScore(
                fullOutcomes: firstSix,
                threshold: config.universal247ToleranceThreshold,
                logic: config.logic
            )
            let passes = SequenceFilterEngine.passesUniversal247Tolerance(
                fullOutcomes: firstSix,
                threshold: config.universal247ToleranceThreshold,
                logic: config.logic,
                productSumV10Top150Enabled: config.productSumV10Top150Enabled
            )
            if !passes {
                if SequenceFilterEngine.usesProductSumV10Model(
                    threshold: config.universal247ToleranceThreshold
                ) {
                    reasons.append(config.productSumV10Top150Enabled
                        ? "V10未通过（未同时进入V8前150注及ABCD结构Q50–299、S12–16范围）"
                        : "V10未通过（ABCD结构乘积Q不在50–299或和值S不在12–16）")
                } else if SequenceFilterEngine.usesJoint150V8Model(
                    threshold: config.universal247ToleranceThreshold
                ) {
                    reasons.append("V8联合150未通过（未进入概率＋ABCD＋V7联合评分前150注）")
                } else if SequenceFilterEngine.usesUniversal405WholeIssueModel(
                    threshold: config.universal247ToleranceThreshold
                ) {
                    let scoreText = score.map { String(format: "%.6f", $0) } ?? "数据不足"
                    reasons.append("V5整期留出通用压缩未通过（得分\(scoreText)，未进入统一前405种）")
                } else if SequenceFilterEngine.usesUniversal247GeneralV4Model(
                    threshold: config.universal247ToleranceThreshold
                ) {
                    let scoreText = score.map { String(format: "%.6f", $0) } ?? "数据不足"
                    reasons.append("通用247统计模型未通过（V4得分\(scoreText)，要求≥0.323295）")
                } else {
                    let scoreText = score.map { String(format: "%.6f", $0) } ?? "数据不足"
                    let thresholdText = String(format: "%.6f", config.universal247ToleranceThreshold)
                    reasons.append("通用247综合容错未通过（得分\(scoreText)，要求≥\(thresholdText)）")
                }
            }
        }
        if config.prizeStatisticalConditionEnabled {
            let switches = OutcomeCondition.winLossSwitches.value(in: firstSix)
            if switches > 2 {
                reasons.append("六串胜负直接切换\(switches)次，要求0-2次")
            }
        }
        return Array(Set(reasons)).sorted()
    }

    /// Mac维护用：将26094–26098每个未命中分组重放到各项条件，
    /// 输出真正的拦截原因，避免只报“TXT没找到”。
    @MainActor
    private func diagnoseBatchFailureReasonsForMaintenance(
        currentConditionInput: String
    ) {
        let expectedGroups: [String: Int] = [
            "26094": 66,
            "26095": 15,
            "26096": 66,
            "26097": 4,
            "26098": 24
        ]
        let protectedProfile = protectedHistoryMaxCompressionEnabled
            ? protectedHistoryMaxCompressionProfile
            : nil
        let protectedTolerance = effectiveProtectedHistoryToleranceRange
        let records = uniquePrizeQueryRecords
        var details: [[String: Any]] = []
        var categoryCounts: [String: Int] = [:]
        var issueFailureCounts: [String: Int] = [:]

        func category(for reason: String) -> String {
            if reason.contains("连续彩果") { return "连续彩果" }
            if reason.contains("连续胜平负") { return "连续胜平负" }
            if reason.contains("大压缩") { return "大压缩" }
            if reason.contains("通用247") { return "通用247综合容错" }
            if reason.contains("通用150") { return "通用150统计压缩" }
            if reason.contains("六串胜负直接切换") { return "奖金统计条件" }
            if reason.hasPrefix("场次") { return "固定场选项" }
            if reason.hasPrefix("S=") { return "基础条件：S" }
            if reason.hasPrefix("M=") { return "基础条件：M" }
            if reason.hasPrefix("σ²=") { return "基础条件：方差" }
            if reason.hasPrefix("判定值2") { return "基础条件：判定值2" }
            if reason.hasPrefix("P_tr=") { return "基础条件：P_tr" }
            if reason.hasPrefix("二阶波动") { return "基础条件：R" }
            if reason.hasPrefix("最终彩果断点") { return "基础条件：B" }
            if reason.hasPrefix("第") && reason.contains("主场判定值为4") {
                return "基础条件：指定位置禁4"
            }
            if reason.hasPrefix("前三场判定值4") {
                return "基础条件：前三场最多1个4"
            }
            if reason.contains("彩果条件") { return "基础条件：彩果容错" }
            return "其他/条件交互"
        }

        for issue in expectedGroups.keys.sorted() {
            guard let groupCount = expectedGroups[issue] else { continue }
            for start in stride(from: 2, to: 2 + groupCount * 6, by: 6) {
                let matchNumbers = (start..<(start + 6)).map(String.init) + ["1"]
                let key = TXTQueryStatisticsCalculator.ticketKey(
                    issue: issue,
                    matchNumbers: matchNumbers
                )
                guard let record = records.filter({
                    TXTQueryStatisticsCalculator.ticketKey(
                        issue: $0.issue,
                        matchNumbers: $0.matchNumbers
                    ) == key
                }).max(by: { $0.queriedAt < $1.queriedAt }) else { continue }
                guard let txt = exactTXTRecord(for: record), txt.isHit != true else { continue }
                guard let config = maintenanceGlobalTXTConfig(
                    for: record,
                    currentInput: currentConditionInput
                ) else { continue }
                var reasons = maintenanceFinalOutcomeFailureReasons(
                    storedOutcomes: record.outcomes,
                    matchNumbers: record.matchNumbers,
                    config: config,
                    protectedProfile: protectedProfile,
                    protectedTolerance: protectedTolerance
                )
                if reasons.isEmpty {
                    reasons = ["单项条件均可通过，但组合在终局交互压缩中未被保留"]
                }
                issueFailureCounts[issue, default: 0] += 1
                for value in Set(reasons.map(category(for:))) {
                    categoryCounts[value, default: 0] += 1
                }
                details.append([
                    "issue": issue,
                    "matches": matchNumbers,
                    "outcomes": Array((record.outcomes ?? []).prefix(6)),
                    "reasons": reasons,
                    "categories": Array(Set(reasons.map(category(for:)))).sorted()
                ])
            }
        }

        let root: [String: Any] = [
            "failedGroups": details.count,
            "issueFailureCounts": issueFailureCounts,
            "categoryCounts": categoryCounts,
            "details": details
        ]
        do {
            let data = try JSONSerialization.data(
                withJSONObject: root,
                options: [.prettyPrinted, .sortedKeys]
            )
            let url = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
                .appendingPathComponent("batch-failure-diagnostics.json")
            try data.write(to: url, options: .atomic)
            NSLog(
                "BATCH-FAILURE-DIAGNOSTICS failed=%ld categories=%@",
                details.count,
                categoryCounts.description
            )
        } catch {
            NSLog("BATCH-FAILURE-DIAGNOSTICS error=%@", error.localizedDescription)
        }
    }

    /// 将Mac本次使用“当前条件＋当前赛果”重算出的整套结果导出。
    /// 真机启动时四个文件成套导入，避免只更新条件计数却遗留旧TXT。
    @MainActor
    private func exportCurrentComputerMaintenancePayload(conditionSignature: String? = nil) {
        let encoder = JSONEncoder()
        let effectiveSignature = conditionSignature ?? globalFilterConditionsSignature
        let currentTXTRecords = uniqueTXTQueryRecords.filter {
            $0.conditionSignature == effectiveSignature
        }
        let abcdCache = UserDefaults.standard.dictionary(forKey: globalABCDCacheStorageKey) as? [String: String] ?? [:]
        let envelope = GlobalPrizeFilterCacheEnvelope(
            conditionSignature: effectiveSignature,
            countsByRecordID: globalFilterCountsByRecordID
        )
        do {
            try encoder.encode(currentTXTRecords).write(
                to: computerSharedTXTQueryHistoryURL,
                options: .atomic
            )
            try encoder.encode(uniquePrizeQueryRecords).write(
                to: computerPrizeHistoryURL,
                options: .atomic
            )
            try encoder.encode(abcdCache).write(
                to: computerABCDCacheURL,
                options: .atomic
            )
            try encoder.encode(envelope).write(
                to: computerGlobalAnswerCacheURL,
                options: .atomic
            )
            for issue in historicalBatchIssues {
                if let snapshot = historicalBatchSnapshots[issue] {
                    try encoder.encode(snapshot).write(
                        to: computerHistoricalBatchURL(for: issue),
                        options: .atomic
                    )
                }
            }
            NSLog(
                "GLOBAL-TXT-REGEN exported txt=%ld prize=%ld cache=%ld historicalBatches=%ld",
                currentTXTRecords.count,
                uniquePrizeQueryRecords.count,
                globalFilterCountsByRecordID.count,
                historicalBatchSnapshots.count
            )
        } catch {
            NSLog("GLOBAL-TXT-REGEN export failed error=%@", error.localizedDescription)
        }
    }

    private func maintenanceGlobalTXTConfig(
        for record: PrizeQueryRecord,
        currentInput: String? = nil
    ) -> FilterConfig? {
        guard record.matchNumbers.count >= 6,
              let logic = cachedABCD(for: record) else { return nil }
        return CurrentConditionConfigFactory.make(
            currentInput: currentInput ?? generatedInput,
            historicalMatchNumbers: record.matchNumbers,
            historicalABCD: logic
        )
    }

    @MainActor
    private func regenerateGlobalPrizeAnswers() async {
        guard !isRegeneratingGlobalPrizeAnswers else { return }
        isRegeneratingGlobalPrizeAnswers = true
        globalPrizeAnswerMessage = "正在从本地缓存同步查询结果…"
        let syncedQueryCount = syncStoredQueryResultsToGlobalAnswersFromCache()
        loadGlobalABCDCache()
        loadGlobalFilterCountCache()
        let records = uniquePrizeQueryRecords
        guard !records.isEmpty else {
            globalPrizeAnswerMessage = "没有可生成的奖金去重记录。"
            isRegeneratingGlobalPrizeAnswers = false
            return
        }
        // 页面先展示本地结果；网络与过滤计算继续异步进行，不再阻塞入口。
        isShowingGlobalPrizeAnswers = true
        await Task.yield()
        // 历史记录已经持久化；后续点击只联网更新最新一条，避免旧记录重复请求。
        let recordsToRefresh = Array(records.suffix(1))
        globalPrizeAnswerMessage = "已同步\(syncedQueryCount)条查询结果，增量更新最新记录0/\(recordsToRefresh.count)条…"
        var completed = 0
        var failed = 0
        for record in recordsToRefresh {
            guard !Task.isCancelled else { break }

            // ABCD 和彩果分别补全：任一数据源临时失败都不能清空已经保存的数据。
            var hasABCD = false
            if let recovered = cachedABCD(for: record) {
                // 先把以前全局生成/查询时保存的ABCD补进独立持久缓存。
                storeGlobalABCD(recovered, for: record)
                hasABCD = true
            } else {
                do {
                    let logic = try await fetchHistoricalABCD(
                        issue: record.issue,
                        matchNumbers: Array(record.matchNumbers.prefix(5))
                    )
                    storeGlobalABCD(logic, for: record)
                    hasABCD = true
                } catch {
                    // 保留内存缓存、持久化缓存和历史条件快照，不回退为空。
                }
            }

            do {
                let updated = try await backfilledPrizeQueryRecord(record)
                if let index = prizeQueryHistory.firstIndex(where: { $0.id == record.id }) {
                    prizeQueryHistory[index] = updated
                }
            } catch {
                // 彩果暂时不全时也保留原记录，下次继续补取。
            }

            if hasABCD {
                completed += 1
            } else {
                failed += 1
            }
            globalPrizeAnswerMessage = "正在更新\(completed + failed)/\(recordsToRefresh.count)条…"
        }
        deduplicatePrizeQueryHistory()
        savePrizeQueryHistory()
        // 所有记录都按条件Tab当前快照重新计算，避免旧缓存混入已关闭或已修改条件。
        let countRecords = uniquePrizeQueryRecords
        globalPrizeAnswerMessage = "正在按最新全部条件计算0/\(countRecords.count)条…"
        await rebuildGlobalFilterCountCache(
            for: countRecords,
            replacingExisting: true,
            markSignatureCurrent: true
        )
        if failed == 0, let latestDate = records.map(\.queriedAt).max() {
            UserDefaults.standard.set(latestDate, forKey: globalPrizeLastSyncStorageKey)
        }
        isRegeneratingGlobalPrizeAnswers = false
        globalPrizeAnswerMessage = failed == 0
            ? "已按条件Tab全部最新条件重新判断\(countRecords.count)条记录。"
            : "已按最新条件重算\(countRecords.count)条；最新记录仍有\(failed)条缺少ABCD。"
        archiveCurrentCalculationVersion(source: "奖金Tab再次生成全部结果")
        isShowingGlobalPrizeAnswers = true
    }

    private var globalPrizeLastSyncStorageKey: String {
        "sequenceFilter.globalPrizeLastSync.v1"
    }

    private var globalABCDCacheStorageKey: String {
        "sequenceFilter.globalABCDCache.v1"
    }

    private var globalFilterCountsCacheStorageKey: String {
        "sequenceFilter.globalFilterCountsCache.v1"
    }

    private var globalFilterConditionsSignatureStorageKey: String {
        "sequenceFilter.globalFilterConditionsSignature.v1"
    }

    private var computedCachePurgeMarkerStorageKey: String {
        "sequenceFilter.staleComputedCachesPurged.liveCurrentV6"
    }

    /// 升级到“只认当前条件”时一次性移除所有旧派生结果。
    /// 奖金历史、TXT原文和已取得的赛果不删除。
    @MainActor
    private func purgeLegacyComputedCachesIfNeeded() {
        let defaults = UserDefaults.standard
        guard !defaults.bool(forKey: computedCachePurgeMarkerStorageKey) else { return }

        defaults.removeObject(forKey: previousRunStorageKey)
        defaults.removeObject(forKey: globalFilterCountsCacheStorageKey)
        defaults.removeObject(forKey: globalFilterConditionsSignatureStorageKey)
        defaults.removeObject(forKey: globalABCDCacheStorageKey)
        defaults.removeObject(forKey: globalPrizeLastSyncStorageKey)
        defaults.removeObject(forKey: "sequenceFilter.globalAnswerCacheSeedCompleted.v1")
        defaults.set(true, forKey: computedCachePurgeMarkerStorageKey)
        defaults.synchronize()

        lastRunSnapshot = nil
        globalFilterCountsByRecordID = [:]
        globalFilterCacheConditionSignature = nil
        globalABCDByPrizeRecordID = [:]
        try? FileManager.default.removeItem(at: computerGlobalAnswerCacheURL)
        try? FileManager.default.removeItem(at: computerABCDCacheURL)
        globalPrizeAnswerMessage = "已删除旧奖金、查询、ABCD与条件计算缓存。"
    }

    /// 条件变更必须同时清理内存、UserDefaults 与待导入文件，
    /// 避免旧结果在下次启动或重装后再次出现。
    @MainActor
    private func invalidateComputedResultsAfterConditionChange() {
        globalFilterCountsByRecordID = [:]
        globalFilterCacheConditionSignature = nil
        lastRunSnapshot = nil
        let defaults = UserDefaults.standard
        defaults.removeObject(forKey: previousRunStorageKey)
        defaults.removeObject(forKey: globalFilterCountsCacheStorageKey)
        defaults.removeObject(forKey: globalFilterConditionsSignatureStorageKey)
        defaults.removeObject(forKey: globalPrizeLastSyncStorageKey)
        defaults.removeObject(forKey: "sequenceFilter.globalAnswerCacheSeedCompleted.v1")
        defaults.synchronize()
        try? FileManager.default.removeItem(at: computerGlobalAnswerCacheURL)
        var invalidatedTXT = false
        for index in sharedTXTQueryHistory.indices where !isCurrentConditionTXT(sharedTXTQueryHistory[index]) {
            if sharedTXTQueryHistory[index].isHit != nil
                || sharedTXTQueryHistory[index].prizeAmount != nil
                || sharedTXTQueryHistory[index].prizeSPValues != nil
                || sharedTXTQueryHistory[index].verificationMessage != "旧条件TXT已失效，禁止复用；请按当前条件重新生成。" {
                sharedTXTQueryHistory[index].isHit = nil
                sharedTXTQueryHistory[index].prizeAmount = nil
                sharedTXTQueryHistory[index].prizeSPValues = nil
                sharedTXTQueryHistory[index].verificationMessage = "旧条件TXT已失效，禁止复用；请按当前条件重新生成。"
                invalidatedTXT = true
            }
        }
        if invalidatedTXT { saveSharedTXTQueryHistory() }
        globalPrizeAnswerMessage = "条件已变更：旧奖金/查询计算结果已删除，等待电脑按当前条件重算。"
    }

    private func globalABCDCacheKey(for record: PrizeQueryRecord) -> String {
        TXTQueryStatisticsCalculator.uniqueKey(issue: record.issue, matchNumbers: Array(record.matchNumbers.prefix(5)))
    }

    private func normalizedABCD(_ value: String?) -> String? {
        guard let value else { return nil }
        let logic = value.filter { "ABCD".contains($0) }
        return logic.count == 5 ? logic : nil
    }

    private func cachedABCD(for record: PrizeQueryRecord) -> String? {
        let persisted = UserDefaults.standard.dictionary(forKey: globalABCDCacheStorageKey)
            as? [String: String] ?? [:]
        return normalizedABCD(globalABCDByPrizeRecordID[record.id])
            ?? normalizedABCD(persisted[globalABCDCacheKey(for: record)])
            ?? normalizedABCD(record.conditionSnapshots?.first?.logic)
            ?? historicalABCD(for: record)
    }

    /// 按“期号＋前5场”从所有本地历史数据中反查ABCD。
    /// 用 Int 比较场次号，兼容 "01" 与 "1" 两种写法。
    private func historicalABCD(for record: PrizeQueryRecord) -> String? {
        let issue = record.issue.trimmingCharacters(in: .whitespacesAndNewlines)
        let numbers = Array(record.matchNumbers.prefix(5)).compactMap(Int.init)
        guard numbers.count == 5 else { return nil }

        if let saved = recommendationHistory.reversed().first(where: {
            $0.issue.trimmingCharacters(in: .whitespacesAndNewlines) == issue
                && Array($0.matchNumbers.prefix(5)).compactMap(Int.init) == numbers
                && normalizedABCD($0.logic) != nil
        }), let logic = normalizedABCD(saved.logic) {
            return logic
        }

        if let logic = prizeQueryHistory.reversed().lazy.compactMap({ saved -> String? in
            guard saved.issue.trimmingCharacters(in: .whitespacesAndNewlines) == issue,
                  Array(saved.matchNumbers.prefix(5)).compactMap(Int.init) == numbers else { return nil }
            return saved.conditionSnapshots?.lazy.compactMap { normalizedABCD($0.logic) }.first
        }).first {
            return logic
        }

        if let logic = sharedTXTQueryHistory.reversed().lazy.compactMap({ saved -> String? in
            guard saved.issue.trimmingCharacters(in: .whitespacesAndNewlines) == issue,
                  let config = try? FilterConfig.parse(saved.normalizedInput),
                  Array(config.matchNumbers.prefix(5)).compactMap(Int.init) == numbers else { return nil }
            return normalizedABCD(config.logic.map(\.displayName).joined())
        }).first {
            return logic
        }

        if let logic = savedFilterSchemes.lazy.compactMap({ saved -> String? in
            guard saved.issue.trimmingCharacters(in: .whitespacesAndNewlines) == issue,
                  let config = try? FilterConfig.parse(saved.normalizedInput),
                  Array(config.matchNumbers.prefix(5)).compactMap(Int.init) == numbers else { return nil }
            return normalizedABCD(config.logic.map(\.displayName).joined())
        }).first {
            return logic
        }

        let lastIssue = UserDefaults.standard.string(forKey: goalModelIssueStorageKey)?
            .trimmingCharacters(in: .whitespacesAndNewlines)
        if lastIssue == issue,
           let snapshot = lastRunSnapshot,
           let config = try? FilterConfig.parse(snapshot.normalizedInput),
           Array(config.matchNumbers.prefix(5)).compactMap(Int.init) == numbers,
           let logic = normalizedABCD(config.logic.map(\.displayName).joined()) {
            return logic
        }
        return nil
    }

    private func loadGlobalABCDCache() {
        var persisted = UserDefaults.standard.dictionary(forKey: globalABCDCacheStorageKey) as? [String: String] ?? [:]
        var changed = false
        for record in prizeQueryHistory {
            let key = globalABCDCacheKey(for: record)
            if let logic = normalizedABCD(persisted[key]) {
                globalABCDByPrizeRecordID[record.id] = logic
            } else if let logic = normalizedABCD(record.conditionSnapshots?.first?.logic)
                ?? historicalABCD(for: record) {
                globalABCDByPrizeRecordID[record.id] = logic
                persisted[key] = logic
                changed = true
            }
        }
        if changed {
            UserDefaults.standard.set(persisted, forKey: globalABCDCacheStorageKey)
        }
    }

    private func loadGlobalFilterCountCache() {
        let defaults = UserDefaults.standard
        guard let signature = defaults.string(forKey: globalFilterConditionsSignatureStorageKey),
              let data = defaults.data(forKey: globalFilterCountsCacheStorageKey),
              let cached = try? JSONDecoder().decode([Int: GlobalPrizeFilterCounts].self, from: data)
        else { return }
        guard signature == globalFilterConditionsSignature else {
            globalFilterCountsByRecordID = [:]
            globalFilterCacheConditionSignature = nil
            defaults.removeObject(forKey: globalFilterCountsCacheStorageKey)
            defaults.removeObject(forKey: globalFilterConditionsSignatureStorageKey)
            globalPrizeAnswerMessage = "已清除与条件Tab最新条件不一致的旧计算结果。"
            return
        }
        let validCounts = currentOutcomeMatchingFilterCounts(cached)
        globalFilterCountsByRecordID = validCounts
        globalFilterCacheConditionSignature = signature
        if validCounts.count != cached.count {
            persistGlobalFilterCountCache()
        }
        if !validCounts.isEmpty {
            globalPrizeAnswerMessage = "已载入\(validCounts.count)条与当前条件及当前赛果完全一致的电脑计算结果。"
        }
    }

    private func currentOutcomeMatchingFilterCounts(
        _ values: [Int: GlobalPrizeFilterCounts]
    ) -> [Int: GlobalPrizeFilterCounts] {
        let recordsByID = Dictionary(uniqueKeysWithValues: uniquePrizeQueryRecords.map { ($0.id, $0) })
        return values.filter { id, counts in
            guard let record = recordsByID[id],
                  let currentOutcome = prizeRecordOutcomeSignature(record),
                  counts.targetCoveredByFinalTXT != nil else { return false }
            return counts.outcomeSignature == currentOutcome
        }
    }

    private func persistGlobalFilterCountCache() {
        guard let data = try? JSONEncoder().encode(globalFilterCountsByRecordID) else { return }
        let defaults = UserDefaults.standard
        defaults.set(data, forKey: globalFilterCountsCacheStorageKey)
        if let signature = globalFilterCacheConditionSignature {
            defaults.set(signature, forKey: globalFilterConditionsSignatureStorageKey)
        } else {
            defaults.removeObject(forKey: globalFilterConditionsSignatureStorageKey)
        }
        scheduleDurableBackup()
    }

    private func storeGlobalABCD(_ value: String, for record: PrizeQueryRecord) {
        guard let logic = normalizedABCD(value) else { return }
        globalABCDByPrizeRecordID[record.id] = logic
        var persisted = UserDefaults.standard.dictionary(forKey: globalABCDCacheStorageKey) as? [String: String] ?? [:]
        persisted[globalABCDCacheKey(for: record)] = logic
        UserDefaults.standard.set(persisted, forKey: globalABCDCacheStorageKey)
        scheduleDurableBackup()
    }

    private func fetchHistoricalABCD(issue: String, matchNumbers: [String]) async throws -> String {
        func logic(from matches: [BeijingSingleMatch]) throws -> String {
            let analyses = try matches.map(PoissonGoalModel.analyze)
            guard analyses.count == 5 else { throw GoalModelError.invalidResponse }
            return analyses.map(\.recommendedLogic.displayName).joined()
        }

        func handicapOddsLogic(from matches: [BeijingSingleMatch]) throws -> String {
            guard matches.count == 5 else { throw GoalModelError.invalidResponse }
            return try matches.map { match in
                guard match.referenceSP.count == 3,
                      match.referenceSP.allSatisfy({ $0 > 1 && $0.isFinite }) else {
                    throw GoalModelError.oddsUnavailable(match.matchNumber)
                }
                let inverse = match.referenceSP.map { 1 / $0 }
                let total = inverse.reduce(0, +)
                guard total > 0 && total.isFinite else {
                    throw GoalModelError.oddsUnavailable(match.matchNumber)
                }
                let probabilities = inverse.map { $0 / total }
                return PoissonGoalModel.recommendedLogic(for: probabilities).mapping.displayName
            }.joined()
        }

        // 已结束场次优先直连500比分页。该页在开奖后仍保留完整普通赔率，
        // Poisson模型再结合让球数重建让球胜/平/负概率。
        do {
            let matches = try await FiveHundredBeijingSingleClient.fetchScorePageOdds(
                issue: issue,
                matchNumbers: matchNumbers
            )
            return try logic(from: matches)
        } catch {
            // 比分页暂时不可用时，继续尝试完整让球SP及其他入口。
        }

        // 若比分页同时保留完整让球三项SP，直接按隐含概率生成ABCD。
        do {
            let matches = try await FiveHundredBeijingSingleClient.fetchHistoricalHandicapOdds(
                issue: issue,
                matchNumbers: matchNumbers
            )
            return try handicapOddsLogic(from: matches)
        } catch {
            // 让球历史SP不全时，再使用原有多源模型。
        }

        // 500网交易页、直播/历史页、奖金页逐级回退，最后再试澳客。
        do {
            return try logic(from: await FiveHundredBeijingSingleClient.fetch(
                issue: issue,
                matchNumbers: matchNumbers
            ))
        } catch {
            // 历史场次可能已从交易页下架，继续尝试其他入口。
        }
        do {
            let matches = try await FiveHundredBeijingSingleClient.fetchLiveMatches(
                issue: issue,
                matchNumbers: matchNumbers
            )
            return try logic(from: matches)
        } catch {
            // 直播页缺历史赔率时继续尝试奖金页。
        }
        do {
            let matches = try await FiveHundredBeijingSingleClient.fetchPrizeMatches(
                issue: issue,
                matchNumbers: matchNumbers
            )
            if matches.allSatisfy({ $0.referenceSP.count == 3 }) {
                return try handicapOddsLogic(from: matches)
            }
            return try logic(from: matches)
        } catch {
            let matches = try await OkoooBeijingSingleClient.fetch(
                issue: issue,
                matchNumbers: matchNumbers
            )
            return try logic(from: matches)
        }
    }

    private func schedulePrizeDerivedStatisticsRefresh() {
        let history = prizeQueryHistory
        var seventhSingleByTicketKey: [String: Int] = [:]
        for record in sharedTXTQueryHistory where isCurrentConditionTXT(record) {
            guard let single = savedSeventhSingleOutcome(record) else { continue }
            seventhSingleByTicketKey[TXTQueryStatisticsCalculator.ticketKey(
                issue: record.issue,
                matchNumbers: record.matchNumbers
            )] = single
        }
        prizeDerivedStatisticsRefreshTask?.cancel()
        prizeDerivedStatisticsRefreshTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 180_000_000)
            guard !Task.isCancelled else { return }
            let snapshot = await Task.detached(priority: .utility) {
                Self.makePrizeRunStatistics(
                    history: history,
                    seventhSingleByTicketKey: seventhSingleByTicketKey
                )
            }.value
            guard !Task.isCancelled else { return }
            cachedPrizeRunStatistics = snapshot
        }
    }

    nonisolated private static func makePrizeRunStatistics(
        history: [PrizeQueryRecord],
        seventhSingleByTicketKey: [String: Int]
    ) -> PrizeRunStatisticsSnapshot {
        var sampleCount = 0
        var three = 0
        var one = 0
        var zero = 0
        var explodeRed = 0
        var protectedDrawPair = 0
        for record in history {
            guard (6...7).contains(record.matchNumbers.count),
                  let storedOutcomes = record.outcomes,
                  storedOutcomes.count >= record.matchNumbers.count else { continue }
            let outcomes: [Int]
            if record.matchNumbers.count == 6 {
                outcomes = Array(storedOutcomes.prefix(6))
            } else {
                let key = TXTQueryStatisticsCalculator.ticketKey(
                    issue: record.issue,
                    matchNumbers: record.matchNumbers
                )
                outcomes = Array(storedOutcomes.prefix(6))
                    + [seventhSingleByTicketKey[key] ?? storedOutcomes[6]]
            }
            guard let summary = PrizeCalculator.outcomeSummary(for: outcomes) else { continue }
            sampleCount += 1
            if summary.win >= 2 { three += 1 }
            if summary.draw >= 2 { one += 1 }
            if summary.loss >= 2 { zero += 1 }
            if PrizeCalculator.shouldExplodeRed(for: outcomes) { explodeRed += 1 }
            if PrizeCalculator.sameResultRunsAtLeastTwoCount(in: outcomes) >= 2,
               PrizeCalculator.hasConsecutiveDrawPair(in: outcomes) {
                protectedDrawPair += 1
            }
        }
        return PrizeRunStatisticsSnapshot(
            sampleCount: sampleCount,
            three: three,
            one: one,
            zero: zero,
            explodeRed: explodeRed,
            protectedDrawPair: protectedDrawPair
        )
    }

    private var prizeTwoRunsAtLeastTwoRecords: [PrizeQueryRecord] {
        uniquePrizeQueryRecords.filter { record in
            guard let outcomes = storedSevenOutcomes(for: record),
                  let summary = PrizeCalculator.outcomeSummary(for: outcomes) else { return false }
            return [summary.win, summary.draw, summary.loss].filter { $0 >= 2 }.count >= 2
        }
    }

    private var prizeOtherCompleteRunRecords: [PrizeQueryRecord] {
        uniquePrizeQueryRecords.filter { record in
            guard let outcomes = storedSevenOutcomes(for: record),
                  let summary = PrizeCalculator.outcomeSummary(for: outcomes) else { return false }
            return [summary.win, summary.draw, summary.loss].filter { $0 >= 2 }.count < 2
        }
    }

    private var prizeExplodeRedRecords: [PrizeQueryRecord] {
        uniquePrizeQueryRecords.filter { record in
            storedSevenOutcomes(for: record).map(PrizeCalculator.shouldExplodeRed) == true
        }
    }

    private var prizeProtectedDrawPairRecords: [PrizeQueryRecord] {
        uniquePrizeQueryRecords.filter { record in
            guard let outcomes = storedSevenOutcomes(for: record) else { return false }
            return PrizeCalculator.sameResultRunsAtLeastTwoCount(in: outcomes) >= 2
                && PrizeCalculator.hasConsecutiveDrawPair(in: outcomes)
        }
    }

    private var prizeIncompleteRunRecords: [PrizeQueryRecord] {
        uniquePrizeQueryRecords.filter { storedSevenOutcomes(for: $0) == nil }
    }

