    private func globalFilterConfig(
        for record: PrizeQueryRecord,
        excludesHistoricalPairing: Bool = true
    ) -> FilterConfig? {
        guard record.matchNumbers.count >= 6,
              let logic = cachedABCD(for: record) else { return nil }
        return CurrentConditionConfigFactory.make(
            currentInput: generatedInput,
            historicalMatchNumbers: record.matchNumbers,
            historicalABCD: logic,
            disablesHistoricalCountPairing: excludesHistoricalPairing
        )
    }

    @MainActor
    private var globalFilterConditionsSignature: String {
        let input = isRestoringInputDefaults
            ? persistedCurrentConditionInputForMaintenance()
            : generatedInput
        return globalFilterConditionsSignature(for: input)
    }

    @MainActor
    private func globalFilterConditionsSignature(
        for input: String,
        persistedValues: [String: String]? = nil
    ) -> String {
        var fields = FilterConfig.canonicalFinalOutcomeRequestTokens(in: input).split(separator: "|", omittingEmptySubsequences: false).map(String.init)
        if !fields.isEmpty { fields[0] = "<MATCHES>" }
        if fields.count > 1 { fields[1] = "<ABCD>" }
        fields = fields.map {
            let upper = $0.uppercased()
            return upper.hasPrefix("PRIZECOUNTON=")
                ? upper.split(separator: "=").first.map { "\($0)=0" } ?? $0
                : $0
        }
        fields.removeAll { $0.contains(":") }
        let persistedProtectedProfile: ComprehensiveAnalysisProfile? = persistedValues
            .flatMap { $0["protectedHistoryMaxCompressionProfile"] }
            .flatMap { Data(base64Encoded: $0) }
            .flatMap { try? JSONDecoder().decode(ComprehensiveAnalysisProfile.self, from: $0) }
        let effectiveProtectedProfile = persistedValues == nil
            ? protectedHistoryMaxCompressionProfile
            : persistedProtectedProfile
        let protectedEnabled = persistedValues.map {
            $0["protectedHistoryMaxCompressionEnabled"] == "1" && effectiveProtectedProfile != nil
        } ?? protectedHistoryMaxCompressionEnabled
        let persistedProtectedTolerance = persistedValues.flatMap {
            ($0["protectedHistoryToleranceEnabled"] == "1")
                ? parseIntegerRange($0["protectedHistoryToleranceInput"] ?? "0-0", maximum: 24)
                : 0...0
        }
        let protectedTolerance = persistedProtectedTolerance ?? effectiveProtectedHistoryToleranceRange
        let protectedSignature = protectedEnabled
            ? "HISTMAX=\(effectiveProtectedProfile?.historyRecordCount ?? 0)-\(effectiveProtectedProfile?.rules.count ?? 0)-\(effectiveProtectedProfile?.generatedAt.timeIntervalSince1970 ?? 0)-TOL\(protectedTolerance.lowerBound)-\(protectedTolerance.upperBound)-CAPOFF"
            : "HISTMAX=OFF"
        let persistedComprehensiveProfile: ComprehensiveAnalysisProfile? = persistedValues
            .flatMap { $0["comprehensiveAnalysisProfile"] }
            .flatMap { Data(base64Encoded: $0) }
            .flatMap { try? JSONDecoder().decode(ComprehensiveAnalysisProfile.self, from: $0) }
        let effectiveComprehensiveProfile = persistedValues == nil
            ? comprehensiveAnalysisProfile
            : persistedComprehensiveProfile
        let comprehensiveEnabled = persistedValues.map {
            $0["comprehensiveAnalysisFilterEnabled"] == "1" && effectiveComprehensiveProfile != nil
        } ?? comprehensiveAnalysisFilterEnabled
        let effectiveComprehensiveTolerance = persistedValues?["comprehensiveAnalysisToleranceInput"]
            ?? comprehensiveAnalysisToleranceInput
        let comprehensiveSignature = comprehensiveEnabled
            ? "COMPREHENSIVE=\(effectiveComprehensiveTolerance)-\(effectiveComprehensiveProfile?.rules.count ?? 0)-\(effectiveComprehensiveProfile?.generatedAt.timeIntervalSince1970 ?? 0)"
            : "COMPREHENSIVE=OFF"
        let universal150IsEnabled = fields.contains { $0.uppercased() == "U150ON=1" }
        let universal247IsEnabled = fields.contains { $0.uppercased() == "U247ON=1" }
        let universal150Signature = universal150IsEnabled
            ? "U150MODEL=\(SequenceFilterEngine.universal150CompressionModelVersion)"
            : "U150MODEL=OFF"
        let universal247Signature = universal247IsEnabled
            ? "U247MODEL=\(SequenceFilterEngine.universal247ToleranceModelVersion)-TH\(fields.first(where: { $0.uppercased().hasPrefix("U247TH=") }) ?? "U247TH=-0.050756")"
            : "U247MODEL=OFF"
        let noFourRuleSignature = fields.contains { $0.uppercased() == "NO4LOWODDS=1" }
            ? "|NO4RULE=MINIMUM-MAPPED-FOUR-PROBABILITY-V2"
            : ""
        let oddsGateEnabled = persistedValues.map {
            $0["overallOddsForecastGateEnabled"] != "0"
                && ($0["svvvSelected"] != "1" || $0["svip10Enabled"] != "0")
        } ?? (overallOddsForecastGateEnabled && (!svvvSelected || svip10Enabled))
        let oddsGateSignature = "|ODDSGATE500ON=\(oddsGateEnabled ? 1 : 0)"
        return fields.joined(separator: "|") + "|" + comprehensiveSignature + "|" + protectedSignature + "|UNIVERSAL=RANGE24-TOLERANCE-ZERO|" + universal247Signature + "|" + universal150Signature + noFourRuleSignature + oddsGateSignature + "|ODDSTABLE=ORDINARY3-HANDICAP-POISSON18-DCM008-V1|EVAL=TXT-SINGLE-SOURCE-OF-TRUTH-V17-LIVE-CONDITION-TAB"
    }

    @MainActor
    private func isCurrentConditionTXT(_ record: SharedTXTQueryRecord) -> Bool {
        record.conditionSignature == globalFilterConditionsSignature
    }

    @MainActor
    private func rebuildGlobalFilterCountCache(
        for records: [PrizeQueryRecord],
        replacingExisting: Bool,
        markSignatureCurrent: Bool = true
    ) async {
        #if !targetEnvironment(simulator)
        // 全量枚举及大压缩仅允许在Mac的iOS Simulator维护流程中执行。
        // 真机只导入 global-answer-cache.json，避免同一查询得到两套结果。
        NSLog("Skipped filter engine on physical device; waiting for computer cache")
        return
        #else
        let jobs = records.compactMap { record -> (Int, FilterConfig, String?, [Int]?)? in
            globalFilterConfig(for: record).map {
                (
                    record.id,
                    $0,
                    prizeRecordOutcomeSignature(record),
                    record.outcomes.map { Array($0.prefix(6)) }
                )
            }
        }
        let protectedPrizePrefixes = protectedPrizeOutcomePrefixes
        let protectedHistoryProfile = protectedHistoryMaxCompressionEnabled
            ? protectedHistoryMaxCompressionProfile
            : nil
        let comprehensiveProfile = comprehensiveAnalysisFilterEnabled
            ? comprehensiveAnalysisProfile
            : nil
        let comprehensiveTolerance = comprehensiveAnalysisFilterEnabled
            ? parsedComprehensiveAnalysisToleranceRange
            : nil
        let protectedHistoryTolerance = effectiveProtectedHistoryToleranceRange
        let protectedHistoryCap = effectiveProtectedHistoryBetCap
        // 引擎计算是纯函数；Mac维护端用3个有界worker并行。
        // 不会在真机执行，且限制并发度避免全局生成时内存峰值过高。
        let calculated = await Task.detached(priority: .userInitiated) {
            let workerCount = min(3, max(1, jobs.count))
            return await withTaskGroup(of: [Int: GlobalPrizeFilterCounts].self) { group in
                for worker in 0..<workerCount {
                    group.addTask {
                        var local: [Int: GlobalPrizeFilterCounts] = [:]
                        for index in stride(from: worker, to: jobs.count, by: workerCount) {
                            guard !Task.isCancelled else { break }
                            let job = jobs[index]
                            let result = SequenceFilterEngine.calculate(
                                job.1,
                                previousContext: nil,
                                comprehensiveAnalysisProfile: comprehensiveProfile,
                                comprehensiveAnalysisToleranceRange: comprehensiveTolerance ?? 0...0,
                                protectedHistoryProfile: protectedHistoryProfile,
                                protectedHistoryToleranceRange: protectedHistoryTolerance,
                                protectedHistoryBetCap: protectedHistoryCap,
                                protectedPrizeOutcomePrefixes: protectedPrizePrefixes
                            )
                            let uniqueBets = result.uniqueExpandedBets
                            let after = uniqueBets.count
                            let before = 729
                            let targetCovered = job.3.map { target in
                                target.count == 6 && uniqueBets.contains { bet in
                                    bet.count >= 6 && Array(bet.prefix(6)) == target
                                }
                            }
                            let targetCoverageDetail: String?
                            if targetCovered == false, let target = job.3, target.count == 6 {
                                let mainCount = min(job.1.logic.count, target.count)
                                let keptMainOutcomes = Set(uniqueBets.compactMap { bet -> String? in
                                    guard bet.count >= mainCount else { return nil }
                                    return Array(bet.prefix(mainCount)).map(String.init).joined()
                                })
                                targetCoverageDetail = "电脑终局覆盖=未通过：" + SequenceFilterEngine.missedOutcomeAnalysis(
                                    outcomes: Array(target.prefix(mainCount)),
                                    config: job.1,
                                    savedKeptOutcomes: keptMainOutcomes
                                )
                            } else {
                                targetCoverageDetail = nil
                            }
                            local[job.0] = GlobalPrizeFilterCounts(
                                before: before,
                                removed: max(0, before - after),
                                after: after,
                                stageSummaries: result.majorFilterStageSummaries,
                                outcomeSignature: job.2,
                                targetCoveredByFinalTXT: targetCovered,
                                targetCoverageDetail: targetCoverageDetail
                            )
                            NSLog(
                                "Global answer cell computation: %ld/%ld worker=%ld",
                                index + 1,
                                jobs.count,
                                worker + 1
                            )
                        }
                        return local
                    }
                }
                var values: [Int: GlobalPrizeFilterCounts] = [:]
                values.reserveCapacity(jobs.count)
                for await local in group {
                    values.merge(local) { _, new in new }
                }
                return values
            }
        }.value
        if replacingExisting {
            globalFilterCountsByRecordID = calculated
        } else {
            globalFilterCountsByRecordID.merge(calculated) { _, new in new }
        }
        if markSignatureCurrent {
            globalFilterCacheConditionSignature = globalFilterConditionsSignature
        }
        persistGlobalFilterCountCache()
        #endif
    }

    private func prizeRecordOutcomeSignature(_ record: PrizeQueryRecord) -> String? {
        guard let outcomes = record.outcomes, outcomes.count >= 6 else { return nil }
        return Array(outcomes.prefix(6)).map(String.init).joined()
    }

    /// 页面渲染时只读缓存，严禁在SwiftUI body/Cell中运行过滤引擎。
    private func globalFilterCounts(for record: PrizeQueryRecord) -> GlobalPrizeFilterCounts? {
        guard globalFilterCacheConditionSignature == globalFilterConditionsSignature,
              let counts = globalFilterCountsByRecordID[record.id],
              let currentOutcome = prizeRecordOutcomeSignature(record),
              counts.outcomeSignature == currentOutcome else { return nil }
        return counts
    }

    private func prizeRecordShouldExplodeRed(_ record: PrizeQueryRecord) -> Bool {
        storedSevenOutcomes(for: record).map(PrizeCalculator.shouldExplodeRed) == true
    }

