    private var uniquePrizeQueryRecords: [PrizeQueryRecord] {
        // 奖金历史在载入、电脑数据覆盖和保存时已按“期号＋前6场”去重。
        // 直接返回状态数组，避免奖金 Tab 一次 body 评估重建多份字典。
        prizeQueryHistory
    }

    /// 26091—26098 所有已保存单据的合并集合。
    /// `uniquePrizeQueryRecords` 已按“期号＋前6场”去重，因此这里只做期号范围筛选，
    /// 不重新抓取、重新计算或改写用户原有结果。
    private var mergedHistoricalPrizeRecords: [PrizeQueryRecord] {
        uniquePrizeQueryRecords.filter { historicalMergedIssues.contains($0.issue) }
    }

    /// V11的冻结单只改变历史统计分母，不改写已保存的赛果。
    /// 优先使用存档快照的判定值2个数；旧快照缺失时再用同场ABCD重算。
    private func isCurrentFrozenV11Record(_ record: PrizeQueryRecord) -> Bool {
        guard usesCurrentFrozenVIPRules else { return false }
        return isVIP1FrozenRecord(record)
    }

    /// VIP 1电脑批算不依赖SwiftUI选择器的异步回填时机。
    private func isVIP1FrozenRecord(_ record: PrizeQueryRecord) -> Bool {
        if let count = record.conditionSnapshots?.first?.valueTwoCount {
            return count >= 4
        }
        guard let outcomes = record.outcomes, outcomes.count >= 5,
              let logic = cachedABCD(for: record) else { return false }
        let mappings = logic.lowercased().compactMap { LogicMapping(rawValue: String($0)) }
        guard mappings.count == 5 else { return false }
        let values = zip(mappings, outcomes.prefix(5)).map { $0.value(for: $1) }
        return values.filter { $0 == 2 }.count >= 4
    }

    private var protectedPrizeOutcomePrefixes: Set<[Int]> {
        protectedPrizeOutcomePrefixesCache
    }

    private func refreshProtectedPrizeOutcomePrefixesCache() {
        let currentInput = generatedInput
        let candidates = uniquePrizeQueryRecords.compactMap { record -> ProtectedPrizeRecalculationInput? in
            guard let snapshot = record.conditionSnapshots?.first,
                  snapshot.outcomes.count >= 6,
                  let logic = cachedABCD(for: record) else { return nil }
            return ProtectedPrizeRecalculationInput(
                matchNumbers: record.matchNumbers,
                logic: logic,
                snapshot: snapshot
            )
        }
        let analysisEnabled = comprehensiveAnalysisFilterEnabled
        let analysisProfile = comprehensiveAnalysisProfile
        let analysisTolerance = parsedComprehensiveAnalysisToleranceRange
        protectedPrizePrefixRefreshTask?.cancel()
        protectedPrizePrefixRefreshTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 220_000_000)
            guard !Task.isCancelled else { return }
            let prefixes = await Task.detached(priority: .utility) {
                Set(candidates.compactMap { candidate -> [Int]? in
                    guard let config = CurrentConditionConfigFactory.make(
                        currentInput: currentInput,
                        historicalMatchNumbers: candidate.matchNumbers,
                        historicalABCD: candidate.logic,
                        disablesHistoricalCountPairing: true
                    ), Self.historicalGlobalConditionPassFlags(
                        candidate.snapshot,
                        config: config
                    ).allSatisfy({ $0 }) else { return nil }
                    if analysisEnabled {
                        guard let analysisProfile, let analysisTolerance,
                              analysisTolerance.contains(
                                Self.comprehensiveAnalysisFailureCount(
                                    candidate.snapshot,
                                    profile: analysisProfile
                                )
                              ) else { return nil }
                    }
                    return Array(candidate.snapshot.outcomes.prefix(6))
                })
            }.value
            guard !Task.isCancelled else { return }
            protectedPrizeOutcomePrefixesCache = prefixes
        }
    }

    private func prizeRecordCompletenessScore(_ record: PrizeQueryRecord) -> Int {
        var score = 0
        if (record.outcomes?.count ?? 0) >= 6 { score += 8 }
        if storedSeventhSingleOutcome(for: record) != nil { score += 4 }
        if record.conditionSnapshots?.isEmpty == false { score += 2 }
        if record.isSettled { score += 1 }
        return score
    }

    private func normalizedStoredMatchNumber(_ value: String) -> String {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return Int(trimmed).map(String.init) ?? trimmed
    }

    private func matchingTXTRecord(for prizeRecord: PrizeQueryRecord) -> SharedTXTQueryRecord? {
        let issue = prizeRecord.issue.trimmingCharacters(in: .whitespacesAndNewlines)
        let firstSix = prizeRecord.matchNumbers.prefix(6).map(normalizedStoredMatchNumber)
        return sharedTXTQueryHistory
            .filter { record in
                isCurrentConditionTXT(record)
                    && record.issue.trimmingCharacters(in: .whitespacesAndNewlines) == issue
                    && record.matchNumbers.prefix(6).map(normalizedStoredMatchNumber) == firstSix
                    && savedSeventhSingleOutcome(record) != nil
            }
            .max { $0.sharedAt < $1.sharedAt }
    }

    private func exactTXTRecord(for prizeRecord: PrizeQueryRecord) -> SharedTXTQueryRecord? {
        let key = TXTQueryStatisticsCalculator.ticketKey(
            issue: prizeRecord.issue,
            matchNumbers: prizeRecord.matchNumbers
        )
        return sharedTXTQueryHistory.filter {
            isCurrentConditionTXT($0)
                && TXTQueryStatisticsCalculator.ticketKey(
                    issue: $0.issue,
                    matchNumbers: $0.matchNumbers
                ) == key
        }.max { $0.sharedAt < $1.sharedAt }
    }

    private func storedSeventhSingleOutcome(for prizeRecord: PrizeQueryRecord) -> Int? {
        matchingTXTRecord(for: prizeRecord).flatMap(savedSeventhSingleOutcome)
    }

    private func storedSevenOutcomes(for prizeRecord: PrizeQueryRecord) -> [Int]? {
        guard (6...7).contains(prizeRecord.matchNumbers.count),
              let outcomes = prizeRecord.outcomes,
              outcomes.count >= prizeRecord.matchNumbers.count else { return nil }
        if prizeRecord.matchNumbers.count == 6 {
            return Array(outcomes.prefix(6))
        }
        if let single = storedSeventhSingleOutcome(for: prizeRecord) {
            return Array(outcomes.prefix(6)) + [single]
        }
        return Array(outcomes.prefix(7))
    }

    private func sixMatchPrizeAmount(for record: PrizeQueryRecord) -> Double? {
        if record.matchNumbers.count >= 6,
           record.amount.isFinite,
           record.amount > 0,
           (record.matchNumbers.count == 6 || record.calculationLabel?.hasPrefix("查询页自动同步") == true) {
            return record.amount
        }
        if let estimate = record.seventhEstimates?.first,
           estimate.sp.isFinite, estimate.sp > 0,
           estimate.amount.isFinite {
            return estimate.amount / estimate.sp
        }
        if let snapshot = record.conditionSnapshots?.first,
           snapshot.spCount == 6,
           snapshot.estimatedPrize.isFinite {
            return snapshot.estimatedPrize
        }
        return nil
    }

