                Text("第7场TXT单选：" + (single.map(String.init) ?? "使用500/澳客实际让球彩果"))
                    .font(.system(.caption, design: .monospaced).weight(.semibold))
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
            }
            if let sevenOutcomes {
                Text("\(sevenOutcomes.count)场实际统计序列：" + sevenOutcomes.map(String.init).joined())
                    .font(.system(.caption, design: .monospaced))
            }
            if let summary {
                Text("连续胜/平/负：\(summary.win)/\(summary.draw)/\(summary.loss)；连续不败/不平/不胜：\(summary.nonLoss)/\(summary.nonDraw)/\(summary.nonWin)")
