    private func prizeStatisticalConditionLine(_ record: PrizeQueryRecord) -> some View {
        let firstSix = Array((record.outcomes ?? []).prefix(6))
        let ready = firstSix.count == 6
        let switches = OutcomeCondition.winLossSwitches.value(in: firstSix)
        let switchPasses = ready && (0...2).contains(switches)
        let switchText = ready ? "\(switchPasses ? "满足" : "不满足")（\(switches)次）" : "待补全"
        let text = "六串胜负直接切换0–2：\(switchText)"
        return Text(text)
            .font(.caption.weight(.semibold))
            .foregroundStyle(SequenceFilterTheme.textSecondary)
            .fixedSize(horizontal: false, vertical: true)
    }

    private func analyzePrizeRecordsWithoutDualResults() {
        let rawRecordCount = prizeQueryHistory.count
        let records = uniquePrizeQueryRecords
        let firstSixComplete = records.filter { ($0.outcomes?.count ?? 0) >= 6 }
        let sevenMatchRecords = records.filter { $0.matchNumbers.count == 7 }
        let matchedSingleRecords = sevenMatchRecords.filter { storedSeventhSingleOutcome(for: $0) != nil }
        let sevenOutcomes = records.compactMap(storedSevenOutcomes)
        let summaries = sevenOutcomes.compactMap { PrizeCalculator.outcomeSummary(for: $0) }
        let threeRunAtLeastTwoCount = summaries.filter { $0.win >= 2 }.count
        let oneRunAtLeastTwoCount = summaries.filter { $0.draw >= 2 }.count
        let zeroRunAtLeastTwoCount = summaries.filter { $0.loss >= 2 }.count
        let explodeRedCount = sevenOutcomes.filter(PrizeCalculator.shouldExplodeRed).count
        let protectedBy11Count = sevenOutcomes.filter { outcomes in
            PrizeCalculator.sameResultRunsAtLeastTwoCount(in: outcomes) >= 2
                && PrizeCalculator.hasConsecutiveDrawPair(in: outcomes)
        }.count
        let amounts = records.compactMap(sixMatchPrizeAmount).filter(\.isFinite)
        let singles = records.compactMap(storedSeventhSingleOutcome)
        let singleCounts = Dictionary(grouping: singles, by: { $0 }).mapValues(\.count)
        let advancedSamples = records.compactMap { $0.conditionSnapshots?.first }
        var lines = [
            "【奖金查询总览】",
            "原始记录：\(rawRecordCount)次；按同期号＋同场次去重：\(records.count)次；重复保留但不重复计算：\(rawRecordCount - records.count)次。",
            "前6场彩果完整：\(firstSixComplete.count)次；缺失：\(records.count - firstSixComplete.count)次。",
            "7场记录匹配到当时TXT第7场单选：\(matchedSingleRecords.count)次；其余使用500/澳客实际让球彩果：\(sevenMatchRecords.count - matchedSingleRecords.count)次。",
            "让球彩果完整、可统计：\(sevenOutcomes.count)次；待赛果：\(records.count - sevenOutcomes.count)次。",
            "让球后连续3长度≥2：\(threeRunAtLeastTwoCount)次；连续1长度≥2：\(oneRunAtLeastTwoCount)次；连续0长度≥2：\(zeroRunAtLeastTwoCount)次。",
            "爆红（至少两项≥2且无11）：\(explodeRedCount)次；相邻11保护：\(protectedBy11Count)次。",
            "第7场单选：胜3 \(singleCounts[3, default: 0])次；平1 \(singleCounts[1, default: 0])次；负0 \(singleCounts[0, default: 0])次。",
            "6场SP奖金可计算：\(amounts.count)次；合计 ¥\(decimal(amounts.reduce(0, +)))；平均 ¥\(decimal(amounts.isEmpty ? 0 : amounts.reduce(0, +) / Double(amounts.count)))。",
            "高级指标可统计：\(advancedSamples.count)次。",
            "说明：6场记录按6场统计；7场记录优先用TXT已保存单选，否则用500/澳客的实际让球彩果，不使用3/0双结果。"
        ]
        if !summaries.isEmpty {
            lines += [
                "",
                "【完整6/7场条件统计】",
                commonIntLine("胜总数", summaries.map(\.winCount)),
                commonIntLine("平总数", summaries.map(\.drawCount)),
                commonIntLine("负总数", summaries.map(\.lossCount)),
                commonIntLine("彩果种类", summaries.map(\.diversity)),
                commonIntLine("彩果和值", summaries.map(\.outcomeSum)),
                commonIntLine("隔场回返", summaries.map(\.returns)),
                commonIntLine("胜负切换", summaries.map(\.winLossSwitches)),
                commonIntLine("连续不败", summaries.map(\.nonLoss)),
                commonIntLine("连续不平", summaries.map(\.nonDraw)),
                commonIntLine("连续不胜", summaries.map(\.nonWin)),
                commonIntLine("连续胜", summaries.map(\.win)),
                commonIntLine("连续平", summaries.map(\.draw)),
                commonIntLine("连续负", summaries.map(\.loss))
            ]
        }
        if !advancedSamples.isEmpty {
            lines += [
                "",
                "【ABCD与SP指标（每次只取1组）】",
                commonOptionalIntLine("乘积Q", advancedSamples.map(\.productQ)),
                commonOptionalIntLine("判定总和S", advancedSamples.map(\.sum)),
                commonOptionalIntLine("位移M", advancedSamples.map(\.displacement)),
                commonOptionalDoubleLine("稳定性σ²", advancedSamples.map(\.variance)),
                commonOptionalIntLine("二阶波动R", advancedSamples.map(\.roughness)),
                commonIntLine("彩果断点B", advancedSamples.map(\.breakpoints)),
                commonOptionalDoubleLine("SP和值", advancedSamples.map(\.spSum)),
                commonDoubleLine("SP乘积", advancedSamples.map(\.spProduct))
            ]
        }
        prizeTXTStatisticsMessage = lines.joined(separator: "\n")
    }

    private func prizeHistoryRow(_ record: PrizeQueryRecord) -> some View {
        let statisticalOutcomes = storedSevenOutcomes(for: record)
        let isExplodeRed = statisticalOutcomes.map(PrizeCalculator.shouldExplodeRed) == true
        let isProtectedBy11 = statisticalOutcomes.map { outcomes in
            PrizeCalculator.sameResultRunsAtLeastTwoCount(in: outcomes) >= 2
                && PrizeCalculator.hasConsecutiveDrawPair(in: outcomes)
        } == true
        return VStack(alignment: .leading, spacing: 5) {
            HStack {
                Text(String(format: "#%03d", record.id))
                    .font(.system(.headline, design: .monospaced))
                Text("第\(record.issue)期")
                    .font(.headline)
                Spacer()
                Text(record.queriedAt.formatted(date: .numeric, time: .shortened))
                    .font(.caption2)
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
            }
            Text("场次：" + displayedMatches(record.matchNumbers, handicaps: record.handicaps))
                .font(.system(.caption, design: .monospaced))
            Text(prizeHistoryOutcomeLine(record))
                .font(.system(.caption, design: .monospaced))
                .foregroundStyle(SequenceFilterTheme.textSecondary)
