            if isExplodeRed {
                Label("爆红：连续3/1/0至少两项≥2，且没有相邻11", systemImage: "exclamationmark.triangle.fill")
                    .font(.caption.weight(.bold))
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
            } else if isProtectedBy11 {
                Label("11保护：至少两项≥2，不爆红", systemImage: "shield.fill")
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
            }
            if prizeConditionAnalysisEnabled, (6...7).contains(record.matchNumbers.count) {
                if let summaries = prizeHistorySeventhRunSummaries(record) {
                    Text(prizeHistorySeventhRunLine(summaries))
                        .font(.system(.caption, design: .monospaced).weight(.semibold))
