                        .fixedSize(horizontal: false, vertical: true)
                    Text(prizeHistoryOutcomeCountLine(summaries))
                        .font(.system(.caption, design: .monospaced).weight(.semibold))
                        .fixedSize(horizontal: false, vertical: true)
                    Text(prizeHistoryOutcomeSumLine(summaries))
                        .font(.system(.caption, design: .monospaced).weight(.semibold))
                        .foregroundStyle(SequenceFilterTheme.textSecondary)
                    prizeRedLightBadge(summaries)
                } else {
                    Text("第7场3/0：等待自动获取并计算")
                        .font(.system(.caption, design: .monospaced).weight(.semibold))
