    private func prizeHistoryOutcomeLine(_ record: PrizeQueryRecord) -> String {
        guard let outcomes = record.outcomes, !outcomes.isEmpty else {
            return "彩果：旧记录未保存"
        }
        let prefix = prizeHistorySeventhRunSummaries(record) == nil ? "彩果：" : "彩果（前6场）："
        return prefix + outcomes.map(String.init).joined(separator: "、")
    }

    private func prizeHistoryRunSummary(_ record: PrizeQueryRecord) -> PrizeRunSummary? {
        if let outcomes = record.outcomes,
           let rebuilt = PrizeCalculator.outcomeSummary(for: outcomes) {
            return rebuilt
        }
        return record.runSummary
    }

    private func prizeHistorySeventhRunSummaries(_ record: PrizeQueryRecord) -> [SeventhOutcomeRunSummary]? {
        if let outcomes = record.outcomes, outcomes.count == 6,
           let calculated = PrizeCalculator.seventhOutcomeRunSummaries(firstSixOutcomes: outcomes) {
            return calculated
        }
        if let stored = record.seventhRunSummaries, stored.count == 2 { return stored }
        guard let estimates = record.seventhEstimates, estimates.count == 2 else { return nil }
        return estimates.map {
            SeventhOutcomeRunSummary(outcome: $0.outcome, runSummary: $0.runSummary)
        }
    }

    private func prizeHistorySeventhRunLine(_ summaries: [SeventhOutcomeRunSummary]) -> String {
        guard let outcome3 = summaries.first(where: { $0.outcome == 3 }),
              let outcome0 = summaries.first(where: { $0.outcome == 0 }) else {
            return "第7场3/0：连续统计不完整"
        }
        return "第7场3/0：连续不败 \(outcome3.runSummary.nonLoss)/\(outcome0.runSummary.nonLoss)　连续不胜 \(outcome3.runSummary.nonWin)/\(outcome0.runSummary.nonWin)　连续不平 \(outcome3.runSummary.nonDraw)/\(outcome0.runSummary.nonDraw)"
    }

    private func prizeHistorySameResultRunLine(_ summaries: [SeventhOutcomeRunSummary]) -> String {
        guard let outcome3 = summaries.first(where: { $0.outcome == 3 }),
              let outcome0 = summaries.first(where: { $0.outcome == 0 }) else {
            return "第7场3/0：连续胜平负统计不完整"
        }
        return "连续胜 \(outcome3.runSummary.win)/\(outcome0.runSummary.win)　连续平 \(outcome3.runSummary.draw)/\(outcome0.runSummary.draw)　连续负 \(outcome3.runSummary.loss)/\(outcome0.runSummary.loss)"
    }

    private func prizeHistoryOutcomeSumLine(_ summaries: [SeventhOutcomeRunSummary]) -> String {
        guard let outcome3 = summaries.first(where: { $0.outcome == 3 }),
              let outcome0 = summaries.first(where: { $0.outcome == 0 }) else {
