    }

    private func analyzePrizeConditionCommonality() {
        let sixMatchRecords = prizeQueryHistory.filter { $0.matchNumbers.count == 6 }
        let sevenMatchRecords = prizeQueryHistory.filter { $0.matchNumbers.count == 7 }
        let otherMatchRecords = prizeQueryHistory.count - sixMatchRecords.count - sevenMatchRecords.count
        let settledRecords = prizeQueryHistory.filter(\.isSettled).count
        let outcomeCompleteRecords = prizeQueryHistory.filter {
            ($0.outcomes?.count ?? 0) >= min(6, $0.matchNumbers.count)
        }.count
        let snapshotCompleteRecords = prizeQueryHistory.filter { $0.conditionSnapshots?.isEmpty == false }.count
        let sixMatchAmounts = sixMatchRecords.map(\.amount).filter(\.isFinite)
        let seventhEstimateAmounts = sevenMatchRecords.flatMap { $0.seventhEstimates ?? [] }
            .map(\.amount)
            .filter(\.isFinite)
        let runSamples: [PrizeRunSummary] = prizeQueryHistory.flatMap { record in
            if let summaries = prizeHistorySeventhRunSummaries(record), !summaries.isEmpty {
                return summaries.map(\.runSummary)
            }
            return prizeHistoryRunSummary(record).map { [$0] } ?? []
        }
        let advancedSamples = prizeQueryHistory.flatMap { $0.conditionSnapshots ?? [] }
        if !runSamples.isEmpty, let profile = makeComprehensiveAnalysisProfile(
            runSamples: runSamples,
            advancedSamples: advancedSamples
        ) {
            comprehensiveAnalysisProfile = profile
            result = nil
        }
        var lines = [
            "【全部记录概况】",
            "奖金查询：\(prizeQueryHistory.count)次；6场 \(sixMatchRecords.count)次；7场 \(sevenMatchRecords.count)次；其他 \(otherMatchRecords)次。",
            "已开奖：\(settledRecords)次；未开奖/估算：\(prizeQueryHistory.count - settledRecords)次。",
            "前6场彩果完整：\(outcomeCompleteRecords)次；缺失：\(prizeQueryHistory.count - outcomeCompleteRecords)次。",
            "全条件指标完整：\(snapshotCompleteRecords)次；缺失：\(prizeQueryHistory.count - snapshotCompleteRecords)次。",
            "6场奖金样本：\(sixMatchAmounts.count)组；合计 ¥\(decimal(sixMatchAmounts.reduce(0, +)))；平均 ¥\(decimal(sixMatchAmounts.isEmpty ? 0 : sixMatchAmounts.reduce(0, +) / Double(sixMatchAmounts.count)))。",
            "7场双结果估算：\(seventhEstimateAmounts.count)组；合计 ¥\(decimal(seventhEstimateAmounts.reduce(0, +)))；平均 ¥\(decimal(seventhEstimateAmounts.isEmpty ? 0 : seventhEstimateAmounts.reduce(0, +) / Double(seventhEstimateAmounts.count)))。",
            "已统计\(runSamples.count)组彩果结果、\(advancedSamples.count)组高级指标。"
        ]
        if prizeConditionAnalysisEnabled {
            let passResults = prizeQueryHistory.compactMap { record in
                record.conditionSnapshots?.first.flatMap(currentPrizeConditionPasses)
            }
            lines += [
                "按当前奖金条件：可判定 \(passResults.count)次；通过 \(passResults.filter { $0 }.count)次；未通过 \(passResults.filter { !$0 }.count)次。"
            ]
        } else {
            lines += ["当前奖金分析开关已关闭，不统计条件通过/未通过次数。"]
        }
        guard !runSamples.isEmpty else {
            lines += ["", "现有记录还没有完整彩果，暂时无法统计条件范围；补全旧数据后可再次统计。"]
            prizeCommonalityMessage = lines.joined(separator: "\n")
            return
        }
        lines += [
            "",
            "“80%集中范围”去掉两端少量极端值，适合用作持续调整条件的参考，不代表未来保证。",
            "",
            "【彩果条件共性】",
            commonIntLine("胜总数", runSamples.map(\.winCount)),
            commonIntLine("平总数", runSamples.map(\.drawCount)),
            commonIntLine("负总数", runSamples.map(\.lossCount)),
            commonIntLine("彩果种类", runSamples.map(\.diversity)),
            commonIntLine("彩果和值", runSamples.map(\.outcomeSum)),
            commonIntLine("隔场回返", runSamples.map(\.returns)),
            commonIntLine("胜负切换", runSamples.map(\.winLossSwitches)),
            commonIntLine("连续不败", runSamples.map(\.nonLoss)),
            commonIntLine("连续不平", runSamples.map(\.nonDraw)),
            commonIntLine("连续不胜", runSamples.map(\.nonWin)),
            commonIntLine("连续胜", runSamples.map(\.win)),
            commonIntLine("连续平", runSamples.map(\.draw)),
            commonIntLine("连续负", runSamples.map(\.loss))
        ]
        if !advancedSamples.isEmpty {
            lines += [
                "",
                "【前5场基础与SP/概率共性（\(advancedSamples.count)组）】",
                commonOptionalIntLine("乘积Q", advancedSamples.map(\.productQ)),
                commonOptionalIntLine("判定总和S", advancedSamples.map(\.sum)),
                commonOptionalIntLine("位移M", advancedSamples.map(\.displacement)),
                commonOptionalDoubleLine("稳定性σ²", advancedSamples.map(\.variance)),
                commonOptionalIntLine("值2次数", advancedSamples.map(\.valueTwoCount)),
                commonOptionalDoubleLine("P_tr%", advancedSamples.map(\.transitionPercent)),
                commonOptionalIntLine("二阶波动R", advancedSamples.map(\.roughness)),
                commonIntLine("彩果断点B", advancedSamples.map(\.breakpoints)),
                commonOptionalDoubleLine("SP和值", advancedSamples.map(\.spSum)),
                commonDoubleLine("SP乘积", advancedSamples.map(\.spProduct)),
                commonDoubleLine("预计奖金", advancedSamples.map(\.estimatedPrize)),
                commonDoubleLine("最大单场SP", advancedSamples.map(\.maximumSingleSP)),
                commonIntLine("SP>4场次数", advancedSamples.map(\.highSPCount)),
                commonOptionalDoubleLine("最低单场概率%", advancedSamples.map(\.minimumProbabilityPercent)),
                commonOptionalDoubleLine("整串全中概率%", advancedSamples.map(\.jointProbabilityPercent)),
                commonIntLine("前3场和值", advancedSamples.map(\.frontOutcomeSum)),
                commonIntLine("后2场和值", advancedSamples.map(\.backOutcomeSum)),
                commonDoubleLine("前3场SP乘积", advancedSamples.map(\.frontSPProduct)),
                commonDoubleLine("后2场SP乘积", advancedSamples.map(\.backSPProduct))
            ]
        } else {
            lines += ["", "旧记录尚未保存SP/概率明细；自动补全后再分析，可得到完整建议范围。"]
        }
        lines += [
            "",
            runSamples.count < 5
                ? "当前样本不足5组，建议先积累更多查询记录，再收紧条件。"
                : "更新条件时可先采用80%集中范围；至少积累20组后，再判断是否继续收紧。"
        ]
        if let profile = comprehensiveAnalysisProfile,
           let best = profile.recommendedRule {
            lines += [
                "",
                "【综合过滤条件】",
                "已生成\(profile.rules.count)项80%集中范围；可在“条件”页开启。",
                "最适合单项：\(best.metric.title) \(decimal(best.lowerBound))-\(decimal(best.upperBound))。",
                "默认容错0-4项，可按复盘结果手动调整。"
            ]
        }
        prizeCommonalityMessage = lines.joined(separator: "\n")
    }

    private func makeComprehensiveAnalysisProfile(
        runSamples: [PrizeRunSummary],
        advancedSamples: [PrizeConditionSnapshot]
    ) -> ComprehensiveAnalysisProfile? {
        var samples: [ComprehensiveAnalysisMetric: [Double]] = [:]
        func add(_ metric: ComprehensiveAnalysisMetric, _ values: [Double]) {
            let valid = values.filter(\.isFinite)
            if !valid.isEmpty { samples[metric] = valid }
        }
        add(.winCount, runSamples.map { Double($0.winCount) })
        add(.drawCount, runSamples.map { Double($0.drawCount) })
        add(.lossCount, runSamples.map { Double($0.lossCount) })
        add(.diversity, runSamples.map { Double($0.diversity) })
        add(.outcomeSum, runSamples.map { Double($0.outcomeSum) })
        add(.returns, runSamples.map { Double($0.returns) })
        add(.winLossSwitches, runSamples.map { Double($0.winLossSwitches) })
        add(.nonLoss, runSamples.map { Double($0.nonLoss) })
        add(.nonDraw, runSamples.map { Double($0.nonDraw) })
        add(.nonWin, runSamples.map { Double($0.nonWin) })
        add(.winRun, runSamples.map { Double($0.win) })
        add(.drawRun, runSamples.map { Double($0.draw) })
        add(.lossRun, runSamples.map { Double($0.loss) })
        add(.productQ, advancedSamples.compactMap(\.productQ).map(Double.init))
        add(.sum, advancedSamples.compactMap(\.sum).map(Double.init))
        add(.displacement, advancedSamples.compactMap(\.displacement).map(Double.init))
        add(.variance, advancedSamples.compactMap(\.variance))
        add(.valueTwoCount, advancedSamples.compactMap(\.valueTwoCount).map(Double.init))
        add(.valueFourCount, advancedSamples.compactMap { $0.valueFourPositions.map { Double($0.count) } })
        add(.transitionPercent, advancedSamples.compactMap(\.transitionPercent))
        add(.roughness, advancedSamples.compactMap(\.roughness).map(Double.init))
        add(.breakpoints, advancedSamples.map { Double($0.breakpoints) })
        add(.spSum, advancedSamples.compactMap(\.spSum))
        add(.spProduct, advancedSamples.map(\.spProduct))
        add(.estimatedPrize, advancedSamples.map(\.estimatedPrize))
        add(.maximumSingleSP, advancedSamples.map(\.maximumSingleSP))
        add(.highSPCount, advancedSamples.map { Double($0.highSPCount) })
        add(.minimumProbabilityPercent, advancedSamples.compactMap(\.minimumProbabilityPercent))
        add(.jointProbabilityPercent, advancedSamples.compactMap(\.jointProbabilityPercent))
        add(.frontOutcomeSum, advancedSamples.map { Double($0.frontOutcomeSum) })
        add(.backOutcomeSum, advancedSamples.map { Double($0.backOutcomeSum) })
        add(.frontSPProduct, advancedSamples.map(\.frontSPProduct))
        add(.backSPProduct, advancedSamples.map(\.backSPProduct))

        let rules = ComprehensiveAnalysisMetric.allCases.compactMap { metric -> ComprehensiveAnalysisRule? in
            guard let values = samples[metric], let range = centralRange(values) else { return nil }
            let centralCount = values.filter { range.central.contains($0) }.count
            let coverage = Double(centralCount) / Double(values.count)
            let fullWidth = range.full.upperBound - range.full.lowerBound
            let relativeWidth = fullWidth > 1e-12
                ? (range.central.upperBound - range.central.lowerBound) / fullWidth
                : 0
            let sampleConfidence = min(1, Double(values.count) / 20)
            let score = coverage * 0.55 + (1 - relativeWidth) * 0.30 + sampleConfidence * 0.15
            return ComprehensiveAnalysisRule(
                metric: metric,
                lowerBound: range.central.lowerBound,
                upperBound: range.central.upperBound,
                sampleCount: values.count,
                score: score
            )
        }
        guard let recommended = rules.max(by: { left, right in
            if abs(left.score - right.score) > 1e-12 { return left.score < right.score }
            if left.sampleCount != right.sampleCount { return left.sampleCount < right.sampleCount }
            return left.metric.rawValue > right.metric.rawValue
        }) else { return nil }
        return ComprehensiveAnalysisProfile(
            generatedAt: Date(),
            historyRecordCount: prizeQueryHistory.count,
            runSampleCount: runSamples.count,
            advancedSampleCount: advancedSamples.count,
            rules: rules,
            recommendedMetric: recommended.metric
        )
    }

    /// 以历史学习样本的完整最小/最大值作为边界。对独立区间条件而言，
    /// 这是不依赖期号、场次号或指定赛果的统一统计规则。
    private func makeProtectedHistoryMaxCompressionProfile(
        records: [PrizeQueryRecord]
    ) -> ComprehensiveAnalysisProfile? {
        guard !records.isEmpty else { return nil }
        var samples: [ComprehensiveAnalysisMetric: [Double]] = [:]
        func add(_ metric: ComprehensiveAnalysisMetric, _ value: Double) {
            guard value.isFinite else { return }
            samples[metric, default: []].append(value)
        }

        for record in records {
            guard let snapshot = record.conditionSnapshots?.first,
                  snapshot.outcomes.count >= 6,
                  let config = globalFilterConfig(for: record) else { return nil }
            let fullOutcomes = Array(snapshot.outcomes.prefix(6))
            let mainOutcomes = Array(fullOutcomes.prefix(config.matchNumbers.count))
            guard mainOutcomes.count == config.logic.count,
                  let summary = PrizeCalculator.outcomeSummary(for: fullOutcomes) else { return nil }
            let values = zip(config.logic, mainOutcomes).map { $0.value(for: $1) }
            let sum = values.reduce(0, +)
            let mean = Double(sum) / Double(values.count)
            let variance = values.reduce(0.0) { $0 + pow(Double($1) - mean, 2) } / Double(values.count)
            let split = min(3, mainOutcomes.count)

            add(.productQ, Double(values.reduce(1, *)))
            add(.sum, Double(sum))
            add(.displacement, Double(zip(values, values.dropFirst()).reduce(0) { $0 + abs($1.1 - $1.0) }))
            add(.variance, variance)
            add(.valueTwoCount, Double(values.filter { $0 == 2 }.count))
            add(.valueFourCount, Double(values.filter { $0 == 4 }.count))
            add(.transitionPercent, prizeTransitionPercent(values))
            add(.roughness, Double(prizeRoughness(values)))
            add(.breakpoints, Double(zip(mainOutcomes, mainOutcomes.dropFirst()).filter { $0 != $1 }.count))
            add(.frontOutcomeSum, Double(mainOutcomes.prefix(split).reduce(0, +)))
            add(.backOutcomeSum, Double(mainOutcomes.dropFirst(split).reduce(0, +)))
            add(.winCount, Double(summary.winCount))
            add(.drawCount, Double(summary.drawCount))
            add(.lossCount, Double(summary.lossCount))
            add(.diversity, Double(summary.diversity))
            add(.outcomeSum, Double(summary.outcomeSum))
            add(.returns, Double(summary.returns))
            add(.winLossSwitches, Double(summary.winLossSwitches))
            add(.nonLoss, Double(summary.nonLoss))
            add(.nonDraw, Double(summary.nonDraw))
            add(.nonWin, Double(summary.nonWin))
            add(.winRun, Double(summary.win))
            add(.drawRun, Double(summary.draw))
            add(.lossRun, Double(summary.loss))
        }

        let rules = ComprehensiveAnalysisMetric.allCases.compactMap { metric -> ComprehensiveAnalysisRule? in
            guard let values = samples[metric], values.count == records.count,
                  let lower = values.min(), let upper = values.max() else { return nil }
            return ComprehensiveAnalysisRule(
                metric: metric,
                lowerBound: lower,
                upperBound: upper,
                sampleCount: records.count,
                score: 1 / (1 + max(0, upper - lower))
            )
        }
        guard let recommended = rules.max(by: { $0.score < $1.score }) else { return nil }
        return ComprehensiveAnalysisProfile(
            generatedAt: Date(),
            historyRecordCount: records.count,
            runSampleCount: records.count,
            advancedSampleCount: records.count,
            rules: rules,
            recommendedMetric: recommended.metric
        )
    }

    private func protectedHistoryProfilePasses(
        _ record: PrizeQueryRecord,
        profile: ComprehensiveAnalysisProfile
    ) -> Bool {
        guard let snapshot = record.conditionSnapshots?.first,
              snapshot.outcomes.count >= 6,
              let config = globalFilterConfig(for: record) else { return false }
        let fullOutcomes = Array(snapshot.outcomes.prefix(6))
        let failureCount = SequenceFilterEngine.comprehensiveAnalysisFailureCount(
            fullOutcomes: fullOutcomes,
            config: config,
            profile: profile,
            outcomeProbabilities: nil,
            outcomeSPs: nil
        )
        let tolerance = SequenceFilterEngine.effectiveProtectedHistoryToleranceRange(
            base: effectiveProtectedHistoryToleranceRange,
            fullOutcomes: fullOutcomes,
            config: config
        )
        return tolerance.contains(failureCount)
    }

    private var queryBigCompressionToleranceStatistics: (
        auditable: Int,
        unavailable: Int,
        cumulativeCounts: [Int]
    )? {
        guard let profile = protectedHistoryMaxCompressionProfile else { return nil }
        let records = uniquePrizeQueryRecords
        let rawFailureCounts = records.compactMap { record -> Int? in
            guard let snapshot = record.conditionSnapshots?.first,
                  snapshot.outcomes.count >= 6,
                  let config = globalFilterConfig(for: record) else { return nil }
            return SequenceFilterEngine.comprehensiveAnalysisFailureCount(
                fullOutcomes: Array(snapshot.outcomes.prefix(6)),
                config: config,
                profile: profile,
                outcomeProbabilities: nil,
                outcomeSPs: nil
            )
        }
        return (
            auditable: rawFailureCounts.count,
            unavailable: max(0, records.count - rawFailureCounts.count),
            cumulativeCounts: (0...4).map { tolerance in
                rawFailureCounts.filter { $0 <= tolerance }.count
            }
        )
    }

    /// 返回大压缩具体拦截项，供查询页和全局答案直接解释“为什么未通过”。
    private func protectedHistoryFailureDetails(
        _ record: PrizeQueryRecord,
        profile: ComprehensiveAnalysisProfile
    ) -> [String] {
        guard let snapshot = record.conditionSnapshots?.first,
              snapshot.outcomes.count >= 6,
              let config = globalFilterConfig(for: record) else {
            return ["大压缩：缺少完整前6场彩果或ABCD，无法核对。"]
        }
        let fullOutcomes = Array(snapshot.outcomes.prefix(6))
        let failureCount = SequenceFilterEngine.comprehensiveAnalysisFailureCount(
            fullOutcomes: fullOutcomes,
            config: config,
            profile: profile,
            outcomeProbabilities: nil,
            outcomeSPs: nil
        )
        let tolerance = SequenceFilterEngine.effectiveProtectedHistoryToleranceRange(
            base: effectiveProtectedHistoryToleranceRange,
            fullOutcomes: fullOutcomes,
            config: config
        )
        if tolerance.contains(failureCount) { return [] }
        let summary = PrizeCalculator.outcomeSummary(for: fullOutcomes)
        let values: [ComprehensiveAnalysisMetric: Double?] = [
            .productQ: snapshot.productQ.map(Double.init),
            .sum: snapshot.sum.map(Double.init),
            .displacement: snapshot.displacement.map(Double.init),
            .variance: snapshot.variance,
            .valueTwoCount: snapshot.valueTwoCount.map(Double.init),
            .valueFourCount: snapshot.valueFourPositions.map { Double($0.count) },
            .transitionPercent: snapshot.transitionPercent,
            .roughness: snapshot.roughness.map(Double.init),
            .breakpoints: Double(snapshot.breakpoints),
            .frontOutcomeSum: Double(snapshot.frontOutcomeSum),
            .backOutcomeSum: Double(snapshot.backOutcomeSum),
            .winCount: summary.map { Double($0.winCount) },
            .drawCount: summary.map { Double($0.drawCount) },
            .lossCount: summary.map { Double($0.lossCount) },
            .diversity: summary.map { Double($0.diversity) },
            .outcomeSum: summary.map { Double($0.outcomeSum) },
            .returns: summary.map { Double($0.returns) },
            .winLossSwitches: summary.map { Double($0.winLossSwitches) },
            .nonLoss: summary.map { Double($0.nonLoss) },
            .nonDraw: summary.map { Double($0.nonDraw) },
            .nonWin: summary.map { Double($0.nonWin) },
            .winRun: summary.map { Double($0.win) },
            .drawRun: summary.map { Double($0.draw) },
            .lossRun: summary.map { Double($0.loss) },
            .spSum: snapshot.spSum,
            .spProduct: snapshot.spProduct,
            .estimatedPrize: snapshot.estimatedPrize,
            .maximumSingleSP: snapshot.maximumSingleSP,
            .highSPCount: Double(snapshot.highSPCount),
            .minimumProbabilityPercent: snapshot.minimumProbabilityPercent,
            .jointProbabilityPercent: snapshot.jointProbabilityPercent,
            .frontSPProduct: snapshot.frontSPProduct,
            .backSPProduct: snapshot.backSPProduct
        ]
        var failures = ["大压缩容错：实际\(failureCount)项不满足，允许\(tolerance.lowerBound)-\(tolerance.upperBound)项"]
        failures.append(contentsOf: profile.rules.compactMap { rule -> String? in
            let bounds = SequenceFilterEngine.comprehensiveAnalysisRuleBoundsLatest(rule)
            guard let value = values[rule.metric] ?? nil else {
                return "大压缩 · \(rule.metric.title)：数据不足（要求\(decimal(bounds.lower))-\(decimal(bounds.upper))）"
            }
            guard !SequenceFilterEngine.comprehensiveAnalysisRulePassesLatest(rule, value: value) else { return nil }
            return "大压缩 · \(rule.metric.title)：实际\(decimal(value))，要求\(decimal(bounds.lower))-\(decimal(bounds.upper))"
        })
        return failures
    }

    /// 只用于展示当前规则的历史核对数；不改写大压缩档案本身。
    private func protectedHistoryCurrentAudit(
        profile: ComprehensiveAnalysisProfile
    ) -> (total: Int, baselinePassed: Int, compressionPassed: Int) {
        let records = uniquePrizeQueryRecords
        let baseline = records.filter(baselineGlobalPrizeRecordPasses)
        let compressed = baseline.filter { protectedHistoryProfilePasses($0, profile: profile) }
        return (records.count, baseline.count, compressed.count)
    }

    private func upgradedComputerVerifiedProfile(
        _ profile: ComprehensiveAnalysisProfile
    ) -> ComprehensiveAnalysisProfile {
        return ComprehensiveAnalysisProfile(
            generatedAt: profile.generatedAt,
            historyRecordCount: profile.historyRecordCount,
            runSampleCount: profile.runSampleCount,
            advancedSampleCount: profile.advancedSampleCount,
            rules: profile.rules,
            recommendedMetric: profile.recommendedMetric,
            protectedExactSignatures: nil,
            protectedAllowedPairSignatures: nil,
            protectedOutcomePositionCounts: nil
        )
    }

    /// 真机只读取电脑端已校验的档案；不在此路径请求网络或重新枚举历史赛果。
    private func loadComputerVerifiedProtectedHistoryProfile() {
        guard let data = Data(base64Encoded: computerVerifiedProtectedHistoryProfileBase64),
              let decoded = try? JSONDecoder().decode(ComprehensiveAnalysisProfile.self, from: data),
              decoded.historyRecordCount >= minimumProtectedHistoryRecordCount else {
            protectedHistoryMaxCompressionEnabled = false
            protectedHistoryMaxCompressionMessage = "电脑端大压缩方案无效，未启用。"
            return
        }
        let profile = upgradedComputerVerifiedProfile(decoded)
        protectedHistoryMaxCompressionProfile = profile
        protectedHistoryMaxCompressionEnabled = true
        protectedHistoryMaxCompressionMessage = "已载入电脑离线复核的通用大压缩：\(profile.historyRecordCount)条学习样本，\(profile.rules.count)项数值范围，无期号/场次/赛果特例。"
        result = nil
    }

    @MainActor
    private func rebuildProtectedHistoryMaxCompressionProfile() async {
        guard !isBuildingProtectedHistoryProfile else { return }
        isBuildingProtectedHistoryProfile = true
        protectedHistoryMaxCompressionMessage = "正在从500获取缺失赛果，失败时改用澳客…"
        await backfillPrizeQueryHistory()
        refreshProtectedPrizeOutcomePrefixesCache()

        let allRecords = uniquePrizeQueryRecords
        let protectedRecords = allRecords.filter(baselineGlobalPrizeRecordPasses)
        guard !protectedRecords.isEmpty else {
            protectedHistoryMaxCompressionEnabled = false
            protectedHistoryMaxCompressionProfile = nil
            protectedHistoryMaxCompressionMessage = "未完成：当前没有完整且通过现有条件的结果。"
            NSLog("Protected max compression blocked: no baseline passing records")
            isBuildingProtectedHistoryProfile = false
            return
        }
        guard protectedRecords.count >= minimumProtectedHistoryRecordCount else {
            protectedHistoryMaxCompressionEnabled = false
            protectedHistoryMaxCompressionProfile = nil
            protectedHistoryMaxCompressionMessage = "未启用：当前仅有\(protectedRecords.count)条可保护结果，需至少\(minimumProtectedHistoryRecordCount)条。请先补全赛果或放宽前置条件。"
            NSLog("Protected max compression blocked: only %ld protected records, minimum is %ld", protectedRecords.count, minimumProtectedHistoryRecordCount)
            isBuildingProtectedHistoryProfile = false
            return
        }
        guard let profile = makeProtectedHistoryMaxCompressionProfile(records: protectedRecords),
              profile.rules.count >= 20 else {
            protectedHistoryMaxCompressionEnabled = false
            protectedHistoryMaxCompressionProfile = nil
            protectedHistoryMaxCompressionMessage = "未完成：历史记录的ABCD或赛果指标不完整，无法安全生成最大压缩条件。"
            NSLog("Protected max compression blocked: profile metrics incomplete")
            isBuildingProtectedHistoryProfile = false
            return
        }
        let failed = protectedRecords.filter { !protectedHistoryProfilePasses($0, profile: profile) }
        guard failed.isEmpty else {
            protectedHistoryMaxCompressionEnabled = false
            protectedHistoryMaxCompressionProfile = nil
            protectedHistoryMaxCompressionMessage = "安全校验失败：仍有\(failed.count)条保护结果未通过，条件未启用。"
            NSLog("Protected max compression blocked: %ld records failed profile", failed.count)
            isBuildingProtectedHistoryProfile = false
            return
        }

        protectedHistoryMaxCompressionProfile = profile
        protectedHistoryMaxCompressionEnabled = true
        result = nil
        var message = "已启用：现有条件通过\(protectedRecords.count)/\(allRecords.count)条；从这些样本提取\(profile.rules.count)项通用数值范围，不使用位置配对或指定记录保护。"
        if let config = currentPrizeConfig {
            let preview = SequenceFilterEngine.calculate(
                config,
                previousContext: nil,
                protectedHistoryProfile: profile,
                protectedHistoryToleranceRange: effectiveProtectedHistoryToleranceRange,
                protectedHistoryBetCap: effectiveProtectedHistoryBetCap,
                protectedPrizeOutcomePrefixes: protectedPrizeOutcomePrefixes
            )
            message += " 当前输入按条件预计由729注压至\(preview.finalBetCount)注。"
        }
        protectedHistoryMaxCompressionMessage = message
        NSLog(
            "Protected max compression enabled: %ld/%ld records, %ld rules",
            protectedRecords.count,
            allRecords.count,
            profile.rules.count
        )
        isBuildingProtectedHistoryProfile = false
    }

    private func commonIntLine(_ title: String, _ values: [Int]) -> String {
        guard let range = centralRange(values.map(Double.init)) else { return "\(title)：数据不足" }
        let counts = Dictionary(grouping: values, by: { $0 }).mapValues(\.count)
        let mode = counts.max { left, right in
            left.value == right.value ? left.key > right.key : left.value < right.value
        }
        return "\(title)：80% \(Int(range.central.lowerBound))-\(Int(range.central.upperBound))；全范围 \(Int(range.full.lowerBound))-\(Int(range.full.upperBound))；常见 \(mode?.key ?? 0)（\(mode?.value ?? 0)次）"
    }

    private func commonOptionalIntLine(_ title: String, _ values: [Int?]) -> String {
        commonIntLine(title, values.compactMap { $0 })
    }

    private func commonDoubleLine(_ title: String, _ values: [Double]) -> String {
        guard let range = centralRange(values) else { return "\(title)：数据不足" }
        return "\(title)：80% \(decimal(range.central.lowerBound))-\(decimal(range.central.upperBound))；全范围 \(decimal(range.full.lowerBound))-\(decimal(range.full.upperBound))"
    }

    private func commonOptionalDoubleLine(_ title: String, _ values: [Double?]) -> String {
        commonDoubleLine(title, values.compactMap { $0 })
    }

    private func centralRange(_ values: [Double]) -> (central: ClosedRange<Double>, full: ClosedRange<Double>)? {
        let ordered = values.filter(\.isFinite).sorted()
        guard let first = ordered.first, let last = ordered.last else { return nil }
        let lowerIndex = min(ordered.count - 1, Int(floor(Double(ordered.count - 1) * 0.1)))
        let upperIndex = min(ordered.count - 1, Int(ceil(Double(ordered.count - 1) * 0.9)))
        return (ordered[lowerIndex]...ordered[upperIndex], first...last)
    }

