    @ViewBuilder
    private func conditionField(
        _ title: String, _ placeholder: String, text: Binding<String>,
        keyboard: UIKeyboardType = .numbersAndPunctuation
    ) -> some View {
        if let rule = basicCondition(for: title) {
            VStack(alignment: .leading, spacing: 8) {
                Toggle("启用" + title, isOn: basicConditionBinding(rule))
                rawConditionField(title, placeholder, text: text, keyboard: keyboard)
                    .disabled(disabledBasicConditions.contains(rule))
            }
        } else {
            rawConditionField(title, placeholder, text: text, keyboard: keyboard)
        }
    }

    @ViewBuilder
    private func rawConditionField(
        _ title: String,
        _ placeholder: String,
        text: Binding<String>,
        keyboard: UIKeyboardType = .numbersAndPunctuation
    ) -> some View {
        if placeholder.split(separator: "-").count == 2,
           placeholder.split(separator: "-").allSatisfy({ Double($0) != nil }) {
            ConditionRangePickers(title: title, fallback: placeholder, text: text)
                .onChange(of: text.wrappedValue) { _ in
                    result = nil
                    currentTXTQueryMessage = nil
                    currentTXTQueryIsHit = nil
                }
        } else {
            LabeledContent(title) {
                TextField(placeholder, text: text)
                    .multilineTextAlignment(.trailing)
                    .font(.system(.body, design: .monospaced))
                    .keyboardType(keyboard)
            }
        }
    }

    @ViewBuilder
    private func steppedIntegerRangePickers(
        lowerTitle: String,
        upperTitle: String,
        lower: Binding<Int>,
        upper: Binding<Int>,
        options: [Int]
    ) -> some View {
        Picker(lowerTitle, selection: lower) {
            ForEach(Array(Set(options + [lower.wrappedValue, upper.wrappedValue])).sorted(), id: \.self) { value in
                Text(String(value)).tag(value)
            }
        }
        .pickerStyle(.menu)
        .onChange(of: lower.wrappedValue) { value in
            if value > upper.wrappedValue { upper.wrappedValue = value }
            result = nil
        }
        Picker(upperTitle, selection: upper) {
            ForEach(Array(Set(options + [lower.wrappedValue, upper.wrappedValue])).sorted(), id: \.self) { value in
                Text(String(value)).tag(value)
            }
        }
        .pickerStyle(.menu)
        .onChange(of: upper.wrappedValue) { value in
            if value < lower.wrappedValue { lower.wrappedValue = value }
            result = nil
        }
    }

    private func defaultOutcomeConditionRange(_ condition: OutcomeCondition) -> String {
        let minimum = condition == .diversity ? 1 : 0
        return "\(minimum)-\(condition.maximum(matchCount: 5))"
    }

