    private var currentPrizeConfig: FilterConfig? { try? FilterConfig.parse(generatedInput) }

    private func currentConditionCellAssessment(
        for record: PrizeQueryRecord,
        excludesHistoricalPairing: Bool = true
    ) -> (
        statusText: String,
        statusColor: Color,
        passedDetails: [String],
        failedDetails: [String]
    ) {
        guard let snapshot = record.conditionSnapshots?.first else {
            let reason = "缺少条件快照：需要完整前6场赛果与指标数据"
            return ("当前条件：无法判定｜原因：\(reason)", .orange, [], [reason])
        }
        guard let config = globalFilterConfig(
            for: record,
            excludesHistoricalPairing: excludesHistoricalPairing
        ) else {
            let reason = "缺少该期ABCD，或条件Tab配置格式无效"
            return ("当前条件：无法判定｜原因：\(reason)", .orange, [], [reason])
        }

        let evaluations = globalConditionEvaluations(
            snapshot,
            config: config,
            usesPrizeOverrides: false,
            mergeMainFilterConditions: true
        )
        guard !evaluations.isEmpty else {
            let reason = "当前记录数据不足，无法生成条件明细"
            return ("当前条件：无法判定｜原因：\(reason)", .orange, [], [reason])
        }
        var details = evaluations.flatMap { name, passes -> [(Bool, String)] in
            if name == "8个主过滤条件（合并）" {
                let mainDetails = mainFilterConditionDetails(
                    snapshot,
                    config: config,
                    usesPrizeOverrides: false
                )
                if passes {
                    return [(true, "8个主过滤条件（合并）=全部通过")]
                }
                // 合并条件未通过时，只列出真正失败的子条件，
                // 避免“条件未通过”下面却显示带✓的通过项。
                return mainDetails.filter { !$0.passes }.map {
                    (false, "8个主过滤条件 · \($0.name)：\($0.value)")
                }
            }
            return [(
                passes,
                "\(name)=\(currentConditionValueDescription(name, snapshot: snapshot, config: config))"
            )]
        }
        let baseFailureCount = evaluations.filter { !$0.1 }.count
        let basePasses = config.allConditionsToleranceEnabled
            ? config.allConditionsToleranceRange.contains(baseFailureCount)
            : baseFailureCount == 0
        let comprehensivePasses = comprehensiveAnalysisPasses(snapshot, config: config)
        if comprehensiveAnalysisFilterEnabled {
            let failureCount = comprehensiveAnalysisFailureCount(snapshot, config: config)
            let toleranceText = parsedComprehensiveAnalysisToleranceRange.map {
                "\($0.lowerBound)-\($0.upperBound)"
            } ?? "无效"
            details.append((
                comprehensivePasses,
                "历史综合分析=\(failureCount.map(String.init) ?? "数据不足")项不满足（容错\(toleranceText)）"
            ))
        }
        var compressionPasses = true
        if protectedHistoryMaxCompressionEnabled,
           let profile = protectedHistoryMaxCompressionProfile {
            let compressionFailures = protectedHistoryFailureDetails(record, profile: profile)
            compressionPasses = compressionFailures.isEmpty
            if compressionFailures.isEmpty {
                let compressionTolerance = SequenceFilterEngine.effectiveProtectedHistoryToleranceRange(
                    base: effectiveProtectedHistoryToleranceRange,
                    fullOutcomes: Array(snapshot.outcomes.prefix(6)),
                    config: config
                )
                details.append((
                    true,
                    "大压缩=通过（\(profile.rules.count)项通用统计区间，容错\(compressionTolerance.lowerBound)-\(compressionTolerance.upperBound)项；无期号/场次/赛果特例）"
                ))
            } else {
                details.append(contentsOf: compressionFailures.map { (false, $0) })
            }
        }
        var universal150Passes = true
        if config.universal150CompressionEnabled {
            let outcomes = Array(snapshot.outcomes.prefix(6))
            let score = SequenceFilterEngine.universal150CompressionScore(
                fullOutcomes: outcomes,
                config: config
            )
            universal150Passes = score.map {
                $0 + 1e-12 >= SequenceFilterEngine.universal150CompressionThreshold
            } ?? false
            let scoreText = score.map { String(format: "%.4f", $0) } ?? "数据不足"
            let thresholdText = String(
                format: "%.4f",
                SequenceFilterEngine.universal150CompressionThreshold
            )
            details.append((
                universal150Passes,
                "通用150注统计压缩=得分\(scoreText)（要求≥\(thresholdText)；六场位置概率＋前五场判定值转移）"
            ))
        }
        var universal247Passes = true
        if config.universal247ToleranceEnabled {
            let isVIP4 = SequenceFilterEngine.usesVIP4Model(
                threshold: config.universal247ToleranceThreshold
            )
            let isVIP3 = SequenceFilterEngine.usesVIP3Model(
                threshold: config.universal247ToleranceThreshold
            )
            let isVIP2 = SequenceFilterEngine.usesVIP2Model(
                threshold: config.universal247ToleranceThreshold
            )
            let score = SequenceFilterEngine.universal247ActiveScore(
                fullOutcomes: Array(snapshot.outcomes.prefix(6)),
                threshold: config.universal247ToleranceThreshold,
                logic: config.logic
            )
            let firstSix = Array(snapshot.outcomes.prefix(6))
            universal247Passes = isVIP4 || isVIP3 || isVIP2 || SequenceFilterEngine.passesUniversal247Tolerance(
                    fullOutcomes: firstSix,
                    threshold: config.universal247ToleranceThreshold,
                    logic: config.logic,
                    productSumV10Top150Enabled: config.productSumV10Top150Enabled
                )
            if isVIP4 {
                details.append((
                    true,
                    "VIP4贝叶斯150=需六场完整普通欧赔＋实际让球；有已结束前一组时加入转移修正，单条结果以最终TXT覆盖为准"
                ))
            } else if isVIP3 {
                details.append((
                    true,
                    "VIP3六场赔率150=需六场完整普通欧赔＋实际让球，单条结果以电脑终局TXT精确覆盖为准"
                ))
            } else if isVIP2 {
                details.append((
                    true,
                    "VIP2联合150=需当期完整让球对照表赔率，单条结果以电脑终局TXT精确覆盖为准"
                ))
            } else if SequenceFilterEngine.usesProductSumV10Model(
                threshold: config.universal247ToleranceThreshold
            ) {
                details.append((
                    universal247Passes,
                    "V10=\(universal247Passes ? "通过" : "未通过")\(config.productSumV10Top150Enabled ? "V8前150＋" : "")ABCD结构Q50–299＋S12–16"
                ))
            } else if SequenceFilterEngine.usesJoint150V8Model(
                threshold: config.universal247ToleranceThreshold
            ) {
                details.append((
                    universal247Passes,
                    "V8联合150=\(universal247Passes ? "进入" : "未进入")统一前150注（概率55%＋ABCD45%＋V7加分）"
                ))
            } else if SequenceFilterEngine.usesUniversal405WholeIssueModel(
                threshold: config.universal247ToleranceThreshold
            ) {
                let scoreText = score.map { String(format: "%.6f", $0) } ?? "数据不足"
                details.append((
                    universal247Passes,
                    "V5整期留出通用压缩=得分\(scoreText)（统一前405种；留出143/203）"
                ))
            } else if SequenceFilterEngine.usesUniversal247GeneralV4Model(
                threshold: config.universal247ToleranceThreshold
            ) {
                let scoreText = score.map { String(format: "%.6f", $0) } ?? "数据不足"
                details.append((
                    universal247Passes,
                    "通用247综合容错=V4得分\(scoreText)（要求≥0.323295；8项通用结构＋1%位置统计）"
                ))
            } else {
                let scoreText = score.map { String(format: "%.6f", $0) } ?? "数据不足"
                details.append((
                    universal247Passes,
                    "通用247综合容错=得分\(scoreText)（要求≥\(String(format: "%.6f", config.universal247ToleranceThreshold))；前6场7项结构指标）"
                ))
            }
        }
        var endToEndTXTPasses = true
        if let outcomes = record.outcomes, outcomes.count >= 6 {
            if let counts = globalFilterCounts(for: record) {
                if counts.targetCoveredByFinalTXT == true {
                    details.append((true, "电脑终局生成=该赛果保留在最终\(counts.after)注中"))
                } else {
                    endToEndTXTPasses = false
                    details.append((
                        false,
                        counts.targetCoverageDetail
                            ?? "电脑终局生成=未覆盖实际赛果，需按当前条件重算"
                    ))
                }
            } else {
                endToEndTXTPasses = false
                details.append((false, "电脑终局生成=待按当前条件重算，旧缓存不计通过"))
            }
            let txtCoverage = txtCoverageAssessment(for: record)
            endToEndTXTPasses = endToEndTXTPasses && txtCoverage.passes
            details.append((txtCoverage.passes, txtCoverage.detail))
        }
        let passedDetails = details.filter(\.0).map(\.1)
        let failedDetails = details.filter { !$0.0 }.map(\.1)
        if basePasses && comprehensivePasses && compressionPasses && universal247Passes && universal150Passes
            && endToEndTXTPasses && baseFailureCount == 0 {
            return ("当前条件：全部过关（\(passedDetails.count)项）", .green, passedDetails, [])
        }

        if basePasses && comprehensivePasses && compressionPasses && universal247Passes && universal150Passes
            && endToEndTXTPasses {
            return (
                "当前条件：容错过关（\(baseFailureCount)项未满足）",
                .orange,
                passedDetails,
                failedDetails
            )
        }
        return (
            "当前条件：未过关（\(failedDetails.count)项未满足）",
            .red,
            passedDetails,
            failedDetails
        )
    }

    private func currentConditionValueDescription(
        _ name: String,
        snapshot: PrizeConditionSnapshot,
        config: FilterConfig
    ) -> String {
        let outcomes = Array(snapshot.outcomes.prefix(config.matchNumbers.count))
        let rangeText: (ClosedRange<Int>) -> String = { "\($0.lowerBound)-\($0.upperBound)" }
        let doubleRangeText: (ClosedRange<Double>) -> String = {
            "\(decimal($0.lowerBound))-\(decimal($0.upperBound))"
        }
        switch name {
        case "8个主过滤条件（合并）":
            return mainFilterConditionDetails(
                snapshot,
                config: config,
                usesPrizeOverrides: false
            ).map { detail in
                "\(detail.name)=\(detail.value)\(detail.passes ? "✓" : "×")"
            }.joined(separator: "\n")
        case "S":
            return "\(snapshot.sum.map(String.init) ?? "数据不足")（要求\(rangeText(config.sumRange))）"
        case "M":
            if config.minimumDistinctDisplacementOrders > 0 {
                let mapped = zip(config.logic, snapshot.outcomes).map { mapping, outcome in mapping.value(for: outcome) }
                return "不同排列中有效\(config.validDistinctDisplacementOrderCount(in: mapped))种（要求≥\(config.minimumDistinctDisplacementOrders)种且M在\(rangeText(config.displacementRange))）"
            }
            return "\(snapshot.displacement.map(String.init) ?? "数据不足")（要求\(rangeText(config.displacementRange))）"
        case "σ²":
            return "\(snapshot.variance.map { decimal($0) } ?? "数据不足")（要求≤\(decimal(config.varianceMaximum))）"
        case "判定值2":
            return "\(snapshot.valueTwoCount.map(String.init) ?? "数据不足")（要求≤\(config.valueTwoMaximum)）"
        case "P_tr":
            return "\(snapshot.transitionPercent.map { decimal($0) } ?? "数据不足")%（要求≥\(decimal(config.transitionMinimumPercent))%）"
        case "R":
            return "\(snapshot.roughness.map(String.init) ?? "数据不足")（要求≤\(config.roughnessMaximum)）"
        case "B":
            return "\(snapshot.breakpoints)（要求\(rangeText(config.breakpointRange))）"
        case "指定位置无4":
            let positions = snapshot.valueFourPositions ?? []
            let actual = positions.isEmpty ? "无4" : "4在第\(positions.map(String.init).joined(separator: ","))位"
            return "\(actual)（禁用位置\(config.noFourPositions.map(String.init).joined(separator: ","))）"
        case "前三场判定值4最多1个":
            let count = snapshot.valueFourPositions?.filter { $0 <= 3 }.count ?? 0
            return "前三场共\(count)个4（要求≤1个）"
        case "六串胜负直接切换0–2":
            let value = OutcomeCondition.winLossSwitches.value(in: Array(snapshot.outcomes.prefix(6)))
            return "\(value)次（要求0-2次）"
        case "彩果条件组（内部容错）":
            let values = config.enabledOutcomeConditions.map {
                "\($0.title)\($0.value(in: outcomes))"
            }.joined(separator: "/")
            return "\(values)（不满足\(config.outcomeConditionFailureCount(in: outcomes))项）"
        case "SP和值":
            let required = parsedPrizeSPSumRange.map(doubleRangeText) ?? "无效"
            return "\(snapshot.spSum.map { decimal($0) } ?? "数据不足")（要求\(required)）"
        case "SP乘积":
            let required = parsedPrizeSPProductRange.map(doubleRangeText) ?? doubleRangeText(config.spProductRange)
            return "\(decimal(snapshot.spProduct))（要求\(required)）"
        case "自定义让球赔率乘积":
            return "\(decimal(snapshot.spProduct))（要求\(config.customHandicapOddsProductRange.lowerBound)-\(config.customHandicapOddsProductRange.upperBound)）"
        case "自定义让球赔率和值":
            return "\(snapshot.spSum.map { decimal($0) } ?? "数据不足")（要求\(config.customHandicapOddsSumRange.lowerBound)-\(config.customHandicapOddsSumRange.upperBound)）"
        case "预计奖金":
            return "¥\(decimal(snapshot.estimatedPrize))（要求¥\(doubleRangeText(config.estimatedPrizeRange))）"
        case "SP风险":
            return "最高\(decimal(snapshot.maximumSingleSP))/高SP \(snapshot.highSPCount)场（要求最高≤\(decimal(config.maximumSingleSP))、场数\(rangeText(config.highSPCountRange))）"
        case "最低概率":
            return "\(snapshot.minimumProbabilityPercent.map { decimal($0) } ?? "数据不足")%（要求≥\(decimal(config.minimumSingleProbabilityPercent))%）"
        case "全中概率":
            return "\(snapshot.jointProbabilityPercent.map { decimal($0) } ?? "数据不足")%（要求\(doubleRangeText(config.jointProbabilityPercentRange))%）"
        case "分组":
            var values: [String] = []
            if config.groupFilterMode.usesOutcomeSum {
                values.append("和值\(snapshot.frontOutcomeSum)/\(snapshot.backOutcomeSum)")
            }
            if config.groupFilterMode.usesSPProduct {
                values.append("SP\(decimal(snapshot.frontSPProduct))/\(decimal(snapshot.backSPProduct))")
            }
            return values.joined(separator: "、")
        case "连续彩果组（内部容错）":
            let runs = "不败\(ConsecutiveRunCondition.nonLoss.longestRun(in: snapshot.outcomes))/不平\(ConsecutiveRunCondition.nonDraw.longestRun(in: snapshot.outcomes))/不胜\(ConsecutiveRunCondition.nonWin.longestRun(in: snapshot.outcomes))"
            let primary = "第一档不满足\(config.consecutiveRunFailureCount(in: snapshot.outcomes))项，要求\(rangeText(config.consecutiveRunToleranceRange))"
            guard config.secondaryConsecutiveRunsEnabled else { return "\(runs)（\(primary)）" }
            let secondaryFailures = [
                ConsecutiveRunCondition.nonLoss,
                ConsecutiveRunCondition.nonDraw,
                ConsecutiveRunCondition.nonWin
            ].filter {
                !config.secondaryConsecutiveRunRange.contains($0.longestRun(in: snapshot.outcomes))
            }.count
            return "\(runs)（\(primary)；第二档\(rangeText(config.secondaryConsecutiveRunRange))不满足\(secondaryFailures)项，要求\(rangeText(config.secondaryConsecutiveRunToleranceRange))）"
        case "连续胜平负组（内部容错）":
            return "胜\(ConsecutiveRunCondition.win.longestRun(in: snapshot.outcomes))/平\(ConsecutiveRunCondition.draw.longestRun(in: snapshot.outcomes))/负\(ConsecutiveRunCondition.loss.longestRun(in: snapshot.outcomes))（不满足\(config.sameResultRunFailureCount(in: snapshot.outcomes))项）"
        default:
            if let condition = config.enabledOutcomeConditions.first(where: { $0.title == name }),
               let range = config.outcomeConditions[condition] {
                return "\(condition.value(in: outcomes))（要求\(rangeText(range))）"
            }
            return "已判定"
        }
    }

    private func conditionValue(_ value: Int?, range: ClosedRange<Int>?) -> String {
        guard let value else { return "数据不足" }
        guard let range else { return String(value) }
        return "\(value)（\(range.lowerBound)-\(range.upperBound) \(range.contains(value) ? "✓" : "×")）"
    }

    private func conditionMaximum<T: BinaryFloatingPoint>(_ value: T?, maximum: T?) -> String {
        guard let value else { return "数据不足" }
        guard let maximum else { return decimal(Double(value)) }
        return "\(decimal(Double(value)))（≤\(decimal(Double(maximum))) \(value <= maximum ? "✓" : "×")）"
    }

    private func conditionMaximum<T: BinaryInteger>(_ value: T?, maximum: T?) -> String {
        guard let value else { return "数据不足" }
        guard let maximum else { return String(Int(value)) }
        return "\(value)（≤\(maximum) \(value <= maximum ? "✓" : "×")）"
    }

    private func conditionMinimum(_ value: Double?, minimum: Double?, suffix: String = "") -> String {
        guard let value else { return "数据不足" }
        guard let minimum else { return decimal(value) + suffix }
        return "\(decimal(value))\(suffix)（≥\(decimal(minimum))\(suffix) \(value + 1e-12 >= minimum ? "✓" : "×")）"
    }

    private func currentPrizeConditionStatus(_ snapshot: PrizeConditionSnapshot) -> String {
        guard prizeConditionAnalysisEnabled else { return "奖金条件分析已关闭。" }
        guard let config = currentPrizeConfig else { return "当前条件格式无效，暂不能比较是否满足。" }
        guard parsedPrizeRoughnessRange != nil else { return "奖金R范围无效，请输入如1-7。" }
        if prizeSPRangeFilterEnabled,
           parsedPrizeSPSumRange == nil || parsedPrizeSPProductRange == nil {
            return "奖金SP和值或乘积范围无效，请输入如8-30、30-900。"
        }
        let active = globalConditionEvaluations(snapshot, config: config, usesPrizeOverrides: true)
        let failures = active.filter { !$0.1 }
        let tolerance = parsedPrizeConditionToleranceRange
        let passes = tolerance?.contains(failures.count) == true
        let details = active.map { "\($0.0)\($0.1 ? "✓" : "×")" }.joined(separator: "、")
        guard let tolerance else {
            return "奖金分析容错范围无效，请输入如0-2。"
        }
        return "奖金独立分析：\(failures.count)项不满足，容错\(tolerance.lowerBound)-\(tolerance.upperBound)项，\(passes ? "通过" : "不通过")。\(details)。"
    }

    private func currentPrizeConditionPasses(_ snapshot: PrizeConditionSnapshot) -> Bool? {
        guard prizeConditionAnalysisEnabled,
              let config = currentPrizeConfig,
              parsedPrizeRoughnessRange != nil,
              let tolerance = parsedPrizeConditionToleranceRange else { return nil }
        if prizeSPRangeFilterEnabled,
           parsedPrizeSPSumRange == nil || parsedPrizeSPProductRange == nil {
            return nil
        }
        let failures = globalConditionEvaluations(
            snapshot,
            config: config,
            usesPrizeOverrides: true
        ).filter { !$0.1 }.count
        return tolerance.contains(failures)
    }

    private func globalConditionEvaluations(
        _ snapshot: PrizeConditionSnapshot,
        config: FilterConfig,
        usesPrizeOverrides: Bool = false,
        mergeMainFilterConditions: Bool = false
    ) -> [(String, Bool)] {
        var active: [(String, Bool)] = []
        if mergeMainFilterConditions {
            let mainDetails = mainFilterConditionDetails(
                snapshot,
                config: config,
                usesPrizeOverrides: usesPrizeOverrides
            )
            active.append(("8个主过滤条件（合并）", mainDetails.allSatisfy(\.passes)))
        } else {
            if let value = snapshot.sum { active.append(("S", config.sumRange.contains(value))) }
            if let value = snapshot.displacement {
                let mapped = zip(config.logic, snapshot.outcomes).map { mapping, outcome in mapping.value(for: outcome) }
                active.append(("M", config.minimumDistinctDisplacementOrders > 0
                    ? config.passesDisplacement(in: mapped)
                    : config.displacementRange.contains(value)))
            }
            if let value = snapshot.variance { active.append(("σ²", value <= config.varianceMaximum + 1e-12)) }
            if let value = snapshot.valueTwoCount { active.append(("判定值2", value <= config.valueTwoMaximum)) }
            if let value = snapshot.transitionPercent { active.append(("P_tr", value + 1e-12 >= config.transitionMinimumPercent)) }
            if let value = snapshot.roughness {
                if usesPrizeOverrides {
                    active.append(("R", parsedPrizeRoughnessRange?.contains(value) == true))
                } else {
                    active.append(("R", value <= config.roughnessMaximum))
                }
            }
            active.append(("B", config.breakpointRange.contains(snapshot.breakpoints)))
        }
        if !config.noFourPositions.isEmpty {
            active.append((
                "指定位置无4",
                snapshot.valueFourPositions.map {
                    Set($0).isDisjoint(with: Set(config.noFourPositions))
                } ?? false
            ))
        }
        if let maximum = config.frontThreeMaximumFourCount {
            active.append((
                "前三场判定值4最多\(maximum)个",
                snapshot.valueFourPositions.map { positions in
                    positions.filter { $0 <= 3 }.count <= maximum
                } ?? false
            ))
        }
        let mainOutcomes = Array(snapshot.outcomes.prefix(config.matchNumbers.count))
        if config.prizeStatisticalConditionEnabled {
            active.append(("六串胜负直接切换0–2", OutcomeCondition.winLossSwitches.value(in: Array(snapshot.outcomes.prefix(6))) <= 2))
        }
        if config.outcomeConditionToleranceEnabled,
           !config.enabledOutcomeConditions.isEmpty {
            active.append(("彩果条件组（内部容错）", config.passesOutcomeConditions(mainOutcomes)))
        } else {
            for condition in config.enabledOutcomeConditions {
                if let range = config.outcomeConditions[condition] {
                    active.append((condition.title, range.contains(condition.value(in: mainOutcomes))))
                }
            }
        }
        if usesPrizeOverrides, prizeSPRangeFilterEnabled {
            let hasSP = (snapshot.spCount ?? 0) >= 5
            active.append(("SP和值", hasSP && snapshot.spSum.map { parsedPrizeSPSumRange?.contains($0) == true } == true))
            active.append(("SP乘积", hasSP && parsedPrizeSPProductRange?.contains(snapshot.spProduct) == true))
        } else if !usesPrizeOverrides, config.spProductFilterEnabled {
            active.append(("SP乘积", (snapshot.spCount ?? 0) >= 5 && config.spProductRange.contains(snapshot.spProduct)))
        }
        if config.customHandicapOddsProductFilterEnabled {
            active.append((
                "自定义让球赔率乘积",
                (snapshot.spCount ?? 0) >= 5
                    && Double(config.customHandicapOddsProductRange.lowerBound) <= snapshot.spProduct
                    && snapshot.spProduct <= Double(config.customHandicapOddsProductRange.upperBound)
            ))
        }
        if config.customHandicapOddsSumFilterEnabled {
            active.append((
                "自定义让球赔率和值",
                (snapshot.spCount ?? 0) >= 5
                    && snapshot.spSum.map {
                        Double(config.customHandicapOddsSumRange.lowerBound) <= $0
                            && $0 <= Double(config.customHandicapOddsSumRange.upperBound)
                    } == true
            ))
        }
        if config.prizeRangeFilterEnabled {
            active.append(("预计奖金", (snapshot.spCount ?? 0) >= 5 && config.estimatedPrizeRange.contains(snapshot.estimatedPrize)))
        }
        if config.spRiskFilterEnabled {
            active.append(("SP风险", (snapshot.spCount ?? 0) >= 5
                && snapshot.maximumSingleSP <= config.maximumSingleSP
                && config.highSPCountRange.contains(snapshot.highSPCount)))
        }
        if config.minimumProbabilityFilterEnabled {
            active.append((
                "最低概率",
                snapshot.minimumProbabilityPercent.map {
                    $0 + 1e-12 >= config.minimumSingleProbabilityPercent
                } ?? false
            ))
        }
        if config.jointProbabilityFilterEnabled {
            active.append((
                "全中概率",
                snapshot.jointProbabilityPercent.map(config.jointProbabilityPercentRange.contains) ?? false
            ))
        }
        if config.groupFilterEnabled {
            var passes = true
            if config.groupFilterMode.usesOutcomeSum {
                passes = passes && config.frontGroupOutcomeSumRange.contains(snapshot.frontOutcomeSum)
                    && config.backGroupOutcomeSumRange.contains(snapshot.backOutcomeSum)
            }
            if config.groupFilterMode.usesSPProduct {
                passes = passes && (snapshot.spCount ?? 0) >= 5
                    && config.frontGroupSPProductRange.contains(snapshot.frontSPProduct)
                    && config.backGroupSPProductRange.contains(snapshot.backSPProduct)
            }
            active.append(("分组", passes))
        }
        if config.consecutiveRunsEnabled {
            active.append(("连续彩果组（内部容错）", config.passesConsecutiveRuns(snapshot.outcomes)))
        }
        if config.sameResultRunsEnabled {
            active.append(("连续胜平负组（内部容错）", config.passesSameResultRuns(snapshot.outcomes)))
        }
        return active
    }

    private func mainFilterConditionDetails(
        _ snapshot: PrizeConditionSnapshot,
        config: FilterConfig,
        usesPrizeOverrides: Bool
    ) -> [(name: String, passes: Bool, value: String)] {
        let integerRange: (ClosedRange<Int>) -> String = { "\($0.lowerBound)-\($0.upperBound)" }
        let mappedValues = zip(config.logic, snapshot.outcomes).map { mapping, outcome in
            mapping.value(for: outcome)
        }
        let distinctMOrders = config.minimumDistinctDisplacementOrders > 0
            ? config.validDistinctDisplacementOrderCount(in: mappedValues) : nil
        let q = SequenceFilterEngine.productQFilterAssessment(
            for: snapshot.outcomes,
            config: config
        )
        let qValue: String
        if let product = q.product, let rank = q.mainOutcomeRank {
            let removal = q.removedExpandedBetCount == 0
                ? "未落入删除区"
                : "该主彩果展开\(q.expansionFactor)注中删\(q.removedExpandedBetCount)注"
            qValue = "Q\(product)、排名\(rank)/\(q.mainOutcomeCount)、\(removal)（全局删\(config.productRemovalCount)注）"
        } else {
            qValue = "数据不足（全局删\(config.productRemovalCount)注）"
        }
        let roughnessPasses: Bool
        let roughnessRequirement: String
        if usesPrizeOverrides {
            roughnessPasses = snapshot.roughness.map { parsedPrizeRoughnessRange?.contains($0) == true } == true
            roughnessRequirement = parsedPrizeRoughnessRange.map(integerRange) ?? "配置无效"
        } else {
            roughnessPasses = snapshot.roughness.map { $0 <= config.roughnessMaximum } == true
            roughnessRequirement = "≤\(config.roughnessMaximum)"
        }
        return [
            ("乘积Q最低删除", q.passes == true, qValue),
            ("S", snapshot.sum.map(config.sumRange.contains) == true,
             "\(snapshot.sum.map(String.init) ?? "数据不足")/要求\(integerRange(config.sumRange))"),
            ("M", config.passesDisplacement(in: mappedValues),
             distinctMOrders.map { "有效不同排列\($0)种/要求≥\(config.minimumDistinctDisplacementOrders)种、M=\(integerRange(config.displacementRange))" }
                ?? "\(snapshot.displacement.map(String.init) ?? "数据不足")/要求\(integerRange(config.displacementRange))"),
            ("σ²", snapshot.variance.map { $0 <= config.varianceMaximum + 1e-12 } == true,
             "\(snapshot.variance.map { decimal($0) } ?? "数据不足")/要求≤\(decimal(config.varianceMaximum))"),
            ("判定值2", snapshot.valueTwoCount.map { $0 <= config.valueTwoMaximum } == true,
             "\(snapshot.valueTwoCount.map(String.init) ?? "数据不足")/要求≤\(config.valueTwoMaximum)"),
            ("P_tr", snapshot.transitionPercent.map { $0 + 1e-12 >= config.transitionMinimumPercent } == true,
             "\(snapshot.transitionPercent.map { decimal($0) } ?? "数据不足")%/要求≥\(decimal(config.transitionMinimumPercent))%"),
            ("R", roughnessPasses,
             "\(snapshot.roughness.map(String.init) ?? "数据不足")/要求\(roughnessRequirement)"),
            ("B", config.breakpointRange.contains(snapshot.breakpoints),
             "\(snapshot.breakpoints)/要求\(integerRange(config.breakpointRange))")
        ]
    }

    private func refreshHistoricalToleranceStatistics() {
        guard let config = try? FilterConfig.parse(generatedInput) else {
            historicalToleranceStatistics = nil
            return
        }
        scheduleHistoricalStatisticsRefresh(for: config)
    }

    /// 条件输入可能在一次编辑中连续变化多次。等输入稳定后再统计历史数据，
    /// 避免每个按键都在主线程重算全部奖金记录。
    private func scheduleHistoricalStatisticsRefresh(for config: FilterConfig?) {
        historicalStatisticsRefreshTask?.cancel()
        guard let config else { return }
        let snapshots = prizeQueryHistory.flatMap { $0.conditionSnapshots ?? [] }
        historicalStatisticsRefreshTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 300_000_000)
            guard !Task.isCancelled else { return }
            let statistics = await Task.detached(priority: .utility) {
                Self.makeHistoricalGlobalToleranceStatistics(
                    config: config,
                    snapshots: snapshots
                )
            }.value
            guard !Task.isCancelled else { return }
            historicalToleranceStatistics = statistics
        }
    }

    nonisolated private static func makeHistoricalGlobalToleranceStatistics(
        config: FilterConfig,
        snapshots: [PrizeConditionSnapshot]
    ) -> HistoricalGlobalToleranceStatistics? {
        let failureCounts = snapshots.compactMap { snapshot -> Int? in
            let passes = historicalGlobalConditionPassFlags(snapshot, config: config)
            guard !passes.isEmpty else { return nil }
            return passes.filter { !$0 }.count
        }.sorted()
        guard !failureCounts.isEmpty else { return nil }
        let maximumBucketLower = (failureCounts.max() ?? 0) / 2 * 2
        let buckets = stride(from: 0, through: maximumBucketLower, by: 2).map { lower in
            HistoricalToleranceBucket(
                lowerBound: lower,
                upperBound: lower + 1,
                count: failureCounts.filter { (lower...(lower + 1)).contains($0) }.count
            )
        }
        let lowerIndex = min(failureCounts.count - 1, Int(floor(Double(failureCounts.count - 1) * 0.1)))
        let upperIndex = min(failureCounts.count - 1, Int(ceil(Double(failureCounts.count - 1) * 0.9)))
        let recommendedLower = failureCounts[lowerIndex] / 2 * 2
        let recommendedUpper = failureCounts[upperIndex] / 2 * 2 + 1
        return HistoricalGlobalToleranceStatistics(
            sampleCount: failureCounts.count,
            buckets: buckets,
            recommendedRange: recommendedLower...recommendedUpper
        )
    }

    /// 不读取 SwiftUI 状态的纯函数，可安全用于后台历史重算。
    nonisolated private static func historicalGlobalConditionPassFlags(
        _ snapshot: PrizeConditionSnapshot,
        config: FilterConfig
    ) -> [Bool] {
        var passes: [Bool] = []
        if let value = snapshot.sum { passes.append(config.sumRange.contains(value)) }
        if let value = snapshot.displacement {
            let mapped = zip(config.logic, snapshot.outcomes).map { mapping, outcome in mapping.value(for: outcome) }
            passes.append(config.minimumDistinctDisplacementOrders > 0
                ? config.passesDisplacement(in: mapped)
                : config.displacementRange.contains(value))
        }
        if let value = snapshot.variance { passes.append(value <= config.varianceMaximum + 1e-12) }
        if let value = snapshot.valueTwoCount { passes.append(value <= config.valueTwoMaximum) }
        if let value = snapshot.transitionPercent { passes.append(value + 1e-12 >= config.transitionMinimumPercent) }
        if let value = snapshot.roughness { passes.append(value <= config.roughnessMaximum) }
        passes.append(config.breakpointRange.contains(snapshot.breakpoints))
        if !config.noFourPositions.isEmpty {
            passes.append(snapshot.valueFourPositions.map {
                Set($0).isDisjoint(with: Set(config.noFourPositions))
            } ?? false)
        }
        if let maximum = config.frontThreeMaximumFourCount {
            passes.append(snapshot.valueFourPositions.map { positions in
                positions.filter { $0 <= 3 }.count <= maximum
            } ?? false)
        }
        let outcomes = Array(snapshot.outcomes.prefix(config.matchNumbers.count))
        if config.prizeStatisticalConditionEnabled {
            passes.append(OutcomeCondition.winLossSwitches.value(in: Array(snapshot.outcomes.prefix(6))) <= 2)
        }
        if config.outcomeConditionToleranceEnabled, !config.enabledOutcomeConditions.isEmpty {
            passes.append(config.passesOutcomeConditions(outcomes))
        } else {
            for condition in config.enabledOutcomeConditions {
                if let range = config.outcomeConditions[condition] {
                    passes.append(range.contains(condition.value(in: outcomes)))
                }
            }
        }
        if config.spProductFilterEnabled {
            passes.append((snapshot.spCount ?? 0) >= 5 && config.spProductRange.contains(snapshot.spProduct))
        }
        if config.customHandicapOddsProductFilterEnabled {
            passes.append(
                (snapshot.spCount ?? 0) >= 5
                    && Double(config.customHandicapOddsProductRange.lowerBound) <= snapshot.spProduct
                    && snapshot.spProduct <= Double(config.customHandicapOddsProductRange.upperBound)
            )
        }
        if config.customHandicapOddsSumFilterEnabled {
            passes.append(
                (snapshot.spCount ?? 0) >= 5
                    && snapshot.spSum.map {
                        Double(config.customHandicapOddsSumRange.lowerBound) <= $0
                            && $0 <= Double(config.customHandicapOddsSumRange.upperBound)
                    } == true
            )
        }
        if config.prizeRangeFilterEnabled {
            passes.append((snapshot.spCount ?? 0) >= 5 && config.estimatedPrizeRange.contains(snapshot.estimatedPrize))
        }
        if config.spRiskFilterEnabled {
            passes.append(
                (snapshot.spCount ?? 0) >= 5
                    && snapshot.maximumSingleSP <= config.maximumSingleSP
                    && config.highSPCountRange.contains(snapshot.highSPCount)
            )
        }
        if config.minimumProbabilityFilterEnabled {
            passes.append(snapshot.minimumProbabilityPercent.map {
                $0 + 1e-12 >= config.minimumSingleProbabilityPercent
            } ?? false)
        }
        if config.jointProbabilityFilterEnabled {
            passes.append(snapshot.jointProbabilityPercent.map(config.jointProbabilityPercentRange.contains) ?? false)
        }
        if config.groupFilterEnabled {
            var groupPasses = true
            if config.groupFilterMode.usesOutcomeSum {
                groupPasses = groupPasses
                    && config.frontGroupOutcomeSumRange.contains(snapshot.frontOutcomeSum)
                    && config.backGroupOutcomeSumRange.contains(snapshot.backOutcomeSum)
            }
            if config.groupFilterMode.usesSPProduct {
                groupPasses = groupPasses
                    && (snapshot.spCount ?? 0) >= 5
                    && config.frontGroupSPProductRange.contains(snapshot.frontSPProduct)
                    && config.backGroupSPProductRange.contains(snapshot.backSPProduct)
            }
            passes.append(groupPasses)
        }
        if config.consecutiveRunsEnabled {
            passes.append(config.passesConsecutiveRuns(snapshot.outcomes))
        }
        if config.sameResultRunsEnabled {
            passes.append(config.passesSameResultRuns(snapshot.outcomes))
        }
        return passes
    }

    private var parsedPrizeConditionToleranceRange: ClosedRange<Int>? {
        let parts = prizeConditionToleranceInput
            .replacingOccurrences(of: "–", with: "-")
            .split(separator: "-", omittingEmptySubsequences: false)
        guard parts.count == 2,
              let lower = Int(parts[0].trimmingCharacters(in: .whitespaces)),
              let upper = Int(parts[1].trimmingCharacters(in: .whitespaces)),
              lower >= 0, lower <= upper, upper <= 30 else { return nil }
        return lower...upper
    }

    private var parsedPrizeRoughnessRange: ClosedRange<Int>? {
        parseIntegerRange(prizeRoughnessRangeInput, maximum: 30)
    }

    private var parsedPrizeSPSumRange: ClosedRange<Double>? {
        parseDecimalRange(prizeSPSumRangeInput)
    }

    private var parsedPrizeSPProductRange: ClosedRange<Double>? {
        parseDecimalRange(prizeSPProductRangeInput)
    }

    private func parseIntegerRange(_ input: String, maximum: Int) -> ClosedRange<Int>? {
        let parts = input
            .replacingOccurrences(of: "–", with: "-")
            .replacingOccurrences(of: "—", with: "-")
            .replacingOccurrences(of: "－", with: "-")
            .split(separator: "-", omittingEmptySubsequences: false)
        guard parts.count == 2,
              let lower = Int(parts[0].trimmingCharacters(in: .whitespaces)),
              let upper = Int(parts[1].trimmingCharacters(in: .whitespaces)),
              lower >= 0, lower <= upper, upper <= maximum else { return nil }
        return lower...upper
    }

    private func parseDecimalRange(_ input: String) -> ClosedRange<Double>? {
        let parts = input
            .replacingOccurrences(of: "–", with: "-")
            .replacingOccurrences(of: "—", with: "-")
            .replacingOccurrences(of: "－", with: "-")
            .split(separator: "-", omittingEmptySubsequences: false)
        guard parts.count == 2,
              let lower = Double(parts[0].trimmingCharacters(in: .whitespaces)),
              let upper = Double(parts[1].trimmingCharacters(in: .whitespaces)),
              lower.isFinite, upper.isFinite,
              lower >= 0, lower <= upper else { return nil }
        return lower...upper
    }

    /// 使用奖金记录已经保存的完整指标复核“历史综合分析”。这样全局答案
    /// 不会因为手机端没有重新下载概率/SP矩阵而跳过条件或把数据误判为空。
    private func comprehensiveAnalysisFailureCount(
        _ snapshot: PrizeConditionSnapshot,
        config: FilterConfig
    ) -> Int? {
        guard let profile = comprehensiveAnalysisProfile else { return nil }
        return Self.comprehensiveAnalysisFailureCount(snapshot, profile: profile)
    }

    nonisolated private static func comprehensiveAnalysisFailureCount(
        _ snapshot: PrizeConditionSnapshot,
        profile: ComprehensiveAnalysisProfile
    ) -> Int {
        let summary = PrizeCalculator.outcomeSummary(for: snapshot.outcomes)
        var values: [ComprehensiveAnalysisMetric: Double] = [:]
        if let value = snapshot.productQ { values[.productQ] = Double(value) }
        if let value = snapshot.sum { values[.sum] = Double(value) }
        if let value = snapshot.displacement { values[.displacement] = Double(value) }
        if let value = snapshot.variance { values[.variance] = value }
        if let value = snapshot.valueTwoCount { values[.valueTwoCount] = Double(value) }
        if let value = snapshot.valueFourPositions { values[.valueFourCount] = Double(value.count) }
        if let value = snapshot.transitionPercent { values[.transitionPercent] = value }
        if let value = snapshot.roughness { values[.roughness] = Double(value) }
        values[.breakpoints] = Double(snapshot.breakpoints)
        values[.frontOutcomeSum] = Double(snapshot.frontOutcomeSum)
        values[.backOutcomeSum] = Double(snapshot.backOutcomeSum)
        if let summary {
            values[.winCount] = Double(summary.winCount)
            values[.drawCount] = Double(summary.drawCount)
            values[.lossCount] = Double(summary.lossCount)
            values[.diversity] = Double(summary.diversity)
            values[.outcomeSum] = Double(summary.outcomeSum)
            values[.returns] = Double(summary.returns)
            values[.winLossSwitches] = Double(summary.winLossSwitches)
            values[.nonLoss] = Double(summary.nonLoss)
            values[.nonDraw] = Double(summary.nonDraw)
            values[.nonWin] = Double(summary.nonWin)
            values[.winRun] = Double(summary.win)
            values[.drawRun] = Double(summary.draw)
            values[.lossRun] = Double(summary.loss)
        }
        if (snapshot.spCount ?? 0) >= 5 {
            if let value = snapshot.spSum { values[.spSum] = value }
            values[.spProduct] = snapshot.spProduct
            values[.estimatedPrize] = snapshot.estimatedPrize
            values[.maximumSingleSP] = snapshot.maximumSingleSP
            values[.highSPCount] = Double(snapshot.highSPCount)
            values[.frontSPProduct] = snapshot.frontSPProduct
            values[.backSPProduct] = snapshot.backSPProduct
        }
        if let value = snapshot.minimumProbabilityPercent {
            values[.minimumProbabilityPercent] = value
        }
        if let value = snapshot.jointProbabilityPercent {
            values[.jointProbabilityPercent] = value
        }
        return profile.rules.reduce(0) { count, rule in
            guard let value = values[rule.metric] else { return count + 1 }
            return count + (SequenceFilterEngine.comprehensiveAnalysisRulePassesLatest(rule, value: value) ? 0 : 1)
        }
    }

    private func comprehensiveAnalysisPasses(
        _ snapshot: PrizeConditionSnapshot,
        config: FilterConfig
    ) -> Bool {
        guard comprehensiveAnalysisFilterEnabled else { return true }
        guard let tolerance = parsedComprehensiveAnalysisToleranceRange,
              let failureCount = comprehensiveAnalysisFailureCount(snapshot, config: config) else {
            return false
        }
        return tolerance.contains(failureCount)
    }

    private var parsedComprehensiveAnalysisToleranceRange: ClosedRange<Int>? {
        let parts = comprehensiveAnalysisToleranceInput
            .replacingOccurrences(of: "–", with: "-")
            .replacingOccurrences(of: "—", with: "-")
            .replacingOccurrences(of: "－", with: "-")
            .split(separator: "-", omittingEmptySubsequences: false)
        guard parts.count == 2,
              let lower = Int(parts[0].trimmingCharacters(in: .whitespaces)),
              let upper = Int(parts[1].trimmingCharacters(in: .whitespaces)),
              lower >= 0, lower <= upper else { return nil }
        return lower...upper
    }

    private var parsedProtectedHistoryToleranceRange: ClosedRange<Int>? {
        parseIntegerRange(protectedHistoryToleranceInput, maximum: 24)
    }

    private var effectiveProtectedHistoryToleranceRange: ClosedRange<Int> {
        guard protectedHistoryToleranceEnabled else { return 0...0 }
        return parsedProtectedHistoryToleranceRange ?? 0...0
    }

    private var effectiveProtectedHistoryBetCap: Int? {
        // 不允许把已经通过条件的组合按排名强制截断。
        // 保留旧存储字段仅为兼容用户数据，计算时永返回 nil。
        nil
    }

    private func decimal(_ value: Double, digits: Int = 3) -> String {
        String(format: "%.*f", digits, value)
            .replacingOccurrences(of: #"\.?0+$"#, with: "", options: .regularExpression)
    }

