    private var cleanedPrizeMatchNumbers: [String] {
        prizeMatchInputs.map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
    }

    private var manuallyDelayedPrizeMatchNumbers: Set<String> {
        Set(
            prizeDelayedMatchNumbersInput
                .split { $0 == "," || $0 == "，" || $0 == "、" || $0 == " " }
                .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
                .filter { !$0.isEmpty && $0.allSatisfy(\.isNumber) }
        )
    }

    private func hasValidPrizeQuery(count: Int) -> Bool {
        let issue = prizeIssueInput.trimmingCharacters(in: .whitespacesAndNewlines)
        let numbers = Array(cleanedPrizeMatchNumbers.prefix(count))
        return !issue.isEmpty
            && numbers.count == count
            && numbers.allSatisfy { !$0.isEmpty && $0.allSatisfy(\.isNumber) }
            && Set(numbers.compactMap(Int.init)).count == count
    }

    private func makePrizeConditionSnapshot(
        matches: [BeijingSingleMatch],
        outcomes: [Int],
        spValues: [Double],
        label: String
    ) -> PrizeConditionSnapshot? {
        guard outcomes.count == spValues.count, outcomes.count >= 5 else { return nil }
        let judgedOutcomes = Array(outcomes.prefix(6))
        let mainOutcomes = Array(judgedOutcomes.prefix(5))
        let mainSP = Array(spValues.prefix(5))
        let prizeSP = Array(spValues.prefix(6))
        let analyses = matches.prefix(5).compactMap { try? PoissonGoalModel.analyze($0) }
        let hasModels = analyses.count == 5
        let logic = hasModels ? analyses.map(\.recommendedLogic) : []
        let values = hasModels ? zip(logic, mainOutcomes).map { $0.value(for: $1) } : []
        let selectedProbabilities: [Double]? = hasModels ? zip(analyses, mainOutcomes).map { analysis, outcome in
            let index = outcome == 3 ? 0 : (outcome == 1 ? 1 : 2)
            return analysis.handicapProbabilities[index]
        } : nil
        let sum = values.isEmpty ? nil : values.reduce(0, +)
        let variance: Double? = sum.map { total in
            let mean = Double(total) / Double(values.count)
            return values.reduce(0.0) { $0 + pow(Double($1) - mean, 2) } / Double(values.count)
        }
        let split = 3
        return PrizeConditionSnapshot(
            label: label,
            outcomes: judgedOutcomes,
            logic: hasModels ? logic.map(\.displayName).joined() : nil,
            productQ: values.isEmpty ? nil : values.reduce(1, *),
            sum: sum,
            displacement: values.isEmpty ? nil : zip(values, values.dropFirst()).reduce(0) { $0 + abs($1.1 - $1.0) },
            variance: variance,
            valueTwoCount: values.isEmpty ? nil : values.filter { $0 == 2 }.count,
            valueFourPositions: values.isEmpty ? nil : values.indices.filter { values[$0] == 4 }.map { $0 + 1 },
            transitionPercent: values.isEmpty ? nil : prizeTransitionPercent(values),
            roughness: values.isEmpty ? nil : prizeRoughness(values),
            breakpoints: zip(mainOutcomes, mainOutcomes.dropFirst()).filter { $0 != $1 }.count,
            spSum: prizeSP.reduce(0, +),
            spProduct: prizeSP.reduce(1, *),
            estimatedPrize: prizeSP.reduce(1, *) * 1.3,
            spCount: prizeSP.count,
            maximumSingleSP: prizeSP.max() ?? 0,
            highSPCount: prizeSP.filter { $0 > 4 }.count,
            minimumProbabilityPercent: selectedProbabilities.map { ($0.min() ?? 0) * 100 },
            jointProbabilityPercent: selectedProbabilities.map { $0.reduce(1, *) * 100 },
            frontOutcomeSum: mainOutcomes.prefix(split).reduce(0, +),
            backOutcomeSum: mainOutcomes.dropFirst(split).reduce(0, +),
            frontSPProduct: mainSP.prefix(split).reduce(1, *),
            backSPProduct: mainSP.dropFirst(split).reduce(1, *)
        )
    }

    private func prizeTransitionPercent(_ values: [Int]) -> Double {
        guard values.count > 1 else { return 100 }
        var counts: [Int: [Int: Int]] = [:]
        var totals: [Int: Int] = [:]
        for (from, to) in zip(values, values.dropFirst()) {
            counts[from, default: [:]][to, default: 0] += 1
            totals[from, default: 0] += 1
        }
        return zip(values, values.dropFirst()).reduce(1.0) { partial, pair in
            partial * Double(counts[pair.0]?[pair.1] ?? 0) / Double(totals[pair.0] ?? 1)
        } * 100
    }

    private func prizeRoughness(_ values: [Int]) -> Int {
        guard values.count >= 3 else { return 0 }
        var result = 0
        for index in 2..<values.count {
            let current = values[index]
            let previous = values[index - 1]
            let previousPrevious = values[index - 2]
            result += abs(current - (2 * previous) + previousPrevious)
        }
        return result
    }

    private func calculatePrizeQuery(matchCount: Int, replaceHighSPWithHandicap: Bool = false) {
        guard hasValidPrizeQuery(count: matchCount) else {
            prizeCalculationMessage = "请输入期号或日期，并填写\(matchCount)个不重复的数字场次号。"
            return
        }
        let requestedIssue = prizeIssueInput.trimmingCharacters(in: .whitespacesAndNewlines)
        let numbers = Array(cleanedPrizeMatchNumbers.prefix(matchCount))
        prizeCalculationMessage = nil
        canRecalculateHighPrizeSP = false
        latestSeventhEstimates = []
        latestPrizeRunSummary = nil
        latestPrizeAmount = nil
        latestPrizeAmountLabel = ""
        latestPrizeConditionSnapshots = []
        isCalculatingPrize = true
        Task {
            defer { isCalculatingPrize = false }
            do {
                let savedAnchor = UserDefaults.standard.string(forKey: goalModelIssueStorageKey)
                let anchor = savedAnchor?.allSatisfy(\.isNumber) == true
                    ? savedAnchor!
                    : (beijingSingleIssueInput.allSatisfy(\.isNumber) ? beijingSingleIssueInput : "26092")
                let issue = try await FiveHundredBeijingSingleClient.resolveIssue(
                    input: requestedIssue,
                    anchorIssue: anchor
                )
                let matches = try await FiveHundredBeijingSingleClient.fetchPrizeMatches(
                    issue: issue,
                    matchNumbers: numbers,
                    requireHandicapSP: matchCount == 7 || replaceHighSPWithHandicap
                )
                let firstSixMatches = Array(matches.prefix(6))
                let autoDelayedMatchNumbers = Set(
                    firstSixMatches
                        .filter(\.isPostponedOver12Hours)
                        .map(\.matchNumber)
                )
                let requestedDelayedMatchNumbers = manuallyDelayedPrizeMatchNumbers
                    .union(autoDelayedMatchNumbers)
                let delayedFirstSixMatchNumbers = Set(
                    firstSixMatches
                        .map(\.matchNumber)
                        .filter { requestedDelayedMatchNumbers.contains($0) }
                )
                if matchCount == 7 {
                    let firstSix = firstSixMatches
                    guard let seventh = matches.last,
                          let estimates = PrizeCalculator.seventhOutcomeEstimates(
                            firstSix: firstSix,
                            seventh: seventh,
                            useHandicapSP: true,
                            treatingFirstSixMatchNumbersAsUnit: delayedFirstSixMatchNumbers
                          ),
                          estimates.count == 2 else {
                        throw GoalModelError.oddsUnavailable(numbers.last ?? "-")
                    }
                    let firstSixValues = firstSix.compactMap { match in
                        if delayedFirstSixMatchNumbers.contains(match.matchNumber) { return 1.0 }
                        return PrizeCalculator.selectedSP(for: match)
                    }
                    let firstSixOutcomes = firstSix.compactMap(\.handicapOutcome)
                    guard firstSixValues.count == 6, firstSixOutcomes.count == 6 else {
                        throw GoalModelError.resultUnavailable(numbers.first ?? "-")
                    }
                    let details = zip(firstSix, firstSixValues).map { match, sp in
                        let handicap = match.handicap.map { signedHandicap($0) } ?? "?"
                        let delayed = delayedFirstSixMatchNumbers.contains(match.matchNumber)
                            ? "（延期>12小时，选项按1）"
                            : ""
                        return "场次\(match.matchNumber)（让球\(handicap)）：让球彩果\(match.handicapOutcome.map(String.init) ?? "-") @ \(String(format: "%.2f", sp))\(delayed)"
                    }.joined(separator: "\n")
                    let normalSeventhSP = [seventh.referenceSP.first, seventh.referenceSP.count == 3 ? seventh.referenceSP[2] : nil]
                        .compactMap { $0 }
                    let hasHighSP = normalSeventhSP.contains { $0 > 5 }
                    let delayedWarning = delayedFirstSixMatchNumbers.isEmpty
                        ? ""
                        : "\n提示：前六场延期>12小时场次\(delayedFirstSixMatchNumbers.sorted().joined(separator: "、"))，每个选项按1.00计入奖金。"
                    let warning = (hasHighSP ? "\n提示：第7场让球SP超过5，当前仍按让球SP计算。" : "") + delayedWarning
                    prizeCalculationMessage = """
                    期号：\(issue)
                    前6场彩果：\(firstSixOutcomes.map(String.init).joined(separator: "、"))
                    \(details)
                    奖金公式：前6场SP乘积 × 第7场对应SP × 1.3\(warning)
                    """
                    latestSeventhEstimates = estimates
                    latestPrizeRunSummary = nil
                    let snapshots = estimates.compactMap { estimate in
                        makePrizeConditionSnapshot(
                            matches: matches,
                            outcomes: firstSixOutcomes + [estimate.outcome],
                            spValues: firstSixValues + [estimate.sp],
                            label: "第7场默认\(estimate.outcome)"
                        )
                    }
                    latestPrizeConditionSnapshots = snapshots
                    canRecalculateHighPrizeSP = false
                    prizeIssueInput = issue
                    appendPrizeQueryRecord(
                        issue: issue,
                        matchNumbers: numbers,
                        handicaps: matches.map(\.handicap),
                        isSettled: false,
                        amount: estimates[0].amount,
                        calculationLabel: "7场双结果估算",
                        runSummary: nil,
                        outcomes: firstSixOutcomes,
                        seventhEstimates: estimates,
                        seventhRunSummaries: estimates.map {
                            SeventhOutcomeRunSummary(outcome: $0.outcome, runSummary: $0.runSummary)
                        },
                        conditionSnapshots: snapshots
                    )
                    return
                }
                let originalValues = matches.compactMap(PrizeCalculator.selectedSP)
                guard originalValues.count == matchCount else {
                    throw GoalModelError.oddsUnavailable(numbers.first ?? "-")
                }
                let values = matches.map { match -> Double in
                    if delayedFirstSixMatchNumbers.contains(match.matchNumber) {
                        return 1.0
                    }
                    if replaceHighSPWithHandicap,
                       let original = PrizeCalculator.selectedSP(for: match), original > 5,
                       let handicap = PrizeCalculator.handicapSP(for: match) {
                        return handicap
                    }
                    return PrizeCalculator.selectedSP(for: match)!
                }
                let amount = values.reduce(1.3, *)
                let highSPMatches = zip(matches, originalValues).filter { $0.1 > 5 }
                let details = zip(matches.indices, zip(matches, values)).map { index, value in
                    let match = value.0
                    let sp = value.1
                    let original = originalValues[index]
                    let delayed = delayedFirstSixMatchNumbers.contains(match.matchNumber)
                        ? "（延期>12小时，选项按1）"
                        : ""
                    let replacement = replaceHighSPWithHandicap && original > 5
                        ? "（原\(String(format: "%.2f", original))，按让球重算）"
                        : ""
                    let handicap = match.handicap.map { signedHandicap($0) } ?? "?"
                    return "场次\(match.matchNumber)（让球\(handicap)）：让球彩果\(match.handicapOutcome.map(String.init) ?? "-") @ \(String(format: "%.2f", sp))\(replacement)\(delayed)"
                }.joined(separator: "\n")
                let isSettled = PrizeCalculator.isFullySettled(matches) && !replaceHighSPWithHandicap
                guard let runSummary = PrizeCalculator.runSummary(for: matches) else {
                    throw GoalModelError.resultUnavailable(numbers.first ?? "-")
                }
                latestPrizeRunSummary = runSummary
                latestPrizeAmount = amount
                let snapshots = makePrizeConditionSnapshot(
                    matches: matches,
                    outcomes: matches.compactMap(\.handicapOutcome),
                    spValues: values,
                    label: "\(matchCount)场实际彩果"
                ).map { [$0] } ?? []
                latestPrizeConditionSnapshots = snapshots
                let amountTitle = replaceHighSPWithHandicap
                    ? "\(matchCount)场让球SP估算"
                    : (isSettled ? "\(matchCount)场开奖金额" : "\(matchCount)场未开奖估算")
                latestPrizeAmountLabel = amountTitle
                let delayedWarning = delayedFirstSixMatchNumbers.isEmpty
                    ? ""
                    : "\n提示：前六场延期>12小时场次\(delayedFirstSixMatchNumbers.sorted().joined(separator: "、"))，每个选项按1.00计入奖金。"
                let warning = (!replaceHighSPWithHandicap && !highSPMatches.isEmpty
                    ? "\n提示：场次\(highSPMatches.map { $0.0.matchNumber }.joined(separator: "、"))的SP超过5，可点下方按钮按让球赛果SP重算。"
                    : "") + delayedWarning
                let automaticPrizeLine: String
                if prizeConditionAnalysisEnabled, let snapshot = snapshots.first {
                    if let passes = currentPrizeConditionPasses(snapshot) {
                        automaticPrizeLine = passes
                            ? "过滤通过｜6场自动奖金：¥\(String(format: "%.2f", snapshot.estimatedPrize))"
                            : "过滤未通过｜不计算6场奖金"
                    } else {
                        automaticPrizeLine = "奖金条件范围无效，暂不计算自动奖金"
                    }
                } else {
                    automaticPrizeLine = "\(amountTitle)：¥\(String(format: "%.2f", amount))"
                }
                prizeCalculationMessage = """
                期号：\(issue)
                状态：\(replaceHighSPWithHandicap ? "已按让球赛果重算" : (isSettled ? "\(matchCount)场均已开奖" : "\(matchCount)场已结束，尚未全部开奖"))
                \(details)
                \(prizeRunSummaryText(runSummary))
                \(automaticPrizeLine)
                公式：\(values.map { String(format: "%.2f", $0) }.joined(separator: " × ")) × 1.3\(warning)
                """
                canRecalculateHighPrizeSP = matchCount == 7
                    && !replaceHighSPWithHandicap
                    && !highSPMatches.isEmpty
                prizeIssueInput = issue
                appendPrizeQueryRecord(
                    issue: issue,
                    matchNumbers: numbers,
                    handicaps: matches.map(\.handicap),
                    isSettled: isSettled,
                    amount: amount,
                    calculationLabel: amountTitle,
                    runSummary: runSummary,
                    outcomes: matches.compactMap(\.handicapOutcome),
                    seventhEstimates: nil,
                    seventhRunSummaries: PrizeCalculator.seventhOutcomeRunSummaries(
                        firstSixOutcomes: matches.compactMap(\.handicapOutcome)
                    ),
                    conditionSnapshots: snapshots
                )
            } catch {
                prizeCalculationMessage = "查询失败：\(error.localizedDescription)"
            }
        }
    }

