    private func goalModelRow(_ analysis: GoalModelAnalysis) -> some View {
        VStack(alignment: .leading, spacing: 6) {
            HStack(alignment: .firstTextBaseline) {
                Text("第\(analysis.match.matchNumber)场 · \(analysis.match.league)")
                    .font(.headline)
                Spacer()
                Text(analysis.recommendedLogic.displayName)
                    .font(.title2.bold())
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
            }
            Text("\(analysis.match.homeTeam) \(signedHandicap(analysis.match.handicap ?? 0)) \(analysis.match.awayTeam)")
                .font(.subheadline.weight(.semibold))
            if analysis.match.hasStarted {
                Text("已开赛场次 · 比分和赛果已隔离")
                    .font(.caption.bold())
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
            }
            Text("让球胜/平/负：\(percent(analysis.handicapProbabilities[0])) / \(percent(analysis.handicapProbabilities[1])) / \(percent(analysis.handicapProbabilities[2]))")
                .font(.system(.caption, design: .monospaced))
            if analysis.handicapFairOdds.count == 3 {
                Text("让球胜/平/负对照表换算赔率：\(analysis.handicapFairOdds.map { String(format: "%.2f", $0) }.joined(separator: " / "))")
                    .font(.system(.caption, design: .monospaced).bold())
                Text("模型去水重算值，不是市场实时SP")
                    .font(.caption2)
                    .foregroundStyle(SequenceFilterTheme.textSecondary)
            }
            Text("预期进球：\(String(format: "%.2f", analysis.homeExpectedGoals)) / \(String(format: "%.2f", analysis.awayExpectedGoals))；大2.5：\(percent(analysis.overTwoPointFiveProbability))；双方进球：\(percent(analysis.bothTeamsScoreProbability))")
                .font(.caption)
            Text("比分前三：\(analysis.topScores.map(\.displayText).joined(separator: "，"))")
                .font(.caption)
            Text("信心指数：\(analysis.confidenceIndex)/100（\(analysis.confidenceText)）")
                .font(.caption.bold())
                .foregroundStyle(SequenceFilterTheme.textSecondary)
            Text("理由：\(analysis.confidenceReason)")
                .font(.caption)
                .foregroundStyle(SequenceFilterTheme.textSecondary)
            Text(analysis.logicNote)
                .font(.caption)
                .foregroundStyle(SequenceFilterTheme.textSecondary)
        }
        .padding(.vertical, 4)
    }

