    @MainActor
    private func calculateAfterEnsuringRequiredMatchTimes() async {
        guard !isCalculating, globalGenerationPhase == nil else { return }
        guard !isRefreshingDoubleMarket else {
            errorMessage = "正在更新赛前行情，请完成后再生成，以使用同一份双选快照。"
            return
        }
        let generationStartedAt = Date()
        globalGenerationPhase = "选场中…"
        defer {
            globalGenerationPhase = nil
            NSLog("GLOBAL-GENERATE stage=finished elapsed=%.3fs", Date().timeIntervalSince(generationStartedAt))
        }
        // 先让按钮反馈本次点击；取数期间也只保留一个生成任务。
        await Task.yield()
        if usesAutomaticSearchOrigin, inputExperienceMode == "v1" {
            // 场号/条件相同不代表行情相同。每次生成重新取得本次快照，
            // 避免 committedKey 命中后始终复用上次的31/10及赔率。
            // 正在选场时等待同一个任务，不额外启动第二条取数链路。
            if !isCalculatingVIP6Matches { scheduleVIP6AutomaticMatchSelection(debounce: false) }
            await vip6AutoSelectionTask?.value
            guard currentSelectionPatternIsValid else {
                result = nil
                errorMessage = vip6AutoSelectionMessage ?? "连续六场的ABCD尚未齐全，请补齐赔率后重新生成。"
                return
            }
        }
        if usesStructuredMatchSelection, !currentSelectionPatternIsValid {
            if !isCalculatingVIP6Matches { scheduleVIP6AutomaticMatchSelection() }
            await vip6AutoSelectionTask?.value
            guard currentSelectionPatternIsValid else {
                result = nil
                errorMessage = vip6AutoSelectionMessage ?? "未取得可用的连续六场，请调整起点或补齐赔率。"
                return
            }
        }
        if usesSVIP10AutomaticDoublePair, automaticDoubleSelectionCommittedKey != automaticDoubleGenerationKey {
            if !isCalculatingVIP6Matches { scheduleVIP6AutomaticMatchSelection() }
            await vip6AutoSelectionTask?.value
            guard usesSVIP10AutomaticDoublePair,
                  automaticDoubleSelectionCommittedKey == automaticDoubleGenerationKey,
                  currentABCDForGeneration != nil else {
                result = nil
                errorMessage = vip6AutoSelectionMessage ?? "自动双选尚未完成，请等待赔率读取后重新生成。"
                return
            }
        }
        NSLog("GLOBAL-GENERATE stage=begin issue=%@ matches=%@", requiredStartTimeIssue, currentCalculationMatchNumbers.joined(separator: ","))
        // “全局生成”与“获取ABCD”共用同一条实时补取链路。以前这里先判空
        // 直接退出，导致用户即使随后点击获取也仍停在旧失败状态。
        if currentABCDForGeneration == nil {
            globalGenerationPhase = "取数中…"
            abcdSourceMessage = "生成前正在自动补取当前\(currentCalculationLogicCount)场ABCD…"
            await fetchABCDForCurrentInput(debounce: false)
        }
        guard let verified = currentABCDForGeneration else {
            result = nil
            errorMessage = "已自动依次查询比分页、交易页和澳客，但当前\(currentCalculationLogicCount)场仍没有完整的真实ABCD。请检查期号和第一场场次，或手动输入完整的\(currentCalculationLogicCount)位ABCD后再次生成。"
            abcdSourceMessage = "已完成全部真实数据源重试；未使用AAAAA或跨期场次伪造ABCD。"
            isLoadingGoalModel = false
            return
        }
        logicInput = verified
        abcdAttemptedKey = abcdInputKey
        isLoadingGoalModel = false

        let requestedConfig: FilterConfig
        do {
            requestedConfig = try FilterConfig.parse(generatedInput)
        } catch {
            result = nil
            errorMessage = error.localizedDescription
            return
        }
        NSLog("GLOBAL-GENERATE stage=config-ready config=%@", requestedConfig.normalizedInput)
        let comprehensiveNeedsSP = !(requestedConfig.svip7RankOddsEnabled || requestedConfig.svip10Frozen160Enabled || requestedConfig.svip11BreakpointOnlyEnabled) && comprehensiveAnalysisFilterEnabled
            && comprehensiveAnalysisProfile?.requiresSPData == true
        let comprehensiveNeedsProbability = !(requestedConfig.svip7RankOddsEnabled || requestedConfig.svip10Frozen160Enabled || requestedConfig.svip11BreakpointOnlyEnabled) && comprehensiveAnalysisFilterEnabled
            && comprehensiveAnalysisProfile?.requiresProbabilityData == true
        let protectedNeedsSP = !(requestedConfig.svip7RankOddsEnabled || requestedConfig.svip10Frozen160Enabled || requestedConfig.svip11BreakpointOnlyEnabled) && protectedHistoryMaxCompressionEnabled
            && protectedHistoryMaxCompressionProfile?.requiresSPData == true
        let protectedNeedsProbability = !(requestedConfig.svip7RankOddsEnabled || requestedConfig.svip10Frozen160Enabled || requestedConfig.svip11BreakpointOnlyEnabled) && protectedHistoryMaxCompressionEnabled
            && protectedHistoryMaxCompressionProfile?.requiresProbabilityData == true
        if requestedConfig.requiresSPData
            || requestedConfig.requiresProbabilityData
            || SequenceFilterEngine.usesVIP4Model(
                threshold: requestedConfig.universal247ToleranceThreshold
            )
            || comprehensiveNeedsSP
            || comprehensiveNeedsProbability
            || protectedNeedsSP
            || protectedNeedsProbability {
            isLoadingGoalModel = true
            globalGenerationPhase = "取数中…"
            abcdSourceMessage = "正在补取当前场次赔率数据，确保已开启条件实际参与过滤…"
            let needsComparisonTableOdds = requestedConfig.requiresSPData
                || SequenceFilterEngine.usesVIP4Model(
                    threshold: requestedConfig.universal247ToleranceThreshold
                )
                || SequenceFilterEngine.usesHandicapOddsV9Model(
                    threshold: requestedConfig.universal247ToleranceThreshold
                )
                || comprehensiveNeedsSP
                || protectedNeedsSP
            let analyses = await loadCurrentAnalysesForProbabilityIfNeeded(
                for: requestedConfig,
                requireCompleteComparisonTableOdds: needsComparisonTableOdds
            )
            NSLog("GLOBAL-GENERATE stage=odds-ready analyses=%ld", analyses.count)
            isLoadingGoalModel = false
            let hasRequiredSP = !requestedConfig.requiresSPData
                || outcomeSPMatrix(for: requestedConfig, analyses: analyses) != nil
            let hasRequiredProbability = !requestedConfig.requiresStrictProbabilityData
                || outcomeProbabilityMatrix(for: requestedConfig, analyses: analyses) != nil
            let hasProfileSP = !(comprehensiveNeedsSP || protectedNeedsSP)
                || outcomeSPMatrix(for: requestedConfig, analyses: analyses) != nil
            let hasProfileProbability = !(comprehensiveNeedsProbability || protectedNeedsProbability)
                || outcomeProbabilityMatrix(for: requestedConfig, analyses: analyses) != nil
            let hasVIP3Context = !SequenceFilterEngine.usesVIP3Model(
                threshold: requestedConfig.universal247ToleranceThreshold
            ) || vip3MatchContext(for: requestedConfig, analyses: analyses) != nil
            let hasVIP4Context = !SequenceFilterEngine.usesVIP4Model(
                threshold: requestedConfig.universal247ToleranceThreshold
            ) || vip4MatchContext(for: requestedConfig, analyses: analyses) != nil
            guard hasRequiredSP, hasRequiredProbability, hasProfileSP, hasProfileProbability,
                  hasVIP3Context, hasVIP4Context else {
                result = nil
                let requiredNumbers = (SequenceFilterEngine.usesVIP4Model(
                    threshold: requestedConfig.universal247ToleranceThreshold
                ) || SequenceFilterEngine.usesVIP3Model(
                    threshold: requestedConfig.universal247ToleranceThreshold
                ))
                    ? requestedConfig.matchNumbers + requestedConfig.extraMatches.filter {
                        Set($0.outcomes) == Set([3, 1, 0])
                    }.prefix(1).map(\.matchNumber)
                    : requestedConfig.matchNumbers
                let missing = HandicapOddsComparisonTableMatrix.missingMatchNumbers(
                    matchNumbers: requiredNumbers,
                    matches: analyses.map(\.match)
                )
                if needsComparisonTableOdds, !missing.isEmpty {
                    errorMessage = "场次\(missing.joined(separator: "、"))缺少完整普通胜/平/负欧赔或让球数，无法按项目让球赔率对照表换算，已停止生成。"
                } else {
                    errorMessage = "当前已开启赔率/概率条件，但未能取得所需六场完整数据，已停止生成；本次不会偷偷关闭条件。"
                }
                return
            }
            if SequenceFilterEngine.usesVIP2Model(
                threshold: requestedConfig.universal247ToleranceThreshold
            ) || SequenceFilterEngine.usesVIP3Model(
                threshold: requestedConfig.universal247ToleranceThreshold
            ) || SequenceFilterEngine.usesVIP4Model(
                threshold: requestedConfig.universal247ToleranceThreshold
            ), let rows = outcomeSPMatrix(for: requestedConfig, analyses: analyses) {
                let convertedABCD = rows.compactMap(
                    LogicMapping.derivedFromComparisonTableOdds
                ).map(\.displayName).joined()
                guard convertedABCD.count == requestedConfig.matchNumbers.count else {
                    result = nil
                    errorMessage = "项目换算后赔率无法生成完整ABCD，已停止生成。"
                    return
                }
                logicInput = convertedABCD
                abcdAttemptedKey = abcdInputKey
                abcdSourceMessage = "ABCD已按项目换算后让球欧赔重新对应：\(convertedABCD)"
            } else if requestedConfig.vip12ProbabilityReductionEnabled,
                      outcomeProbabilityMatrix(for: requestedConfig, analyses: analyses) == nil {
                abcdSourceMessage = "六场实时概率未取全，\(vip11FamilyVersionLabel)已自动使用ABCD映射概率继续减注。"
            } else {
                abcdSourceMessage = "赔率数据已就绪，已开启条件将全部参与过滤。"
            }
        }
        globalGenerationPhase = "生成中…"
        await calculate()
    }

    @MainActor
    private func calculate() async {
        errorMessage = nil
        estimatedHitProbability = nil
        hitProbabilityExplanation = nil
        do {
            let config = try FilterConfig.parse(generatedInput)
            let comprehensiveProfile = comprehensiveAnalysisFilterEnabled ? comprehensiveAnalysisProfile : nil
            let protectedHistoryProfile = protectedHistoryMaxCompressionEnabled
                ? protectedHistoryMaxCompressionProfile
                : nil
            let comprehensiveTolerance: ClosedRange<Int>
            if comprehensiveAnalysisFilterEnabled,
               let comprehensiveProfile,
               let parsed = parsedComprehensiveAnalysisToleranceRange,
               parsed.upperBound <= comprehensiveProfile.rules.count {
                comprehensiveTolerance = parsed
            } else {
                comprehensiveTolerance = 0...0
            }
            let protectedPrizePrefixes = protectedPrizeOutcomePrefixes
            let protectedHistoryTolerance = effectiveProtectedHistoryToleranceRange
            let protectedHistoryCap = effectiveProtectedHistoryBetCap
            isCalculating = true
            defer { isCalculating = false }
            // 进入实际计算前已由上层补齐已开启条件需要的赔率/概率数据。
            let previous: (outcomes: [Int], logic: [LogicMapping], logicSource: String)? = nil
            let previousAnalysis: (message: String, hitFlag: Int)? = nil
            let vip3Numbers = (SequenceFilterEngine.usesVIP4Model(
                threshold: config.universal247ToleranceThreshold
            ) || SequenceFilterEngine.usesVIP3Model(
                threshold: config.universal247ToleranceThreshold
            ))
                ? config.extraMatches.filter { Set($0.outcomes) == Set([3, 1, 0]) }
                    .prefix(1).map(\.matchNumber)
                : []
            let vip4Numbers = SequenceFilterEngine.usesVIP4Model(
                threshold: config.universal247ToleranceThreshold
            ) ? vip4AnalysisNumbers(for: config) : []
            let probabilityCount = config.vip12ProbabilityReductionEnabled
                ? config.matchNumbers.count
                : min(
                    config.calculationMatchCount ?? config.matchNumbers.count,
                    config.matchNumbers.count
                )
            // 与生成前的补取口径保持一致：SVIP2 虽然基础指标用前
            // 5 场，自定义赔率乘积却用前 6 场。这里不能再把已经
            // 补齐的第 6 场从计算快照中裁掉。
            let requiredMainCount = max(
                probabilityCount,
                config.requiredCustomOddsMatchCount
            )
            let requestedMainNumbers = Array(config.matchNumbers.prefix(requiredMainCount))
            let requested = Set((requestedMainNumbers + vip3Numbers + vip4Numbers).compactMap(Int.init))
            let enteredIssue = beijingSingleIssueInput.trimmingCharacters(in: .whitespacesAndNewlines)
            let cachedIssue = enteredIssue.count == 5 && enteredIssue.allSatisfy(\.isNumber)
                ? enteredIssue
                : (UserDefaults.standard.string(forKey: goalModelIssueStorageKey) ?? "")
            let cachedAnalyses = goalModelAnalyses.filter {
                $0.match.issue == cachedIssue
                    && Int($0.match.matchNumber).map(requested.contains) == true
            }
            let currentAnalyses = cachedAnalyses.count == requested.count ? cachedAnalyses : []
            let activeConfig = config
            let activeProfile = comprehensiveProfile
            let activeProtectedHistoryProfile = protectedHistoryProfile
            let currentProbabilities = outcomeProbabilityMatrix(
                for: config,
                analyses: currentAnalyses
            )
            let currentSPs = outcomeSPMatrix(for: config, analyses: currentAnalyses)
            let currentVIP3Context = vip3MatchContext(
                for: config,
                analyses: currentAnalyses
            )
            let currentVIP4Context = vip4MatchContext(
                for: config,
                analyses: currentAnalyses
            )
            let requiredDataMissing = (config.requiresSPData && currentSPs == nil)
                || (config.requiresStrictProbabilityData && currentProbabilities == nil)
                || (comprehensiveProfile?.requiresSPData == true && currentSPs == nil)
                || (comprehensiveProfile?.requiresProbabilityData == true && currentProbabilities == nil)
                || (protectedHistoryProfile?.requiresSPData == true && currentSPs == nil)
                || (protectedHistoryProfile?.requiresProbabilityData == true && currentProbabilities == nil)
                || (SequenceFilterEngine.usesVIP3Model(
                    threshold: config.universal247ToleranceThreshold
                ) && currentVIP3Context == nil)
                || (SequenceFilterEngine.usesVIP4Model(
                    threshold: config.universal247ToleranceThreshold
                ) && currentVIP4Context == nil)
            if requiredDataMissing {
                NSLog("GLOBAL-GENERATE stage=required-data-missing analyses=%ld", currentAnalyses.count)
                result = nil
                errorMessage = "当前已开启赔率/概率条件，但完整数据不可用，已停止生成；不会使用关闭条件的离线兜底配置。"
                return
            }
            let marketShares = activeConfig.matchNumbers.map { number in
                currentAnalyses.first { Int($0.match.matchNumber) == Int(number) }?.match.marketBettingShares ?? []
            }
            let applyRelationships = shouldApplyRelationshipCondition(
                for: activeConfig,
                analyses: currentAnalyses
            )
            let calculated = await Task.detached(priority: .userInitiated) {
                SequenceFilterEngine.calculate(
                    activeConfig,
                    previousContext: previous.map {
                        PreviousResultContext(
                            logic: $0.logic,
                            outcomes: $0.outcomes,
                            hitFlag: previousAnalysis?.hitFlag ?? 0
                        )
                    },
                    currentOutcomeProbabilities: currentProbabilities,
                    currentOutcomeSPs: currentSPs,
                    vip4Context: currentVIP4Context,
                    vip3Context: currentVIP3Context,
                    currentMarketBettingShares: marketShares,
                    applyPoissonRelationshipCondition: applyRelationships,
                    comprehensiveAnalysisProfile: activeProfile,
                    comprehensiveAnalysisToleranceRange: comprehensiveTolerance,
                    protectedHistoryProfile: activeProtectedHistoryProfile,
                    protectedHistoryToleranceRange: protectedHistoryTolerance,
                    protectedHistoryBetCap: protectedHistoryCap,
                    protectedPrizeOutcomePrefixes: protectedPrizePrefixes,
                    captureQueryStages: true
                )
            }.value
            NSLog("GLOBAL-GENERATE stage=engine-ready bets=%ld rows=%ld", calculated.finalBetCount, calculated.displayResultLines.count)
            if let failure = calculated.maximum105FailureMessage {
                result = nil
                errorMessage = failure
                return
            }
            if overallOddsForecastGateEnabled && (!svvvSelected || svip10Enabled),
               let currentSPs,
               let forecast = SequenceFilterEngine.overallOddsForecast(
                   bets: calculated.uniqueExpandedBets,
                   customOdds: currentSPs
               ) {
                let weakIndex = forecast.weakestPosition - 1
                let weakMatch = config.matchNumbers.indices.contains(weakIndex)
                    ? config.matchNumbers[weakIndex]
                    : "第\(forecast.weakestPosition)场"
                if forecast.isLow {
                    result = nil
                    errorMessage = "整体赔率预测偏低：最终组合的六场自定义赔率乘积中位数为\(String(format: "%.2f", forecast.medianProduct))，低于500，本次未生成TXT。建议更换场次\(weakMatch)（当前组合选中赔率中位数\(String(format: "%.2f", forecast.weakestMedianSelectedOdd))），优先选择让球后胜平负三项赔率更均衡的比赛，然后重新获取ABCD。"
                    abcdSourceMessage = "整体赔率未通过生成门禁；未保存TXT或查询记录。"
                    return
                }
                abcdSourceMessage = "整体赔率预测正常：六场自定义赔率乘积中位数\(String(format: "%.2f", forecast.medianProduct))，已继续生成。"
            }
            result = calculated
            currentTXTGenerationIssue = beijingSingleIssueInput.trimmingCharacters(in: .whitespacesAndNewlines)
            currentTXTPrizeCaptureTask?.cancel()
            currentTXTPrizeGenerationID = calculated.generationID
            currentTXTPrizeSnapshots = TXTQuerySPSnapshot.capture(currentAnalyses.map(\.match))
            let prizeIssue = currentTXTGenerationIssue
            let prizeNumbers = Array((config.matchNumbers + config.extraMatches.map(\.matchNumber)).prefix(7))
            // Capture published reference SP when this TXT is generated, including
            // the seventh match. Network work does not delay TXT display or filtering.
            currentTXTPrizeCaptureTask = Task {
                do {
                    let fetched = try await FiveHundredBeijingSingleClient.fetchLiveMatches(
                        issue: prizeIssue, matchNumbers: prizeNumbers
                    )
                    try Task.checkCancellation()
                    return TXTQuerySPSnapshot.capture(fetched)
                } catch { return [] }
            }

            currentTXTQueryMessage = nil
            currentTXTQueryIsHit = nil
            archiveGeneratedResultLocally(calculated)
            NSLog("GLOBAL-GENERATE stage=locally-archived bets=%ld", calculated.finalBetCount)
            previousAnalysisMessage = previous.map {
                "\($0.logicSource)。\(previousAnalysis?.message ?? "")"
            } ?? "本次未输入上一次5场，过滤分析未使用历史赛果。"
            savePreviousRunSnapshot(
                from: calculated,
                analyzedPreviousOutcomes: previous?.outcomes,
                analyzedPreviousLogic: previous?.logic,
                analyzedPreviousHit: previousAnalysis?.hitFlag
            )
        } catch {
            errorMessage = error.localizedDescription
        }
    }

    private var abcdInputKey: String {
        beijingSingleIssueInput + "|" + currentCalculationMatchNumbers.joined(separator: ",") + "|" + abcdSource.rawValue
    }

    private var hasValidMainNumbers: Bool {
        let numbers = currentCalculationMatchNumbers.compactMap(Int.init)
        let basicValidity = numbers.count == currentCalculationLogicCount
            && numbers.allSatisfy { $0 > 0 }
            && Set(numbers).count == currentCalculationLogicCount
        guard basicValidity else { return false }
        guard usesVIP6AutomaticMatchSelection, !hasManualMatchSelection, let first = numbers.first else { return true }
        return numbers.dropFirst().allSatisfy { $0 > first }
    }

    private var hasCurrentABCD: Bool {
        abcdAttemptedKey == abcdInputKey && normalizedCurrentABCD(logicInput) != nil
    }

    /// 首页生成只接受当前场次已取得或已缓存的真实ABCD。
    /// 历史版本曾用AAAAA占位，即使它还留在界面或缓存中也不允许生成。
    private var currentABCDForGeneration: String? {
        if usesVIP6AutomaticMatchSelection {
            return hasCurrentABCD ? normalizedCurrentABCD(logicInput) : nil
        }
        let entered = hasCurrentABCD ? normalizedABCD(logicInput) : nil
        return [entered, cachedCurrentABCDForMVP()]
            .compactMap { $0 }
            .first { $0 != "AAAAA" }
    }

    private var hasAutomaticallyFetchedCurrentABCD: Bool {
        automaticallyFetchedABCDKey == abcdInputKey
            && normalizedCurrentABCD(logicInput) != nil
    }

    /// 启动时只恢复本地ABCD，不自动联网。联网更新由用户点击按钮触发。
    private func restoreCurrentABCDFromCache() {
        let issue = beijingSingleIssueInput.trimmingCharacters(in: .whitespacesAndNewlines)
        let numbers = currentCalculationMatchNumbers
        guard !issue.isEmpty, numbers.count == currentCalculationLogicCount else { return }

        let logic = strictlyCachedCurrentABCD(issue: issue, matchNumbers: numbers)
        guard let logic else {
            automaticallyFetchedABCDKey = nil
            abcdSourceMessage = "尚无当前期号和场次的ABCD缓存；需要时点击获取。"
            return
        }
        logicInput = logic
        abcdAttemptedKey = abcdInputKey
        automaticallyFetchedABCDKey = abcdInputKey
        abcdSourceMessage = "ABCD已从本地缓存恢复 · 第\(issue)期 · 场次\(numbers.joined(separator: ","))"
        NSLog("VIP7 ABCD restored issue=%@ matches=%@ logic=%@", issue, numbers.joined(separator: ","), logic)
        isLoadingGoalModel = false
    }

    private func loadGoalModelRecommendations() {
        if hasManualMatchSelection {
            Task { await fetchABCDForCurrentInput(debounce: false) }
            return
        }
        if usesVIP6AutomaticMatchSelection {
            vip6AutoSelectionTask?.cancel()
            guard let first = Int(automaticMatchSearchStart),
                  first > 0 else {
                vip6AutoSelectionMessage = "请输入有效的第一场场次号。"
                return
            }
            if selectedConditionVersionID == "svip11-breakpoint-selection" || usesSVIP10AutomaticDoublePair || usesStructuredMatchSelection {
                scheduleVIP6AutomaticMatchSelection()
                return
            }
            // 手动点击只重取界面上从第一场连续累加出的当前六场，不再依赖
            // 整期自动选择器。fetchABCDForCurrentInput 内部会依次尝试
            // 500比分页、500交易页和澳客。
            syncSequentialMatchInputs()
            vip6AutoSelectionMessage = "正在重新获取当前连续6场ABCD…"
            NSLog("VIP7 direct ABCD retry issue=%@ first=%d", beijingSingleIssueInput, first)
            vip6AutoSelectionTask = Task { @MainActor in
                await fetchABCDForCurrentInput(debounce: false)
            }
            return
        }
        Task { await fetchABCDForCurrentInput(debounce: false) }
    }

    /// 仅为完赛后核验补取真实比分。该数组不会传入选场器或ABCD模型。
    @MainActor
    private func loadVIP6CompletedResultVerification() async {
        guard usesVIP6AutomaticMatchSelection,
              hasValidMainNumbers,
              normalizedCurrentABCD(logicInput) != nil,
              !isLoadingVIP6ResultVerification else { return }
        let requestedIssue = beijingSingleIssueInput.trimmingCharacters(in: .whitespacesAndNewlines)
        let requestedNumbers = currentCalculationMatchNumbers
        let requestedKey = abcdInputKey
        isLoadingVIP6ResultVerification = true
        vip6ResultVerificationMessage = "正在读取真实比分；该数据只用于过滤核验。"
        defer { isLoadingVIP6ResultVerification = false }
        do {
            let issue: String
            if requestedIssue.count == 5, requestedIssue.allSatisfy(\.isNumber) {
                issue = requestedIssue
            } else {
                issue = try await resolveCurrentIssue()
            }
            let matches = try await FiveHundredBeijingSingleClient.fetchScorePageOdds(
                issue: issue,
                matchNumbers: requestedNumbers
            )
            guard requestedKey == abcdInputKey,
                  requestedNumbers == currentCalculationMatchNumbers else { return }
            vip6SelectedMatchesWithResults = matches
            let completed = matches.filter { $0.handicapOutcome != nil }.count
            vip6ResultVerificationMessage = completed == currentCalculationLogicCount
                ? "已取得6/6场真实赛果，已按VIP7当前启用条件完成核验。"
                : "已取得\(completed)/\(currentCalculationLogicCount)场真实赛果；未齐前不判定过关。"
        } catch {
            guard requestedKey == abcdInputKey else { return }
            vip6ResultVerificationMessage = "真实核验暂不可用：\(error.localizedDescription)。本次不会猜测赛果或输出过关结论。"
        }
    }

    @MainActor
    private func fetchABCDForCurrentInput(debounce: Bool) async {
        let key = abcdInputKey
        let requestedIssue = beijingSingleIssueInput.trimmingCharacters(in: .whitespacesAndNewlines)
        let requestedNumbers = currentCalculationMatchNumbers
        let fallbackLogic = (abcdAttemptedKey == key ? normalizedCurrentABCD(logicInput) : nil)
            ?? strictlyCachedCurrentABCD(issue: requestedIssue, matchNumbers: requestedNumbers)
        let requestID = UUID()
        abcdRequestID = requestID
        logicInput = fallbackLogic ?? ""
        abcdAttemptedKey = fallbackLogic == nil ? nil : key
        automaticallyFetchedABCDKey = nil
        goalModelErrorMessage = nil
        goalModelAnalyses = []
        result = nil
        isLoadingGoalModel = false
        guard hasValidMainNumbers else {
            abcdSourceMessage = "请填齐\(currentCalculationLogicCount)个不同的正整数场次号。"
            return
        }
        isLoadingGoalModel = true
        abcdSourceMessage = "正在按期号和场次获取数据并生成ABCD…"
        let numbers = currentCalculationMatchNumbers
        let source = abcdSource
        NSLog("ABCD request: %@", key)
        defer {
            if abcdRequestID == requestID { isLoadingGoalModel = false }
        }
        do {
            if debounce {
                try await Task.sleep(nanoseconds: 800_000_000)
                guard key == abcdInputKey, abcdRequestID == requestID else { return }
            }
            let issue = try await resolveCurrentIssue()
            let analyses: [GoalModelAnalysis]
            let recommendation: String
            let fetchedSource: String
            if usesConvertedOddsVIPABCD {
                let matches = try await FiveHundredBeijingSingleClient.fetchScorePageOdds(
                    issue: issue,
                    matchNumbers: numbers
                )
                guard let convertedLogic = HandicapOddsComparisonTableMatrix.logic(
                    matchNumbers: numbers,
                    matches: matches
                ) else { throw GoalModelError.invalidResponse }
                recommendation = convertedLogic
                analyses = await Task.detached(priority: .userInitiated) {
                    matches.compactMap { try? PoissonGoalModel.analyze($0) }
                }.value
                fetchedSource = "500比分页/交易页/澳客自动回退→项目对照表"
                if usesVIP6AutomaticMatchSelection,
                   let first = numbers.first.flatMap(Int.init) {
                    let usesFrontFiveM = ["svip11-breakpoint-selection", "svip10-frozen-160", "svip9-dual-s", "svip8-current-three", "svip6-three-condition", "svip5-current-snapshot", "svip4-permutation-lowest-odds", "svip1-xs-current", "svip2-all-basic", "svip3-current-no-four", "vip9-front-five-m3-6", "vip10-front-five-real-sum", "vip11-front-five-mapped-sum", "vip12-probability-bottom20", "vip14-s15-18", "vip15-s15-20-single-no-four", "vip16-probability-top200"]
                        .contains(selectedConditionVersionID)
            let displacementRange = ["svip2-all-basic", "svip3-current-no-four"].contains(selectedConditionVersionID) ? 2...6 : 3...6
                    if let vipRecommendation = VIP6MatchRecommender.recommendConsecutive(
                        firstMatchNumber: first,
                        matches: matches,
                        displacementMatchCount: usesFrontFiveM ? 5 : 6,
                        displacementRange: usesFrontFiveM ? displacementRange : 4...8
                    ) {
                        noFourPositionInput = String(vipRecommendation.noFourPosition)
                        if selectedConditionVersionID == "svip3-current-no-four" {
                            secondNoFourPositionInput = String(vipRecommendation.secondLowestNoFourPosition)
                        }
                    }
                    vip6SelectedMatchesWithResults = matches
                    conditionHandicaps = Dictionary(uniqueKeysWithValues: matches.compactMap { match in
                        guard let handicap = match.handicap else { return nil }
                        return (match.matchNumber, handicap)
                    })
                }
            } else {
                let fetched = try await MultiSourceABCDClient.fetch(
                    issue: issue,
                    matchNumbers: numbers,
                    source: source
                )
                analyses = fetched.analyses
                recommendation = fetched.analyses.map { $0.recommendedLogic.displayName }.joined()
                fetchedSource = fetched.source
            }
            try Task.checkCancellation()
            guard key == abcdInputKey, abcdRequestID == requestID else { return }
            guard recommendation.count == currentCalculationLogicCount else {
                throw GoalModelError.invalidMatchNumbers
            }
            NSLog("ABCD success: %@ %@", fetchedSource, recommendation)
            goalModelAnalyses = analyses
            logicInput = recommendation
            abcdAttemptedKey = key
            automaticallyFetchedABCDKey = key
            abcdSourceMessage = "ABCD已获取 · 来源：\(fetchedSource) · 第\(issue)期 · 场次\(numbers.joined(separator: ","))"
            // 获取ABCD不改写用户已经保存的筛选条件。
            conditionRecommendationMessage = "ABCD已更新；保留你保存的筛选条件。"
            persistCurrentABCD(issue: issue, matchNumbers: numbers, logic: recommendation)
            saveGoalModelRecommendation(issue: issue, matchNumbers: numbers, logic: recommendation)
        } catch {
            guard !Task.isCancelled, key == abcdInputKey, abcdRequestID == requestID else { return }
            automaticallyFetchedABCDKey = nil
            if let fallbackLogic {
                logicInput = fallbackLogic
                abcdAttemptedKey = key
                abcdSourceMessage = "实时刷新失败，已恢复同期号＋同场次缓存ABCD \(fallbackLogic)，可以继续生成。"
            } else {
                logicInput = ""
                abcdAttemptedKey = key
                abcdSourceMessage = "三个真实数据入口均未取全；请核对期号和第一场，或手动输入本期\(currentCalculationLogicCount)位ABCD。"
            }
            goalModelErrorMessage = error.localizedDescription
            NSLog("ABCD failure: %@", error.localizedDescription)
        }
    }

    /// 只允许“同期号＋完全相同场次顺序”的缓存参与当前生成。
    /// 六场模式必须命中完整六场，绝不把旧的前五场ABCD拼接成六位。
    private func strictlyCachedCurrentABCD(issue: String, matchNumbers: [String]) -> String? {
        let cleanIssue = issue.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanNumbers = matchNumbers.map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
        guard !cleanIssue.isEmpty,
              cleanNumbers.count == currentCalculationLogicCount else { return nil }
        let persisted = UserDefaults.standard.dictionary(forKey: globalABCDCacheStorageKey)
            as? [String: String] ?? [:]
        let cacheKey = TXTQueryStatisticsCalculator.uniqueKey(
            issue: cleanIssue,
            matchNumbers: cleanNumbers
        )
        return normalizedCurrentABCD(persisted[cacheKey])
            ?? recommendationHistory.reversed().first(where: { saved in
                saved.issue.trimmingCharacters(in: .whitespacesAndNewlines) == cleanIssue
                    && saved.matchNumbers.compactMap(Int.init) == cleanNumbers.compactMap(Int.init)
            }).flatMap { normalizedCurrentABCD($0.logic) }
    }

    private func persistCurrentABCD(issue: String, matchNumbers: [String], logic: String) {
        guard let normalized = normalizedCurrentABCD(logic) else { return }
        let cacheKey = TXTQueryStatisticsCalculator.uniqueKey(
            issue: issue.trimmingCharacters(in: .whitespacesAndNewlines),
            matchNumbers: matchNumbers.map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
        )
        var persisted = UserDefaults.standard.dictionary(forKey: globalABCDCacheStorageKey)
            as? [String: String] ?? [:]
        persisted[cacheKey] = normalized
        UserDefaults.standard.set(persisted, forKey: globalABCDCacheStorageKey)
        UserDefaults.standard.synchronize()
    }

    private func recommendFromABCDButton() {
        let cleaned = logicInput.lowercased().filter { "abcd".contains($0) }
        if cleaned.count == 5 {
            applyRecommendedConditionsFromManualLogic(cleaned)
        } else {
            loadGoalModelRecommendations()
        }
    }

    private func loadPreviousResultFromFiveHundred() async throws -> (
        outcomes: [Int],
        logic: [LogicMapping],
        logicSource: String
    ) {
        let numbers = previousMatchNumbers
        guard numbers.count == 5,
              numbers.allSatisfy({ !$0.isEmpty && $0.allSatisfy(\.isNumber) }),
              Set(numbers.compactMap(Int.init)).count == 5 else {
            throw PreviousResultInputError.invalidMatchNumbers
        }
        let requestedIssue = previousIssueInput.trimmingCharacters(in: .whitespacesAndNewlines)
        let issue: String
        if !requestedIssue.isEmpty {
            let savedAnchor = UserDefaults.standard.string(forKey: goalModelIssueStorageKey) ?? beijingSingleIssueInput
            issue = try await FiveHundredBeijingSingleClient.resolveIssue(
                input: requestedIssue,
                anchorIssue: savedAnchor
            )
        } else if let saved = matchedPreviousRecommendation {
            issue = saved.issue
        } else {
            issue = try await resolveCurrentIssue()
        }
        let saved = recommendationHistory.reversed().first { record in
            record.issue == issue
                && Set(record.matchNumbers.compactMap(Int.init)) == Set(numbers.compactMap(Int.init))
        }
        let matches = try await fetchCompletedHandicapOutcomes(
            issue: issue,
            matchNumbers: numbers
        ).matches
        let outcomes = try matches.map { match -> Int in
            guard let outcome = match.handicapOutcome
                    ?? (isPostponedOverTwelveHours(match) ? 1 : nil) else {
                throw GoalModelError.resultUnavailable(match.matchNumber)
            }
            return outcome
        }
        if let saved {
            let savedLogic = saved.logic.lowercased().compactMap { LogicMapping(rawValue: String($0)) }
            guard savedLogic.count == 5 else { throw PreviousResultInputError.noSavedLogic }
            let orderedLogic: [LogicMapping] = try numbers.map { number in
                guard let index = saved.matchNumbers.firstIndex(where: { Int($0) == Int(number) }) else {
                    throw PreviousResultInputError.noSavedLogic
                }
                return savedLogic[index]
            }
            return (outcomes, orderedLogic, "ABCD采用已保存记录")
        }

        let recalculated = try await Task.detached(priority: .userInitiated) {
            try matches.map(PoissonGoalModel.analyze)
        }.value
        let logic = recalculated.map(\.recommendedLogic)
        let logicText = logic.map(\.displayName).joined()
        saveGoalModelRecommendation(issue: issue, matchNumbers: numbers, logic: logicText)
        return (outcomes, logic, "ABCD由500实时赔率重新计算：\(logicText)")
    }

    private var hasValidPreviousMatchNumbers: Bool {
        let numbers = previousMatchNumbers.compactMap(Int.init)
        return numbers.count == 5 && numbers.allSatisfy { $0 > 0 } && Set(numbers).count == 5
    }

    private var hasValidPreviousQuery: Bool {
        hasValidPreviousMatchNumbers
            && !previousIssueInput.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    private func analyzeMissedResultAutomatically() {
        missedResultAnalysisMessage = nil
        isAnalyzingMissedResult = true
        Task {
            defer { isAnalyzingMissedResult = false }
            do {
                let loaded = try await loadPreviousResultFromFiveHundred()
                let inputNumbers = previousMatchNumbers
                let logicText = loaded.logic.map(\.displayName).joined()
                let outcomeText = loaded.outcomes.map(String.init).joined()
                let savedConfig = lastRunSnapshot.flatMap {
                    try? FilterConfig.parse($0.normalizedInput)
                }
                let isExactSavedRun = savedConfig.map {
                    Set($0.matchNumbers.compactMap(Int.init)) == Set(inputNumbers.compactMap(Int.init))
                } ?? false

                let analysisConfig: FilterConfig
                let orderedOutcomes: [Int]
                if let savedConfig, isExactSavedRun {
                    let indices = savedConfig.matchNumbers.compactMap { savedNumber in
                        inputNumbers.firstIndex { Int($0) == Int(savedNumber) }
                    }
                    guard indices.count == 5 else { throw PreviousResultInputError.invalidMatchNumbers }
                    orderedOutcomes = indices.map { loaded.outcomes[$0] }
                    analysisConfig = replacingLogic(
                        in: savedConfig,
                        with: indices.map { loaded.logic[$0] }
                    )
                } else {
                    orderedOutcomes = loaded.outcomes
                    analysisConfig = replacingLogic(
                        in: savedConfig ?? FilterConfig.current,
                        with: loaded.logic
                    )
                }

                let detail = SequenceFilterEngine.missedOutcomeAnalysis(
                    outcomes: orderedOutcomes,
                    config: analysisConfig,
                    savedKeptOutcomes: isExactSavedRun
                        ? Set(lastRunSnapshot?.keptOutcomes ?? [])
                        : nil
                )
                let recordNote = isExactSavedRun
                    ? "已匹配当时保存的筛选记录。"
                    : "未找到这5场对应的完整筛选记录；仅分析可确认的基础条件和Q阶段。"
                let schemeText = savedSchemeComparison(
                    issue: previousIssueInput,
                    matchNumbers: inputNumbers,
                    outcomes: loaded.outcomes
                )
                missedResultAnalysisMessage = "\(loaded.logicSource)\n场次：\(inputNumbers.joined(separator: ","))\nABCD：\(logicText)\n实际彩果：\(outcomeText)\n\(recordNote)\n\(detail)\(schemeText)"
            } catch {
                missedResultAnalysisMessage = "分析失败：\(error.localizedDescription)"
            }
        }
    }

    private func analyzeManualPreviousResult() {
        missedResultAnalysisMessage = nil
        let rawOutcome = manualPreviousOutcomeInput.trimmingCharacters(in: .whitespacesAndNewlines)
        let compactOutcome = rawOutcome
            .replacingOccurrences(of: " ", with: "")
            .replacingOccurrences(of: ",", with: "")
            .replacingOccurrences(of: "，", with: "")
            .replacingOccurrences(of: "/", with: "")
        let outcomes = compactOutcome.compactMap { Int(String($0)) }
        guard compactOutcome.count == 5,
              outcomes.count == 5,
              outcomes.allSatisfy({ [3, 1, 0].contains($0) }) else {
            missedResultAnalysisMessage = "手动查询失败：请输入正好5位3/1/0赛果，例如31013。"
            return
        }
        let numbers = previousMatchNumbers
        guard hasValidPreviousMatchNumbers else {
            missedResultAnalysisMessage = "手动查询失败：请先输入5个有效且不重复的场次号。"
            return
        }

        let typedLogic = manualPreviousLogicInput
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .uppercased()
            .filter { "ABCD".contains($0) }
        let logicInInputOrder: [LogicMapping]
        let logicSource: String
        if !manualPreviousLogicInput.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            guard typedLogic.count == 5 else {
                missedResultAnalysisMessage = "手动查询失败：ABCD必须正好是5个A/B/C/D字符。"
                return
            }
            logicInInputOrder = typedLogic.lowercased().compactMap { LogicMapping(rawValue: String($0)) }
            logicSource = "手动ABCD"
        } else if let saved = matchedPreviousRecommendation {
            let savedLogic = saved.logic.lowercased().compactMap { LogicMapping(rawValue: String($0)) }
            guard savedLogic.count == 5 else {
                missedResultAnalysisMessage = "手动查询失败：已保存ABCD格式无效。"
                return
            }
            logicInInputOrder = numbers.compactMap { number in
                saved.matchNumbers.firstIndex(where: { Int($0) == Int(number) }).map { savedLogic[$0] }
            }
            guard logicInInputOrder.count == 5 else {
                missedResultAnalysisMessage = "手动查询失败：历史ABCD与当前场次无法一一对应。"
                return
            }
            logicSource = "已保存ABCD"
        } else {
            missedResultAnalysisMessage = "手动查询失败：未找到同期号＋同场次ABCD，请在ABCD输入框手动填写5位。"
            return
        }

        let savedConfig = lastRunSnapshot.flatMap { try? FilterConfig.parse($0.normalizedInput) }
        let isExactSavedRun = savedConfig.map {
            Set($0.matchNumbers.compactMap(Int.init)) == Set(numbers.compactMap(Int.init))
        } ?? false
        let baseConfig = savedConfig ?? currentPrizeConfig ?? FilterConfig.current

        let analyzedOutcomes: [Int]
        let analyzedLogic: [LogicMapping]
        if let savedConfig, isExactSavedRun {
            let indices = savedConfig.matchNumbers.compactMap { savedNumber in
                numbers.firstIndex { Int($0) == Int(savedNumber) }
            }
            guard indices.count == 5 else {
                missedResultAnalysisMessage = "手动查询失败：保存快照场次顺序无法对应。"
                return
            }
            analyzedOutcomes = indices.map { outcomes[$0] }
            analyzedLogic = indices.map { logicInInputOrder[$0] }
        } else {
            analyzedOutcomes = outcomes
            analyzedLogic = logicInInputOrder
        }

        let analysisConfig = replacingLogic(in: baseConfig, with: analyzedLogic)
        let savedKept = isExactSavedRun ? Set(lastRunSnapshot?.keptOutcomes ?? []) : nil
        let detail = SequenceFilterEngine.missedOutcomeAnalysis(
            outcomes: analyzedOutcomes,
            config: analysisConfig,
            savedKeptOutcomes: savedKept
        )
        let compactAnalyzed = analyzedOutcomes.map(String.init).joined()
        let exactHit = savedKept?.contains(compactAnalyzed)
        let baseFailed = !SequenceFilterEngine.baseFilterFailureReasons(
            for: analyzedOutcomes,
            config: analysisConfig
        ).isEmpty
        let qOrLaterFailed = detail.contains("被删除") || detail.contains("未在当时保留结果中")
        let headline: String
        if let exactHit {
            headline = exactHit ? "命中：是（已核对当时生成快照）" : "命中：否"
        } else if !baseFailed && !qOrLaterFailed {
            headline = "前5场判定：通过（无当时快照，第6/7场仍需另行核对）"
        } else {
            headline = "前5场判定：未通过"
        }
        missedResultAnalysisMessage = "\(headline)\n场次：\(numbers.joined(separator: ","))\nABCD：\(analyzedLogic.map(\.displayName).joined())（\(logicSource)）\n手动赛果：\(outcomes.map(String.init).joined())\n\(detail)"
    }

    /// 查询页手动赛果：只填第1场，后5场自动递增。
    /// 这里只做TXT精确命中核对；全条件枚举由Mac缓存提供。
    @MainActor
    private func queryFinalityStatus(
        issue: String,
        matchNumbers: [String]
    ) async -> (allowed: Bool, message: String, outcomes: [Int]?) {
        do {
            let anchor = UserDefaults.standard.string(forKey: goalModelIssueStorageKey)
                ?? beijingSingleIssueInput
            let resolvedIssue = try await FiveHundredBeijingSingleClient.resolveIssue(
                input: issue,
                anchorIssue: anchor
            )
            let numbers = Array(matchNumbers.prefix(6))
            let fetched = try await fetchQueryMatchesWithScoreboardFallback(
                issue: resolvedIssue,
                matchNumbers: numbers
            )
            let matches = fetched.matches
            guard QueryFinalityGate.permitsResult(
                matches: matches,
                expectedCount: numbers.count
            ) else {
                let unfinished = matches.filter {
                    !QueryFinalityGate.isFinallyEnded($0) && !$0.isPostponedOver12Hours
                }.map(\.matchNumber)
                if matches.count != numbers.count {
                    return (false, "场次数据未取齐，暂不返回查询结果。", nil)
                }
                if !unfinished.isEmpty {
                    return (false, "场次\(unfinished.joined(separator: "、"))未最终结束；只有明确延期超过12小时才可按1计算，当前不出查询结果。", nil)
                }
                return (false, "比赛已结束但让球赛果未完整发布，暂不返回查询结果。", nil)
            }
            let postponed = matches.filter(\.isPostponedOver12Hours).map(\.matchNumber)
            let note = postponed.isEmpty
                ? "六场均已最终结束。"
                : "终局门禁已通过；场次\(postponed.joined(separator: "、"))延期超过12小时，按1计算。"
            return (true, note, matches.compactMap(QueryFinalityGate.resolvedOutcome))
        } catch {
            return (false, "暂时无法确认六场是否最终结束，不返回查询结果：\(error.localizedDescription)", nil)
        }
    }

    /// 直接检查当前内存中的全量TXT，避免旧缓存或其他期号的TXT造成假命中。
    @MainActor
    private func queryCurrentTXT(reasonsOnly: Bool = false) async {
        guard !isQueryingCurrentTXT else { return }
        isQueryingCurrentTXT = true
        defer { isQueryingCurrentTXT = false }
        currentTXTQueryShowsFailureReasons = reasonsOnly
        currentTXTQueryMessage = "正在核对当前TXT…"
        currentTXTQueryIsHit = nil
        isShowingCurrentTXTQueryResult = true
        guard let result else {
            if reasonsOnly, let errorMessage, !errorMessage.isEmpty {
                currentTXTQueryMessage = "当前计算未生成TXT，已有提示：\n\(errorMessage)\n\n尚无最终TXT，不能判断六场是否过关。"
            } else {
                currentTXTQueryMessage = "查询结果：无法判定。\n原因：尚未生成当前TXT，请先点全局生成。"
            }
            return
        }
        let issue = beijingSingleIssueInput.trimmingCharacters(in: .whitespacesAndNewlines)
        guard issue == currentTXTGenerationIssue,
              let currentConfig = try? FilterConfig.parse(generatedInput),
              result.matchesGenerationRequest(currentConfig) else {
            currentTXTQueryMessage = "查询结果：无法判定。\n原因：期号、场次或条件已改变；请重新生成TXT，不能复用旧TXT。"
            return
        }
        let numbers = Array((result.config.matchNumbers + result.config.extraMatches.map(\.matchNumber)).prefix(6))
        guard numbers.count == 6 else {
            currentTXTQueryMessage = "查询结果：无法判定。\n原因：当前TXT不足6场，无法核对六串。"
            return
        }

        let compact = currentTXTManualOutcomes.filter { !$0.isWhitespace && $0 != "," && $0 != "，" && $0 != "/" }
        let outcomes: [Int]
        let source: String
        if compact.isEmpty {
            let finality = await queryFinalityStatus(issue: issue, matchNumbers: numbers)
            guard finality.allowed, let resolved = finality.outcomes, resolved.count == 6 else {
                currentTXTQueryMessage = "查询结果：暂不能判定。\n原因：\(finality.message)"
                return
            }
            outcomes = resolved
            source = "真实终场赛果"
        } else {
            let entered = compact.compactMap { Int(String($0)) }
            guard compact.count == 6, entered.count == 6,
                  entered.allSatisfy({ [3, 1, 0].contains($0) }) else {
                currentTXTQueryMessage = "查询结果：无法判定。\n原因：请正好输入6位3/1/0赛果，例如310130；或清空后查真实赛果。"
                return
            }
            outcomes = entered
            source = "手动模拟赛果"
        }

        guard inputExperienceMode == "v1",
              self.result?.generationID == result.generationID,
              beijingSingleIssueInput.trimmingCharacters(in: .whitespacesAndNewlines) == issue,
              currentTXTGenerationIssue == issue,
              result.matchesGenerationRequest(try? FilterConfig.parse(generatedInput)),
              currentTXTManualOutcomes.filter({ !$0.isWhitespace && $0 != "," && $0 != "，" && $0 != "/" }) == compact else {
            currentTXTQueryIsHit = nil
            currentTXTQueryMessage = "查询结果：无法判定。期号、条件或TXT在查询期间已改变，请重新查询。"
            return
        }
        let target = Array(outcomes.prefix(6))
        let head = "第\(issue)期 · 场次\(numbers.joined(separator: "、")) · \(source)\(target.map(String.init).joined())"
        if reasonsOnly {
            let diagnosis = await Task.detached(priority: .userInitiated) {
                result.inputFailureDiagnosis(for: target)
            }.value
            guard inputExperienceMode == "v1",
                  self.result?.generationID == result.generationID,
                  currentTXTGenerationIssue == issue,
                  beijingSingleIssueInput.trimmingCharacters(in: .whitespacesAndNewlines) == issue,
                  result.matchesGenerationRequest(try? FilterConfig.parse(generatedInput)),
                  currentTXTManualOutcomes.filter({ !$0.isWhitespace && $0 != "," && $0 != "，" && $0 != "/" }) == compact else {
                currentTXTQueryMessage = "输入、条件或TXT在分析期间已改变，请重新分析。"
                return
            }
            currentTXTQueryIsHit = diagnosis.isHit
            currentTXTQueryMessage = head + "\n\n" + diagnosis.text
            return
        }
        let bets = expandedSharedTXTBets(result)
        let hit = bets.contains { $0.count >= 6 && Array($0.prefix(6)) == target }
        currentTXTQueryIsHit = hit
        let attribution = result.queryAttribution(for: target)
        if hit || attribution == .hit {
            currentTXTQueryIsHit = true
            let multiplier = validBetMultiplier ?? 1
            let matchedBets = bets.filter { $0.count >= 6 && Array($0.prefix(6)) == target }
            let seventhOptions = Array(Set(matchedBets.compactMap { $0.count >= 7 ? $0[6] : nil }))
            let allNumbers = Array((result.config.matchNumbers + result.config.extraMatches.map(\.matchNumber)).prefix(7))
            let baseMessage = "查询结果：前6场命中。\n\(head)\n当前全量TXT共\(bets.count)注。"
            currentTXTQueryMessage = baseMessage + "\n正在计算六场、七场奖金…"
            let prizeText = await currentTXTPrizeSummary(
                issue: issue, generationID: result.generationID, matchNumbers: allNumbers,
                firstSixOutcomes: target, seventhOptions: seventhOptions,
                isSimulation: !compact.isEmpty, multiplier: multiplier
            )
            guard self.result?.generationID == result.generationID,
                  currentTXTGenerationIssue == issue,
                  beijingSingleIssueInput.trimmingCharacters(in: .whitespacesAndNewlines) == issue,
                  result.matchesGenerationRequest(try? FilterConfig.parse(generatedInput)),
                  currentTXTManualOutcomes.filter({ !$0.isWhitespace && $0 != "," && $0 != "，" && $0 != "/" }) == compact,
                  (validBetMultiplier ?? 1) == multiplier else {
                currentTXTQueryIsHit = nil
                currentTXTQueryMessage = "查询期间TXT、赛果、条件或倍数已改变，请重新查询。"
                return
            }
            currentTXTQueryMessage = baseMessage + "\n\n" + prizeText
            return
        }

        switch attribution {
        case .hit:
            break // Handled together with exact TXT hits above.
        case .excluded(let reason):
            let failures = result.queryConditionFailureReasons(for: target)
            let comparison = failures.isEmpty ? "" : "\n已开启条件核对（仅列失败或数据不足项）：\n" + failures.enumerated()
                .map { "\($0.offset + 1). \($0.element)" }.joined(separator: "\n")
            currentTXTQueryMessage = "查询结果：前6场未命中。\n\(head)\n当前全量TXT共\(bets.count)注。\(comparison)\n实际淘汰阶段：\(reason)\n归因依据：本次生成时的条件、自定义赔率及逐阶段实际保留组合。"
        case .unavailable(let reason):
            currentTXTQueryMessage = "查询结果：前6场未命中。\n\(head)\n归因记录不可用：\(reason)"
        }
    }

    @MainActor
    private func queryVIPInputFailureReasons() async {
        guard !isQueryingCurrentTXT else { return }
        isQueryingCurrentTXT = true
        defer { isQueryingCurrentTXT = false }
        currentTXTQueryShowsFailureReasons = true
        currentTXTQueryIsHit = nil
        currentTXTQueryMessage = "正在核对当前选场的终局赛果…"
        isShowingCurrentTXTQueryResult = true
        guard let selection = vip1Selection else {
            currentTXTQueryMessage = vip1SelectionMessage.map {
                "当前计算未生成选场，已有提示：\n\($0)\n\n尚无最终选场，不能判断六场是否过关。"
            } ?? "暂不能分析：请先生成当前VIP选场。"
            return
        }
        let token = vip1SelectionToken
        let mode = inputExperienceMode
        do {
            let fetched = try await FiveHundredBeijingSingleClient.fetchAllIssueMatches(issue: selection.issue)
            guard token == vip1SelectionToken, mode == inputExperienceMode else {
                currentTXTQueryMessage = "输入或生成结果在分析期间已改变，请重新生成后查看原因。"
                return
            }
            let selected = selection.legs.compactMap { leg in
                fetched.first { $0.issue == selection.issue && Int($0.matchNumber) == leg.number }
            }
            guard selection.legs.count == 6,
                  QueryFinalityGate.permitsResult(matches: selected, expectedCount: 6) else {
                currentTXTQueryMessage = "暂不能判断：前六场尚未全部最终结束，或终局数据未取齐；不会将未完赛当作未过关。"
                return
            }
            let outcomes = selected.compactMap(QueryFinalityGate.resolvedOutcome)
            guard outcomes.count == 6 else {
                currentTXTQueryMessage = "暂不能判断：缺少完整六场让球赛果。"
                return
            }
            let reasons = selection.missReasons(outcomes: outcomes)
            currentTXTQueryIsHit = reasons.isEmpty
            let head = "第\(selection.issue)期 · \(mode.uppercased()) · 真实终场赛果\(outcomes.map(String.init).joined())"
            let details = reasons.enumerated().map { "\($0.offset + 1). \($0.element)" }.joined(separator: "\n")
            currentTXTQueryMessage = head + (reasons.isEmpty
                ? "\n\n计算结果：前六场已过关，没有未过关原因。"
                : "\n\n计算结果：前六场未过关。\n" + details)
                + "\n\n只核对本次生成的六场选择；第七场不参与前六场过关判断。"
        } catch {
            guard token == vip1SelectionToken, mode == inputExperienceMode else {
                currentTXTQueryMessage = "输入或生成结果已改变，请重新分析。"
                return
            }
            currentTXTQueryMessage = "暂不能分析：终局数据获取失败，请重试。\n\(error.localizedDescription)"
        }
    }

    @MainActor
    private func currentTXTPrizeSummary(
        issue: String, generationID: UUID, matchNumbers: [String],
        firstSixOutcomes: [Int], seventhOptions: [Int],
        isSimulation: Bool, multiplier: Int
    ) async -> String {
        let hasSnapshot = currentTXTPrizeGenerationID == generationID
        var snapshots = hasSnapshot ? currentTXTPrizeSnapshots : []
        let capture = hasSnapshot ? currentTXTPrizeCaptureTask : nil
        if let capture {
            let fetchedSnapshots = await capture.value
            for saved in fetchedSnapshots where !snapshots.contains(where: {
                $0.issue == saved.issue && Int($0.matchNumber) == Int(saved.matchNumber)
            }) { snapshots.append(saved) }
        }
        var matches = (try? await FiveHundredBeijingSingleClient.fetchLiveMatches(
            issue: issue, matchNumbers: matchNumbers
        )) ?? []
        if matches.isEmpty, matchNumbers.count > 6 {
            matches = (try? await FiveHundredBeijingSingleClient.fetchLiveMatches(
                issue: issue, matchNumbers: Array(matchNumbers.prefix(6))
            )) ?? []
        }
        return TXTQueryPrizeCalculator.calculate(
            issue: issue, matchNumbers: matchNumbers, firstSixOutcomes: firstSixOutcomes,
            seventhOptions: seventhOptions, matches: matches, snapshots: snapshots,
            isSimulation: isSimulation, multiplier: multiplier
        ).displayText
    }

    private func clearQueryResult(at index: Int, message: String) {
        guard sharedTXTQueryHistory.indices.contains(index) else { return }
        sharedTXTQueryHistory[index].lastCheckedAt = Date()
        sharedTXTQueryHistory[index].observedOutcomes = nil
        sharedTXTQueryHistory[index].verificationMessage = message
        sharedTXTQueryHistory[index].isFinalResult = false
        sharedTXTQueryHistory[index].isHit = nil
        sharedTXTQueryHistory[index].prizeAmount = nil
        sharedTXTQueryHistory[index].prizeSPValues = nil
        saveSharedTXTQueryHistory()
    }

    @MainActor
    private func applyManualSharedTXTQueryResult() async {
        manualQueryResultMessage = nil
        let issue = previousIssueInput.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !issue.isEmpty else {
            manualQueryResultMessage = "手动查询失败：请输入期号或日期。"
            return
        }
        let numbers = manualSequentialQueryMatchNumbers
        guard numbers.count == 6 else {
            manualQueryResultMessage = "手动查询失败：请输入6个大于0且不重复的场次号。"
            return
        }
        let compact = manualQuerySixOutcomeInput.filter { !$0.isWhitespace && $0 != "," && $0 != "，" && $0 != "/" }
        let enteredOutcomes = compact.compactMap { Int(String($0)) }
        guard compact.count == 6,
              enteredOutcomes.count == 6,
              enteredOutcomes.allSatisfy({ [3, 1, 0].contains($0) }) else {
            manualQueryResultMessage = "手动查询失败：请输入正好6位3/1/0赛果，例如310130。"
            return
        }
        guard let matchedRecord = sharedTXTQueryHistory.reversed().first(where: { record in
            return isCurrentConditionTXT(record)
                && record.issue.trimmingCharacters(in: .whitespacesAndNewlines) == issue
                && Array(record.matchNumbers.prefix(6)).compactMap(Int.init) == numbers.compactMap(Int.init)
        }) else {
            manualQueryResultMessage = "手动查询失败：未找到与条件Tab当前版本一致的TXT，请先按当前条件导入或生成。"
            return
        }
        let finality = await queryFinalityStatus(
            issue: matchedRecord.issue,
            matchNumbers: matchedRecord.matchNumbers
        )
        guard finality.allowed else {
            if let latestIndex = sharedTXTQueryHistory.firstIndex(where: { $0.id == matchedRecord.id }) {
                clearQueryResult(at: latestIndex, message: finality.message)
            }
            manualQueryResultMessage = finality.message
            return
        }
        guard let index = sharedTXTQueryHistory.firstIndex(where: { $0.id == matchedRecord.id }) else { return }
        guard let outcomes = finality.outcomes, outcomes.count == 6 else { return }
        let resolvedCompact = outcomes.map(String.init).joined()

        var seen = Set<[Int]>()
        let bets = sharedTXTQueryHistory[index].betOutcomes.compactMap { bet -> [Int]? in
            guard bet.count >= 6 else { return nil }
            let firstSix = Array(bet.prefix(6))
            return seen.insert(firstSix).inserted ? firstSix : nil
        }
        let hit = bets.contains(outcomes)
        let prizeAmount: Double? = {
            guard hit,
                  let sp = sharedTXTQueryHistory[index].prizeSPValues,
                  sp.count >= 6 else { return nil }
            return Array(sp.prefix(6)).reduce(1.3, *)
        }()
        sharedTXTQueryHistory[index].lastCheckedAt = Date()
        sharedTXTQueryHistory[index].observedOutcomes = outcomes.map(Optional.some)
        sharedTXTQueryHistory[index].verificationMessage = hit
            ? "已确认终局赛果\(resolvedCompact)：TXT实际命中。已核对\(bets.count)个去重前6场组合。"
            : "已确认终局赛果\(resolvedCompact)：TXT实际未命中。已核对\(bets.count)个去重前6场组合。"
        sharedTXTQueryHistory[index].isFinalResult = true
        sharedTXTQueryHistory[index].isHit = hit
        sharedTXTQueryHistory[index].prizeAmount = prizeAmount
        saveSharedTXTQueryHistory()
        let synced = syncStoredQueryResultsToGlobalAnswersFromCache()
        manualQueryResultMessage = "已核对终局赛果\(resolvedCompact)：TXT\(hit ? "命中" : "未命中")；\(synced > 0 ? "已同步奖金Tab。" : "奖金Tab无需重复同步。")"
    }

    /// “查看全部查询结果”单条 Cell 的手动判定。
    /// 直接使用该 Cell 绑定的 TXT，避免同期号多组场次时命中错记录。
    @MainActor
    private func applyManualSharedTXTQueryResult(_ rawInput: String, to recordID: UUID) async {
        let compact = rawInput.filter { character in
            character == "3" || character == "1" || character == "0"
        }
        let enteredOutcomes = compact.compactMap { Int(String($0)) }
        guard compact.count == 6, enteredOutcomes.count == 6 else { return }
        guard let initialIndex = sharedTXTQueryHistory.firstIndex(where: { $0.id == recordID }) else { return }
        guard isCurrentConditionTXT(sharedTXTQueryHistory[initialIndex]) else {
            manualOutcomeInputsByRecordID[recordID] = compact
            return
        }
        let record = sharedTXTQueryHistory[initialIndex]
        let finality = await queryFinalityStatus(
            issue: record.issue,
            matchNumbers: record.matchNumbers
        )
        guard finality.allowed else {
            if let latestIndex = sharedTXTQueryHistory.firstIndex(where: { $0.id == recordID }) {
                clearQueryResult(at: latestIndex, message: finality.message)
            }
            manualOutcomeInputsByRecordID[recordID] = compact
            return
        }
        guard let index = sharedTXTQueryHistory.firstIndex(where: { $0.id == recordID }) else { return }
        guard let outcomes = finality.outcomes, outcomes.count == 6 else { return }
        let resolvedCompact = outcomes.map(String.init).joined()

        let previousOutcomes = sharedTXTQueryHistory[index].observedOutcomes?
            .prefix(6)
            .compactMap { $0 }
        var seen = Set<[Int]>()
        let bets = sharedTXTQueryHistory[index].betOutcomes.compactMap { bet -> [Int]? in
            guard bet.count >= 6 else { return nil }
            let firstSix = Array(bet.prefix(6))
            return seen.insert(firstSix).inserted ? firstSix : nil
        }
        let hit = bets.contains(outcomes)
        let canReuseStoredSP = previousOutcomes == outcomes
        let prizeAmount: Double? = {
            guard hit,
                  canReuseStoredSP,
                  let sp = sharedTXTQueryHistory[index].prizeSPValues,
                  sp.count >= 6 else { return nil }
            return Array(sp.prefix(6)).reduce(1.3, *)
        }()

        sharedTXTQueryHistory[index].lastCheckedAt = Date()
        sharedTXTQueryHistory[index].observedOutcomes = outcomes.map(Optional.some)
        sharedTXTQueryHistory[index].verificationMessage = hit
            ? "已确认终局赛果\(resolvedCompact)：TXT实际命中。已核对\(bets.count)个去重前6场组合。"
            : "已确认终局赛果\(resolvedCompact)：TXT实际未命中。已核对\(bets.count)个去重前6场组合。"
        sharedTXTQueryHistory[index].isFinalResult = true
        sharedTXTQueryHistory[index].isHit = hit
        sharedTXTQueryHistory[index].prizeAmount = prizeAmount
        manualOutcomeInputsByRecordID[recordID] = compact
        saveSharedTXTQueryHistory()
        _ = syncStoredQueryResultsToGlobalAnswersFromCache()
    }

    private func analyzePreviousResult(
        _ outcomes: [Int],
        previousLogic: [LogicMapping],
        fallbackConfig: FilterConfig
    ) -> (message: String, hitFlag: Int) {
        let compact = outcomes.map(String.init).joined()
        let logicText = previousLogic.map(\.displayName).joined()
        guard let snapshot = lastRunSnapshot else {
            let analysisConfig = replacingLogic(in: fallbackConfig, with: previousLogic)
            let failures = SequenceFilterEngine.baseFilterFailureReasons(
                for: outcomes,
                config: analysisConfig
            )
            let message = failures.isEmpty
                ? "上次 \(logicText)/\(compact)：按当前基础条件可以通过；暂无旧筛选记录可核对。"
                : "上次 \(logicText)/\(compact)：按当前条件未通过——\(failures.joined(separator: "；"))。"
            return (message, 0)
        }

        let recordedConfig = (try? FilterConfig.parse(snapshot.normalizedInput)) ?? fallbackConfig
        let logicMatchesRecord = recordedConfig.logic == previousLogic
        if logicMatchesRecord, snapshot.keptOutcomes.contains(compact) {
            return ("上次 \(logicText)/\(compact)：位于上次保留范围内。", 1)
        }
        if logicMatchesRecord, snapshot.removedOutcomes.contains(compact) {
            let method = snapshot.modelCoveragePercent == nil ? "随机过滤" : "概率过滤"
            return ("上次 \(logicText)/\(compact)：通过基础条件，但被上次\(method)排除。", 0)
        }

        let previousConfig = replacingLogic(in: recordedConfig, with: previousLogic)
        let failures = SequenceFilterEngine.baseFilterFailureReasons(
            for: outcomes,
            config: previousConfig
        )
        if !logicMatchesRecord {
            let message = failures.isEmpty
                ? "上次 \(logicText)/\(compact)：输入逻辑与保存记录不同；按输入逻辑可通过基础条件，但无法核对上次筛选结果。"
                : "上次 \(logicText)/\(compact)：输入逻辑与保存记录不同；按输入逻辑未通过——\(failures.joined(separator: "；"))。"
            return (message, 0)
        }
        let message = failures.isEmpty
            ? "上次 \(logicText)/\(compact)：未在上次保存内容中找到。"
            : "上次 \(logicText)/\(compact)：被上次基础条件过滤——\(failures.joined(separator: "；"))。"
        return (message, 0)
    }

    private func replacingLogic(
        in config: FilterConfig,
        with logic: [LogicMapping]
    ) -> FilterConfig {
        FilterConfig(
            matchNumbers: config.matchNumbers,
            logic: logic,
            sumRange: config.sumRange,
            displacementRange: config.displacementRange,
            displacementMatchCount: config.displacementMatchCount,
            sumMatchCount: config.sumMatchCount,
            calculationMatchCount: config.calculationMatchCount,
            sumUsesOutcomeSP: config.sumUsesOutcomeSP,
            varianceMaximum: config.varianceMaximum,
            valueTwoMaximum: config.valueTwoMaximum,
            transitionMinimumPercent: config.transitionMinimumPercent,
            roughnessMaximum: config.roughnessMaximum,
            breakpointRange: config.breakpointRange,
            productRemovalCount: config.productRemovalCount,
            noFourPositions: config.noFourPositions,
            minimumDistinctDisplacementOrders: config.minimumDistinctDisplacementOrders,
            svip5TailRemovalCount: config.svip5TailRemovalCount,
            svip5FourCountFilterEnabled: config.svip5FourCountFilterEnabled,
            frontFiveActualMEnabled: config.frontFiveActualMEnabled,
            frontFiveActualMRange: config.frontFiveActualMRange,
            frontFiveNoTripleDrawEnabled: config.frontFiveNoTripleDrawEnabled,
