    private var inputDefaultsStorageKey: String { "sequenceFilter.inputDefaults.v1" }
    private var savedFilterSchemesStorageKey: String { "sequenceFilter.savedFilterSchemes.v1" }

    /// 升级及旧设置导入后都清除105上限；其余条件与历史TXT保持。
    private func applyCurrentSelectionSettings() {
        let defaults = UserDefaults.standard
        for key in [inputDefaultsStorageKey, SVVVConditionPackage.storageKey] {
            guard let values = defaults.dictionary(forKey: key) as? [String: String] else { continue }
            let updated = FilterInputDefaults.currentDirectionalDoubleSettings(from: FilterInputDefaults.removingFixed105Limit(from: values))
            if updated != values { defaults.set(updated, forKey: key) }
        }
        defaults.synchronize()
    }

    private func installSVVVPackageIfNeeded() {
        let defaults = UserDefaults.standard
        guard !defaults.bool(forKey: SVVVConditionPackage.migrationKey),
              var values = defaults.dictionary(forKey: inputDefaultsStorageKey) as? [String: String],
              values["selectedConditionVersionID"] == "svip10-frozen-160" else { return }
        defaults.set(SVVVConditionPackage.snapshot(from: values), forKey: SVVVConditionPackage.storageKey)
        values["svvvSelected"] = "1"
        defaults.set(values, forKey: inputDefaultsStorageKey)
        defaults.set(true, forKey: SVVVConditionPackage.migrationKey)
        defaults.synchronize()
    }

    private func saveSVVVPackageIfSelected(values: [String: String]? = nil) {
        guard svvvSelected else { return }
        UserDefaults.standard.set(SVVVConditionPackage.snapshot(from: values ?? persistedInputValues),
                                  forKey: SVVVConditionPackage.storageKey)
    }

    private func saveSVVVP11PackageIfSelected(values: [String: String]? = nil) {
        guard svvvp11Selected else { return }
        UserDefaults.standard.set(SVVVConditionPackage.snapshot(from: values ?? persistedInputValues),
                                  forKey: SVVVP11ConditionPackage.storageKey)
    }

    private func activateSVVVP11Package(reset: Bool = false) {
        let defaults = UserDefaults.standard
        guard reset || !svvvp11Selected else { return }
        inputDefaultsSaveTask?.cancel()
        saveSVVVPackageIfSelected()
        if !svvvp11Selected {
            defaults.set(persistedInputValues, forKey: SVVVP11ConditionPackage.previousStorageKey)
        }
        let values: [String: String]
        if !reset, let saved = defaults.dictionary(forKey: SVVVP11ConditionPackage.storageKey) as? [String: String] {
            values = SVVVP11ConditionPackage.restoring(saved, onto: persistedInputValues)
        } else {
            guard let recommended = try? SVVVP11ConditionPackage.recommendedValues(onto: persistedInputValues) else { return }
            values = recommended
        }
        defaults.set(values, forKey: inputDefaultsStorageKey)
        defaults.set(SVVVConditionPackage.snapshot(from: values), forKey: SVVVP11ConditionPackage.storageKey)
        defaults.synchronize()
        isRestoringInputDefaults = true
        restoreInputDefaults()
        invalidateComputedResultsAfterConditionChange()
        conditionVersionMessage = "已载入svvvp11；起点、第7场与倍数保持当前输入。"
        DispatchQueue.main.async {
            isRestoringInputDefaults = false
            scheduleDurableBackup()
        }
    }

    private func restoreBeforeSVVVP11Package() {
        let defaults = UserDefaults.standard
        guard let saved = defaults.dictionary(forKey: SVVVP11ConditionPackage.previousStorageKey) as? [String: String] else { return }
        inputDefaultsSaveTask?.cancel()
        saveSVVVP11PackageIfSelected()
        defaults.set(SVVVP11ConditionPackage.restoringPrevious(saved, onto: persistedInputValues), forKey: inputDefaultsStorageKey)
        defaults.synchronize()
        isRestoringInputDefaults = true
        restoreInputDefaults()
        invalidateComputedResultsAfterConditionChange()
        conditionVersionMessage = "已恢复载入svvvp11之前的条件；当前起点、第7场和倍数保留。"
        DispatchQueue.main.async {
            isRestoringInputDefaults = false
            scheduleDurableBackup()
        }
    }

    private func installSVVVP11RevisionIfNeeded() {
        let defaults = UserDefaults.standard
        guard let values = defaults.dictionary(forKey: inputDefaultsStorageKey) as? [String: String],
              values["svvvp11Selected"] == "1",
              values["svvvp11PresetRevision"] != "unrestricted-40-prize-v2",
              let updated = try? SVVVP11ConditionPackage.recommendedValues(onto: values) else { return }
        defaults.set(updated, forKey: inputDefaultsStorageKey)
        defaults.set(SVVVConditionPackage.snapshot(from: updated), forKey: SVVVP11ConditionPackage.storageKey)
        defaults.synchronize()
    }

    private func installSVVVHighPassConditionsIfNeeded() {
        let defaults = UserDefaults.standard
        guard !defaults.bool(forKey: SVVVConditionPackage.highPassMigrationKey),
              let values = defaults.dictionary(forKey: inputDefaultsStorageKey) as? [String: String],
              values["svvvSelected"] == "1", values["selectedConditionVersionID"] == "svip10-frozen-160" else { return }
        let updated = SVVVConditionPackage.addingHighPassConditions(to: values)
        defaults.set(updated, forKey: inputDefaultsStorageKey)
        defaults.set(SVVVConditionPackage.snapshot(from: updated), forKey: SVVVConditionPackage.storageKey)
        defaults.set(true, forKey: SVVVConditionPackage.highPassMigrationKey)
        defaults.synchronize()
    }

    private func installSVVVHighPass93ConditionsIfNeeded() {
        let defaults = UserDefaults.standard
        guard !defaults.bool(forKey: SVVVConditionPackage.highPass40MigrationKey),
              let values = defaults.dictionary(forKey: inputDefaultsStorageKey) as? [String: String],
              values["svvvSelected"] == "1", values["selectedConditionVersionID"] == "svip10-frozen-160" else { return }
        let updated = SVVVConditionPackage.addingHighPass93Conditions(to: values)
        defaults.set(updated, forKey: inputDefaultsStorageKey)
        defaults.set(SVVVConditionPackage.snapshot(from: updated), forKey: SVVVConditionPackage.storageKey)
        defaults.set(true, forKey: SVVVConditionPackage.highPass40MigrationKey)
        defaults.synchronize()
    }

    private func installSVVVHighPass98PackagesIfNeeded() {
        let defaults = UserDefaults.standard
        guard let values = defaults.dictionary(forKey: inputDefaultsStorageKey) as? [String: String],
              values["svvvSelected"] == "1", values["selectedConditionVersionID"] == "svip10-frozen-160" else { return }
        let hundredNeeded = !defaults.bool(forKey: SVVVConditionPackage.highPass100MigrationKey)
        let fiftyNeeded = !defaults.bool(forKey: SVVVConditionPackage.highPass50MigrationKey)
        var updated = values
        if hundredNeeded { updated = SVVVConditionPackage.addingHighPass98Conditions(to: updated) }
        if fiftyNeeded { updated = SVVVConditionPackage.addingHighPass98FiftyConditions(to: updated) }
        updated = SVVVConditionPackage.removingRelativePositionConditions(from: updated)
        guard hundredNeeded || fiftyNeeded || updated != values
                || !defaults.bool(forKey: SVVVConditionPackage.relativePositionRemovalKey) else { return }
        defaults.set(updated, forKey: inputDefaultsStorageKey)
        defaults.set(SVVVConditionPackage.snapshot(from: updated), forKey: SVVVConditionPackage.storageKey)
        defaults.set(true, forKey: SVVVConditionPackage.highPass100MigrationKey)
        defaults.set(true, forKey: SVVVConditionPackage.highPass50MigrationKey)
        defaults.set(true, forKey: SVVVConditionPackage.relativePositionRemovalKey)
        defaults.synchronize()
    }

    private func activateSVVVPackage() {
        let defaults = UserDefaults.standard
        guard let package = defaults.dictionary(forKey: SVVVConditionPackage.storageKey) as? [String: String],
              package["selectedConditionVersionID"] == "svip10-frozen-160" else { return }
        if svvvSelected { return }
        inputDefaultsSaveTask?.cancel()
        saveSVVVP11PackageIfSelected()
        var restored = SVVVConditionPackage.restoring(package, onto: persistedInputValues)
        restored["svvvp11Selected"] = "0"
        defaults.set(restored, forKey: inputDefaultsStorageKey)
        defaults.synchronize()
        isRestoringInputDefaults = true
        restoreInputDefaults()
        result = nil
        currentTXTQueryMessage = nil
        currentTXTQueryIsHit = nil
        conditionVersionMessage = "已载入svvv，已恢复打包范围和全部分项开关。"
        DispatchQueue.main.async {
            isRestoringInputDefaults = false
            scheduleDurableBackup()
        }
    }

