    private func scheduleInputDefaultsSave() {
        guard hasLoadedInputDefaults else { return }
        inputDefaultsSaveTask?.cancel()
        inputDefaultsSaveTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 350_000_000)
            guard !Task.isCancelled else { return }
            let values = persistedInputValues
            UserDefaults.standard.set(values, forKey: inputDefaultsStorageKey)
            saveSVVVPackageIfSelected(values: values)
            saveSVVVP11PackageIfSelected(values: values)
            if selectedConditionVersionID == "svip8-current-three" {
                let keys = ["sumInput", "svip6SumEnabled", "noFourPositionFilterEnabled", "svip4NoFourSelection", "currentConditionPackageEnabled"]
                UserDefaults.standard.set(persistedInputValues.filter { keys.contains($0.key) }, forKey: "sequenceFilter.svip8Snapshot.v1")
            }
            scheduleDurableBackup()
        }
    }

    private func scheduleDurableBackup(delayNanoseconds: UInt64 = 8_000_000_000) {
        durableBackupTask?.cancel()
        durableBackupTask = Task { @MainActor in
            if delayNanoseconds > 0 {
                try? await Task.sleep(nanoseconds: delayNanoseconds)
            }
            guard !Task.isCancelled else { return }
            _ = await Task.detached(priority: .utility) {
                DurableAppBackup.backupNow()
            }.value
        }
    }

