           let data = try? JSONEncoder().encode(profile) {
            values["comprehensiveAnalysisProfile"] = data.base64EncodedString()
        }
        values["protectedHistoryMaxCompressionEnabled"] = protectedHistoryMaxCompressionEnabled ? "1" : "0"
        values["protectedHistoryToleranceEnabled"] = protectedHistoryToleranceEnabled ? "1" : "0"
        values["protectedHistoryToleranceInput"] = protectedHistoryToleranceInput
        values["protectedHistoryBetCapEnabled"] = protectedHistoryBetCapEnabled ? "1" : "0"
        values["protectedHistoryBetCapInput"] = protectedHistoryBetCapInput
        if let profile = protectedHistoryMaxCompressionProfile,
           let data = try? JSONEncoder().encode(profile) {
            values["protectedHistoryMaxCompressionProfile"] = data.base64EncodedString()
        }
        for index in prizeMatchInputs.indices {
            values["prizeMatchInput\(index + 1)"] = prizeMatchInputs[index]
        }
        for condition in OutcomeCondition.editorCases {
            values["OC_" + condition.rawValue] = outcomeConditionInputs[condition] ?? ""
            values["OCON_" + condition.rawValue] = outcomeConditionEnabled[condition] == true ? "1" : "0"
        }
        values.merge(finalResultFilterInputValues) { _, current in current }
        return values
    }

    private func restoreInputDefaults() {
        let saved = UserDefaults.standard.dictionary(forKey: inputDefaultsStorageKey) as? [String: String]
        let migrated = lastRunSnapshot.flatMap { try? FilterConfig.parse($0.normalizedInput) }
            .map(FilterInputDefaults.values)
        if let stored = saved ?? migrated {
            let values = FilterInputDefaults.currentDirectionalDoubleSettings(from: stored)
            automaticFinalOutcomeExclusions = values["automaticFinalOutcomeExclusionsEnabled"] != "0"
            finalOutcomeManualSelectionKey = values["finalOutcomeManualSelectionKey"] ?? ""
            historicalOutcomeWindows = Set([50, 100, 150, 200].filter { values["historyWindow\($0)Enabled"] == "1" })
            finalResultInverted = values["finalResultInverted"] == "1"
            finalOutcomeExclusion1Enabled = values["finalOutcomeExclusion1Enabled"] == "1"
            finalOutcomeExclusion1Position = min(6, max(1, Int(values["finalOutcomeExclusion1Position"] ?? "1") ?? 1))
            finalOutcomeExclusion1Outcome = Int(values["finalOutcomeExclusion1Outcome"] ?? "3").flatMap { [3, 1, 0].contains($0) ? $0 : nil } ?? 3
            finalOutcomeExclusion2Enabled = values["finalOutcomeExclusion2Enabled"] == "1"
            finalOutcomeExclusion2Position = min(6, max(1, Int(values["finalOutcomeExclusion2Position"] ?? "2") ?? 2))
            finalOutcomeExclusion2Outcome = Int(values["finalOutcomeExclusion2Outcome"] ?? "3").flatMap { [3, 1, 0].contains($0) ? $0 : nil } ?? 3
            svvvp11Selected = values["svvvp11Selected"] == "1"
                && values["selectedConditionVersionID"] == "svip10-frozen-160"
            svvvSelected = values["svvvSelected"] == "1"
                && values["selectedConditionVersionID"] == "svip10-frozen-160"
            svvvHighPass40Enabled = values["svvvHighPass40Enabled"] == "1"
            svvvHighPass100Enabled = values["svvvHighPass100Enabled"] == "1"
            svvvHighPass50Enabled = values["svvvHighPass50Enabled"] == "1"
            svvvHighPass50DoubleEnabled = values["svvvHighPass50DoubleEnabled"] == "1"
            conditionTextInput = values["conditionTextInput"] ?? ""
            enteredConditionIDs = (values["enteredConditionIDs"] ?? "").split(separator: ",").map(String.init)
            disabledBasicConditions = Set((values["disabledBasicConditions"] ?? "").split(separator: ",")
                .compactMap { BasicCondition(rawValue: String($0)) })
            valueThreeMaximumInput = values["valueThreeMaximumInput"] ?? "5"
            svip10RRangeInput = values["svip10RRangeInput"] ?? "0-15"
            svip10ValueTwoMaximumInput = values["svip10ValueTwoMaximumInput"] ?? "4"
            svip5TailReductionEnabled = false
            svip5FourCountFilterEnabled = values["svip5FourCountFilterEnabled"] == "1"
            frontFiveActualMEnabled = values["frontFiveActualMEnabled"] == "1"
            frontFiveActualMRangeInput = values["frontFiveActualMRangeInput"] ?? "3-6"
            frontFiveNoTripleDrawEnabled = values["frontFiveNoTripleDrawEnabled"] == "1"
            frontFiveLossCountEnabled = values["frontFiveLossCountEnabled"] == "1"
            frontFiveWinCountEnabled = values["frontFiveWinCountEnabled"] == "1"
            combinedThreeStructureEnabled = values["combinedThreeStructureEnabled"] == "1"
            combinedThreeRRangeInput = values["combinedThreeRRangeInput"] ?? "3-15"
            sixLossCount14Enabled = values["sixLossCount14Enabled"] == "1"
            frontFiveR39Enabled = values["frontFiveR39Enabled"] == "1"
            svip10NoFourEnabled = values["svip10NoFourEnabled"] != "0"
            svip10SecondDoubleLowestProbabilityEnabled = values["svip10SecondDoubleLowestProbabilityEnabled"] != "0"
            svip10CalibratedDoubleSelectionEnabled = values["svip10CalibratedDoubleSelectionEnabled"] == "1"
            svip10AutomaticDoublePairEnabled = values["svip10AutomaticDoublePairEnabled"] != "0"
            svip10AllABCDEnabled = values["svip10AllABCDEnabled"] != "0"
            svip10DoubleJudgmentFactors = values["svip10DoubleJudgmentFactors"].flatMap(DoubleJudgmentFactor.parse) ?? Set(DoubleJudgmentFactor.allCases)
            svip10StatisticalLineBudgetEnabled = values["svip10StatisticalLineBudgetEnabled"] == "1"
            svip10ProbabilityMass60Enabled = values["svip10ProbabilityMass60Enabled"] != "0"
            svip10FrontTwoADEnabled = values["svip10FrontTwoADEnabled"] != "0"
            svip10NoFourPosition = min(6, max(1, Int(values["svip10NoFourPosition"] ?? "1") ?? 1))
            vipSeventhNumber = values["vipSeventhNumber"] ?? "1"
            vipSeventhOutcome = values["vipSeventhOutcome"] ?? "3"
            inputExperienceMode = ["vip1","vip2"].contains(values["inputExperienceMode"] ?? "") ? values["inputExperienceMode"]! : "v1"
            if inputExperienceMode == "vip1", !["3","0"].contains(vipSeventhOutcome) { vipSeventhOutcome="3" }
            vip1StartInput = values["vip1StartInput"] ?? values["match1Input"] ?? "1"
            vip1EndInput = values["vip1EndInput"] ?? values["singleMatchInput"] ?? "7"
            svip11BreakpointRangeInput = values["svip11BreakpointRangeInput"] ?? "2-4"
            svip10ColdCountEnabled = values["svip10ColdCountEnabled"] != "0"
            svip10ColdCountRangeInput = values["svip10ColdCountRangeInput"] ?? "0-2"
            svip10DrawCountEnabled = values["svip10DrawCountEnabled"] == "1"
