            svip10WinLossSwitchEnabled = values["svip10WinLossSwitchEnabled"] != "0"
            svip10FiveMatchMEnabled = values["svip10FiveMatchMEnabled"] != "0"
            svip10FiveMatchMRangeInput = values["svip10FiveMatchMRangeInput"] ?? "2-6"
            svip10FrontFiveSameOutcomeRunMaximum2Enabled = values["svip10FrontFiveSameOutcomeRunMaximum2Enabled"] == "1"
            svip10FrontFiveReturnMaximum2Enabled = values["svip10FrontFiveReturnMaximum2Enabled"] != "0"
            svip10FrontFiveNoConsecutiveDrawEnabled = values["svip10FrontFiveNoConsecutiveDrawEnabled"] == "1"
            svip10FrontFiveValueThreeMaximum2Enabled = values["svip10FrontFiveValueThreeMaximum2Enabled"] == "1"
            svip10SixMatchFavoriteCount1To4Enabled = values["svip10SixMatchFavoriteCount1To4Enabled"] != "0"
            svip10SixMatchMinimumOddsProductEnabled = values["svip10SixMatchMinimumOddsProductEnabled"] != "0"
            svip10SixMatchMinimumOddsProductInput = values["svip10SixMatchMinimumOddsProductInput"] ?? "380"
            svip10SixMatchBreakpoint3To5Enabled = values["svip10SixMatchBreakpoint3To5Enabled"] != "0"
            svip10SixMatchBreakpointRangeInput = values["svip10SixMatchBreakpointRangeInput"] ?? "2-5"
            svip10TopThreeProbabilityRecovery100Enabled = values["svip10TopThreeProbabilityRecovery100Enabled"] != "0"
            overallOddsForecastGateEnabled = values["overallOddsForecastGateEnabled"] != "0"
