            svip10Enabled = values["svip10Enabled"] != "0"
            six250ScoreUpperInput = values["six250ScoreUpperInput"] ?? "7.5"
            svip9TXTCompactEnabled = values["svip9TXTCompactEnabled"] != "0"
            svip9TXTAdditionalLimit = Int(values["svip9TXTAdditionalLimit"] ?? "50") ?? 50
            svip9BaseSumRangeInput = values["svip9BaseSumRangeInput"] ?? "13-22"
            oddsAdaptiveSEnabled = values["oddsAdaptiveSEnabled"] != "0"
            v1RecommendedSEnabled = values["v1RecommendedSEnabled"] == "1"
            svip6SumEnabled = values["svip6SumEnabled"] != "0"
            six250SumRangeInput = values["six250SumRangeInput"] ?? "12-22"
            six250MRangeInput = values["six250MRangeInput"] ?? "0-7"
