            if let value = values["marketWeightPercent"], let weight = Int(value), (0...30).contains(weight) { marketWeightPercent = weight }
            if let value = values["finalReduction"], let mode = FinalReductionMode(rawValue: value) { finalReduction = mode }
            if let value = values["randomSeedInput"] { randomSeedInput = value }
            if let value = values["beijingSingleIssueInput"] { beijingSingleIssueInput = value }
            if let value = values["prizeDelayedMatchNumbersInput"] { prizeDelayedMatchNumbersInput = value }
            if let value = values["match1Input"], !value.isEmpty { match1Input = value }
            matchSearchStartInput = values["matchSearchStartInput"] ?? values["match1Input"] ?? "1"
            if let value = values["match2Input"], !value.isEmpty { match2Input = value }
            if let value = values["match3Input"], !value.isEmpty { match3Input = value }
            if let value = values["match4Input"], !value.isEmpty { match4Input = value }
            if let value = values["match5Input"], !value.isEmpty { match5Input = value }
            if let value = values["fixedFullMatchInput"], !value.isEmpty { fixedFullMatchInput = value }
            if let value = values["logicInput"] {
                let cleaned = value.filter { "ABCD".contains($0) }
                if cleaned.count == 5 || cleaned.count == 6 { logicInput = cleaned }
            }
            if let value = values["singleMatchInput"], !value.isEmpty { singleMatchInput = value }
            if let value = values["betMultiplierInput"], !value.isEmpty { betMultiplierInput = value }
            if let value = values["firstMatchStartTime"],
               let interval = TimeInterval(value), interval > 0 {
                firstMatchStartTime = Date(timeIntervalSince1970: interval)
            }
            if let value = values["seventhMatchStartTime"],
               let interval = TimeInterval(value), interval > 0 {
                seventhMatchStartTime = Date(timeIntervalSince1970: interval)
            }
            if let value = values["firstMatchStartTimeContext"] { firstMatchStartTimeContext = value }
            if let value = values["seventhMatchStartTimeContext"] { seventhMatchStartTimeContext = value }
