            if let value = values["manualFirstMatchTimePriorityEnabled"] { manualFirstMatchTimePriorityEnabled = value == "1" }
            if let value = values["manualSeventhMatchTimePriorityEnabled"] { manualSeventhMatchTimePriorityEnabled = value == "1" }
            if let value = values["txtDisplaysSeventhMatch"] { txtDisplaysSeventhMatch = value == "1" }
