                }
            }
            if let value = values["sumInput"] { sumInput = value }
            if let value = values["displacementInput"] { displacementInput = value }
            if let value = values["svip4MinimumDistinctMOrdersInput"] { svip4MinimumDistinctMOrdersInput = value }
            if let value = values["varianceInput"] { varianceInput = value }
            if let value = values["valueTwoMaximumInput"] { valueTwoMaximumInput = value }
            if let value = values["frontThreeMaximumFourFilterEnabled"] {
                frontThreeMaximumFourFilterEnabled = value == "1"
            }
            if let value = values["noFourPositionFilterEnabled"] {
                noFourPositionFilterEnabled = value == "1"
            }
            if values["frontThreeMaximumFourFilterEnabled"] == nil,
               [
"svip1-xs-current", "svip2-all-basic", "svip3-current-no-four", "vip6-automatic-odds", "vip7-enabled-only", "vip8-current-day", "vip9-front-five-m3-6", "vip10-front-five-real-sum", "vip11-front-five-mapped-sum", "vip12-probability-bottom20", "vip14-s15-18", "vip15-s15-20-single-no-four", "vip16-probability-top200"]
                .contains(values["selectedConditionVersionID"] ?? ""),
               values["noFourPositionFilterEnabled"] == "1" {
                // 旧VIP版本借NO4字段执行的实际规则是“前三场最多1个4”。
                // 升级后拆成两个开关，这里只迁移真实语义，不额外开启指定场次禁4。
                frontThreeMaximumFourFilterEnabled = true
                noFourPositionFilterEnabled = false
            }
            if let value = values["noFourPositionInput"],
               let position = Int(value), (1...6).contains(position) {
                noFourPositionInput = value
            } else if let legacyValue = values["noFourPositionsInput"],
                      let firstPosition = legacyValue.split(separator: ",").compactMap({ Int($0) }).first,
                      (1...6).contains(firstPosition) {
                noFourPositionFilterEnabled = true
                noFourPositionInput = String(firstPosition)
            }
            if let value = values["svip4NoFourSelection"],
               value == "auto" || Int(value).map({ (1...6).contains($0) }) == true {
                svip4NoFourSelection = value
            }
            if let value = values["secondNoFourPositionFilterEnabled"] {
                secondNoFourPositionFilterEnabled = value == "1"
            }
            if let value = values["secondNoFourPositionInput"],
               let position = Int(value), (1...6).contains(position) {
                secondNoFourPositionInput = value
            }
            if let value = values["transitionMinimumInput"] { transitionMinimumInput = value }
            if let value = values["roughnessMaximumInput"] { roughnessMaximumInput = value }
            if let value = values["breakpointInput"] { breakpointInput = value }
            productRemovalCountInput = "0"
            if let value = values["singleOutcomeInput"] { singleOutcomeInput = value }
            if let value = values["consecutiveRunsEnabled"] { consecutiveRunsEnabled = value == "1" }
