            }
            if let value = values["protectConsecutiveDrawPair"] {
                protectConsecutiveDrawPair = value == "1"
            }
            if let value = values["spProductFilterEnabled"] { spProductFilterEnabled = value == "1" }
            if let value = values["spProductRangeInput"] { spProductRangeInput = value }
            if let value = values["customHandicapOddsProductFilterEnabled"] {
