            }
            if let encoded = values["protectedHistoryMaxCompressionProfile"],
               let data = Data(base64Encoded: encoded),
               let profile = try? JSONDecoder().decode(ComprehensiveAnalysisProfile.self, from: data) {
                protectedHistoryMaxCompressionProfile = upgradedComputerVerifiedProfile(profile)
            }
            if let value = values["protectedHistoryMaxCompressionEnabled"] {
