            }
            if let value = values["protectedHistoryBetCapInput"],
               let cap = Int(value), (1...729).contains(cap) {
                protectedHistoryBetCapInput = value
            }
            if let profile = protectedHistoryMaxCompressionProfile,
               profile.historyRecordCount < minimumProtectedHistoryRecordCount {
                protectedHistoryMaxCompressionProfile = nil
                protectedHistoryMaxCompressionEnabled = false
                protectedHistoryMaxCompressionMessage = "旧大压缩仅保护\(profile.historyRecordCount)条，低于至少\(minimumProtectedHistoryRecordCount)条的要求，已自动关闭。"
            }
            // 大压缩只在电脑端重算。若本机缓存不存在或因旧档案未达30条被清除，
            // 导入已离线复核的34条档案并默认开启；后续会随常规输入默认值落盘。
            if protectedHistoryMaxCompressionProfile == nil {
                loadComputerVerifiedProtectedHistoryProfile()
            }
            if let value = values["abcdSource"], let source = ABCDDataSource(rawValue: value) {
                abcdSource = source
            }
            outcomeConditionInputs[.wins] = ""
            for condition in OutcomeCondition.editorCases {
                let input = values["OC_" + condition.rawValue] ?? ""
                outcomeConditionInputs[condition] = input
                outcomeConditionEnabled[condition] = values["OCON_" + condition.rawValue].map { $0 == "1" }
                    ?? !input.isEmpty
            }
        }
        if protectedHistoryMaxCompressionProfile == nil {
            loadComputerVerifiedProtectedHistoryProfile()
        }
        applyGenericCompression150DefaultsIfNeeded()
        applyCustomHandicapOddsDefaultsIfNeeded()
        applyUniversalCompressionZeroToleranceDefaultsIfNeeded()
        applyUniversal150StatisticalCompressionDefaultsIfNeeded()
        applyUniversal247ToleranceDefaultsIfNeeded()
