        applySVIP3SecondLowestNoFourMigrationIfNeeded()
        applySVIP4PermutationDefaultsIfNeeded()
        applySVIP5CurrentDefaultsIfNeeded()
        applySVIP5FourCountDefaultsIfNeeded()
        applyFrontFiveNoTripleDrawDefaultsIfNeeded()
        applyFrontFiveLossCountDefaultsIfNeeded()
        applyFrontFiveOutcomeCountRangesDefaultsIfNeeded()
        applyBreakpointZeroToFiveDefaultsIfNeeded()
        applyCombinedThreeStructureDefaultsIfNeeded()
        applyNoFourDefaultOffOnce()
        applyM26AndCombinedR315Once()
        applyExpandedRangesOctober19Once()
        applyWiderFiveConditionsOnce()
        applyTopFiveRelaxedOnce()
        applyTopFiveSecondRelaxedOnce()
        applySixMatchPackageOnce()
        applySix250Once()
        applySVIP6Once()
        applySVIP8Once()
        applySVIP9Once()
        applyScore75Once()
        applySVIP10Once()
        applySVIP10Score6Once()
        applySVIP10Score66NoFourOnce()
        applySVIP10RelaxFourOnce()
        applySVIP10Score55Once()
        applySVIP10NoFourDefaultOnOnce()
        applySVIP10Sum15Once()
        applySVIP10M3TwoCap4Once()
        applySVIP10Score55to66Once()
        applySVIP10Score58to68Once()
        applySVIP11Once()
        applySVIP11M2S14Once()
        let additionsMigration = "sequenceFilter.svip10Additional180.20261020.v1"
        if !UserDefaults.standard.bool(forKey: additionsMigration) {
            // Preserve every saved range, version, manual seventh match and prior toggle.
            for cache in [previousRunStorageKey, globalFilterCountsCacheStorageKey, globalFilterConditionsSignatureStorageKey] {
                UserDefaults.standard.removeObject(forKey: cache)
            }
            UserDefaults.standard.set(true, forKey: additionsMigration)
        }
        applySVIP10Cold250Once()
        applySVIP10WinLossSwitchOnce()
        applySVIP10HighestDoubleNoFourOnce()
        applySVIP10ProbabilityMass60Once()
        applySVIP10FiveMatchMOnce()
        applySVIP10ConcreteStructureConditionsOnce()
        applySVIP10StableFavoriteCountOnce()
        applySVIP10MinimumOddsProductOnce()
        applySVIP10Breakpoint3To5Once()
        applySVIP10ProbabilityRecovery100Once()
        applySVIP10SecondDoubleLowestProbabilityOnce()
        applySVIP10CalibratedDoubleSelectionOnce()
        hasLoadedInputDefaults = true
        // @State 在当前 onAppear 事务内尚未提交。同步读
        // persistedInputValues 会把旧默认值写回去（例如把RUN2的0改成1）。
        DispatchQueue.main.async {
            UserDefaults.standard.set(persistedInputValues, forKey: inputDefaultsStorageKey)
            UserDefaults.standard.synchronize()
            // VIP7的入口承诺是“只填第一场”。启动恢复期间的 @State 变化
            // 会因 hasLoadedInputDefaults 拦截而错过 onChange，因此在恢复完成后补一次。
            // 此时6个场次已真正提交到 @State，先按完整key恢复ABCD缓存。
            restoreCurrentABCDFromCache()
            if selectedConditionVersionID == "svip11-breakpoint-selection" || usesSVIP10AutomaticDoublePair || usesStructuredMatchSelection {
                scheduleVIP6AutomaticMatchSelection()
            } else if selectedConditionVersionID == "svip3-current-no-four",
               (noFourPositionFilterEnabled || secondNoFourPositionFilterEnabled) {
                // SVIP3两个禁4位置都必须随当期自定义赔率重算，
                // 不能因为恢复到旧ABCD缓存就沿用上期场次。
                scheduleVIP6AutomaticMatchSelection()
            } else if usesVIP6AutomaticMatchSelection,
                      (!hasValidMainNumbers || currentABCDForGeneration == nil) {
                scheduleVIP6AutomaticMatchSelection()
            } else if usesVIP6AutomaticMatchSelection,
                      vip6SelectedMatchesWithResults.isEmpty {
                Task { await loadVIP6CompletedResultVerification() }
            }
        }
    }

