    /// 将升级前XS已保存的当前条件原样固化为VIP5，并立即设为当前版本。
    /// 仅执行一次，之后尊重用户在选择器中的手动切换。
    private func applyVIP5CurrentSnapshotDefaultsIfNeeded() {
        let migrationKey = "sequenceFilter.vip5.currentSnapshot.migration.v1"
        let defaults = UserDefaults.standard
        guard !defaults.bool(forKey: migrationKey) else { return }

        let sourceVersionID = selectedConditionVersionID
        let fallbackInput = persistedCurrentConditionInputForMaintenance()
        let currentInput = (try? FilterConfig.parse(generatedInput))?.normalizedInput
            ?? (try? FilterConfig.parse(fallbackInput))?.normalizedInput
            ?? fallbackInput
        defaults.set(currentInput, forKey: vip5SnapshotStorageKey)
        defaults.set(sourceVersionID, forKey: vip5SourceVersionStorageKey)

        selectedConditionVersionID = "vip5-current-snapshot"
        disableAllVIP5ConditionSwitches()
        var values = defaults.dictionary(forKey: inputDefaultsStorageKey) as? [String: String] ?? [:]
        values.merge(persistedInputValues) { _, current in current }
        values["selectedConditionVersionID"] = selectedConditionVersionID
        defaults.set(values, forKey: inputDefaultsStorageKey)
        defaults.set(selectedConditionVersionID, forKey: lastVIPConditionVersionStorageKey)
        defaults.set(true, forKey: migrationKey)
        defaults.removeObject(forKey: previousRunStorageKey)
        defaults.removeObject(forKey: globalFilterCountsCacheStorageKey)
        defaults.removeObject(forKey: globalFilterConditionsSignatureStorageKey)
        defaults.removeObject(forKey: globalPrizeLastSyncStorageKey)
        defaults.synchronize()
        conditionVersionMessage = "已将XS当前数值设为VIP Version 5，条件Tab全部过滤开关已关闭。"
    }

