    /// 旧版用“切到V1”表示关闭VIP。升级后只迁移总开关状态，绝不重载任何条件版本。
    private func applyVIPMasterSwitchMigrationIfNeeded() {
        let migrationKey = "sequenceFilter.vipMasterSwitch.migration.v2"
        let defaults = UserDefaults.standard
        guard !defaults.bool(forKey: migrationKey) else { return }
        let values = defaults.dictionary(forKey: inputDefaultsStorageKey) as? [String: String] ?? [:]
        let persistedVersionID = values["selectedConditionVersionID"] ?? selectedConditionVersionID
        let lastVIPVersionID = defaults.string(forKey: lastVIPConditionVersionStorageKey)
        let isLegacyVIP5Close = persistedVersionID == "current-v1"
            && lastVIPVersionID == "vip5-current-snapshot"
        vipConditionsEnabled = vipConditionVersionIDs.contains(persistedVersionID)
        var updatedValues = values
        updatedValues["vipConditionsEnabled"] = vipConditionsEnabled ? "1" : "0"
        if isLegacyVIP5Close {
            // 旧版关闭VIP会把部分V1开关叠到VIP5数值上，形成意外的混合条件。
            // 这里只撤销这些开关，不改任何数值范围，也不载入任何默认版本。
            disableAllVIP5ConditionSwitches()
            let disabledKeys = [
                "outcomeConditionToleranceEnabled",
                "allConditionsToleranceEnabled",
                "consecutiveRunsEnabled",
                "secondaryConsecutiveRunsEnabled",
                "sameResultRunsEnabled",
                "protectConsecutiveDrawPair",
                "frontThreeMaximumFourFilterEnabled",
                "noFourPositionFilterEnabled",
                "spProductFilterEnabled",
                "customHandicapOddsProductFilterEnabled",
                "customHandicapOddsSumFilterEnabled",
                "prizeRangeFilterEnabled",
                "spRiskFilterEnabled",
                "minimumProbabilityFilterEnabled",
                "jointProbabilityFilterEnabled",
                "groupFilterEnabled",
                "prizeConditionAnalysisEnabled",
                "prizeSPRangeFilterEnabled",
                "prizeStatisticalConditionEnabled",
                "prizeStatisticalCountPatternEnabled",
                "comprehensiveAnalysisFilterEnabled",
                "protectedHistoryMaxCompressionEnabled",
                "protectedHistoryToleranceEnabled",
                "protectedHistoryBetCapEnabled",
                "universal150CompressionEnabled",
                "universal247ToleranceEnabled",
                "productSumV10Top150Enabled"
            ]
            for key in disabledKeys {
                updatedValues[key] = "0"
            }
            for condition in OutcomeCondition.editorCases {
                updatedValues["OCON_" + condition.rawValue] = "0"
            }
            updatedValues["finalReduction"] = FinalReductionMode.off.rawValue
            result = nil
            lastRunSnapshot = nil
            defaults.removeObject(forKey: previousRunStorageKey)
            defaults.removeObject(forKey: globalFilterCountsCacheStorageKey)
            defaults.removeObject(forKey: globalFilterConditionsSignatureStorageKey)
        }
        defaults.set(updatedValues, forKey: inputDefaultsStorageKey)
        defaults.set(true, forKey: migrationKey)
        defaults.synchronize()
    }

    /// 确保旧版“关闭VIP”留下的开关在SwiftUI完成首轮状态回填后也保持关闭。
    private func applyVIPOffCleanupMigrationIfNeeded() {
        let migrationKey = "sequenceFilter.vipOffCleanup.migration.v3"
        let defaults = UserDefaults.standard
        guard !defaults.bool(forKey: migrationKey),
              defaults.string(forKey: lastVIPConditionVersionStorageKey) == "vip5-current-snapshot" else { return }
        let values = defaults.dictionary(forKey: inputDefaultsStorageKey) as? [String: String] ?? [:]
        guard values["vipConditionsEnabled"] == "0"
                || values["selectedConditionVersionID"] == "current-v1" else { return }
        defaults.set(true, forKey: migrationKey)
        DispatchQueue.main.async {
            disableAllVIP5ConditionSwitches()
            result = nil
            lastRunSnapshot = nil
            DispatchQueue.main.async {
                UserDefaults.standard.set(persistedInputValues, forKey: inputDefaultsStorageKey)
                UserDefaults.standard.removeObject(forKey: previousRunStorageKey)
                UserDefaults.standard.removeObject(forKey: globalFilterCountsCacheStorageKey)
                UserDefaults.standard.removeObject(forKey: globalFilterConditionsSignatureStorageKey)
                UserDefaults.standard.synchronize()
            }
        }
    }

