              let config = try? FilterConfig.parse(normalizedInput) else {
            selectedConditionVersionID = "vip5-current-snapshot"
            disableAllVIP5ConditionSwitches()
            conditionVersionMessage = "VIP5已保留当前数值并关闭全部条件开关。"
            return
        }
        let snapshot = SavedFilterScheme(
            id: UUID(),
            name: "VIP Version 5",
            savedAt: Date(),
            issue: "",
            inputValues: [:],
            normalizedInput: config.normalizedInput,
            keptOutcomes: [],
            finalBetCount: 0
        )
        loadFilterScheme(snapshot)
        disableAllVIP5ConditionSwitches()
        selectedConditionVersionID = "vip5-current-snapshot"
        conditionVersionMessage = "已载入VIP Version 5：保留XS当前数值，条件Tab全部过滤开关已关闭。"
    }

