    private func loadSavedFilterSchemes() {
        guard let data = UserDefaults.standard.data(forKey: savedFilterSchemesStorageKey),
              let schemes = try? JSONDecoder().decode([SavedFilterScheme].self, from: data) else { return }
        savedFilterSchemes = schemes.sorted { $0.savedAt > $1.savedAt }
    }

    private func persistSavedFilterSchemes() {
        guard let data = try? JSONEncoder().encode(savedFilterSchemes) else { return }
        UserDefaults.standard.set(data, forKey: savedFilterSchemesStorageKey)
        scheduleDurableBackup()
    }

    private func saveCurrentFilterScheme() {
        do {
            let config = try FilterConfig.parse(generatedInput)
            guard let result, result.config.normalizedInput == config.normalizedInput else {
                filterSchemeMessage = "条件已变化，请先点“全局生成”再保存。"
                return
            }
            let trimmedName = filterSchemeNameInput.trimmingCharacters(in: .whitespacesAndNewlines)
            let scheme = SavedFilterScheme(
                id: UUID(),
                name: trimmedName.isEmpty ? "方案\(savedFilterSchemes.count + 1)" : trimmedName,
                savedAt: Date(),
                issue: beijingSingleIssueInput,
                inputValues: persistedInputValues,
                normalizedInput: config.normalizedInput,
                keptOutcomes: result.records.map { $0.outcomes.map(String.init).joined() },
                finalBetCount: result.finalBetCount
            )
            savedFilterSchemes.insert(scheme, at: 0)
            persistSavedFilterSchemes()
            filterSchemeNameInput = ""
            filterSchemeMessage = "已保存“\(scheme.name)”，查询赛果时会自动比较。"
        } catch {
            filterSchemeMessage = "保存失败：\(error.localizedDescription)"
        }
    }

    private func loadFilterScheme(_ scheme: SavedFilterScheme) {
        guard let config = try? FilterConfig.parse(scheme.normalizedInput) else {
            filterSchemeMessage = "该方案格式已损坏，无法载入。"
            return
        }
        disabledBasicConditions = config.disabledBasicConditions
        valueThreeMaximumInput = String(config.valueThreeMaximum)
        svip10RRangeInput = "\(config.six250RRange.lowerBound)-\(config.six250RRange.upperBound)"
        svip10ValueTwoMaximumInput = String(config.valueTwoMaximum)
        enteredConditionIDs = config.outcomeConditions.keys.map { "OC_" + $0.rawValue }.sorted()
        sumInput = "\(config.sumRange.lowerBound)-\(config.sumRange.upperBound)"
        displacementInput = "\(config.displacementRange.lowerBound)-\(config.displacementRange.upperBound)"
        if config.minimumDistinctDisplacementOrders > 0 {
            svip4MinimumDistinctMOrdersInput = String(config.minimumDistinctDisplacementOrders)
        }
        varianceInput = compactDecimal(config.varianceMaximum, maximumDigits: 4)
        valueTwoMaximumInput = String(config.valueTwoMaximum)
        frontThreeMaximumFourFilterEnabled = config.frontThreeMaximumFourCount != nil
        noFourPositionFilterEnabled = config.lowestCustomOddsNoFourEnabled || !config.noFourPositions.isEmpty
        noFourPositionInput = config.noFourPositions.first.map(String.init) ?? "1"
        svip4NoFourSelection = config.lowestCustomOddsNoFourEnabled
            ? "auto"
            : (config.noFourPositions.first.map(String.init) ?? "auto")
        secondNoFourPositionFilterEnabled = config.noFourPositions.count > 1
        secondNoFourPositionInput = config.noFourPositions.dropFirst().first.map(String.init) ?? "2"
        transitionMinimumInput = compactDecimal(config.transitionMinimumPercent, maximumDigits: 4)
        roughnessMaximumInput = String(config.roughnessMaximum)
        breakpointInput = "\(config.breakpointRange.lowerBound)-\(config.breakpointRange.upperBound)"
        productRemovalCountInput = "0"
        finalReduction = config.finalReduction
        randomSeedInput = String(config.randomSeed)
        marketWeightPercent = config.marketWeightPercent
        finalRemovalPercent = config.finalRemovalPercent
        consecutiveRunsEnabled = config.consecutiveRunsEnabled
        nonLossRunInput = "\(config.nonLossRunRange.lowerBound)-\(config.nonLossRunRange.upperBound)"
        nonDrawRunInput = "\(config.nonDrawRunRange.lowerBound)-\(config.nonDrawRunRange.upperBound)"
        nonWinRunInput = "\(config.nonWinRunRange.lowerBound)-\(config.nonWinRunRange.upperBound)"
        consecutiveRunToleranceInput = "\(config.consecutiveRunToleranceRange.lowerBound)-\(config.consecutiveRunToleranceRange.upperBound)"
        secondaryConsecutiveRunsEnabled = config.secondaryConsecutiveRunsEnabled
        secondaryConsecutiveRunRangeInput = "\(config.secondaryConsecutiveRunRange.lowerBound)-\(config.secondaryConsecutiveRunRange.upperBound)"
        secondaryConsecutiveRunToleranceInput = "\(config.secondaryConsecutiveRunToleranceRange.lowerBound)-\(config.secondaryConsecutiveRunToleranceRange.upperBound)"
        sameResultRunsEnabled = config.sameResultRunsEnabled
        winRunInput = "\(config.winRunRange.lowerBound)-\(config.winRunRange.upperBound)"
        drawRunInput = "\(config.drawRunRange.lowerBound)-\(config.drawRunRange.upperBound)"
        lossRunInput = "\(config.lossRunRange.lowerBound)-\(config.lossRunRange.upperBound)"
        sameResultRunToleranceInput = "\(config.sameResultRunToleranceRange.lowerBound)-\(config.sameResultRunToleranceRange.upperBound)"
        protectConsecutiveDrawPair = config.protectConsecutiveDrawPair
        spProductFilterEnabled = config.spProductFilterEnabled
        spProductRangeInput = "\(config.spProductRange.lowerBound)-\(config.spProductRange.upperBound)"
        customHandicapOddsProductFilterEnabled = config.customHandicapOddsProductFilterEnabled
        customHandicapOddsProductMinimum = config.customHandicapOddsProductRange.lowerBound
        customHandicapOddsProductMaximum = config.customHandicapOddsProductRange.upperBound
        customHandicapOddsSumFilterEnabled = config.customHandicapOddsSumFilterEnabled
        customHandicapOddsSumMinimum = config.customHandicapOddsSumRange.lowerBound
        customHandicapOddsSumMaximum = config.customHandicapOddsSumRange.upperBound
        prizeRangeFilterEnabled = config.prizeRangeFilterEnabled
        estimatedPrizeRangeInput = "\(config.estimatedPrizeRange.lowerBound)-\(config.estimatedPrizeRange.upperBound)"
        spRiskFilterEnabled = config.spRiskFilterEnabled
        maximumSingleSPInput = String(config.maximumSingleSP)
        highSPThresholdInput = String(config.highSPThreshold)
        highSPCountRangeInput = "\(config.highSPCountRange.lowerBound)-\(config.highSPCountRange.upperBound)"
        minimumProbabilityFilterEnabled = config.minimumProbabilityFilterEnabled
        minimumSingleProbabilityInput = String(config.minimumSingleProbabilityPercent)
        jointProbabilityFilterEnabled = config.jointProbabilityFilterEnabled
        jointProbabilityRangeInput = "\(config.jointProbabilityPercentRange.lowerBound)-\(config.jointProbabilityPercentRange.upperBound)"
        svip5TailReductionEnabled = false
        svip5FourCountFilterEnabled = config.svip5FourCountFilterEnabled
        frontFiveActualMEnabled = config.frontFiveActualMEnabled
        frontFiveActualMRangeInput = "\(config.frontFiveActualMRange.lowerBound)-\(config.frontFiveActualMRange.upperBound)"
        frontFiveNoTripleDrawEnabled = config.frontFiveNoTripleDrawEnabled
        frontFiveLossCountEnabled = config.frontFiveLossCountEnabled
        frontFiveWinCountEnabled = config.frontFiveWinCountEnabled
        combinedThreeStructureEnabled = config.combinedThreeStructureEnabled
        combinedThreeRRangeInput = "\(config.combinedThreeRRange.lowerBound)-\(config.combinedThreeRRange.upperBound)"
        sixLossCount14Enabled = config.sixLossCount14Enabled
        frontFiveR39Enabled = config.frontFiveR39Enabled
        frontFiveNoTripleLossEnabled = config.frontFiveNoTripleLossEnabled
        frontFiveLossCountRangeInput = "\(config.frontFiveLossCountRange.lowerBound)-\(config.frontFiveLossCountRange.upperBound)"
        frontFiveWinCountRangeInput = "\(config.frontFiveWinCountRange.lowerBound)-\(config.frontFiveWinCountRange.upperBound)"
        vip12ProbabilityReductionEnabled = config.vip12ProbabilityReductionEnabled
        svip1CustomOddsGuardEnabled = config.svip1CustomOddsGuardEnabled
        groupFilterEnabled = config.groupFilterEnabled
        groupFilterMode = config.groupFilterMode
        frontGroupOutcomeSumInput = "\(config.frontGroupOutcomeSumRange.lowerBound)-\(config.frontGroupOutcomeSumRange.upperBound)"
        backGroupOutcomeSumInput = "\(config.backGroupOutcomeSumRange.lowerBound)-\(config.backGroupOutcomeSumRange.upperBound)"
        frontGroupSPProductInput = "\(config.frontGroupSPProductRange.lowerBound)-\(config.frontGroupSPProductRange.upperBound)"
        backGroupSPProductInput = "\(config.backGroupSPProductRange.lowerBound)-\(config.backGroupSPProductRange.upperBound)"
        prizeStatisticalConditionEnabled = config.prizeStatisticalConditionEnabled
        prizeStatisticalCountPatternEnabled = config.prizeStatisticalCountPatternEnabled
        universal150CompressionEnabled = config.universal150CompressionEnabled
        universal247ToleranceEnabled = config.universal247ToleranceEnabled
        universal247ToleranceThresholdInput = config.universal247ToleranceThreshold.formatted(
            .number.precision(.fractionLength(0...6))
        )
        productSumV10Top150Enabled = config.productSumV10Top150Enabled
        outcomeConditionInputs = Dictionary(uniqueKeysWithValues: OutcomeCondition.editorCases.map { condition in
            (condition, config.outcomeConditions[condition].map { "\($0.lowerBound)-\($0.upperBound)" } ?? "")
        })
        outcomeConditionEnabled = Dictionary(uniqueKeysWithValues: OutcomeCondition.editorCases.map { condition in
            (condition, config.outcomeConditions[condition] != nil)
        })
        outcomeConditionToleranceEnabled = config.outcomeConditionToleranceEnabled
        outcomeConditionToleranceInput = "\(config.outcomeConditionToleranceRange.lowerBound)-\(config.outcomeConditionToleranceRange.upperBound)"
        allConditionsToleranceEnabled = config.allConditionsToleranceEnabled
        allConditionsToleranceInput = "\(config.allConditionsToleranceRange.lowerBound)-\(config.allConditionsToleranceRange.upperBound)"
        result = nil
        filterSchemeMessage = "已载入“\(scheme.name)”的条件，请回到输入页重新生成。"
    }

    private func deleteFilterScheme(_ scheme: SavedFilterScheme) {
        savedFilterSchemes.removeAll { $0.id == scheme.id }
        persistSavedFilterSchemes()
        filterSchemeMessage = "已删除“\(scheme.name)”。"
    }

    private func savedSchemeComparison(issue: String, matchNumbers: [String], outcomes: [Int]) -> String {
        let comparable = savedFilterSchemes.compactMap { scheme -> String? in
            guard let config = try? FilterConfig.parse(scheme.normalizedInput),
                  Set(config.matchNumbers.compactMap(Int.init)) == Set(matchNumbers.compactMap(Int.init)) else { return nil }
            let indices = config.matchNumbers.compactMap { savedNumber in
                matchNumbers.firstIndex { Int($0) == Int(savedNumber) }
            }
            guard indices.count == outcomes.count else { return nil }
            let compact = indices.map { outcomes[$0] }.map(String.init).joined()
            return "\(scheme.name)：\(scheme.keptOutcomes.contains(compact) ? "保留" : "过滤")（\(scheme.finalBetCount)注）"
        }
        guard !comparable.isEmpty else { return "" }
        return "\n多套方案复盘（\(issue)）：\n" + comparable.joined(separator: "\n")
    }

    private func loadPreviousRunSnapshot() {
        if let savedIssue = UserDefaults.standard.string(forKey: goalModelIssueStorageKey),
           !savedIssue.isEmpty {
            beijingSingleIssueInput = savedIssue
        }
        if let historyData = UserDefaults.standard.data(forKey: goalModelHistoryStorageKey),
           let history = try? JSONDecoder().decode([GoalModelRecommendationSnapshot].self, from: historyData) {
            recommendationHistory = history
        }
        guard let data = UserDefaults.standard.data(forKey: previousRunStorageKey),
              let snapshot = try? JSONDecoder().decode(PreviousRunSnapshot.self, from: data) else {
            return
        }
        lastRunSnapshot = snapshot
        if recommendationHistory.isEmpty,
           let config = try? FilterConfig.parse(snapshot.normalizedInput) {
            saveGoalModelRecommendation(
                issue: beijingSingleIssueInput,
                matchNumbers: config.matchNumbers,
                logic: config.logic.map(\.displayName).joined()
            )
        }
    }

    private func savePreviousRunSnapshot(
        from result: FilterResult,
        analyzedPreviousOutcomes: [Int]?,
        analyzedPreviousLogic: [LogicMapping]?,
        analyzedPreviousHit: Int?
    ) {
        let snapshot = PreviousRunSnapshot(
            savedAt: Date(),
            normalizedInput: result.config.normalizedInput,
            keptOutcomes: result.records.map(\.compactOutcomes),
            removedOutcomes: result.removedRecords.map(\.compactOutcomes),
            randomSeed: nil,
            modelCoveragePercent: result.modelCoveragePercent,
            analyzedPreviousOutcome: analyzedPreviousOutcomes?.map(String.init).joined(),
            analyzedPreviousLogic: analyzedPreviousLogic?.map(\.displayName).joined(),
            analyzedPreviousHit: analyzedPreviousHit
        )
        guard let data = try? JSONEncoder().encode(snapshot) else { return }
        UserDefaults.standard.set(data, forKey: previousRunStorageKey)
        lastRunSnapshot = snapshot
        scheduleDurableBackup()
    }

    private var previousRunStorageKey: String {
        "sequenceFilter.previousRun.v1"
    }

    private var prizeQueryHistoryStorageKey: String {
        "sequenceFilter.prizeQueryHistory.v1"
    }

    private var vip1FrozenPrizeRecordsStorageKey: String {
        "sequenceFilter.vip1FrozenPrizeRecords.v1"
    }

    private func loadExplicitTXTShareHistory() {
        let defaults = UserDefaults.standard
        let saved = defaults.data(forKey: ExplicitTXTShareArchive.storageKey)
            .flatMap { try? JSONDecoder().decode([SharedTXTQueryRecord].self, from: $0) } ?? []
        let legacy = defaults.dictionary(forKey: ExplicitTXTShareArchive.legacyBackupKey) ?? [:]
        legacyTXTArchive = ["sequenceFilter.sharedTXTQueryHistory.v1", "sequenceFilter.recentTXTQueryHistory.v1"]
            .flatMap { key in (legacy[key] as? Data).flatMap { try? JSONDecoder().decode([SharedTXTQueryRecord].self, from: $0) } ?? [] }
        // Adopt only explicit evidence if a newer archive was previously restored.
        // An old sharedAt, filename or existing file does not prove a share click.
        explicitTXTShareHistory = ExplicitTXTShareArchive.confirmed(legacyTXTArchive + saved)
    }

    private func persistExplicitTXTShareHistory() {
        guard let data = try? JSONEncoder().encode(explicitTXTShareHistory) else { return }
        UserDefaults.standard.set(data, forKey: ExplicitTXTShareArchive.storageKey)
        UserDefaults.standard.synchronize()
        scheduleDurableBackup()
    }

    private func recordExplicitTXTShare(_ snapshot: SharedTXTQueryRecord?) {
        guard let snapshot else { return }
        explicitTXTShareHistory = ExplicitTXTShareArchive.admitting(snapshot, into: explicitTXTShareHistory)
        persistExplicitTXTShareHistory()
    }

    private var localTXTArchiveRecords: [SharedTXTQueryRecord] {
        var byID: [UUID: SharedTXTQueryRecord] = [:]
        for record in legacyTXTArchive + sharedTXTQueryHistory + recentTXTQueryHistory where record.txtContent != nil { byID[record.id] = record }
        return byID.values.sorted { $0.sharedAt > $1.sharedAt }
    }

    private var localTXTArchivePage: some View {
        List {
            Section {
                Text("本机生成、导入和旧TXT原样保留；这些记录不自动进入查询Tab。打开所需TXT并点击分享后，查询Tab才会收录那次实际分享的内容。")
                    .font(.caption).foregroundStyle(.secondary)
            }
            ForEach(localTXTArchiveRecords) { record in
                recentTXTQueryRecordRow(record, canVerify: false)
            }
        }
        .navigationTitle("本机TXT存档")
    }

    private func sharePreviewTXT(_ preview: TXTPreview) {
        guard let source = preview.sharingRecord ?? preview.editingContext?.record else {
            txtExclusionMessage = "缺少这份TXT的投注快照，无法分享；请从本机TXT存档重新打开。"
            return
        }
        do {
            let url = try writeShareFile(filename: preview.shareURL.lastPathComponent, text: preview.content)
            let snapshot = try ExplicitTXTShareArchive.snapshot(source: source, text: preview.content, filename: url.lastPathComponent)
            previewShareableReport = ShareableReport(url: url, txtSnapshot: snapshot)
        } catch { txtExclusionMessage = "分享失败：\(error.localizedDescription)" }
    }

    private var recentTXTQueryHistoryStorageKey: String {
        "sequenceFilter.recentTXTQueryHistory.v1"
    }

    @MainActor
    private func loadRecentTXTQueryHistory(legacyData: Data?) async {
        let data = UserDefaults.standard.data(forKey: recentTXTQueryHistoryStorageKey)
        let loaded = await Task.detached(priority: .utility) {
            let decoder = JSONDecoder()
            let archived = data.flatMap { try? decoder.decode([SharedTXTQueryRecord].self, from: $0) } ?? []
            var legacy = legacyData.flatMap { try? decoder.decode([SharedTXTQueryRecord].self, from: $0) } ?? []
            for index in legacy.indices {
                let message = legacy[index].verificationMessage ?? ""
                if message.hasPrefix("手动赛果") || message.contains("达到自动判定条件") || message.contains("超过2小时") {
                    legacy[index].isFinalResult = false
                    legacy[index].observedOutcomes = nil
                }
                legacy[index].isHit = RecentTXTQueryArchive.hit(
                    bets: legacy[index].betOutcomes,
                    outcomes: legacy[index].observedOutcomes ?? [],
                    isFinal: legacy[index].isFinalResult
                )
                legacy[index].verificationMessage = nil
            }
            return RecentTXTQueryArchive.retained(legacy + archived)
        }.value
        recentTXTQueryHistory = RecentTXTQueryArchive.retained(loaded + recentTXTQueryHistory)
        hasLoadedRecentTXTQueryHistory = true
        saveRecentTXTQueryHistory()
    }

    /// 保存原文和投注快照。后续条件变更或历史维护不能覆盖此存档。
    private func archiveRecentTXTRecord(_ record: SharedTXTQueryRecord) {
        var snapshot = record
        snapshot.isHit = RecentTXTQueryArchive.hit(
            bets: record.betOutcomes,
            outcomes: record.observedOutcomes ?? [],
            isFinal: record.isFinalResult
        )
        snapshot.verificationMessage = nil
        recentTXTQueryHistory.append(snapshot)
        saveRecentTXTQueryHistory()
    }

    private func saveRecentTXTQueryHistory() {
        let records = RecentTXTQueryArchive.retained(recentTXTQueryHistory)
        recentTXTQueryHistory = records
        guard hasLoadedRecentTXTQueryHistory else { return }
        let storageKey = recentTXTQueryHistoryStorageKey
        recentTXTHistoryPersistenceTask?.cancel()
        recentTXTHistoryPersistenceTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 250_000_000)
            guard !Task.isCancelled else { return }
            let data = await Task.detached(priority: .utility) {
                try? JSONEncoder().encode(records)
            }.value
            guard !Task.isCancelled, let data else { return }
            UserDefaults.standard.set(data, forKey: storageKey)
            scheduleDurableBackup()
        }
    }

    private func persistRecentTXTHistoryImmediately() {
        guard hasLoadedRecentTXTQueryHistory,
              let data = try? JSONEncoder().encode(RecentTXTQueryArchive.retained(recentTXTQueryHistory)) else { return }
        UserDefaults.standard.set(data, forKey: recentTXTQueryHistoryStorageKey)
    }

    @MainActor
    private func verifyRecentTXTRecords() async {
        guard !isVerifyingRecentTXTRecords else { return }
        isVerifyingRecentTXTRecords = true
        defer { isVerifyingRecentTXTRecords = false }
        let cutoff = Date().addingTimeInterval(-RecentTXTQueryArchive.retentionInterval)
        let ids = explicitTXTShareHistory.reversed().filter { ($0.explicitShareInitiatedAt ?? .distantPast) >= cutoff }.map(\.id)
        for id in ids {
            guard !Task.isCancelled else { return }
            await verifyRecentTXTRecord(id)
        }
    }

    @MainActor
    private func verifyRecentTXTRecord(_ id: UUID) async {
        guard !verifyingRecentTXTRecordIDs.contains(id),
              let record = explicitTXTShareHistory.first(where: { $0.id == id }),
              record.matchNumbers.count >= 6 else { return }
        verifyingRecentTXTRecordIDs.insert(id)
        defer { verifyingRecentTXTRecordIDs.remove(id) }
        do {
            let anchor = UserDefaults.standard.string(forKey: goalModelIssueStorageKey) ?? beijingSingleIssueInput
            let issue = try await FiveHundredBeijingSingleClient.resolveIssue(input: record.issue, anchorIssue: anchor)
            let fetched = try await fetchQueryMatchesWithScoreboardFallback(
                issue: issue,
                matchNumbers: Array(record.matchNumbers.prefix(6))
            )
            try Task.checkCancellation()
            let matches = fetched.matches
            let final = QueryFinalityGate.permitsResult(matches: matches, expectedCount: 6)
            let outcomes = matches.map(QueryFinalityGate.resolvedOutcome)
            let hit = await Task.detached(priority: .userInitiated) {
                RecentTXTQueryArchive.hit(bets: record.betOutcomes, outcomes: outcomes, isFinal: final)
            }.value
            try Task.checkCancellation()
            guard let index = explicitTXTShareHistory.firstIndex(where: { $0.id == id }) else { return }
            explicitTXTShareHistory[index].lastCheckedAt = Date()
            explicitTXTShareHistory[index].observedOutcomes = final ? outcomes : nil
            explicitTXTShareHistory[index].observedHandicaps = matches.map(\.handicap)
            explicitTXTShareHistory[index].isFinalResult = final
            explicitTXTShareHistory[index].isHit = hit
            explicitTXTShareHistory[index].verificationMessage = hit.map {
                $0 ? "已核对保存的TXT：前六场命中。" : "已核对保存的TXT：前六场未命中。"
            } ?? "前六场尚未全部最终结束或赛果未齐，暂不判断命中。"
            persistExplicitTXTShareHistory()
        } catch is CancellationError {
            return
        } catch {
            guard let index = explicitTXTShareHistory.firstIndex(where: { $0.id == id }) else { return }
            explicitTXTShareHistory[index].lastCheckedAt = Date()
            explicitTXTShareHistory[index].verificationMessage = "查询失败：\(error.localizedDescription)，请稍后重试。"
            persistExplicitTXTShareHistory()
        }
    }

    private var sharedTXTQueryHistoryStorageKey: String {
        "sequenceFilter.sharedTXTQueryHistory.v1"
    }

    private func loadSharedTXTQueryHistory() {
        guard let data = UserDefaults.standard.data(forKey: sharedTXTQueryHistoryStorageKey),
              let records = try? JSONDecoder().decode([SharedTXTQueryRecord].self, from: data) else { return }
        let originalCount = records.count
        var normalized = deduplicatedSharedTXTRecords(records)
        var invalidatedOldConclusions = false
        // 旧版允许手动赛果直接出结果，也曾将延迟2小时的场次自动判定。
        // 升级后先撤销这些旧结论，必须重新通过终局门禁。
        for index in normalized.indices {
            let message = normalized[index].verificationMessage ?? ""
            let usedLegacyPrematureResult = message.hasPrefix("手动赛果")
                || message.contains("达到自动判定条件")
                || message.contains("超过2小时")
            if usedLegacyPrematureResult {
                normalized[index].observedOutcomes = nil
                normalized[index].isFinalResult = false
                normalized[index].isHit = nil
                normalized[index].prizeAmount = nil
                normalized[index].prizeSPValues = nil
                normalized[index].verificationMessage = "旧版提前判定已撤销；比赛未全部最终结束时不返回查询结果，明确延期超过12小时的场次才按1计算。"
                invalidatedOldConclusions = true
            }
        }
        for index in normalized.indices where !isCurrentConditionTXT(normalized[index]) {
            if normalized[index].isHit != nil
                || normalized[index].prizeAmount != nil
                || normalized[index].prizeSPValues != nil
                || normalized[index].verificationMessage != "旧条件TXT已失效，禁止复用；请按当前条件重新生成。" {
                normalized[index].isHit = nil
                normalized[index].prizeAmount = nil
                normalized[index].prizeSPValues = nil
                normalized[index].verificationMessage = "旧条件TXT已失效，禁止复用；请按当前条件重新生成。"
                invalidatedOldConclusions = true
            }
        }
        sharedTXTQueryHistory = normalized
        if normalized.count != originalCount || invalidatedOldConclusions,
           let encoded = try? JSONEncoder().encode(normalized) {
            // 不再依赖 @State 在同一启动事务中已经提交，
            // 避免下次启动又保存到旧的 1 条或重复记录。
            UserDefaults.standard.set(encoded, forKey: sharedTXTQueryHistoryStorageKey)
        }
    }

    private func saveSharedTXTQueryHistory() {
        let normalized = deduplicatedSharedTXTRecords(sharedTXTQueryHistory)
        let storageKey = sharedTXTQueryHistoryStorageKey
        if normalized.count != sharedTXTQueryHistory.count {
            sharedTXTQueryHistory = normalized
        }
        sharedTXTHistoryPersistenceTask?.cancel()
        sharedTXTHistoryPersistenceTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 250_000_000)
            guard !Task.isCancelled else { return }
            let saved = await Task.detached(priority: .utility) {
                guard let data = try? JSONEncoder().encode(normalized) else { return false }
                UserDefaults.standard.set(data, forKey: storageKey)
                return true
            }.value
            guard !Task.isCancelled, saved else { return }
            scheduleDurableBackup()
        }
        schedulePrizeDerivedStatisticsRefresh()
    }

    private func persistSharedTXTHistoryImmediately() {
        if let data = try? JSONEncoder().encode(sharedTXTQueryHistory) {
            UserDefaults.standard.set(data, forKey: sharedTXTQueryHistoryStorageKey)
        }
    }

    private func upsertSharedTXTQueryRecord(_ record: SharedTXTQueryRecord) {
        var record = record
        if record.generationCustomOdds == nil,
           currentTXTGenerationIssue == record.issue,
           let generated = result,
           generated.config.normalizedInput == record.normalizedInput {
            record.generationCustomOdds = generated.queryCustomOdds
        }
        let key = TXTQueryStatisticsCalculator.ticketKey(issue: record.issue, matchNumbers: record.matchNumbers)
        sharedTXTQueryHistory.removeAll {
            TXTQueryStatisticsCalculator.ticketKey(issue: $0.issue, matchNumbers: $0.matchNumbers) == key
        }
        sharedTXTQueryHistory.append(record)
        saveSharedTXTQueryHistory()
    }

    private func deduplicateSharedTXTQueryHistory() {
        sharedTXTQueryHistory = deduplicatedSharedTXTRecords(sharedTXTQueryHistory)
    }

    private func deduplicatedSharedTXTRecords(
        _ records: [SharedTXTQueryRecord]
    ) -> [SharedTXTQueryRecord] {
        var unique: [String: SharedTXTQueryRecord] = [:]
        for record in records {
            let key = TXTQueryStatisticsCalculator.ticketKey(issue: record.issue, matchNumbers: record.matchNumbers)
            if let existing = unique[key] {
                let recordIsCurrent = isCurrentConditionTXT(record)
                let existingIsCurrent = isCurrentConditionTXT(existing)
                if existingIsCurrent && !recordIsCurrent { continue }
                if existingIsCurrent == recordIsCurrent && existing.sharedAt >= record.sharedAt { continue }
            }
            unique[key] = record
        }
        return unique.values.sorted { $0.sharedAt < $1.sharedAt }
    }

    private func handleTXTImport(_ result: Result<[URL], Error>) {
        do {
            guard let url = try result.get().first else { return }
            let accessed = url.startAccessingSecurityScopedResource()
            defer { if accessed { url.stopAccessingSecurityScopedResource() } }
            let data = try Data(contentsOf: url)
            guard let text = String(data: data, encoding: .utf8)
                ?? String(data: data, encoding: .unicode)
                ?? String(data: data, encoding: .utf16LittleEndian) else {
                throw CocoaError(.fileReadCorruptFile)
            }
            let imported = try SharedTXTImportParser.parse(text)
            let fallbackIssue = previousIssueInput.trimmingCharacters(in: .whitespacesAndNewlines)
            let issue = imported.issue ?? (fallbackIssue.isEmpty ? nil : fallbackIssue)
            guard let issue else {
                txtImportMessage = "导入失败：TXT中没有期号。请先在下方输入过往期号或日期，再上传。"
                return
            }
            previousIssueInput = issue
            let textWithIssue = imported.issue == nil ? "期号：\(issue)\n\(text)" : text
            let savedText = txtContentAddingTotalAmount(
                textWithIssue,
                betCount: imported.betOutcomes.count
            )
            let record = SharedTXTQueryRecord(
                id: UUID(),
                sharedAt: Date(),
                issue: issue,
                filename: filenameIncludingIssue(url.lastPathComponent, issue: issue),
                txtContent: savedText,
                normalizedInput: "",
                matchNumbers: imported.matchNumbers,
                betOutcomes: imported.betOutcomes,
                finalBetCount: imported.betOutcomes.count,
                conditionSignature: nil,
                lastCheckedAt: nil,
                observedOutcomes: nil,
                observedHandicaps: nil,
                verificationMessage: "TXT已导入，正在获取彩果…",
                isFinalResult: false,
                isHit: nil,
                prizeAmount: nil,
                prizeSPValues: nil
            )
            upsertSharedTXTQueryRecord(record)
            archiveRecentTXTRecord(record)
            txtImportMessage = "已读取期号和场次，正在按条件Tab当前值重新生成TXT并判定。"
            Task { await refreshSharedTXTRecordUsingCurrentConditions(record.id) }
        } catch {
            txtImportMessage = "导入失败：\(error.localizedDescription)"
        }
    }

    private func shareSavedTXTRecord(_ record: SharedTXTQueryRecord) {
        guard let text = record.txtContent else { return }
        do {
            let textWithAmount = txtContentAddingTotalAmount(
                text,
                betCount: record.finalBetCount
            )
            let fileURL = try writeShareFile(
                filename: record.filename,
                text: textWithAmount
            )
            let snapshot = try ExplicitTXTShareArchive.snapshot(source: record, text: textWithAmount, filename: fileURL.lastPathComponent)
            shareableReport = ShareableReport(url: fileURL, txtSnapshot: snapshot)
        } catch {
            txtImportMessage = "TXT生成失败：\(error.localizedDescription)"
        }
    }

    private func txtContentAddingTotalAmount(_ content: String, betCount: Int) -> String {
        guard !content.contains("总金额：") else { return content }
        var lines = content.components(separatedBy: .newlines)
        let amountLine = "总金额：\(max(0, betCount) * 2)元（\(max(0, betCount))注 × 2元）"
        if let totalIndex = lines.firstIndex(where: {
            let line = $0.trimmingCharacters(in: .whitespacesAndNewlines)
            return line.hasPrefix("最终：") || line.hasPrefix("总注数：") || line.hasPrefix("去重后总注数：")
        }) {
            lines.insert(amountLine, at: totalIndex + 1)
        } else if let issueIndex = lines.firstIndex(where: {
            $0.trimmingCharacters(in: .whitespacesAndNewlines).hasPrefix("期号：")
        }) {
            lines.insert(amountLine, at: issueIndex + 1)
        } else {
            lines.insert(amountLine, at: 0)
        }
        return lines.joined(separator: "\n")
    }

    private func makeTXTPreview(
        title: String,
        content: String,
        observedOutcomes: [Int?]?,
        editingRecord: SharedTXTQueryRecord? = nil,
        part: TXTSharePart? = nil,
        generationID: UUID? = nil,
        displayedMatchNumbers: [String]? = nil,
        previewID: UUID? = nil
    ) -> TXTPreview {
        if previewID == nil { txtExclusionMessage = nil }
        let safeTitle = title.map { character in
            character.isLetter || character.isNumber || character == "-" || character == "_"
                ? character
                : "-"
        }
        let fileURL = (try? writeShareFile(
            filename: "\(String(safeTitle.prefix(100))).txt",
            text: content
        )) ?? FileManager.default.temporaryDirectory.appendingPathComponent("TXT-preview.txt")
        return TXTPreview(
            id: previewID ?? UUID(),
            title: title,
            content: content,
            highlightedLineIndices: highlightedTXTLineIndices(
                content: content,
                observedOutcomes: observedOutcomes
            ),
            shareURL: fileURL,
            editingContext: part?.editableExportPart == nil ? nil : editingRecord.map {
                TXTEditingContext(record: $0, generationID: generationID,
                    displayedMatchNumbers: displayedMatchNumbers ?? txtDisplayedMatchNumbers(for: $0))
            },
            part: part, sharingRecord: editingRecord
        )
    }

    private func txtDisplayedMatchNumbers(for record: SharedTXTQueryRecord) -> [String] {
        if let saved = record.displayedMatchNumbers { return saved }
        if record.matchNumbers.count == 7,
           let line = record.txtContent?.components(separatedBy: .newlines).first(where: { $0.contains("→") || $0.contains("->") }),
           let parsed = try? SharedTXTImportParser.parse(line), parsed.matchNumbers.count == 6,
           Set(parsed.matchNumbers.compactMap(Int.init)) == Set(record.matchNumbers.prefix(6).compactMap(Int.init)) {
            return Array(record.matchNumbers.prefix(6))
        }
        return record.matchNumbers
    }

    private func highlightedTXTLineIndices(
        content: String,
        observedOutcomes: [Int?]?
    ) -> Set<Int> {
        guard let observedOutcomes else { return [] }
        let verificationCount = min(6, observedOutcomes.count)
        guard verificationCount > 0 else { return [] }
        let checkedOutcomes = Array(observedOutcomes.prefix(verificationCount))
        guard checkedOutcomes.allSatisfy({ $0 != nil }) else { return [] }
        let target = checkedOutcomes.compactMap { $0 }

        var highlighted = Set<Int>()
        for (index, line) in content.components(separatedBy: .newlines).enumerated() {
            guard (line.contains("→") || line.contains("->")),
                  let parsed = try? SharedTXTImportParser.parse(line) else { continue }
            if parsed.betOutcomes.contains(where: { bet in
                bet.count >= verificationCount
                    && Array(bet.prefix(verificationCount)) == target
            }) {
                highlighted.insert(index)
            }
        }
        return highlighted
    }

    /// 用查询记录自己的期号、场次、ABCD和第6/7场选项，
    /// 按条件Tab当前全部条件重新生成该条的总量TXT。
    @MainActor
    private func rebuildSharedTXTRecordUsingCurrentConditions(
        _ source: SharedTXTQueryRecord
    ) async -> Bool {
        guard source.matchNumbers.count >= 6 else { return false }
        let logic: String
        if let saved = cachedABCD(for: source) {
            logic = saved
        } else {
            do {
                logic = try await fetchHistoricalABCD(
                    issue: source.issue,
                    matchNumbers: Array(source.matchNumbers.prefix(5))
                )
                storeGlobalABCD(logic, for: source)
            } catch {
                return false
            }
        }

        guard let config = CurrentConditionConfigFactory.make(
            currentInput: generatedInput,
            historicalMatchNumbers: source.matchNumbers,
            historicalABCD: logic
        ) else {
            return false
        }

        let comprehensive = comprehensiveAnalysisFilterEnabled ? comprehensiveAnalysisProfile : nil
        let comprehensiveTolerance = comprehensiveAnalysisFilterEnabled
            ? (parsedComprehensiveAnalysisToleranceRange ?? 0...0)
            : 0...0
        let protectedProfile = protectedHistoryMaxCompressionEnabled
            ? protectedHistoryMaxCompressionProfile
            : nil
        let protectedTolerance = effectiveProtectedHistoryToleranceRange
        let protectedCap = effectiveProtectedHistoryBetCap
        let protectedPrefixes = protectedPrizeOutcomePrefixes
        let requiresLiveModelData = config.requiresSPData
            || config.requiresProbabilityData
            || SequenceFilterEngine.usesVIP4Model(
                threshold: config.universal247ToleranceThreshold
            )
            || comprehensive?.requiresSPData == true
            || comprehensive?.requiresProbabilityData == true
            || protectedProfile?.requiresSPData == true
            || protectedProfile?.requiresProbabilityData == true
        var analyses: [GoalModelAnalysis] = []
        if requiresLiveModelData {
            do {
                let requiresComparisonTableOdds = config.requiresSPData
                    || SequenceFilterEngine.usesVIP4Model(
                        threshold: config.universal247ToleranceThreshold
                    )
                    || SequenceFilterEngine.usesHandicapOddsV9Model(
                        threshold: config.universal247ToleranceThreshold
                    )
                    || comprehensive?.requiresSPData == true
                    || protectedProfile?.requiresSPData == true
                var analysisNumbers = (SequenceFilterEngine.usesVIP4Model(
                    threshold: config.universal247ToleranceThreshold
                ) || SequenceFilterEngine.usesVIP3Model(
                    threshold: config.universal247ToleranceThreshold
                ) || config.vip12ProbabilityReductionEnabled)
                    ? Array(source.matchNumbers.prefix(6))
                    : Array(source.matchNumbers.prefix(5))
                if SequenceFilterEngine.usesVIP4Model(
                    threshold: config.universal247ToleranceThreshold
                ), let first = source.matchNumbers.first.flatMap(Int.init), first > 6 {
                    analysisNumbers.append(contentsOf: ((first - 6)..<first).map(String.init))
                    analysisNumbers = Array(Set(analysisNumbers)).sorted {
                        (Int($0) ?? 0) < (Int($1) ?? 0)
                    }
                }
                if requiresComparisonTableOdds {
                    let matches = try await FiveHundredBeijingSingleClient.fetchScorePageOdds(
                        issue: source.issue,
                        matchNumbers: analysisNumbers
                    )
                    analyses = try await Task.detached(priority: .userInitiated) {
                        try matches.map(PoissonGoalModel.analyze)
                    }.value
                } else {
                    analyses = try await MultiSourceABCDClient.fetch(
                        issue: source.issue,
                        matchNumbers: analysisNumbers,
                        source: .automatic
                    ).analyses
                }
                if requiresComparisonTableOdds, let stored = source.observedHandicaps {
                    let storedByMatch = Dictionary(uniqueKeysWithValues: zip(source.matchNumbers, stored).compactMap {
                        pair -> (Int, Int)? in
                        guard let number = Int(pair.0), let handicap = pair.1 else { return nil }
                        return (number, handicap)
                    })
                    // 历史236单回放时，用存档的当时让球数输入对照表。
                    analyses = try analyses.map { analysis in
                        guard let number = Int(analysis.match.matchNumber),
                              let storedHandicap = storedByMatch[number],
                              storedHandicap != analysis.match.handicap else { return analysis }
                        return try PoissonGoalModel.analyze(
                            analysis.match.replacingHandicap(storedHandicap)
                        )
                    }
                }
            } catch {
                let hasStrictLiveRequirement = config.requiresSPData
                    || config.requiresStrictProbabilityData
                    || SequenceFilterEngine.usesVIP4Model(
                        threshold: config.universal247ToleranceThreshold
                    )
                    || comprehensive?.requiresSPData == true
                    || comprehensive?.requiresProbabilityData == true
                    || protectedProfile?.requiresSPData == true
                    || protectedProfile?.requiresProbabilityData == true
                if hasStrictLiveRequirement { return false }
                analyses = []
            }
        }
        let probabilities = outcomeProbabilityMatrix(for: config, analyses: analyses)
        let spValues = outcomeSPMatrix(for: config, analyses: analyses)
        let currentVIP3Context = vip3MatchContext(for: config, analyses: analyses)
        let currentVIP4Context = vip4MatchContext(for: config, analyses: analyses)
        let marketShares = config.matchNumbers.map { number in
            analyses.first { Int($0.match.matchNumber) == Int(number) }?
                .match.marketBettingShares ?? []
        }
        let applyRelationships = shouldApplyRelationshipCondition(
            for: config,
            analyses: analyses
        )
        let generated = await Task.detached(priority: .userInitiated) {
            SequenceFilterEngine.calculate(
                config,
                previousContext: nil,
                currentOutcomeProbabilities: probabilities,
                currentOutcomeSPs: spValues,
                vip4Context: currentVIP4Context,
                vip3Context: currentVIP3Context,
                currentMarketBettingShares: marketShares,
                applyPoissonRelationshipCondition: applyRelationships,
                comprehensiveAnalysisProfile: comprehensive,
                comprehensiveAnalysisToleranceRange: comprehensiveTolerance,
                protectedHistoryProfile: protectedProfile,
                protectedHistoryToleranceRange: protectedTolerance,
                protectedHistoryBetCap: protectedCap,
                protectedPrizeOutcomePrefixes: protectedPrefixes
            )
        }.value
        let bets = deduplicatedTXTBets(generated.uniqueExpandedBets)
        let multiplier = txtMultiplier(from: source.txtContent) ?? 1
        let rows = generated.config.txtCompactEnabled ? generatedResultTXTRows(generated) : compressedTXTRows(matchNumbers: source.matchNumbers, bets: bets)
        let text = [
            "期号：\(source.issue)",
            "TXT分组：总量",
            "生成方式：查询页按条件Tab最新条件自动重建",
            "投注倍数：\(multiplier)倍",
            sharedTXTBody(rows: rows, multiplier: multiplier, originalPassingCount: generated.config.txtCompactEnabled ? generated.preFullPackageBetCount : nil)
        ].joined(separator: "\n")
        let ticketKey = TXTQueryStatisticsCalculator.ticketKey(
            issue: source.issue,
            matchNumbers: source.matchNumbers
        )
        let matchingPrizeRecord = uniquePrizeQueryRecords.filter {
            TXTQueryStatisticsCalculator.ticketKey(
                issue: $0.issue,
                matchNumbers: $0.matchNumbers
            ) == ticketKey
        }.max {
            let leftScore = prizeRecordCompletenessScore($0)
            let rightScore = prizeRecordCompletenessScore($1)
            return leftScore == rightScore
                ? $0.queriedAt < $1.queriedAt
                : leftScore < rightScore
        }
        let stored = Array((source.observedOutcomes ?? []).prefix(6))
        let target = stored.count == 6 && stored.allSatisfy { $0 != nil }
            ? stored.compactMap { $0 }
            : matchingPrizeRecord?.outcomes.map { Array($0.prefix(6)) }
        let finalityConfirmed = source.isFinalResult || matchingPrizeRecord?.isSettled == true
        let covered = finalityConfirmed ? target.map { outcomes in
            bets.contains {
                $0.count >= 6 && Array($0.prefix(6)) == outcomes
            }
        } : nil
        let message: String
        if !finalityConfirmed {
            message = "已按条件Tab最新全部条件重建TXT；比赛未全部最终结束，暂不返回查询结果。"
        } else if let target, let covered {
            message = covered
                ? "已按条件Tab最新全部条件重建TXT；已找到实际赛果\(target.map(String.init).joined())。"
                : "已按条件Tab最新全部条件重建TXT；TXT中找不到实际赛果\(target.map(String.init).joined())。"
        } else {
            message = "已按条件Tab最新全部条件重建TXT，正在重新获取赛果。"
        }
        let rebuilt = SharedTXTQueryRecord(
            id: source.id,
            sharedAt: Date(),
            issue: source.issue,
            filename: source.filename,
            txtContent: text,
            normalizedInput: generated.config.normalizedInput,
            matchNumbers: source.matchNumbers,
            betOutcomes: bets,
            finalBetCount: bets.count,
            conditionSignature: globalFilterConditionsSignature,
            lastCheckedAt: source.lastCheckedAt,
            observedOutcomes: source.observedOutcomes,
            observedHandicaps: source.observedHandicaps,
            verificationMessage: message,
            isFinalResult: finalityConfirmed,
            isHit: covered,
            prizeAmount: covered == false ? nil : source.prizeAmount,
            prizeSPValues: covered == false ? nil : source.prizeSPValues,
            generationCustomOdds: spValues
        )
        upsertSharedTXTQueryRecord(rebuilt)
        if let prizeRecord = matchingPrizeRecord {
            globalFilterCountsByRecordID[prizeRecord.id] = GlobalPrizeFilterCounts(
                before: 729,
                removed: max(0, 729 - bets.count),
                after: bets.count,
                stageSummaries: generated.majorFilterStageSummaries,
                outcomeSignature: prizeRecordOutcomeSignature(prizeRecord),
                targetCoveredByFinalTXT: finalityConfirmed ? covered : nil,
                targetCoverageDetail: finalityConfirmed && covered == false
                    ? "本Cell已按条件Tab最新条件完整全局生成，终局TXT未找到实际赛果。"
                    : nil
            )
        }
        return true
    }

    /// 查询结果页的总开关：以全部奖金去重记录为 Cell 全集，
    /// 用本地已保存的赛果和ABCD重算当前版本TXT。这样八期200多单
    /// 不会因为以前没分享过TXT而被遗漏，也不需要大量历史网络请求。
    @MainActor
    private func verifyAllSharedTXTRecordsUsingCurrentConditions() async {
        guard !isVerifyingAllSharedTXTRecords else { return }
        sharedTXTBulkVerificationMessage = "正在读取条件Tab最新规则…"
        let total = uniquePrizeQueryRecords.count
        guard total > 0 else {
            sharedTXTBulkVerificationMessage = "当前没有可计算的单据。"
            return
        }

        isVerifyingAllSharedTXTRecords = true
        defer { isVerifyingAllSharedTXTRecords = false }
        sharedTXTBulkVerificationMessage = "正在按当前版本计算全部\(total)个 Cell…"
        let calculationTargets: [PrizeQueryRecord]? = usesCurrentFrozenVIPRules
            ? uniquePrizeQueryRecords.filter { !isVIP1FrozenRecord($0) }
            : nil
        await recomputeAllTXTAndGlobalFromCurrentRulesForMaintenance(
            targetRecords: calculationTargets
        )
        if usesCurrentFrozenVIPRules {
            let frozenKeys = Set(locallySavedVIP1FrozenRecords.map {
                TXTQueryStatisticsCalculator.ticketKey(
                    issue: $0.issue,
                    matchNumbers: $0.matchNumbers
                )
            })
            sharedTXTQueryHistory.removeAll { record in
                frozenKeys.contains(
                    TXTQueryStatisticsCalculator.ticketKey(
                        issue: record.issue,
                        matchNumbers: record.matchNumbers
                    )
                )
            }
            saveSharedTXTQueryHistory()
        }
        let merged = mergedHistoricalPrizeRecords
        let frozen = merged.filter(isCurrentFrozenV11Record)
        let effective = merged.filter { !isCurrentFrozenV11Record($0) }
        let passed = effective.filter { prizeUnderlyingConditionStatus(for: $0).passes }.count
        let failed = effective.count - passed
        let calculated = merged.filter { globalFilterCounts(for: $0) != nil }.count
        sharedTXTBulkVerificationMessage = frozen.isEmpty
            ? "已按条件Tab当前版本完整计算\(calculated)/\(merged.count)个26091—26098 Cell；通过\(passed)单、未通过\(failed)单。"
            : "已按V11完整计算\(calculated)/\(merged.count)个26091—26098 Cell；冻结\(frozen.count)单，有效\(effective.count)单中通过\(passed)单、未通过\(failed)单。"
        archiveCurrentCalculationVersion(source: "查询Tab按当前全部条件更新所有Cell")
    }

    /// 单条刷新也必须先用条件Tab当前值完整生成新TXT，再查询赛果。
    /// 即使旧记录的条件签名仍相同，也不允许跳过本次全局生成。
    @MainActor
    private func refreshSharedTXTRecordUsingCurrentConditions(_ id: UUID) async {
        guard !refreshingSharedTXTRecordIDs.contains(id),
              let source = sharedTXTQueryHistory.first(where: { $0.id == id }) else { return }
        refreshingSharedTXTRecordIDs.insert(id)
        defer { refreshingSharedTXTRecordIDs.remove(id) }
        guard await rebuildSharedTXTRecordUsingCurrentConditions(source) else {
            if let index = sharedTXTQueryHistory.firstIndex(where: { $0.id == id }) {
                sharedTXTQueryHistory[index].isHit = nil
                sharedTXTQueryHistory[index].prizeAmount = nil
                sharedTXTQueryHistory[index].verificationMessage = "未能按条件Tab当前值重新生成TXT：请检查该期号、场次和ABCD。"
                saveSharedTXTQueryHistory()
            }
            return
        }
        verifySharedTXTRecord(id)
        while verifyingSharedTXTRecordIDs.contains(id), !Task.isCancelled {
            try? await Task.sleep(nanoseconds: 150_000_000)
        }
    }

    private func verifySharedTXTRecord(_ id: UUID) {
        guard let record = sharedTXTQueryHistory.first(where: { $0.id == id }),
              !verifyingSharedTXTRecordIDs.contains(id) else { return }
        guard isCurrentConditionTXT(record) else {
            if let index = sharedTXTQueryHistory.firstIndex(where: { $0.id == id }) {
                sharedTXTQueryHistory[index].isHit = nil
                sharedTXTQueryHistory[index].prizeAmount = nil
                sharedTXTQueryHistory[index].prizeSPValues = nil
                sharedTXTQueryHistory[index].verificationMessage = "旧条件TXT已失效，禁止查询复用；请按当前条件重新生成。"
                saveSharedTXTQueryHistory()
            }
            return
        }
        verifyingSharedTXTRecordIDs.insert(id)
        // 先落库“正在查询”，即使历史场次的数据源超时，用户也能确认本次点击已生效。
        if let index = sharedTXTQueryHistory.firstIndex(where: { $0.id == id }) {
            sharedTXTQueryHistory[index].lastCheckedAt = Date()
            sharedTXTQueryHistory[index].verificationMessage = "正在查询第\(record.issue)期第\(record.matchNumbers.prefix(6).joined(separator: "、"))场赛果…"
            sharedTXTQueryHistory[index].isFinalResult = false
            sharedTXTQueryHistory[index].isHit = nil
            sharedTXTQueryHistory[index].prizeAmount = nil
            sharedTXTQueryHistory[index].prizeSPValues = nil
            saveSharedTXTQueryHistory()
        }
        Task {
            defer { verifyingSharedTXTRecordIDs.remove(id) }
            do {
                let anchor = UserDefaults.standard.string(forKey: goalModelIssueStorageKey)
                    ?? beijingSingleIssueInput
                let resolvedIssue = try await FiveHundredBeijingSingleClient.resolveIssue(
                    input: record.issue,
                    anchorIssue: anchor
                )
                let verificationCount = min(6, record.matchNumbers.count)
                let verifiedMatchNumbers = Array(record.matchNumbers.prefix(verificationCount))
                let fetchedMatches = try await fetchQueryMatchesWithScoreboardFallback(
                    issue: resolvedIssue,
                    matchNumbers: verifiedMatchNumbers
                )
                let matches = fetchedMatches.matches
                let postponedOver12HourIndices = Set(matches.indices.filter {
                    matches[$0].isPostponedOver12Hours
                })
                let outcomes = matches.map(QueryFinalityGate.resolvedOutcome)
                var seenBets = Set<[Int]>()
                let checkedBets = record.betOutcomes.compactMap { bet -> [Int]? in
                    guard bet.count >= verificationCount else { return nil }
                    let checked = Array(bet.prefix(verificationCount))
                    return seenBets.insert(checked).inserted ? checked : nil
                }
                let compatibleBets = checkedBets.filter { bet in
                    return zip(bet, outcomes).allSatisfy { expected, actual in
                        actual == nil || actual == expected
                    }
                }
                let allFinishedOrPostponedOver12Hours = matches.count == verificationCount
                    && matches.allSatisfy {
                        QueryFinalityGate.isFinallyEnded($0) || $0.isPostponedOver12Hours
                    }
                // 只有六场都最终结束且真实让球赛果齐全才允许出结果。
                // 唯一例外：数据源明确写出延期超过12小时时，该场按1处理。
                let final = QueryFinalityGate.permitsResult(
                    matches: matches,
                    expectedCount: verificationCount
                )
                let hit = final ? !compatibleBets.isEmpty : nil
                let prizeSPValues: [Double]? = {
                    guard final, hit == true, verificationCount == 6 else { return nil }
                    let values = matches.enumerated().compactMap { index, match in
                        postponedOver12HourIndices.contains(index)
                            ? 1.0
                            : PrizeCalculator.selectedSP(for: match)
                    }
                    return values.count == 6 ? values : nil
                }()
                let prizeAmount = prizeSPValues.map { $0.reduce(1.3, *) }
                let postponedNote = postponedOver12HourIndices.isEmpty
                    ? ""
                    : "；场次\(postponedOver12HourIndices.sorted().map { matches[$0].matchNumber }.joined(separator: "、"))延期超过12小时，按1计算"
                let message: String
                if !allFinishedOrPostponedOver12Hours {
                    message = "前\(verificationCount)场尚未全部最终结束：暂不返回通过、未通过、命中、未命中或奖金结果。"
                } else if !final {
                    message = "前\(verificationCount)场已结束，但让球赛果尚未完整发布：暂不返回查询结果。"
                } else if !compatibleBets.isEmpty {
                    if let prizeAmount {
                        message = "前\(verificationCount)场已满足终局门禁\(postponedNote)：命中。奖金¥\(String(format: "%.2f", prizeAmount))。第7场不参与判定。"
                    } else {
                        message = "前\(verificationCount)场已满足终局门禁\(postponedNote)：命中。当前尚无完整6场SP，暂不能计算奖金。第7场不参与判定。"
                    }
                } else {
                    let reason = await sharedTXTNoHitReason(record: record, outcomes: outcomes, matches: matches, isFinal: final)
                    message = "前\(verificationCount)场已满足终局门禁\(postponedNote)：未命中。\(reason)"
                }
                guard isCurrentConditionTXT(record),
                      let index = sharedTXTQueryHistory.firstIndex(where: { $0.id == id }),
                      sharedTXTQueryHistory[index].sharedAt == record.sharedAt else { return }
                sharedTXTQueryHistory[index].issue = resolvedIssue
                sharedTXTQueryHistory[index].lastCheckedAt = Date()
                sharedTXTQueryHistory[index].observedOutcomes = final ? outcomes : nil
                sharedTXTQueryHistory[index].observedHandicaps = matches.map(\.handicap)
                sharedTXTQueryHistory[index].verificationMessage = message + (fetchedMatches.usedScoreboard
                    ? "（已自动使用比分Tab整期比分兜底）"
                    : "")
                sharedTXTQueryHistory[index].isFinalResult = final
                sharedTXTQueryHistory[index].isHit = hit
                sharedTXTQueryHistory[index].prizeAmount = prizeAmount
                sharedTXTQueryHistory[index].prizeSPValues = prizeSPValues
                saveSharedTXTQueryHistory()
                if final {
                    await syncSharedTXTQueryResultToGlobalAnswers(
                        sharedTXTQueryHistory[index],
                        matches: matches,
                        outcomes: outcomes
                    )
                }
            } catch {
                guard let index = sharedTXTQueryHistory.firstIndex(where: { $0.id == id }) else { return }
                sharedTXTQueryHistory[index].lastCheckedAt = Date()
                sharedTXTQueryHistory[index].verificationMessage = "查询失败：\(error.localizedDescription)。比赛中或数据源尚未更新时，可稍后重试。"
                sharedTXTQueryHistory[index].isFinalResult = false
                sharedTXTQueryHistory[index].isHit = nil
                sharedTXTQueryHistory[index].prizeAmount = nil
                sharedTXTQueryHistory[index].prizeSPValues = nil
                saveSharedTXTQueryHistory()
            }
        }
    }

    private func isFinishedMatch(_ match: BeijingSingleMatch) -> Bool {
        QueryFinalityGate.isFinallyEnded(match)
    }

    /// 查询页统一赛况入口：常规按场次获取失败，或返回的场次没有比分时，
    /// 自动拉取“比分”Tab使用的整期数据，再按场次号回填。
    @MainActor
    private func fetchQueryMatchesWithScoreboardFallback(
        issue: String,
        matchNumbers: [String]
    ) async throws -> (matches: [BeijingSingleMatch], usedScoreboard: Bool) {
        var primaryMatches: [BeijingSingleMatch]?
        do {
            primaryMatches = try await FiveHundredBeijingSingleClient.fetchLiveMatches(
                issue: issue,
                matchNumbers: matchNumbers
            )
        } catch {
            primaryMatches = nil
        }

        if let primaryMatches,
           primaryMatches.allSatisfy({ $0.homeScore != nil && $0.awayScore != nil }) {
            return (primaryMatches, false)
        }

        do {
            let scoreboard = try await FiveHundredBeijingSingleClient.fetchIssueScoreboard(issue: issue)
            let keepsCurrentPage = scoreLoadedIssue == issue
            let pageCount = ScoreMatchPagination.pageRanges(totalCount: scoreboard.count).count
            scoreMatches = scoreboard
            scoreSelectedPage = keepsCurrentPage
                ? min(scoreSelectedPage, max(0, pageCount - 1))
                : 0
            scoreLoadedIssue = issue
            scoreLastUpdatedAt = Date()
            scoreMessage = "查询页未取到完整比分，已自动从比分Tab整期数据补取。"

            let selected = try matchNumbers.map { number -> BeijingSingleMatch in
                guard let scoreMatch = scoreboard.first(where: { Int($0.matchNumber) == Int(number) }) else {
                    if let original = primaryMatches?.first(where: { Int($0.matchNumber) == Int(number) }) {
                        return original
                    }
                    throw GoalModelError.matchNotFound(number)
                }
                guard let original = primaryMatches?.first(where: {
                    Int($0.matchNumber) == Int(number)
                }) else { return scoreMatch }
                return BeijingSingleMatch(
                    issue: issue,
                    matchNumber: original.matchNumber,
                    fixtureID: scoreMatch.fixtureID.isEmpty ? original.fixtureID : scoreMatch.fixtureID,
                    league: scoreMatch.league.isEmpty ? original.league : scoreMatch.league,
                    matchTime: scoreMatch.matchTime.isEmpty ? original.matchTime : scoreMatch.matchTime,
                    status: scoreMatch.status.isEmpty ? original.status : scoreMatch.status,
                    homeTeam: scoreMatch.homeTeam.isEmpty ? original.homeTeam : scoreMatch.homeTeam,
                    awayTeam: scoreMatch.awayTeam.isEmpty ? original.awayTeam : scoreMatch.awayTeam,
                    handicap: scoreMatch.handicap ?? original.handicap,
                    referenceSP: original.referenceSP.isEmpty ? scoreMatch.referenceSP : original.referenceSP,
                    marketOdds: original.marketOdds.isEmpty ? scoreMatch.marketOdds : original.marketOdds,
                    marketBettingShares: original.marketBettingShares.isEmpty
                        ? scoreMatch.marketBettingShares
                        : original.marketBettingShares,
                    homeScore: scoreMatch.homeScore ?? original.homeScore,
                    awayScore: scoreMatch.awayScore ?? original.awayScore,
                    settledSP: original.settledSP ?? scoreMatch.settledSP
                )
            }
            return (selected, true)
        } catch {
            if let primaryMatches { return (primaryMatches, false) }
            throw error
        }
    }

    /// 旧版内置电脑快照入口永久停用。
    /// 保留空实现是为了防止维护分支无意中恢复调用旧数据。
    @MainActor
    private func importComputerVerifiedQuerySnapshots() -> Int {
        0
    }

    /// 移除旧版在TXT查询结果中持久化的“旧条件结论”。保留赛果和投注差异，
    /// 条件结论统一由当前条件Tab实时显示，避免出现已取消的“第3场判定值为4”。
    @MainActor
    private func removeLegacyTXTConditionConclusions() -> Int {
        var cleaned = 0
        for index in sharedTXTQueryHistory.indices {
            guard let message = sharedTXTQueryHistory[index].verificationMessage,
                  let range = message.range(of: "\n结论：") else { continue }
            sharedTXTQueryHistory[index].verificationMessage = String(message[..<range.lowerBound])
            cleaned += 1
        }
        if cleaned > 0 { saveSharedTXTQueryHistory() }
        return cleaned
    }

    /// 真机只整理查询赛果并导入电脑缓存；不在手机上运行过滤引擎。
    @MainActor
    private func refreshAllQueryConditionJudgments() async {
        guard !isRefreshingQueryConditions else { return }
        isRefreshingQueryConditions = true
        defer { isRefreshingQueryConditions = false }

        let cleanedLegacyMessages = removeLegacyTXTConditionConclusions()
        // 禁止再导入 App 内置的旧电脑快照。只同步查询页当前保存的原始赛果，
        // 并且只接受条件签名＋赛果签名都一致的新电脑计算结果。
        let synced = syncStoredQueryResultsToGlobalAnswersFromCache()
        importComputerGeneratedGlobalAnswerCache()
        refreshProtectedPrizeOutcomePrefixesCache()
        let records = uniquePrizeQueryRecords
        guard !records.isEmpty else {
            queryConditionsRefreshMessage = "没有可按当前条件复核的查询记录。"
            return
        }
        let computerReady = records.filter { record in
            guard let counts = globalFilterCounts(for: record) else { return false }
            return counts.outcomeSignature == prizeRecordOutcomeSignature(record)
        }
        let passed = computerReady.filter(globalPrizeRecordPasses).count
        let pending = records.count - computerReady.count
        let profileText = protectedHistoryMaxCompressionEnabled ? "，已包含大压缩" : ""
        queryConditionsRefreshMessage = "已清除\(cleanedLegacyMessages)条旧结论；未导入任何内置旧快照。与当前条件签名及赛果签名都一致的电脑结果\(computerReady.count)条：通过\(passed)条、未通过\(computerReady.count - passed)条、待电脑按最新条件计算\(pending)条\(profileText)。"
        globalPrizeAnswerMessage = "\(synced > 0 ? "已同步\(synced)条查询赛果；" : "")手机未运行过滤引擎，待计算记录\(pending)条。"
    }

    /// 查询Tab每次得到赛果后都写入奖金Tab的去重记录，并立即刷新“全局答案”缓存。
    /// 这样无需再手动进入奖金页点击更新，期号＋场次仍是唯一键。
    @MainActor
    private func syncSharedTXTQueryResultToGlobalAnswers(
        _ sharedRecord: SharedTXTQueryRecord,
        matches: [BeijingSingleMatch],
        outcomes: [Int?]
    ) async {
        guard sharedRecord.matchNumbers.count >= 6 else { return }
        let firstSixOutcomes = outcomes.prefix(6).compactMap { $0 }
        let spValues = sharedRecord.prizeSPValues
        let snapshot: PrizeConditionSnapshot?
        if firstSixOutcomes.count == 6,
           let spValues,
           spValues.count >= 6 {
            snapshot = makePrizeConditionSnapshot(
                matches: Array(matches.prefix(6)),
                outcomes: firstSixOutcomes,
                spValues: Array(spValues.prefix(6)),
                label: "查询页自动同步"
            )
        } else {
            snapshot = nil
        }
        let runSummary = firstSixOutcomes.count == 6
            ? PrizeCalculator.outcomeSummary(for: firstSixOutcomes)
            : nil
        appendPrizeQueryRecord(
            issue: sharedRecord.issue,
            matchNumbers: sharedRecord.matchNumbers,
            handicaps: sharedRecord.observedHandicaps,
            isSettled: sharedRecord.isFinalResult,
            amount: sharedRecord.prizeAmount ?? 0,
            calculationLabel: sharedRecord.prizeAmount == nil
                ? "查询页自动同步（金额待赔率）"
                : "查询页自动同步",
            runSummary: runSummary,
            outcomes: firstSixOutcomes.isEmpty ? nil : firstSixOutcomes,
            seventhEstimates: nil,
            seventhRunSummaries: nil,
            conditionSnapshots: snapshot.map { [$0] }
        )
        let key = TXTQueryStatisticsCalculator.ticketKey(
            issue: sharedRecord.issue,
            matchNumbers: sharedRecord.matchNumbers
        )
        guard let globalRecord = uniquePrizeQueryRecords.filter({
            TXTQueryStatisticsCalculator.ticketKey(issue: $0.issue, matchNumbers: $0.matchNumbers) == key
        }).max(by: {
            let leftScore = prizeRecordCompletenessScore($0)
            let rightScore = prizeRecordCompletenessScore($1)
            return leftScore == rightScore ? $0.queriedAt < $1.queriedAt : leftScore < rightScore
        }) else { return }
        if let logic = cachedABCD(for: globalRecord) {
            storeGlobalABCD(logic, for: globalRecord)
        }
        let hasMatchingLatestComputerResult = globalFilterCounts(for: globalRecord)?.outcomeSignature
            == prizeRecordOutcomeSignature(globalRecord)
        globalPrizeAnswerMessage = hasMatchingLatestComputerResult
            ? "查询结果已同步，并对应条件Tab最新条件的电脑计算结果。"
            : "查询结果已同步到奖金Tab；等待电脑按条件Tab最新条件计算。"
    }

    /// 把查询Tab已经保存的数据一次性写入奖金去重历史。
    /// 这里只读取本地缓存，不联网、不逐条运行过滤引擎，保证“全局答案”立即打开。
    @MainActor
    private func syncStoredQueryResultsToGlobalAnswersFromCache() -> Int {
        let sourceRecords = uniqueTXTQueryRecords.filter {
            $0.matchNumbers.count >= 6
                && ($0.observedOutcomes?.contains(where: { $0 != nil }) == true)
        }
        guard !sourceRecords.isEmpty else { return 0 }

        var nextID = (prizeQueryHistory.map(\.id).max() ?? 0) + 1
        var synced = 0
        var persistedABCD = UserDefaults.standard.dictionary(forKey: globalABCDCacheStorageKey)
            as? [String: String] ?? [:]

        for source in sourceRecords {
            let key = TXTQueryStatisticsCalculator.ticketKey(
                issue: source.issue,
                matchNumbers: source.matchNumbers
            )
            let existingIndex = prizeQueryHistory.firstIndex {
                TXTQueryStatisticsCalculator.ticketKey(issue: $0.issue, matchNumbers: $0.matchNumbers) == key
            }
            let existing = existingIndex.map { prizeQueryHistory[$0] }
            let id = existing?.id ?? nextID
            if existing == nil { nextID += 1 }

            let firstSix = Array((source.observedOutcomes ?? []).prefix(6))
            let sourceOutcomes: [Int]? = firstSix.count == 6 && firstSix.allSatisfy({ $0 != nil })
                ? firstSix.compactMap { $0 }
                : nil
            let mergedOutcomes = sourceOutcomes ?? existing?.outcomes
            let logic = cachedABCD(for: source)
            let sourceSP = source.prizeSPValues.map { Array($0.prefix(6)) }
            let generatedSnapshot = mergedOutcomes.flatMap { outcomes in
                makeStoredPrizeConditionSnapshot(
                    outcomes: outcomes,
                    spValues: sourceSP,
                    logicText: logic,
                    estimatedPrize: source.prizeAmount,
                    label: "查询页本地同步"
                )
            }
            // 查询Tab的最新完整记录优先，不能被奖金Tab旧快照压住。
            let mergedSnapshots = generatedSnapshot.map { [$0] }
                ?? existing?.conditionSnapshots
            let mergedAmount = source.prizeAmount ?? existing?.amount ?? 0
            let sourceUpdatedAt = source.lastCheckedAt ?? source.sharedAt
            let mergedQueriedAt = max(existing?.queriedAt ?? sourceUpdatedAt, sourceUpdatedAt)
            let merged = PrizeQueryRecord(
                id: id,
                queriedAt: mergedQueriedAt,
                issue: source.issue,
                matchNumbers: source.matchNumbers,
                handicaps: source.observedHandicaps ?? existing?.handicaps,
                isSettled: source.isFinalResult || (existing?.isSettled == true),
                amount: mergedAmount,
                calculationLabel: source.prizeAmount == nil
                    ? (existing?.calculationLabel ?? "查询页本地同步（金额待赔率）")
                    : "查询页本地同步",
                runSummary: mergedOutcomes.flatMap(PrizeCalculator.outcomeSummary(for:))
                    ?? existing?.runSummary,
                outcomes: mergedOutcomes,
                seventhEstimates: existing?.seventhEstimates,
                seventhRunSummaries: existing?.seventhRunSummaries,
                conditionSnapshots: mergedSnapshots
            )

            let improved = existing == nil
                || ((existing?.outcomes?.count ?? 0) < 6 && (merged.outcomes?.count ?? 0) >= 6)
                // “刷新全部判断”必须把旧记录也改为最新本地彩果＋ABCD快照，
                // 不能因查询时间未变而沿用缺少条件快照的旧状态。
                || generatedSnapshot != nil
                || (existing?.conditionSnapshots?.isEmpty != false && merged.conditionSnapshots?.isEmpty == false)
                || ((existing?.amount ?? 0) <= 0 && merged.amount > 0)
                || sourceUpdatedAt > (existing?.queriedAt ?? .distantPast)
            guard improved else { continue }
            if let existingIndex {
                prizeQueryHistory[existingIndex] = merged
            } else {
                prizeQueryHistory.append(merged)
            }
            if let logic {
                globalABCDByPrizeRecordID[id] = logic
                let abcdKey = TXTQueryStatisticsCalculator.uniqueKey(
                    issue: source.issue,
                    matchNumbers: Array(source.matchNumbers.prefix(5))
                )
                persistedABCD[abcdKey] = logic
            }
            synced += 1
        }

        guard synced > 0 else { return 0 }
        deduplicatePrizeQueryHistory()
        savePrizeQueryHistory()
        UserDefaults.standard.set(persistedABCD, forKey: globalABCDCacheStorageKey)
        scheduleDurableBackup()
        return synced
    }

    private func cachedABCD(for record: SharedTXTQueryRecord) -> String? {
        // ABCD也按“期号＋前5场”读取全局最新缓存，保证查询Tab与奖金Tab一致。
        // 旧TXT的 normalizedInput 仅作缓存未补全时的ABCD迁移回退，不读取其他旧条件。
        let persisted = UserDefaults.standard.dictionary(forKey: globalABCDCacheStorageKey)
            as? [String: String] ?? [:]
        let key = TXTQueryStatisticsCalculator.uniqueKey(
            issue: record.issue,
            matchNumbers: Array(record.matchNumbers.prefix(5))
        )
        if let logic = normalizedABCD(persisted[key]) {
            return logic
        }
        if let config = try? FilterConfig.parse(record.normalizedInput),
           Array(config.matchNumbers.prefix(5)).compactMap(Int.init)
            == Array(record.matchNumbers.prefix(5)).compactMap(Int.init),
           let logic = normalizedABCD(config.logic.map(\.displayName).joined()) {
            return logic
        }
        return nil
    }

    private func storeGlobalABCD(_ value: String, for record: SharedTXTQueryRecord) {
        guard let logic = normalizedABCD(value) else { return }
        var persisted = UserDefaults.standard.dictionary(forKey: globalABCDCacheStorageKey)
            as? [String: String] ?? [:]
        let key = TXTQueryStatisticsCalculator.uniqueKey(
            issue: record.issue,
            matchNumbers: Array(record.matchNumbers.prefix(5))
        )
        persisted[key] = logic
        UserDefaults.standard.set(persisted, forKey: globalABCDCacheStorageKey)
    }

    private func makeStoredPrizeConditionSnapshot(
        outcomes: [Int],
        spValues: [Double]?,
        logicText: String?,
        estimatedPrize: Double?,
        label: String
    ) -> PrizeConditionSnapshot? {
        guard outcomes.count >= 6,
              let normalizedLogic = normalizedABCD(logicText) else { return nil }
        let mappings = normalizedLogic.compactMap { LogicMapping(rawValue: String($0).lowercased()) }
        guard mappings.count == 5 else { return nil }
        let judgedOutcomes = Array(outcomes.prefix(6))
        let mainOutcomes = Array(judgedOutcomes.prefix(5))
        let values = zip(mappings, mainOutcomes).map { $0.value(for: $1) }
        let sum = values.reduce(0, +)
        let mean = Double(sum) / Double(values.count)
        let variance = values.reduce(0.0) { $0 + pow(Double($1) - mean, 2) }
            / Double(values.count)
        let completeSP = spValues.flatMap { values in
            values.count >= 6 ? Array(values.prefix(6)) : nil
        }
        let mainSP = completeSP.map { Array($0.prefix(5)) }
        let spProduct = completeSP?.reduce(1, *) ?? 1
        let split = 3
        return PrizeConditionSnapshot(
            label: label,
            outcomes: judgedOutcomes,
            logic: normalizedLogic,
            productQ: values.reduce(1, *),
            sum: sum,
            displacement: zip(values, values.dropFirst()).reduce(0) { $0 + abs($1.1 - $1.0) },
            variance: variance,
            valueTwoCount: values.filter { $0 == 2 }.count,
            valueFourPositions: values.indices.filter { values[$0] == 4 }.map { $0 + 1 },
            transitionPercent: prizeTransitionPercent(values),
            roughness: prizeRoughness(values),
            breakpoints: zip(mainOutcomes, mainOutcomes.dropFirst()).filter { $0 != $1 }.count,
            spSum: completeSP?.reduce(0, +),
            spProduct: spProduct,
            estimatedPrize: estimatedPrize ?? completeSP.map { $0.reduce(1, *) * 1.3 } ?? 0,
            spCount: completeSP?.count,
            maximumSingleSP: completeSP?.max() ?? 0,
            highSPCount: completeSP?.filter { $0 > 4 }.count ?? 0,
            minimumProbabilityPercent: nil,
            jointProbabilityPercent: nil,
            frontOutcomeSum: mainOutcomes.prefix(split).reduce(0, +),
            backOutcomeSum: mainOutcomes.dropFirst(split).reduce(0, +),
            frontSPProduct: mainSP?.prefix(split).reduce(1, *) ?? 1,
            backSPProduct: mainSP?.dropFirst(split).reduce(1, *) ?? 1
        )
    }

    private func sharedTXTAllOptionHitAmount(
        bets: [[Int]],
        matches: [BeijingSingleMatch],
        outcomes: [Int?],
        verificationCount: Int,
        unitMatchIndices: Set<Int>
    ) -> Double? {
        guard verificationCount > 0,
              matches.count >= verificationCount,
              outcomes.count >= verificationCount else { return nil }
        var total = 0.0
        for bet in bets {
            guard bet.count >= verificationCount else { continue }
            var amount = 1.3
            for index in 0..<verificationCount {
                let match = matches[index]
                let outcome = outcomes[index] ?? bet[index]
                let spIndex: Int
                switch outcome {
                case 3: spIndex = 0
                case 1: spIndex = 1
                case 0: spIndex = 2
                default: return nil
                }
                let value: Double?
                if unitMatchIndices.contains(index) {
                    value = 1.0
                } else if outcomes[index] != nil,
                   let settled = match.settledSP,
                   settled > 0,
                   settled.isFinite {
                    value = settled
                } else if match.referenceSP.indices.contains(spIndex) {
                    value = match.referenceSP[spIndex]
                } else {
                    value = nil
                }
                guard let value, value > 0, value.isFinite else { return nil }
                amount *= value
            }
            total += amount
        }
        return total.isFinite ? total : nil
    }

    private func isPostponedOverTwelveHours(_ match: BeijingSingleMatch) -> Bool {
        match.handicapOutcome == nil && match.isPostponedOver12Hours
    }

    private func sharedTXTNoHitReason(
        record: SharedTXTQueryRecord,
        outcomes: [Int?],
        matches: [BeijingSingleMatch],
        isFinal: Bool
    ) async -> String {
        let knownIndices = outcomes.indices.filter { outcomes[$0] != nil }
        let closest = record.betOutcomes.min { left, right in
            let leftCount = knownIndices.filter { left.indices.contains($0) && left[$0] != outcomes[$0] }.count
            let rightCount = knownIndices.filter { right.indices.contains($0) && right[$0] != outcomes[$0] }.count
            return leftCount < rightCount
        }
        let differences: [String] = closest.map { bet in
            knownIndices.compactMap { index in
                guard bet.indices.contains(index), let actual = outcomes[index], bet[index] != actual else { return nil }
                let handicap = matches.indices.contains(index)
                    ? matches[index].handicap.map { signedHandicap($0) } ?? "?"
                    : "?"
                return "第\(record.matchNumbers[index])场（让球\(handicap)）实际让球彩果\(actual)，最接近投注为\(bet[index])"
            }
        } ?? []
        let parts = differences.isEmpty
            ? ["当前已出彩果的组合不在TXT范围内。"]
            : ["与TXT最接近投注相差：" + differences.joined(separator: "；") + "。"]
        guard isFinal, isCurrentConditionTXT(record),
              let config = try? FilterConfig.parse(record.normalizedInput),
              config.six250RelationshipEnabled else { return parts.joined(separator: "\n") }
        let target = outcomes.prefix(6).compactMap { $0 }
        guard target.count == 6 else { return parts.joined(separator: "\n") }
        let odds = record.generationCustomOdds
        let reasons = await Task.detached(priority: .userInitiated) {
            SequenceFilterEngine.baseFilterFailureReasons(for: target, config: config, currentOutcomeSPs: odds)
        }.value
        guard !reasons.isEmpty else { return parts.joined(separator: "\n") }
        let comparison = reasons.enumerated().map { "\($0.offset + 1). \($0.element)" }.joined(separator: "\n")
        return parts.joined(separator: "\n") + "\n本单条件核对（生成时参数；仅列失败或数据不足项）：\n" + comparison
    }

    private func loadPrizeQueryHistory() {
        guard let data = UserDefaults.standard.data(forKey: prizeQueryHistoryStorageKey),
              let records = try? JSONDecoder().decode([PrizeQueryRecord].self, from: data) else {
            loadVIP1FrozenPrizeRecords(merging: [])
            return
        }
        let originalCount = records.count
        let normalized = deduplicatedPrizeRecords(records)
        prizeQueryHistory = normalized
        loadVIP1FrozenPrizeRecords(merging: normalized)
        if normalized.count != originalCount,
           let encoded = try? JSONEncoder().encode(normalized) {
            UserDefaults.standard.set(encoded, forKey: prizeQueryHistoryStorageKey)
        }
    }

    /// 29条VIP 1冻结单使用独立本地档案。即使有效TXT被整批覆盖为206条，
    /// 这些原始单据仍能在三级页面恢复，且不参与通过率与注数统计。
    private func loadVIP1FrozenPrizeRecords(merging records: [PrizeQueryRecord]) {
        let saved: [PrizeQueryRecord]
        if let data = UserDefaults.standard.data(forKey: vip1FrozenPrizeRecordsStorageKey),
           let decoded = try? JSONDecoder().decode([PrizeQueryRecord].self, from: data) {
            saved = decoded
        } else {
            saved = []
        }
        let currentFrozen = records.filter {
            historicalMergedIssues.contains($0.issue) && isVIP1FrozenRecord($0)
        }
        let merged = deduplicatedPrizeRecords(saved + currentFrozen).filter {
            historicalMergedIssues.contains($0.issue) && isVIP1FrozenRecord($0)
        }
        locallySavedVIP1FrozenRecords = merged
        persistVIP1FrozenPrizeRecords(merged)
    }

    private func persistVIP1FrozenPrizeRecords(_ records: [PrizeQueryRecord]) {
        guard let data = try? JSONEncoder().encode(records) else { return }
        UserDefaults.standard.set(data, forKey: vip1FrozenPrizeRecordsStorageKey)
    }

    private var pendingHandicapOutcomeBackfillCount: Int {
        prizeQueryHistory.filter { record in
            (6...7).contains(record.matchNumbers.count)
                && (record.outcomes?.count ?? 0) < record.matchNumbers.count
        }.count
    }

    @MainActor
    private func backfillMissingHandicapOutcomes() async {
        guard !isBackfillingHandicapOutcomes else { return }
        let pendingIDs = prizeQueryHistory.filter { record in
            (6...7).contains(record.matchNumbers.count)
                && (record.outcomes?.count ?? 0) < record.matchNumbers.count
        }.map(\.id)
        guard !pendingIDs.isEmpty else {
            if handicapOutcomeBackfillMessage != nil {
                handicapOutcomeBackfillMessage = "让球后彩果已全部补全。"
            }
            return
        }

        isBackfillingHandicapOutcomes = true
        handicapOutcomeBackfillMessage = "正在从500优先、澳客备用补全\(pendingIDs.count)条记录…"
        var completed = 0
        var fiveHundredCount = 0
        var okoooCount = 0
        var failed = 0
        var lastError: String?

        for id in pendingIDs {
            guard !Task.isCancelled,
                  let record = prizeQueryHistory.first(where: { $0.id == id }) else { break }
            do {
                let fetched = try await fetchCompletedHandicapOutcomes(
                    issue: record.issue,
                    matchNumbers: record.matchNumbers
                )
                let outcomes = fetched.matches.compactMap(\.handicapOutcome)
                guard outcomes.count == record.matchNumbers.count else {
                    throw GoalModelError.resultUnavailable(record.matchNumbers.first ?? "-")
                }
                let updated = PrizeQueryRecord(
                    id: record.id,
                    queriedAt: record.queriedAt,
                    issue: record.issue,
                    matchNumbers: record.matchNumbers,
                    handicaps: fetched.matches.map(\.handicap),
                    isSettled: true,
                    amount: record.amount,
                    calculationLabel: record.calculationLabel,
                    runSummary: PrizeCalculator.runSummary(for: Array(fetched.matches.prefix(6))),
                    outcomes: outcomes,
                    seventhEstimates: record.seventhEstimates,
                    seventhRunSummaries: record.seventhRunSummaries,
                    conditionSnapshots: record.conditionSnapshots
                )
                if let index = prizeQueryHistory.firstIndex(where: { $0.id == id }) {
                    prizeQueryHistory[index] = updated
                    savePrizeQueryHistory()
                }
                completed += 1
                if fetched.source == "500" { fiveHundredCount += 1 } else { okoooCount += 1 }
                handicapOutcomeBackfillMessage = "已补全\(completed)/\(pendingIDs.count)条让球彩果…"
            } catch {
                failed += 1
                lastError = error.localizedDescription
            }
        }

        isBackfillingHandicapOutcomes = false
        if failed == 0 {
            handicapOutcomeBackfillMessage = "已补全\(completed)条（500：\(fiveHundredCount)，澳客：\(okoooCount)）。"
        } else {
            handicapOutcomeBackfillMessage = "已补全\(completed)条，\(failed)条失败：\(lastError ?? "赛果尚未发布")"
        }
    }

    private func fetchCompletedHandicapOutcomes(
        issue: String,
        matchNumbers: [String]
    ) async throws -> (matches: [BeijingSingleMatch], source: String) {
        do {
            let matches = try await FiveHundredBeijingSingleClient.fetchCompletedResults(
                issue: issue,
                matchNumbers: matchNumbers
            )
            guard QueryFinalityGate.permitsResult(
                matches: matches,
                expectedCount: matchNumbers.count
            ) else {
                throw GoalModelError.resultUnavailable(matchNumbers.first ?? "-")
            }
            return (matches, "500")
        } catch {
            do {
                // 500即时页保留“改期/延期”状态，只有明确
                // “延期超过12小时”才按1，不允许其他数据源的缺省值覆盖。
                let fetched = try await fetchQueryMatchesWithScoreboardFallback(
                    issue: issue,
                    matchNumbers: matchNumbers
                )
                let liveMatches = fetched.matches
                guard QueryFinalityGate.permitsResult(
                    matches: liveMatches,
                    expectedCount: matchNumbers.count
                ) else {
                    throw GoalModelError.resultUnavailable(
                        liveMatches.first(where: {
                            (!QueryFinalityGate.isFinallyEnded($0) || $0.handicapOutcome == nil)
                                && !isPostponedOverTwelveHours($0)
                        })?.matchNumber ?? matchNumbers.first ?? "-"
                    )
                }
                return (
                    liveMatches,
                    fetched.usedScoreboard
                        ? "500比分Tab兜底"
                        : "500（明确延期超过12小时按1）"
                )
            } catch {
                let matches = try await OkoooBeijingSingleClient.fetchCompletedResults(
                    issue: issue,
                    matchNumbers: matchNumbers
                )
                guard QueryFinalityGate.permitsResult(
                    matches: matches,
                    expectedCount: matchNumbers.count
                ) else {
                    throw GoalModelError.resultUnavailable(matchNumbers.first ?? "-")
                }
                return (matches, "澳客")
            }
        }
    }

    private func resolvedHistoricalHandicapOutcomes(_ matches: [BeijingSingleMatch]) -> [Int] {
        matches.compactMap { match in
            match.handicapOutcome ?? (isPostponedOverTwelveHours(match) ? 1 : nil)
        }
    }

    private var pendingPrizeHistoryBackfillCount: Int {
        prizeQueryHistory.filter {
            (6...7).contains($0.matchNumbers.count)
                && ($0.outcomes?.count != 6
                    || prizeHistorySeventhRunSummaries($0)?.count != 2
                    || $0.conditionSnapshots?.isEmpty != false)
        }.count
    }

    @MainActor
    private func backfillPrizeQueryHistory() async {
        guard !isBackfillingPrizeHistory else { return }
        let pendingRecords = prizeQueryHistory.filter {
            (6...7).contains($0.matchNumbers.count)
                && ($0.outcomes?.count != 6
                    || prizeHistorySeventhRunSummaries($0)?.count != 2
                    || $0.conditionSnapshots?.isEmpty != false)
        }
        guard !pendingRecords.isEmpty else {
            if prizeHistoryBackfillMessage != nil {
                prizeHistoryBackfillMessage = "旧记录的彩果和第7场3/0结果已全部补全。"
            }
            return
        }

        isBackfillingPrizeHistory = true
        prizeHistoryBackfillMessage = "正在自动获取\(pendingRecords.count)条旧记录…"
        var completed = 0
        var failed = 0
        var lastErrorMessage: String?

        for record in pendingRecords {
            guard !Task.isCancelled else { break }
            do {
                let updatedRecord = try await backfilledPrizeQueryRecord(record)
                if let currentIndex = prizeQueryHistory.firstIndex(where: { $0.id == record.id }) {
                    prizeQueryHistory[currentIndex] = updatedRecord
                    savePrizeQueryHistory()
                    completed += 1
                    prizeHistoryBackfillMessage = "已补全\(completed)/\(pendingRecords.count)条旧记录…"
                }
            } catch {
                failed += 1
                lastErrorMessage = error.localizedDescription
            }
        }

        isBackfillingPrizeHistory = false
        if failed == 0 {
            prizeHistoryBackfillMessage = "已自动补全\(completed)条旧记录的彩果和第7场3/0结果。"
        } else {
            let detail = lastErrorMessage.map { "：\($0)" } ?? ""
            prizeHistoryBackfillMessage = "已补全\(completed)条，还有\(failed)条未获取\(detail)"
        }
    }

    private func backfilledPrizeQueryRecord(_ record: PrizeQueryRecord) async throws -> PrizeQueryRecord {
        if record.matchNumbers.count == 6 {
            let matches = try await fetchCompletedHandicapOutcomes(
                issue: record.issue,
                matchNumbers: record.matchNumbers
            ).matches
            let outcomes = resolvedHistoricalHandicapOutcomes(matches)
            guard outcomes.count == 6,
                  let summaries = PrizeCalculator.seventhOutcomeRunSummaries(firstSixOutcomes: outcomes) else {
                throw GoalModelError.resultUnavailable(record.matchNumbers.first ?? "-")
            }
            let spValues = matches.compactMap(PrizeCalculator.selectedSP)
            let snapshots = spValues.count == 6
                ? makePrizeConditionSnapshot(
                    matches: matches,
                    outcomes: outcomes,
                    spValues: spValues,
                    label: "6场实际彩果"
                ).map { [$0] }
                : nil
            return PrizeQueryRecord(
                id: record.id,
                queriedAt: record.queriedAt,
                issue: record.issue,
                matchNumbers: record.matchNumbers,
                handicaps: matches.map(\.handicap),
                isSettled: record.isSettled,
                amount: record.amount,
                calculationLabel: record.calculationLabel,
                runSummary: PrizeCalculator.runSummary(for: matches),
                outcomes: outcomes,
                seventhEstimates: nil,
                seventhRunSummaries: summaries,
                conditionSnapshots: snapshots ?? record.conditionSnapshots
            )
        }

        do {
            let matches = try await FiveHundredBeijingSingleClient.fetchPrizeMatches(
                issue: record.issue,
                matchNumbers: record.matchNumbers
            )
            if let updated = makeBackfilledPrizeQueryRecord(record, matches: matches, useHandicapSP: false) {
                return updated
            }
        } catch {
            // 普通SP不完整时继续尝试让球SP，连续统计的彩果不受SP来源影响。
        }

        do {
            let matches = try await FiveHundredBeijingSingleClient.fetchPrizeMatches(
                issue: record.issue,
                matchNumbers: record.matchNumbers,
                requireHandicapSP: true
            )
            if let updated = makeBackfilledPrizeQueryRecord(record, matches: matches, useHandicapSP: true) {
                return updated
            }
        } catch {
            // 500的7场SP页若暂时缺数据，继续用500比分页；仍失败则由该方法回退澳客。
        }

        let firstSixNumbers = Array(record.matchNumbers.prefix(6))
        let completed = try await fetchCompletedHandicapOutcomes(
            issue: record.issue,
            matchNumbers: firstSixNumbers
        ).matches
        let outcomes = resolvedHistoricalHandicapOutcomes(completed)
        guard outcomes.count == 6,
              let summaries = PrizeCalculator.seventhOutcomeRunSummaries(firstSixOutcomes: outcomes) else {
            throw GoalModelError.resultUnavailable(record.matchNumbers.first ?? "-")
        }
        let spValues = completed.compactMap(PrizeCalculator.selectedSP)
        let snapshot = spValues.count == 6
            ? makePrizeConditionSnapshot(
                matches: completed,
                outcomes: outcomes,
                spValues: spValues,
                label: "6场实际彩果（500/澳客补全）"
            )
            : nil
        return PrizeQueryRecord(
            id: record.id,
            queriedAt: record.queriedAt,
            issue: record.issue,
            matchNumbers: record.matchNumbers,
            handicaps: completed.map(\.handicap) + Array(record.handicaps?.dropFirst(6) ?? []),
            isSettled: true,
            amount: record.amount,
            calculationLabel: record.calculationLabel,
            runSummary: PrizeCalculator.runSummary(for: completed),
            outcomes: outcomes,
            seventhEstimates: record.seventhEstimates,
            seventhRunSummaries: summaries,
            conditionSnapshots: snapshot.map { [$0] } ?? record.conditionSnapshots
        )
    }

    private func makeBackfilledPrizeQueryRecord(
        _ record: PrizeQueryRecord,
        matches: [BeijingSingleMatch],
        useHandicapSP: Bool
    ) -> PrizeQueryRecord? {
        guard matches.count == 7, let seventh = matches.last else { return nil }
        let firstSix = Array(matches.prefix(6))
        let outcomes = firstSix.compactMap(\.handicapOutcome)
        guard outcomes.count == 6,
              let estimates = PrizeCalculator.seventhOutcomeEstimates(
                firstSix: firstSix,
                seventh: seventh,
                useHandicapSP: useHandicapSP
              ),
              estimates.count == 2 else { return nil }
        let outcome3Amount = estimates.first(where: { $0.outcome == 3 })?.amount ?? record.amount
        let firstSixValues = firstSix.compactMap(PrizeCalculator.selectedSP)
        let snapshots = firstSixValues.count == 6 ? estimates.compactMap { estimate in
            makePrizeConditionSnapshot(
                matches: matches,
                outcomes: outcomes + [estimate.outcome],
                spValues: firstSixValues + [estimate.sp],
                label: "第7场默认\(estimate.outcome)"
            )
        } : []
        return PrizeQueryRecord(
            id: record.id,
            queriedAt: record.queriedAt,
            issue: record.issue,
            matchNumbers: record.matchNumbers,
            handicaps: matches.map(\.handicap),
            isSettled: record.isSettled,
            amount: outcome3Amount,
            calculationLabel: record.calculationLabel ?? "7场双结果估算",
            runSummary: nil,
            outcomes: outcomes,
            seventhEstimates: estimates,
            seventhRunSummaries: estimates.map {
                SeventhOutcomeRunSummary(outcome: $0.outcome, runSummary: $0.runSummary)
            },
            conditionSnapshots: snapshots.isEmpty ? record.conditionSnapshots : snapshots
        )
    }

    private func savePrizeQueryHistory() {
        let normalized = deduplicatedPrizeRecords(prizeQueryHistory)
        if normalized.count != prizeQueryHistory.count {
            prizeQueryHistory = normalized
        }
        let currentFrozen = normalized.filter {
            historicalMergedIssues.contains($0.issue) && isVIP1FrozenRecord($0)
        }
        let frozenArchive = deduplicatedPrizeRecords(
            locallySavedVIP1FrozenRecords + currentFrozen
        ).filter {
            historicalMergedIssues.contains($0.issue) && isVIP1FrozenRecord($0)
        }
        locallySavedVIP1FrozenRecords = frozenArchive
        schedulePrizeHistoryPersistence(history: normalized, frozen: frozenArchive)
        schedulePrizeDerivedStatisticsRefresh()
        scheduleHistoricalStatisticsRefresh(for: try? FilterConfig.parse(generatedInput))
        refreshProtectedPrizeOutcomePrefixesCache()
    }

    private func schedulePrizeHistoryPersistence(
        history: [PrizeQueryRecord],
        frozen: [PrizeQueryRecord]
    ) {
        let historyStorageKey = prizeQueryHistoryStorageKey
        let frozenStorageKey = vip1FrozenPrizeRecordsStorageKey
        prizeHistoryPersistenceTask?.cancel()
        prizeHistoryPersistenceTask = Task { @MainActor in
            try? await Task.sleep(nanoseconds: 250_000_000)
            guard !Task.isCancelled else { return }
            let saved = await Task.detached(priority: .utility) {
                guard let historyData = try? JSONEncoder().encode(history),
                      let frozenData = try? JSONEncoder().encode(frozen) else { return false }
                UserDefaults.standard.set(historyData, forKey: historyStorageKey)
                UserDefaults.standard.set(frozenData, forKey: frozenStorageKey)
                return true
            }.value
            guard !Task.isCancelled, saved else { return }
            scheduleDurableBackup()
        }
    }

    private func persistPrizeHistoryImmediately() {
        if let data = try? JSONEncoder().encode(prizeQueryHistory) {
            UserDefaults.standard.set(data, forKey: prizeQueryHistoryStorageKey)
        }
        if let data = try? JSONEncoder().encode(locallySavedVIP1FrozenRecords) {
            UserDefaults.standard.set(data, forKey: vip1FrozenPrizeRecordsStorageKey)
        }
    }

    private func appendPrizeQueryRecord(
        issue: String,
        matchNumbers: [String],
        handicaps: [Int?]?,
        isSettled: Bool,
        amount: Double,
        calculationLabel: String,
        runSummary: PrizeRunSummary?,
        outcomes: [Int]?,
        seventhEstimates: [SeventhOutcomeEstimate]?,
        seventhRunSummaries: [SeventhOutcomeRunSummary]?,
        conditionSnapshots: [PrizeConditionSnapshot]?
    ) {
        let key = TXTQueryStatisticsCalculator.ticketKey(issue: issue, matchNumbers: matchNumbers)
        let existingIndex = prizeQueryHistory.firstIndex {
            TXTQueryStatisticsCalculator.ticketKey(issue: $0.issue, matchNumbers: $0.matchNumbers) == key
        }
        let id = existingIndex.map { prizeQueryHistory[$0].id }
            ?? ((prizeQueryHistory.map(\.id).max() ?? 0) + 1)
        let record = PrizeQueryRecord(
            id: id,
            queriedAt: Date(),
            issue: issue,
            matchNumbers: matchNumbers,
            handicaps: handicaps,
            isSettled: isSettled,
            amount: amount,
            calculationLabel: calculationLabel,
            runSummary: runSummary,
            outcomes: outcomes,
            seventhEstimates: seventhEstimates,
            seventhRunSummaries: seventhRunSummaries,
            conditionSnapshots: conditionSnapshots
        )
        if let existingIndex {
            prizeQueryHistory[existingIndex] = record
        } else {
            prizeQueryHistory.append(record)
        }
        savePrizeQueryHistory()
    }

    private func deduplicatePrizeQueryHistory() {
        prizeQueryHistory = deduplicatedPrizeRecords(prizeQueryHistory)
    }

    private func deduplicatedPrizeRecords(
        _ records: [PrizeQueryRecord]
    ) -> [PrizeQueryRecord] {
        var unique: [String: PrizeQueryRecord] = [:]
        for record in records {
            let key = TXTQueryStatisticsCalculator.ticketKey(
                issue: record.issue,
                matchNumbers: record.matchNumbers
            )
            if let existing = unique[key], existing.queriedAt >= record.queriedAt {
                continue
            }
            unique[key] = record
        }
        return unique.values.sorted { $0.queriedAt < $1.queriedAt }
    }

    private func prizeRunSummaryText(_ summary: PrizeRunSummary) -> String {
        """
        胜/平/负总场数：\(summary.winCount)/\(summary.drawCount)/\(summary.lossCount)　彩果种类：\(summary.diversity)
        连续不败：\(summary.nonLoss)场　连续不胜：\(summary.nonWin)场　连续不平：\(summary.nonDraw)场
        连续胜：\(summary.win)场　连续平：\(summary.draw)场　连续负：\(summary.loss)场
        彩果和值：\(summary.outcomeSum)　隔场回返：\(summary.returns)次　胜负切换：\(summary.winLossSwitches)次
        """
    }

    private var goalModelIssueStorageKey: String {
        "sequenceFilter.goalModelIssue.v1"
    }

    private func resolveCurrentIssue() async throws -> String {
        let input = beijingSingleIssueInput.trimmingCharacters(in: .whitespacesAndNewlines)
        let savedAnchor = UserDefaults.standard.string(forKey: goalModelIssueStorageKey)
        let anchor = savedAnchor?.allSatisfy(\.isNumber) == true
            ? savedAnchor!
            : (input.allSatisfy(\.isNumber) && !input.isEmpty ? input : "26092")
        let issue = try await FiveHundredBeijingSingleClient.resolveIssue(
            input: input,
            anchorIssue: anchor
        )
        UserDefaults.standard.set(issue, forKey: goalModelIssueStorageKey)
        resolvedIssueMessage = input != issue ? "\(input) → 北单第\(issue)期" : "当前使用北单第\(issue)期"
        return issue
    }

    @MainActor
    private func loadBeijingSingleScores() async {
        guard !isLoadingScores else { return }
        isLoadingScores = true
        scoreMessage = nil
        defer { isLoadingScores = false }
        do {
            let issue = try await resolveCurrentIssue()
            let matches = try await FiveHundredBeijingSingleClient.fetchIssueScoreboard(issue: issue)
            try Task.checkCancellation()
            let keepsCurrentPage = scoreLoadedIssue == issue
            let pageCount = ScoreMatchPagination.pageRanges(totalCount: matches.count).count
            scoreMatches = matches
            scoreSelectedPage = keepsCurrentPage
                ? min(scoreSelectedPage, max(0, pageCount - 1))
                : 0
            scoreLoadedIssue = issue
            scoreLastUpdatedAt = Date()
            scoreMessage = "已从500北单比分页获取第\(issue)期\(matches.count)场；下拉可刷新实时状态。"
            startScoreOddsConfidenceCalculation(matches: matches, issue: issue)
        } catch is CancellationError {
            return
        } catch {
            scoreMessage = "比分获取失败：\(error.localizedDescription)"
        }
    }

    @MainActor
    private func refreshScoreTab() {
        guard !isLoadingScores else { return }
        scoreRefreshTask?.cancel()
        scoreRefreshTask = Task { await loadBeijingSingleScores() }
    }

    /// 比分页可能同时有上百场；Poisson/Dixon–Coles拟合全部移到后台，
    /// 点击或刷新产生新任务时取消旧结果，主线程只提交最终快照。
    @MainActor
    private func startScoreOddsConfidenceCalculation(
        matches: [BeijingSingleMatch],
        issue: String
    ) {
        scoreOddsConfidenceTask?.cancel()
        scoreOddsRecommendationsByMatchNumber = [:]
        isCalculatingScoreOddsConfidence = true
        scoreOddsConfidenceMessage = nil
        let blindMatches = matches.map(\.resultBlindCopy)
        scoreOddsConfidenceTask = Task {
            let recommendations = await Task.detached(priority: .userInitiated) {
                var values: [String: OddsConfidenceRecommendation] = [:]
                for match in blindMatches {
                    try Task.checkCancellation()
                    guard !match.hasStarted,
                          match.handicap != nil,
                          match.marketOdds.count == 3,
                          let analysis = try? PoissonGoalModel.analyze(match),
                          let recommendation = OddsConfidenceGate.evaluateCandidate(analysis) else {
                        continue
                    }
                    values[match.matchNumber] = recommendation
                }
                return values
            }.result
            guard !Task.isCancelled, scoreLoadedIssue == issue else { return }
            switch recommendations {
            case .success(let values):
                scoreOddsRecommendationsByMatchNumber = values
                let greenCount = values.values.filter { $0.decision == .bet }.count
                let observationCount = values.values.filter { $0.decision == .observe }.count
                scoreOddsConfidenceMessage = "本期已计算\(values.count)场：绿色\(greenCount)场，黄色\(observationCount)场；其余不投注或数据不完整。"
            case .failure:
                scoreOddsRecommendationsByMatchNumber = [:]
                scoreOddsConfidenceMessage = "赔率置信度计算已取消。"
            }
            isCalculatingScoreOddsConfidence = false
        }
    }

    private func resolveIssueOnly() {
        goalModelErrorMessage = nil
        isResolvingIssue = true
        Task {
            do {
                _ = try await resolveCurrentIssue()
            } catch {
                resolvedIssueMessage = nil
                goalModelErrorMessage = error.localizedDescription
            }
            isResolvingIssue = false
        }
    }

    @MainActor
    private func refreshIssueFromCurrentTime() async {
        let formatter = DateFormatter()
        formatter.calendar = Calendar(identifier: .gregorian)
        formatter.locale = Locale(identifier: "zh_CN")
        formatter.timeZone = TimeZone(identifier: "Asia/Shanghai")
        formatter.dateFormat = "yyyyMMdd"
        let dateInput = formatter.string(from: Date())
        let savedAnchor = UserDefaults.standard.string(forKey: goalModelIssueStorageKey) ?? "26092"
        isResolvingIssue = true
        do {
            let issue = try await FiveHundredBeijingSingleClient.resolveIssue(
                input: dateInput,
                anchorIssue: savedAnchor
            )
            beijingSingleIssueInput = issue
            UserDefaults.standard.set(issue, forKey: goalModelIssueStorageKey)
            resolvedIssueMessage = "按北京时间 \(dateInput) 获取：北单第\(issue)期"
            goalModelErrorMessage = nil
        } catch {
            resolvedIssueMessage = nil
            goalModelErrorMessage = "启动时按当前时间获取期号失败：\(error.localizedDescription)"
        }
        isResolvingIssue = false
    }

    private var goalModelHistoryStorageKey: String {
        "sequenceFilter.goalModelHistory.v1"
    }

    private func saveGoalModelRecommendation(issue: String, matchNumbers: [String], logic: String) {
        let cleanIssue = issue.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanNumbers = matchNumbers.map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
        recommendationHistory.removeAll { saved in
            saved.issue == cleanIssue && saved.matchNumbers.compactMap(Int.init) == cleanNumbers.compactMap(Int.init)
        }
        recommendationHistory.append(
            GoalModelRecommendationSnapshot(
                savedAt: Date(),
                issue: cleanIssue,
                matchNumbers: cleanNumbers,
                logic: logic.uppercased()
            )
        )
        recommendationHistory = Array(recommendationHistory.suffix(50))
        if let data = try? JSONEncoder().encode(recommendationHistory) {
            UserDefaults.standard.set(data, forKey: goalModelHistoryStorageKey)
            scheduleDurableBackup()
        }
    }

    private var previousMatchNumbers: [String] {
        [previousMatch1Input, previousMatch2Input, previousMatch3Input,
         previousMatch4Input, previousMatch5Input]
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
    }

    private var manualSequentialQueryMatchNumbers: [String] {
        let values = [
            manualQueryFirstMatchInput,
            manualQueryMatch2Input,
            manualQueryMatch3Input,
            manualQueryMatch4Input,
            manualQueryMatch5Input,
            manualQueryMatch6Input
        ].map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
        let numbers = values.compactMap(Int.init)
        guard numbers.count == 6,
              numbers.allSatisfy({ $0 > 0 }),
              Set(numbers).count == 6 else { return [] }
        return numbers.map(String.init)
