    private var matchedPreviousRecommendation: GoalModelRecommendationSnapshot? {
        let requested = previousMatchNumbers.compactMap(Int.init)
        guard requested.count == 5, Set(requested).count == 5 else { return nil }
        let requestedIssue = previousIssueInput.trimmingCharacters(in: .whitespacesAndNewlines)
        return recommendationHistory.reversed().first { saved in
            let recorded = saved.matchNumbers.compactMap(Int.init)
            let issueMatches = requestedIssue.isEmpty || saved.issue == requestedIssue
            return issueMatches && recorded.count == 5 && Set(recorded) == Set(requested)
        }
    }

    private var goalModelRecommendation: String {
        currentFilteredMatchNumbers.compactMap { number in
            goalModelAnalyses.first { Int($0.match.matchNumber) == Int(number) }?.recommendedLogic.displayName
        }.joined()
    }

    private var goalModelConfidenceIndex: Int {
        let main = currentFilteredMatchNumbers.compactMap { number in
            goalModelAnalyses.first { Int($0.match.matchNumber) == Int(number) }
        }
        guard !main.isEmpty else { return 0 }
        return Int(
            (Double(main.map(\.confidenceIndex).reduce(0, +))
                / Double(main.count)).rounded()
        )
    }

    private var oddsConfidenceRecommendation: OddsConfidenceRecommendation? {
        let selected = currentFilteredMatchNumbers.compactMap { number in
            goalModelAnalyses.first { Int($0.match.matchNumber) == Int(number) }
        }
        guard selected.count == currentFilteredMatchNumbers.count else { return nil }
        return OddsConfidenceGate.evaluate(analyses: selected)
    }

    private var bestScoreOddsRecommendation: OddsConfidenceRecommendation? {
        func decisionRank(_ decision: OddsConfidenceDecision) -> Int {
            switch decision {
            case .bet: return 3
            case .observe: return 2
            case .skip: return 1
            }
        }
        return scoreOddsRecommendationsByMatchNumber.values.max { left, right in
            let leftRank = decisionRank(left.decision)
            let rightRank = decisionRank(right.decision)
            if leftRank != rightRank { return leftRank < rightRank }
            if left.outcomeProbability != right.outcomeProbability {
                return left.outcomeProbability < right.outcomeProbability
            }
            return left.modelConfidenceIndex < right.modelConfidenceIndex
        }
    }

    private func oddsConfidenceDecisionColor(_ decision: OddsConfidenceDecision) -> Color {
        switch decision {
        case .bet: return .green
        case .observe: return .orange
        case .skip: return .red
        }
    }

