           let first=Int(match1Input.trimmingCharacters(in:.whitespacesAndNewlines)),first>0 {
            return (0..<5).map{String(first+$0)}
        }
        return [match1Input, match2Input, match3Input, match4Input, match5Input]
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
    }

    /// VIP6把原“第6场全包”提升为第6个主计算场；其余版本仍保持5主场＋全包场。
    private var currentCalculationMatchNumbers: [String] {
        guard usesVIP6AutomaticMatchSelection else { return currentFilteredMatchNumbers }
        return currentFilteredMatchNumbers + [
            effectiveFixedFullMatchInput.trimmingCharacters(in: .whitespacesAndNewlines)
        ]
    }

    /// 与引擎使用同一份已换算的自定义让球赔率，展示动态禁4的实际场次。
    private var currentLowestOddsNoFourDescription: String? {
        guard let config = try? FilterConfig.parse(generatedInput) else { return nil }
        var descriptions: [String] = []
        if config.lowestCustomOddsNoFourEnabled {
            let issue = beijingSingleIssueInput.trimmingCharacters(in: .whitespacesAndNewlines)
            let currentAnalyses = goalModelAnalyses.filter { $0.match.issue == issue }
            let rows = outcomeSPMatrix(for: config, analyses: currentAnalyses)
            let selection = config.lowestFourProbabilityNoFourSelection(in: rows)
            let position = selection?.position
                ?? ((currentTXTGenerationIssue == issue
                     && result?.matchesGenerationRequest(config) == true)
                    ? result?.config.resolvedLowestCustomOddsNoFourPosition : nil)
            if let position, config.matchNumbers.indices.contains(position - 1) {
                let match = config.matchNumbers[position - 1]
                let probability = selection.map { String(format: "%.2f%%", $0.probability * 100) }
                    ?? "当次生成已确定"
                descriptions.append("4概率最低，禁4：第\(position)场（场次\(match)，4概率\(probability)）")
            } else {
                descriptions.append("4概率最低的场次禁4：赔率未齐，尚不能确定场次")
            }
        }
        for position in config.noFourPositions where config.matchNumbers.indices.contains(position - 1) {
            let label = usesSVIPPermutationVersion
                ? "手动指定不为4"
                : "固定禁4"
            descriptions.append("\(label)：第\(position)场（场次\(config.matchNumbers[position - 1])）")
        }
        return descriptions.isEmpty ? nil : descriptions.joined(separator: "；")
    }

    private var currentCalculationLogicCount: Int {
        usesVIP6AutomaticMatchSelection ? 6 : 5
    }

    private var noFourSelectedMatchNumber: String? {
        guard noFourPositionFilterEnabled,
              let position = Int(noFourPositionInput),
              currentCalculationMatchNumbers.indices.contains(position - 1) else { return nil }
        let number = currentCalculationMatchNumbers[position - 1]
        return number.isEmpty ? nil : number
    }

    /// 只对数据源已给出完整比分与实际让球的场次做赛后核对。
    /// 未完赛、比分缺失或ABCD不完整时不猜测，也不计入命中。
    private var completedMappedResultRows: [CompletedMappedResultRow] {
        guard usesVIP6AutomaticMatchSelection,
              let logic = normalizedCurrentABCD(logicInput) else { return [] }
        let mappings = logic.lowercased().compactMap { LogicMapping(rawValue: String($0)) }
        guard mappings.count == currentCalculationLogicCount else { return [] }
        let matchesByNumber = Dictionary(
            vip6SelectedMatchesWithResults.map { ($0.matchNumber, $0) },
            uniquingKeysWith: { first, _ in first }
        )
        return currentCalculationMatchNumbers.enumerated().compactMap { index, number in
            guard let match = matchesByNumber[number],
                  let outcome = match.handicapOutcome else { return nil }
            let mapping = mappings[index]
            return CompletedMappedResultRow(
                position: index + 1,
                match: match,
                logic: mapping,
                outcome: outcome,
                mappedValue: mapping.value(for: outcome)
            )
        }
    }

    private var completedMappedDisplacement: Int {
        let allValues = completedMappedResultRows.map(\.mappedValue)
        let values = usesVIP10FrontFiveRealSum ? Array(allValues.prefix(5)) : allValues
        return zip(values, values.dropFirst()).reduce(0) { $0 + abs($1.1 - $1.0) }
    }

    private var completedVIP10RealOddsSum: Double? {
        guard usesVIP10FrontFiveRealSum,
              let config = try? FilterConfig.parse(generatedInput),
              let odds = outcomeSPMatrix(for: config, analyses: goalModelAnalyses) else { return nil }
        let outcomes = completedMappedResultRows.sorted { $0.position < $1.position }
            .prefix(5).map(\.outcome)
        guard outcomes.count == 5, odds.count >= 5 else { return nil }
        return zip(odds.prefix(5), outcomes).reduce(0.0) { partial, pair in
            let index = pair.1 == 3 ? 0 : (pair.1 == 1 ? 1 : 2)
            return partial + pair.0[index]
        }
    }

    private var completedVIP7FilterVerification: (passes: Bool, reasons: [String])? {
        let rows = completedMappedResultRows.sorted { $0.position < $1.position }
        guard rows.count == currentCalculationLogicCount,
              rows.map(\.position) == Array(1...currentCalculationLogicCount),
              let config = try? FilterConfig.parse(generatedInput),
              config.matchNumbers.compactMap(Int.init)
                == currentCalculationMatchNumbers.compactMap(Int.init) else { return nil }
        let reasons = SequenceFilterEngine.baseFilterFailureReasons(
            for: rows.map(\.outcome),
            config: config,
            currentOutcomeSPs: outcomeSPMatrix(for: config, analyses: goalModelAnalyses)
        )
        return (reasons.isEmpty, reasons)
    }

    private func normalizedCurrentABCD(_ value: String?) -> String? {
        guard let value else { return nil }
        let logic = value.filter { "ABCD".contains($0) }
        return logic.count == currentCalculationLogicCount ? logic : nil
    }

