    private func syncSequentialMatchInputs() {
        guard !hasManualMatchSelection else { return }
        guard selectedConditionVersionID != "svip11-breakpoint-selection" else { return }
        guard let first = Int(match1Input.trimmingCharacters(in: .whitespacesAndNewlines)) else { return }
        match2Input = String(first + 1)
        match3Input = String(first + 2)
