    @MainActor
    private func scheduleVIP6AutomaticMatchSelection(debounce: Bool = true) {
        if hasManualMatchSelection {
            vip6AutoSelectionTask?.cancel()
            vip6AutoSelectionTask = Task { @MainActor in await fetchABCDForCurrentInput(debounce: debounce) }
            return
        }
        vip6AutoSelectionTask?.cancel()
        automaticDoubleSelectionCommittedKey = nil
        svip10DoubleMarketEvidence = []; svip10DoubleMarketNotes = [:]; svip10AutomaticDoublePresentation = nil
        svip10DoubleMarketLiveEvidence = []; svip10DoubleMarketLiveNotes = [:]
        svip10MarketLastCheck = nil; svip10MarketRefreshMessage = nil
        guard hasLoadedInputDefaults, inputExperienceMode == "v1", usesVIP6AutomaticMatchSelection else { return }
        let firstText = automaticMatchSearchStart
        guard let first = Int(firstText), first > 0 else {
            isCalculatingVIP6Matches = false
            vip6AutoSelectionMessage = "请输入有效的第一场场次号。"
            return
        }
        // 倾向选场完成后才提交实际六场，搜索起点不参与投注场次写回。
        if !usesAutomaticSearchOrigin { syncSequentialMatchInputs() }
        logicInput = ""
        abcdAttemptedKey = nil
        automaticallyFetchedABCDKey = nil
        goalModelAnalyses = []
        vip6SelectedMatchesWithResults = []
        goalModelErrorMessage = nil
        result = nil
        isCalculatingVIP6Matches = true
        vip6AutoSelectionMessage = selectedConditionVersionID == "svip11-breakpoint-selection"
            ? "正在按前5场彩果断点\(svip11BreakpointRangeInput)概率搜索非连续场次…"
            : (usesFrontTwoADSelection ? "正在向后查找前两场为A或D的六场，允许不连续…" : (usesAllABCDSelection ? "正在向后补齐包含ABCD的六场，允许不连续…" : "已设为连续6场，正在读取这6场的真实赔率…"))
        if usesSVIP10AutomaticDoublePair { vip6AutoSelectionMessage = "正在从起点\(first)读取连续六场，择优选一场31/30/10双选…" }
        let issueInput = beijingSingleIssueInput
        let settingsKey = automaticDoubleSelectionSettingsKey
        vip6AutoSelectionTask = Task { @MainActor in
            do {
                if debounce { try await Task.sleep(nanoseconds: 700_000_000) }
                try Task.checkCancellation()
                guard automaticMatchSearchStart == firstText,
                      beijingSingleIssueInput == issueInput,
                      automaticDoubleSelectionSettingsKey == settingsKey,
                      usesVIP6AutomaticMatchSelection else { return }
                await calculateVIP6AutomaticMatchSelection(firstMatchNumber: first)
            } catch is CancellationError {
                return
            } catch {
                isCalculatingVIP6Matches = false
                vip6AutoSelectionMessage = "VIP6自动选场失败：\(error.localizedDescription)"
            }
        }
    }

    @MainActor
    private func calculateVIP6AutomaticMatchSelection(firstMatchNumber: Int, preserveGeneratedResult: Bool = false) async {
        guard !hasManualMatchSelection else { return }
        isCalculatingVIP6Matches = true
        let collectOnly = preserveGeneratedResult && result != nil
        if !collectOnly { vip6AutoSelectionMessage = "正在读取整期普通欧赔和实际让球…" }
        defer { isCalculatingVIP6Matches = false }
        do {
            let issue = try await resolveCurrentIssue()
            let usesDoublePairs = usesSVIP10AutomaticDoublePair
            let requiresABCD = usesAllABCDSelection
            let requiresFrontAD = usesFrontTwoADSelection
            let fixedFrontTwo = false
            let adWithinSix = usesADDoublesWithinSix
            let automaticDoubleCount = currentAutomaticDoubleCount
            let requiresPattern = requiresABCD || requiresFrontAD || fixedFrontTwo || adWithinSix
            let selectionSettingsKey = automaticDoubleSelectionSettingsKey
            let selectionCalibrated = svip10CalibratedDoubleSelectionEnabled
            let selectionFactors = svip10DoubleJudgmentFactors
            let excludedSingleMatch = Int(singleMatchInput.trimmingCharacters(in: .whitespacesAndNewlines))
            if (usesDoublePairs || usesAutomaticSearchOrigin), !requiresPattern, let excludedSingleMatch,
               (firstMatchNumber..<(firstMatchNumber + 6)).contains(excludedSingleMatch) {
                logicInput = ""
                vip6AutoSelectionMessage = "第7场不能与固定连续6场重复，请修改第7场或第一场场次。"
                return
            }
            let allMatches = try await FiveHundredBeijingSingleClient.fetchAllIssueMatches(issue: issue,
                firstMatchNumberForDoubles: (usesDoublePairs || usesAutomaticSearchOrigin) && !requiresPattern ? firstMatchNumber : nil,
                excludingMatchNumbers: Set([excludedSingleMatch].compactMap { $0 }),
                firstMatchNumberForSelection: requiresPattern ? firstMatchNumber : nil,
                requireAllABCD: requiresABCD, requireFrontTwoAD: requiresFrontAD, fixedFrontTwoDoubles: fixedFrontTwo, calibratedForSelection: selectionCalibrated, adDoublesWithinSix: adWithinSix, adDoubleCountWithinSix: 1)
            try Task.checkCancellation()
            guard Int(automaticMatchSearchStart) == firstMatchNumber,
                  usesVIP6AutomaticMatchSelection else { return }
            let usesBreakpointSelection = selectedConditionVersionID == "svip11-breakpoint-selection"
            let usesFrontFiveM = ["svip11-breakpoint-selection", "svip10-frozen-160", "svip9-dual-s", "svip8-current-three", "svip6-three-condition", "svip5-current-snapshot", "svip4-permutation-lowest-odds", "svip1-xs-current", "svip2-all-basic", "svip3-current-no-four", "vip9-front-five-m3-6", "vip10-front-five-real-sum", "vip11-front-five-mapped-sum", "vip12-probability-bottom20", "vip14-s15-18", "vip15-s15-20-single-no-four", "vip16-probability-top200"]
                .contains(selectedConditionVersionID)
            let usesSixMatchMappedSum = usesVIP11FrontFiveMappedSum
            let scopeDescription = usesSixMatchMappedSum
                ? (["svip2-all-basic", "svip3-current-no-four"].contains(selectedConditionVersionID) ? "\(vip11FamilyVersionLabel)前5场M=2–6与六场234和值14–20" : "VIP11前5场M=3–6与六场234和值13–17")
                : (selectedConditionVersionID == "vip10-front-five-real-sum"
                    ? "VIP10前5场全部条件（S为真实让球欧赔13–17）"
                    : (usesFrontFiveM ? "前5场M=3–6" : "6场M=4–8"))
            if !collectOnly {
                vip6AutoSelectionMessage = usesBreakpointSelection ? "已取得\(allMatches.count)场，正在搜索前5场彩果断点\(svip11BreakpointRangeInput)概率…" : "已取得\(allMatches.count)场，正在计算\(scopeDescription)覆盖率和ABCD…"
                if usesDoublePairs { vip6AutoSelectionMessage = "所选6场已确定，正在读取赛前欧赔、亚盘及公开资金数据…" }
            }
            var selectionPool = allMatches
            var requestedNumbers = Array(firstMatchNumber..<(firstMatchNumber + 6))
            if collectOnly { requestedNumbers = currentCalculationMatchNumbers.compactMap(Int.init) }
            else if requiresPattern {
                vip6AutoSelectionMessage = "正在从起点\(firstMatchNumber)顺延选场，确保六场中至少有一场A/D…"
                requestedNumbers = try await Task.detached(priority: .userInitiated) {
                    try VIP6MatchRecommender.selectMatchNumbers(firstMatchNumber: firstMatchNumber,
                        matches: allMatches, excludingMatchNumbers: Set([excludedSingleMatch].compactMap { $0 }),
                        requireAllABCD: requiresABCD, requireFrontTwoAD: requiresFrontAD, fixedFrontTwoDoubles: fixedFrontTwo, calibrated: selectionCalibrated, adDoublesWithinSix: adWithinSix, adDoubleCountWithinSix: 1)
                }.value
            }
            var selectedMarket = DoubleMarketFetchResult(evidence: [], notes: [:])
            var checkedGroups: Set<[Int]> = []
            var checkedMarkets: [[Int]: DoubleMarketFetchResult] = [:]
            while true {
                try Task.checkCancellation()
                guard automaticDoubleSelectionSettingsKey == selectionSettingsKey,
                      Int(automaticMatchSearchStart) == firstMatchNumber else { return }
                guard checkedGroups.insert(requestedNumbers).inserted else {
                    // 倾向排名可能在核验另一组报价后回到已核验的组。
                    // 使用本次同组快照，不重复请求，也不把正常回选当成循环错误。
                    if fixedFrontTwo || adWithinSix, let checked = checkedMarkets[requestedNumbers] {
                        selectedMarket = checked
                        svip10DoubleMarketLiveEvidence = checked.displayEvidence
                        svip10DoubleMarketLiveNotes = checked.notes
                        break
                    }
                    throw NSError(domain: "ABCDSelection", code: 1, userInfo: [NSLocalizedDescriptionKey:
                        "赔率更新后选场发生变化，请刷新后重试。"])
                }
                let numbers = Set(requestedNumbers)
                selectedMarket = usesDoublePairs ? await DoubleMarketDataClient.fetch(matches: selectionPool.filter {
                    Int($0.matchNumber).map(numbers.contains) == true
                }, factors: selectionFactors, includeTrends: true, leadTime: DoubleMarketDataClient.decisionLeadTime)
                    : DoubleMarketFetchResult(evidence: [], notes: [:])
                try Task.checkCancellation()
                checkedMarkets[requestedNumbers] = selectedMarket
                guard automaticDoubleSelectionSettingsKey == selectionSettingsKey,
                      Int(automaticMatchSearchStart) == firstMatchNumber else { return }
                if usesDoublePairs {
                    svip10DoubleMarketLiveEvidence = selectedMarket.displayEvidence
                    svip10DoubleMarketLiveNotes = selectedMarket.notes
                    svip10MarketLastCheck = Date()
                    let count = selectedMarket.evidence.filter { Date().timeIntervalSince($0.capturedAt) < 180 }.count
                    svip10MarketRefreshMessage = "本次有\(count)/6场可用近期赛前快照；逐场查看实际采样时间及缺失项。"
                    if preserveGeneratedResult && result != nil || isCalculating {
                        svip10MarketRefreshMessage = "本次有\(count)/6场可用近期赛前快照，已归档。已生成结果沿用原快照；点击上方刷新按钮可重新选双选并重新生成。"
                        return
                    }
                }
                if usesDoublePairs && !selectionFactors.isEmpty {
                    selectionPool = DoubleMarketDataClient.applyingVerifiedQuotes(
                        DoubleMarketDataClient.verifiedEvidence(selectedMarket.evidence, matches: selectionPool,
                            matchNumbers: requestedNumbers, leadTime: DoubleMarketDataClient.decisionLeadTime), to: selectionPool)
                }
                if !requiresPattern { break }
                let currentPool = selectionPool
                let adjusted = try await Task.detached(priority: .userInitiated) {
                    try VIP6MatchRecommender.selectMatchNumbers(firstMatchNumber: firstMatchNumber,
                        matches: currentPool, excludingMatchNumbers: Set([excludedSingleMatch].compactMap { $0 }),
                        requireAllABCD: requiresABCD, requireFrontTwoAD: requiresFrontAD, fixedFrontTwoDoubles: fixedFrontTwo, calibrated: selectionCalibrated, adDoublesWithinSix: adWithinSix, adDoubleCountWithinSix: 1)
                }.value
                if adjusted == requestedNumbers { break }
                requestedNumbers = adjusted
            }
            let selectionNumbers = requestedNumbers
            let selectionMatches = selectionPool
            let market = selectedMarket
            let selectionBreakpointRange = svip11SelectedBreakpointRange
            let displacementRange = ["svip2-all-basic", "svip3-current-no-four"].contains(selectedConditionVersionID) ? 2...6 : 3...6
            guard let recommendation = await Task.detached(priority: .userInitiated, operation: {
                if usesDoublePairs {
                    return VIP6MatchRecommender.recommendAutomaticDoubles(firstMatchNumber: firstMatchNumber,
                        matches: selectionMatches, excludingMatchNumbers: Set([excludedSingleMatch].compactMap { $0 }), calibrated: selectionCalibrated,
                        factors: selectionFactors, evidence: market.evidence, matchNumbers: selectionNumbers, fixedFrontTwo: fixedFrontTwo, requireFrontTwoAD: requiresFrontAD, adDoublesWithinSix: adWithinSix, adDoubleCountWithinSix: 1, automaticDoubleCount: automaticDoubleCount)
                }
                if usesBreakpointSelection {
                    return VIP6MatchRecommender.recommendFrontFiveBreakpoints(firstMatchNumber: firstMatchNumber, matches: allMatches, excludingMatchNumbers: Set([excludedSingleMatch].compactMap { $0 }), breakpointRange: selectionBreakpointRange)
                }
                return VIP6MatchRecommender.recommendMatches(
                    numbers: selectionNumbers,
                    matches: selectionMatches,
                    displacementMatchCount: usesFrontFiveM ? 5 : 6,
                    displacementRange: usesFrontFiveM ? displacementRange : 4...8
                )
            }).value else {
                if usesDoublePairs || requiresPattern {
                    logicInput = ""
                    vip6AutoSelectionMessage = "当前所选6场的自定义赔率不完整，尚未完成双选；请刷新补齐，不会从范围外换场。"
                    return
                }
                if usesBreakpointSelection {
                    logicInput = ""
                    vip6AutoSelectionMessage = "自定义赔率完整的候选不足6场，尚不能完成断点概率选场。请刷新整期数据后重试。"
                    return
                }
                vip6AutoSelectionMessage = "整期入口字段不完整，正在切换比分页、交易页和澳客重取当前连续6场…"
                await fetchABCDForCurrentInput(debounce: false)
                return
            }
            try Task.checkCancellation()
            guard !hasManualMatchSelection,
                  recommendation.mainMatchNumbers.first == selectionNumbers.first,
                  recommendation.mainMatchNumbers.count == 6,
                  (usesBreakpointSelection || recommendation.mainMatchNumbers == selectionNumbers),
                  automaticDoubleSelectionSettingsKey == selectionSettingsKey,
                  (selectedConditionVersionID == "svip11-breakpoint-selection") == usesBreakpointSelection,
                  Int(automaticMatchSearchStart) == firstMatchNumber,
                  usesVIP6AutomaticMatchSelection else { return }

            if requiresABCD, Set(recommendation.logic) != Set("ABCD") {
                logicInput = ""
                vip6AutoSelectionMessage = "最新赔率换算后的六场尚未同时包含ABCD，请刷新后重新选场。"
                return
            }
            if requiresFrontAD, !recommendation.logic.prefix(2).allSatisfy({ "AD".contains($0) }) {
                logicInput = ""
                vip6AutoSelectionMessage = "最新赔率换算后前两场不满足A/D，请刷新后重新选场。"
                return
            }
            if usesDoublePairs {
                svip10DoubleMarketEvidence = market.evidence; svip10DoubleMarketNotes = market.notes
                svip10AutomaticDoublePresentation = recommendation.automaticDoubleSelection
            }
            if String(recommendation.mainMatchNumbers[0]) != match1Input {
                programmaticallySelectedFirstMatch = String(recommendation.mainMatchNumbers[0])
                match1Input = String(recommendation.mainMatchNumbers[0])
            }
            match2Input = String(recommendation.mainMatchNumbers[1])
            match3Input = String(recommendation.mainMatchNumbers[2])
            match4Input = String(recommendation.mainMatchNumbers[3])
            match5Input = String(recommendation.mainMatchNumbers[4])
            fixedFullMatchInput = String(recommendation.sixthMatchNumber)
            noFourPositionInput = String(recommendation.noFourPosition)
            if selectedConditionVersionID == "svip3-current-no-four" {
                secondNoFourPositionInput = String(recommendation.secondLowestNoFourPosition)
            }

            let selectedNumbers = recommendation.mainMatchNumbers.map(String.init)
            let allMatchesByNumber = Dictionary(
                selectionMatches.map { ($0.matchNumber, $0) },
                uniquingKeysWith: { first, _ in first }
            )
            let selectedMatches = selectedNumbers.compactMap { allMatchesByNumber[$0] }
            guard selectedMatches.count == selectedNumbers.count else {
                throw GoalModelError.invalidMatchNumbers
            }
            // 真实赛果只留给完赛后的诚实核验页。PoissonGoalModel.analyze
            // 内部会再转成 resultBlindCopy，因此选场和ABCD不可能读到比分。
            vip6SelectedMatchesWithResults = selectedMatches
            let completedResultCount = selectedMatches.filter { $0.handicapOutcome != nil }.count
            vip6ResultVerificationMessage = completedResultCount == selectedNumbers.count
                ? "已取得6/6场真实赛果，已按VIP7当前启用条件完成核验。"
                : "已取得\(completedResultCount)/\(selectedNumbers.count)场真实赛果；未齐前不判定过关。"
            conditionHandicaps = Dictionary(uniqueKeysWithValues: selectedMatches.compactMap { match in
                guard let handicap = match.handicap else { return nil }
                return (match.matchNumber, handicap)
            })

            // 选场器在此时已经用对照表得到完整6位ABCD。必须立即提交和落盘，
            // 后面的Poisson明细只用于展示，任何单场拟合失败都不能再阻断ABCD。
            logicInput = recommendation.logic
            abcdAttemptedKey = abcdInputKey
            automaticallyFetchedABCDKey = abcdInputKey
            abcdSourceMessage = "ABCD已自动生成：\(recommendation.logic) · 第\(issue)期 · 场次\(selectedNumbers.joined(separator: ","))"
            if recommendation.automaticDoubleSelection != nil {
                automaticDoubleSelectionCommittedKey = automaticDoubleGenerationKey
            }

            var persisted = UserDefaults.standard.dictionary(forKey: globalABCDCacheStorageKey)
                as? [String: String] ?? [:]
            let cacheKey = TXTQueryStatisticsCalculator.uniqueKey(
                issue: issue,
                matchNumbers: selectedNumbers
            )
            persisted[cacheKey] = recommendation.logic
            UserDefaults.standard.set(persisted, forKey: globalABCDCacheStorageKey)
            saveGoalModelRecommendation(
                issue: issue,
                matchNumbers: selectedNumbers,
                logic: recommendation.logic
            )
            UserDefaults.standard.set(persistedInputValues, forKey: inputDefaultsStorageKey)
            UserDefaults.standard.synchronize()
            NSLog(
                "VIP7 ABCD committed issue=%@ matches=%@ logic=%@",
                issue,
                selectedNumbers.joined(separator: ","),
                recommendation.logic
            )

            let analyses = await Task.detached(priority: .userInitiated) {
                selectedMatches.compactMap { try? PoissonGoalModel.analyze($0) }
            }.value
            try Task.checkCancellation()
            guard automaticDoubleSelectionSettingsKey == selectionSettingsKey,
                  Int(match1Input.trimmingCharacters(in: .whitespacesAndNewlines)) == recommendation.mainMatchNumbers.first else { return }
            goalModelAnalyses = analyses

            let warnings = vip6HandicapDepthWarnings(matches: selectedMatches)
            let percentage = String(format: "%.2f", recommendation.mCoverageProbability * 100)
            let noFourPercentage = String(format: "%.2f", recommendation.noFourProbability * 100)
            let secondNoFourPercentage = String(
                format: "%.2f",
                recommendation.secondLowestNoFourProbability * 100
            )
            let dayText = recommendation.outsideFirstMatchDayCount == 0
                ? "6场均在第一场当天"
                : "当天场次不足，有\(recommendation.outsideFirstMatchDayCount)场跨天"
            let warningText = warnings.isEmpty ? "" : "；盘口提示：" + warnings.joined(separator: "、")
            let mDescription = usesFrontFiveM ? "前5场M=3–6" : "6场M=4–8"
            let secondNoFourText = selectedConditionVersionID == "svip3-current-no-four"
                ? "；第\(recommendation.secondLowestNoFourPosition)场判定值4概率第二低（约\(secondNoFourPercentage)%）"
                : ""
            vip6AutoSelectionMessage = "VIP\(usesFrontFiveM ? "9" : "6")已选定6场\(selectedNumbers.joined(separator: ","))；\(dayText)；\(mDescription)赛前估算约\(percentage)%；赔率参考中第\(recommendation.noFourPosition)场判定值4概率最低（约\(noFourPercentage)%）\(secondNoFourText)\(warningText)"
            conditionRecommendationMessage = "VIP\(usesFrontFiveM ? "9" : "6")已使用所选6场；“前三场最多1个4”和“某一场不是4”均按条件Tab开关执行。M覆盖率不是整单中奖率。"
            if let automatic = recommendation.automaticDoubleSelection {
                let choices = automatic.choices.map { "场次\($0.number)双选\($0.retainedOutcomes.map(String.init).joined())" }.joined(separator: "；")
                vip6AutoSelectionMessage = "已在所选6场内自动选择：\(choices)；六场\(selectedNumbers.joined(separator: ","))。所选双选赔率基础估算\(String(format: "%.2f", automatic.estimatedJointCoverage * 100))%（独立假设），不是多因素模型的实测命中率。"
                conditionRecommendationMessage = adWithinSix ? "保留起点；六场没有A/D时顺延找一场A/D替换靠后的B/C，仍选六场。只择优选一场A/D双选，A选31、D选10，位置不固定，其余五场初始全选，再按当前已开条件过滤，不设注数上限。" : (automaticDoubleCount == 1 ? "连续六场内择优选一场31/30/10双选，不限A/D，其余五场初始全选；再执行当前条件，不固定注数。" : "固定本次六场，两场双选、四场全选，再执行其余已开条件。")
                if let forecast = DoubleForwardForecast.make(selection: automatic, matches: selectedMatches,
                    calibrated: selectionCalibrated, factors: selectionFactors, allABCDSelection: requiresABCD, frontTwoADSelection: requiresFrontAD, fixedFrontTwoDoubles: fixedFrontTwo, adDoublesWithinSix: adWithinSix, adDoubleCountWithinSix: 1, automaticDoubleCount: automaticDoubleCount) {
                    do {
                        if try await DoubleForwardValidationStore.shared.record(forecast) { doubleForwardRevision += 1 }
                    } catch {
                        svip10MarketRefreshMessage = "双选已完成，但赛前登记保存失败：\(error.localizedDescription)；本次不计入实测。"
                    }
                }
            }
            if usesBreakpointSelection {
                vip6AutoSelectionMessage = "SVIP11按断点概率选场：\(selectedNumbers.joined(separator: ","))；前5场彩果断点\(svip11BreakpointRangeInput)估计概率\(percentage)%；第6场取第5场之后最近的有效场次。大型候选池为确定性搜索所得，并非全局最优保证。"
                conditionRecommendationMessage = "固定输入第1场，允许非连续选场；断点\(svip11BreakpointRangeInput)同时用于选场和过滤；并过滤前6场S、前5场实际M与指定场次不是4。"
            }
            if requiresABCD {
                vip6AutoSelectionMessage = "已补齐ABCD：\(recommendation.logic)；六场\(selectedNumbers.joined(separator: ","))（允许不连续）。" + (vip6AutoSelectionMessage ?? "")
            }
            if adWithinSix { vip6AutoSelectionMessage = "六场内A/D双选已确定，位置随本次六场变化；" + (vip6AutoSelectionMessage ?? "") }
            if requiresFrontAD { vip6AutoSelectionMessage = "前两场A/D已满足：\(recommendation.logic.prefix(2))；" + (vip6AutoSelectionMessage ?? "") }
            scheduleDurableBackup()
        } catch is CancellationError {
            return
        } catch {
            if collectOnly {
                svip10MarketRefreshMessage = "行情检查失败：\(error.localizedDescription)；已生成结果继续使用原快照。"
                return
            }
            if usesSVIP10AutomaticDoublePair || usesStructuredMatchSelection {
                logicInput = ""
                vip6AutoSelectionMessage = "六场选场失败：\(error.localizedDescription)。请刷新重试。"
                return
            }
            if selectedConditionVersionID == "svip11-breakpoint-selection" {
                logicInput = ""
                vip6AutoSelectionMessage = "断点概率选场失败：\(error.localizedDescription)。请刷新重试。"
                return
            }
            let reason = error.localizedDescription
            vip6AutoSelectionMessage = "整期入口失败，正在切换比分页、交易页和澳客重取当前连续6场…"
            goalModelErrorMessage = "整期入口失败：\(reason)；已自动启动六场直取回退。"
            await fetchABCDForCurrentInput(debounce: false)
        }
    }

    private func vip6HandicapDepthWarnings(matches: [BeijingSingleMatch]) -> [String] {
        matches.compactMap { match in
            guard let handicap = match.handicap,
                  match.marketOdds.count == 3,
                  let favoriteIndex = match.marketOdds.indices.min(by: {
                      match.marketOdds[$0] < match.marketOdds[$1]
                  }),
                  favoriteIndex != 1 else { return nil }
            let favoriteOdds = match.marketOdds[favoriteIndex]
            let expectedMagnitude: Int
            if favoriteOdds <= 1.08 {
                expectedMagnitude = 4
            } else if favoriteOdds <= 1.15 {
                expectedMagnitude = 3
            } else if favoriteOdds <= 1.45 {
                expectedMagnitude = 2
            } else if favoriteOdds < 1.90 {
                expectedMagnitude = 1
            } else {
                expectedMagnitude = 0
            }
            let expected = favoriteIndex == 0 ? -expectedMagnitude : expectedMagnitude
            guard abs(handicap) > abs(expected) else { return nil }
            return "第\(match.matchNumber)场实际\(signedHandicap(handicap))，比经验线\(signedHandicap(expected))深"
        }
    }

    private func loadCurrentAnalysesForProbabilityIfNeeded(
        for config: FilterConfig,
        requireCompleteComparisonTableOdds: Bool
    ) async -> [GoalModelAnalysis] {
        let issue: String
        do {
            issue = try await resolveCurrentIssue()
        } catch {
            goalModelErrorMessage = "命中概率暂未计算：\(error.localizedDescription)"
            return []
        }
        let isVIP4 = SequenceFilterEngine.usesVIP4Model(
            threshold: config.universal247ToleranceThreshold
        )
        let isVIP3 = SequenceFilterEngine.usesVIP3Model(
            threshold: config.universal247ToleranceThreshold
        )
        let requestedNumbers: [String]
        if isVIP4 {
            requestedNumbers = vip4AnalysisNumbers(for: config)
        } else if isVIP3,
                  let sixth = config.extraMatches.first(where: {
                      Set($0.outcomes) == Set([3, 1, 0])
                  }) {
            requestedNumbers = config.matchNumbers + [sixth.matchNumber]
        } else {
            let probabilityCount = config.vip12ProbabilityReductionEnabled
                ? config.matchNumbers.count
                : min(
                    config.calculationMatchCount ?? config.matchNumbers.count,
                    config.matchNumbers.count
                )
            // 按开启条件的真实作用范围补取。SVIP2 基础条件多数用
            // 前 5 场，但自定义赔率乘积用前 6 场，不能只请求前 5 场。
            let requiredCount = max(probabilityCount, config.requiredCustomOddsMatchCount)
            requestedNumbers = Array(config.matchNumbers.prefix(requiredCount))
        }
        let requested = requestedNumbers.compactMap(Int.init)
        let matchingIssueAnalyses = goalModelAnalyses.filter { $0.match.issue == issue }
        let available = Set(matchingIssueAnalyses.compactMap { Int($0.match.matchNumber) })
        if requested.count == requestedNumbers.count,
           Set(requested).count == requestedNumbers.count,
           Set(requested).isSubset(of: available) {
            if !requireCompleteComparisonTableOdds
                || HandicapOddsComparisonTableMatrix.rows(
                    matchNumbers: requestedNumbers,
                    matches: matchingIssueAnalyses.map(\.match)
                ) != nil {
                return matchingIssueAnalyses
            }
        }
        do {
            let matches = try await (requireCompleteComparisonTableOdds
                ? FiveHundredBeijingSingleClient.fetchScorePageOdds(
                    issue: issue,
                    matchNumbers: requestedNumbers
                )
                : FiveHundredBeijingSingleClient.fetch(
                    issue: issue,
                    matchNumbers: requestedNumbers
                ))
            let analyses = try await Task.detached(priority: .userInitiated) {
                try matches.map(PoissonGoalModel.analyze)
            }.value
            goalModelAnalyses = analyses
            return analyses
        } catch {
            goalModelErrorMessage = "命中概率暂未计算：\(error.localizedDescription)"
            return []
        }
    }

    private func outcomeProbabilityMatrix(
        for config: FilterConfig,
        analyses: [GoalModelAnalysis]
    ) -> [[Double]]? {
        let byMatch = Dictionary(uniqueKeysWithValues: analyses.compactMap { analysis in
            Int(analysis.match.matchNumber).map { ($0, analysis) }
        })
        let requiredCount = (config.vip12ProbabilityReductionEnabled || config.svip1CustomOddsGuardEnabled)
            ? config.matchNumbers.count
            : min(config.calculationMatchCount ?? config.matchNumbers.count, config.matchNumbers.count)
        let selected = config.matchNumbers.prefix(requiredCount).compactMap { match -> GoalModelAnalysis? in
            guard let number = Int(match), let analysis = byMatch[number] else {
                return nil
            }
            return analysis
        }
        guard selected.count == requiredCount else {
            return nil
        }
        return selected.map(\.handicapProbabilities)
    }

    private func outcomeSPMatrix(
        for config: FilterConfig,
        analyses: [GoalModelAnalysis]
    ) -> [[Double]]? {
        let requiredCount = config.requiredCustomOddsMatchCount
        return HandicapOddsComparisonTableMatrix.rows(
            matchNumbers: Array(config.matchNumbers.prefix(requiredCount)),
            matches: analyses.map(\.match)
        )
    }

    private func vip3MatchContext(
        for config: FilterConfig,
        analyses: [GoalModelAnalysis]
    ) -> VIP3MatchContext? {
        guard SequenceFilterEngine.usesVIP3Model(
            threshold: config.universal247ToleranceThreshold
        ),
        let sixth = config.extraMatches.first(where: {
            Set($0.outcomes) == Set([3, 1, 0])
        }) else { return nil }
        let numbers = config.matchNumbers + [sixth.matchNumber]
        let byNumber = Dictionary(uniqueKeysWithValues: analyses.compactMap { analysis in
            Int(analysis.match.matchNumber).map { ($0, analysis) }
        })
        let selected = numbers.compactMap { value in
            Int(value).flatMap { byNumber[$0] }
        }
        guard selected.count == 6,
              let odds = HandicapOddsComparisonTableMatrix.rows(
                matchNumbers: numbers,
                matches: selected.map(\.match)
              ) else { return nil }
        let handicaps = selected.compactMap(\.match.handicap)
        guard handicaps.count == 6 else { return nil }
        let comparisonLogic = odds.compactMap(LogicMapping.derivedFromComparisonTableOdds)
        guard comparisonLogic.count == 6 else { return nil }
        return VIP3MatchContext(
            comparisonTableOdds: odds,
            handicaps: handicaps,
            leagues: selected.map(\.match.league),
            logic: comparisonLogic
        )
    }

    private func vip4MatchContext(
        for config: FilterConfig,
        analyses: [GoalModelAnalysis],
        previousOutcomes: [Int]? = nil
    ) -> VIP4MatchContext? {
        guard SequenceFilterEngine.usesVIP4Model(
            threshold: config.universal247ToleranceThreshold
        ),
        let sixth = config.extraMatches.first(where: {
            Set($0.outcomes) == Set([3, 1, 0])
        }) else { return nil }
        let numbers = config.matchNumbers + [sixth.matchNumber]
        let byNumber = Dictionary(uniqueKeysWithValues: analyses.compactMap { analysis in
            Int(analysis.match.matchNumber).map { ($0, analysis) }
        })
        let selected = numbers.compactMap { value in
            Int(value).flatMap { byNumber[$0] }
        }
        guard selected.count == 6 else { return nil }
        let inputs = selected.compactMap { analysis -> VIP4MatchInput? in
            guard let handicap = analysis.match.handicap,
                  analysis.match.marketOdds.count == 3,
                  analysis.handicapFairOdds.count == 3 else { return nil }
            return VIP4MatchInput(
                comparisonTableOdds: analysis.handicapFairOdds,
                ordinaryOdds: analysis.match.marketOdds,
                handicap: handicap,
                league: analysis.match.league,
                logic: LogicMapping.derivedFromComparisonTableOdds(analysis.handicapFairOdds) ?? .a,
                homeExpectedGoals: analysis.homeExpectedGoals,
                awayExpectedGoals: analysis.awayExpectedGoals,
                fitError: analysis.fitError
            )
        }
        guard inputs.count == 6 else { return nil }
        let derivedPreviousOutcomes: [Int]?
        if let previousOutcomes, previousOutcomes.count == 6 {
            derivedPreviousOutcomes = previousOutcomes
        } else if let first = numbers.first.flatMap(Int.init), first > 6 {
            let previous = ((first - 6)..<first).compactMap { byNumber[$0]?.match.handicapOutcome }
            derivedPreviousOutcomes = previous.count == 6 ? previous : nil
        } else {
            derivedPreviousOutcomes = nil
        }
        return VIP4MatchContext(
            matches: inputs,
            previousOutcomes: derivedPreviousOutcomes
        )
    }

    private func vip4AnalysisNumbers(for config: FilterConfig) -> [String] {
        guard let sixth = config.extraMatches.first(where: {
            Set($0.outcomes) == Set([3, 1, 0])
        }) else { return config.matchNumbers }
        var numbers = config.matchNumbers + [sixth.matchNumber]
        if let first = config.matchNumbers.first.flatMap(Int.init), first > 6 {
            numbers.append(contentsOf: ((first - 6)..<first).map(String.init))
        }
        return Array(Set(numbers)).sorted { (Int($0) ?? 0) < (Int($1) ?? 0) }
    }

    private func applyRecommendedConditions(
        recommendation: String,
        matchNumbers: [String],
        analyses: [GoalModelAnalysis]
    ) {
        let logic = recommendation.lowercased().compactMap { LogicMapping(rawValue: String($0)) }
        let probabilities = matchNumbers.compactMap { number in
            analyses.first { Int($0.match.matchNumber) == Int(number) }?.handicapProbabilities
        }
        guard let recommended = SequenceFilterEngine.recommendedConditions(
            logic: logic,
            outcomeProbabilities: probabilities
        ) else { return }
        sumInput = "\(recommended.sumRange.lowerBound)-\(recommended.sumRange.upperBound)"
        displacementInput = "\(recommended.displacementRange.lowerBound)-\(recommended.displacementRange.upperBound)"
        varianceInput = compactDecimal(recommended.varianceMaximum, maximumDigits: 4)
        valueTwoMaximumInput = String(recommended.valueTwoMaximum)
        transitionMinimumInput = compactDecimal(recommended.transitionMinimumPercent, maximumDigits: 3)
        conditionRecommendationMessage = "已依据 \(recommendation) 与五场泊松概率更新默认范围；现在仍可手动调整。"
    }

    private func applyRecommendedConditionsFromManualLogic(_ input: String) {
        let cleaned = input.lowercased().filter { "abcd".contains($0) }
        let logic = cleaned.compactMap { LogicMapping(rawValue: String($0)) }
        guard cleaned.count == 5,
              logic.count == 5,
              let recommended = SequenceFilterEngine.recommendedConditions(logic: logic) else {
            return
        }
        sumInput = "\(recommended.sumRange.lowerBound)-\(recommended.sumRange.upperBound)"
        displacementInput = "\(recommended.displacementRange.lowerBound)-\(recommended.displacementRange.upperBound)"
        varianceInput = compactDecimal(recommended.varianceMaximum, maximumDigits: 4)
        valueTwoMaximumInput = String(recommended.valueTwoMaximum)
        transitionMinimumInput = compactDecimal(recommended.transitionMinimumPercent, maximumDigits: 3)
        conditionRecommendationMessage = "ABCD \(cleaned.uppercased()) 推荐：S \(sumInput)，M \(displacementInput)，σ²≤\(varianceInput)，值2≤\(valueTwoMaximumInput)，P_tr≥\(transitionMinimumInput)%。可手动调整。"
    }

    private func compactDecimal(_ value: Double, maximumDigits: Int) -> String {
        var text = String(format: "%.*f", maximumDigits, value)
        while text.contains(".") && text.last == "0" { text.removeLast() }
        if text.last == "." { text.removeLast() }
        return text
    }

    private func shouldApplyRelationshipCondition(
        for config: FilterConfig,
        analyses: [GoalModelAnalysis]
    ) -> Bool {
        let byMatch = Dictionary(uniqueKeysWithValues: analyses.compactMap { analysis in
            Int(analysis.match.matchNumber).map { ($0, analysis) }
        })
        let selected = config.matchNumbers.compactMap { match in
            Int(match).flatMap { byMatch[$0] }
        }
        return selected.count == config.matchNumbers.count
            && selected.allSatisfy { $0.confidenceIndex >= 55 }
    }

    private func filterMethodDescription(_ result: FilterResult) -> String {
        "不再执行乘积Q删注；第六场全包始终作为完整选项参与其余条件过滤。"
    }

    private func hitProbabilityEstimate(
        for result: FilterResult,
        analyses: [GoalModelAnalysis]
    ) -> (probability: Double, explanation: String)? {
        let byMatch = Dictionary(uniqueKeysWithValues: analyses.compactMap { analysis in
            Int(analysis.match.matchNumber).map { ($0, analysis) }
        })
        func outcomeProbability(_ outcome: Int, matchNumber: String) -> Double? {
            guard let number = Int(matchNumber), let analysis = byMatch[number] else { return nil }
            let index = outcome == 3 ? 0 : (outcome == 1 ? 1 : (outcome == 0 ? 2 : -1))
            guard index >= 0, analysis.handicapProbabilities.indices.contains(index) else { return nil }
            return analysis.handicapProbabilities[index]
        }

        var mainCoverage = 0.0
        for record in result.records {
            var joint = 1.0
            for (match, outcome) in zip(result.config.matchNumbers, record.outcomes) {
                guard let probability = outcomeProbability(outcome, matchNumber: match) else { return nil }
                joint *= probability
            }
            mainCoverage += joint
        }

        let estimate = min(max(mainCoverage, 0), 1)
        let explanation = "只计算保留主场组合的五场模型覆盖率，不包括固定场命中率。减半可能删除部分固定场选项，因此该数值不是完整TXT的中奖概率。"
        return (estimate, explanation)
    }

    private func confidenceColor(_ index: Int) -> Color {
        if index >= 75 { return .green }
        if index >= 55 { return .blue }
        return .orange
    }

    private func percent(_ value: Double) -> String {
        "\(String(format: "%.1f", value * 100))%"
    }

    private func signedHandicap(_ value: Int) -> String {
        value > 0 ? "+\(value)" : "\(value)"
    }

    private func displayedMatches(_ matchNumbers: [String], handicaps: [Int?]?) -> String {
        matchNumbers.enumerated().map { index, number in
            guard let handicaps, handicaps.indices.contains(index), let handicap = handicaps[index] else {
                return "\(number)（让球待获取）"
            }
            return "\(number)（让球\(signedHandicap(handicap))）"
        }.joined(separator: "、")
    }

