    private func packageRuntimeInput(_ input: String, enabled: Bool, relationship: Bool? = nil, relationshipRanges: [String]? = nil, scoreUpper: String? = nil) -> String {
        var fields = input.components(separatedBy: "|").map {
            $0 == "MCOUNT=5" ? "MCOUNT=6" : ($0 == "CALCCOUNT=5" ? "CALCCOUNT=6" : $0)
        }
        let extraStart = fields.indices.dropFirst(7).first { fields[$0].contains(":") } ?? (fields.count - 1)
        let ranges = relationshipRanges ?? [six250SumRangeInput, six250MRangeInput, six250RRangeInput]
        fields.insert(contentsOf: ["SCORE250=\(scoreUpper ?? six250ScoreUpperInput)", "S250=\(ranges[0])", "M250=\(ranges[1])", "R250=\(ranges[2])", "SIX250=\((relationship ?? six250RelationshipEnabled) ? 1 : 0)", "SIXSCOPE=1", "PACKAGEON=\(enabled ? 1 : 0)"], at: extraStart)
        return fields.joined(separator: "|")
    }

    private func svip7RuntimeInput(_ input: String, enabled: Bool) -> String {
        let fields = input.components(separatedBy: "|")
        guard fields.count >= 2 else { return input }
        let extras = fields.dropFirst(2).filter { $0.contains(":") }
        return ([fields[0], fields[1], "0-24", "0-100", "100", "6", "0", "100", "0-5",
                 "QDROP0", "FINAL=OFF", "SVIP7=1", "SIXSCOPE=1", "SUMCOUNT=6", "MCOUNT=6",
                 "CALCCOUNT=6", "PACKAGEON=\(enabled ? 1 : 0)", "NO4="]
                + extras + ["MERGE3"]).joined(separator: "|")
    }

    private func applyingConditionEditorSettings(to input: String, values: [String: String]) -> String {
        let disabled = Set((values["disabledBasicConditions"] ?? "").split(separator: ",")
            .compactMap { BasicCondition(rawValue: String($0)) })
        let outcomes = FilterInputDefaults.enabledEditorOutcomeRanges(values: values,
            defaultRanges: Dictionary(uniqueKeysWithValues: OutcomeCondition.editorCases.map {
                ($0, defaultOutcomeConditionRange($0))
            }))
        var fields = input.components(separatedBy: "|")
        if values["selectedConditionVersionID"] == "svip10-frozen-160", fields.count > 7 {
            fields[5] = values["svip10ValueTwoMaximumInput"] ?? "4"
            fields = fields.map { $0.hasPrefix("R250=") ? "R250=\(values["svip10RRangeInput"] ?? "0-15")" : $0 }
        }
        let switched = FilterConfig.appendingConditionSwitches(to: fields.joined(separator: "|"), disabled: disabled,
            valueThreeMaximum: Int(values["valueThreeMaximumInput"] ?? "5") ?? -1, outcomeRanges: outcomes)
        let groupEnabled: Bool? = values["svvvSelected"] == "1"
            && values["selectedConditionVersionID"] == "svip10-frozen-160"
            ? values["svvvHighPass40Enabled"] == "1" : nil
        let withForty = FilterConfig.appendingHighPass93Group(to: switched, enabled: groupEnabled)
        let hundredEnabled: Bool? = values["svvvSelected"] == "1"
            && values["selectedConditionVersionID"] == "svip10-frozen-160"
            ? values["svvvHighPass100Enabled"] == "1" : nil
        let withHundred = FilterConfig.appendingHighPass98Group(to: withForty, enabled: hundredEnabled)
        let fiftyEnabled: Bool? = values["svvvSelected"] == "1"
            && values["selectedConditionVersionID"] == "svip10-frozen-160"
            ? values["svvvHighPass50Enabled"] == "1" : nil
        let withFifty = FilterConfig.appendingHighPass98FiftyGroup(to: withHundred, enabled: fiftyEnabled)
        let assembled = FilterConfig.appendingHighPass50Double(to: withFifty,
            enabled: fiftyEnabled != nil && values["svvvHighPass50DoubleEnabled"] == "1")
        let live = values["selectedConditionVersionID"] == "svip10-frozen-160"
            ? FilterInputDefaults.removingLiveDoubleRestrictions(from: assembled) : assembled
        return FilterConfig.appendingFinalResultFilters(to: live,
            values: values["selectedConditionVersionID"] == "svip10-frozen-160" ? values : [:])
    }

    private var conditionEditorRuntimeValues: [String: String] {
        var values = [
            "svvvSelected": svvvSelected ? "1" : "0",
            "svvvHighPass40Enabled": svvvHighPass40Enabled ? "1" : "0",
            "svvvHighPass100Enabled": svvvHighPass100Enabled ? "1" : "0",
            "svvvHighPass50Enabled": svvvHighPass50Enabled ? "1" : "0",
            "svvvHighPass50DoubleEnabled": svvvHighPass50DoubleEnabled ? "1" : "0",
            "selectedConditionVersionID": selectedConditionVersionID,
            "disabledBasicConditions": disabledBasicConditions.map(\.rawValue).sorted().joined(separator: ","),
            "enteredConditionIDs": enteredConditionIDs.joined(separator: ","),
            "valueThreeMaximumInput": valueThreeMaximumInput,
            "svip10RRangeInput": svip10RRangeInput,
            "svip10ValueTwoMaximumInput": svip10ValueTwoMaximumInput
        ]
        for condition in OutcomeCondition.editorCases {
            values["OCON_" + condition.rawValue] = outcomeConditionEnabled[condition] == true ? "1" : "0"
            values["OC_" + condition.rawValue] = outcomeConditionInputs[condition] ?? defaultOutcomeConditionRange(condition)
        }
        values.merge(finalResultFilterInputValues) { _, current in current }
        return values
    }

