    private var baseGeneratedInput: String {
        if selectedConditionVersionID == "svip11-breakpoint-selection" {
            let fields = rawGeneratedInput.components(separatedBy: "|")
            return FilterConfig.svip11Input(numbers: fields[0].components(separatedBy: ","), logic: fields[1], extras: fields.filter { $0.contains(":") }, enabled: isVIPConditionEnabled && svip10Enabled, noFourPosition: svip10NoFourEnabled ? svip10NoFourPosition : nil, sumRange: svip10SumRangeInput, mRange: svip10MRangeInput, breakpointRange: svip11BreakpointRangeInput, adaptiveS: v1RecommendedSEnabled)
        }
        if selectedConditionVersionID == "svip10-frozen-160" {
            let fields = rawGeneratedInput.components(separatedBy: "|")
            let input = FilterConfig.svip10Input(numbers: fields[0].components(separatedBy: ","), logic: fields[1], extras: fields.filter { $0.contains(":") }, enabled: isVIPConditionEnabled && svip10Enabled, scoreRange: svip10ScoreRangeInput, noFourPosition: nil, sumRange: svip10SumRangeInput, mRange: svip10MRangeInput)
            return FilterConfig.appendingSVIP10AdditionalInput(input, coldEnabled: svip10ColdCountEnabled, coldRange: svip10ColdCountRangeInput, drawEnabled: svip10DrawCountEnabled, drawRange: svip10DrawCountRangeInput, winLossSwitchEnabled: svip10WinLossSwitchEnabled, highestDoubleProbabilityTopTwoEnabled: false, secondDoubleLowestProbabilityEnabled: false, fiveMatchMEnabled: svip10FiveMatchMEnabled, fiveMatchMRange: svip10FiveMatchMRangeInput, frontFiveSameOutcomeRunMaximum2Enabled: svip10FrontFiveSameOutcomeRunMaximum2Enabled, frontFiveReturnMaximum2Enabled: svip10FrontFiveReturnMaximum2Enabled, frontFiveNoConsecutiveDrawEnabled: svip10FrontFiveNoConsecutiveDrawEnabled, frontFiveValueThreeMaximum2Enabled: svip10FrontFiveValueThreeMaximum2Enabled, sixMatchFavoriteCount1To4Enabled: svip10SixMatchFavoriteCount1To4Enabled, sixMatchMinimumOddsProductEnabled: svip10SixMatchMinimumOddsProductEnabled, sixMatchMinimumOddsProduct: svip10SixMatchMinimumOddsProductInput, sixMatchBreakpoint3To5Enabled: svip10SixMatchBreakpoint3To5Enabled, topThreeProbabilityRecovery100Enabled: svip10TopThreeProbabilityRecovery100Enabled, statisticalLineBudgetEnabled: svip10StatisticalLineBudgetEnabled, probabilityMass60Enabled: svip10ProbabilityMass60Enabled, calibratedDoubleSelectionEnabled: svip10CalibratedDoubleSelectionEnabled, sixMatchBreakpointRange: svip10SixMatchBreakpointRangeInput, automaticDoublePairEnabled: false, judgmentFactors: [], marketEvidence: [], allABCDSelectionEnabled: false, maximum105Enabled: false, frontTwoADEnabled: false, fixedFrontTwoDoublesEnabled: false, adDoublesWithinSixEnabled: false, adDoubleCountWithinSix: 1, automaticDoubleCount: currentAutomaticDoubleCount)
        }
        if selectedConditionVersionID == "svip9-dual-s" {
            var fields = rawGeneratedInput(for: "svip5-current-snapshot").components(separatedBy: "|")
            fields[2] = svip9BaseSumRangeInput
            let legacy = packageRuntimeInput(fields.joined(separator: "|"), enabled: true)
            return FilterConfig.svip9Input(inheritingSVIP5: legacy, fixedRange: sumInput, fixedEnabled: isVIPConditionEnabled && svip6SumEnabled, adaptiveEnabled: isVIPConditionEnabled && oddsAdaptiveSEnabled, legacyEnabled: isVIPConditionEnabled && currentConditionPackageEnabled, compactEnabled: svip9TXTCompactEnabled, maximumAdditionalBets: svip9TXTAdditionalLimit)
        }
        if ["svip11-breakpoint-selection", "svip10-frozen-160", "svip9-dual-s", "svip8-current-three", "svip6-three-condition"].contains(selectedConditionVersionID) {
            let fields = rawGeneratedInput.components(separatedBy: "|")
            return FilterConfig.svip6Input(numbers: fields[0].components(separatedBy: ","), logic: fields[1], extras: fields.filter { $0.contains(":") }, sumRange: sumInput, sumEnabled: isVIPConditionEnabled && svip6SumEnabled, noFourPosition: isVIPConditionEnabled && noFourPositionFilterEnabled ? Int(svip4NoFourSelection) : nil, broadPackageEnabled: isVIPConditionEnabled && currentConditionPackageEnabled)
        }
        if isVIPConditionEnabled && selectedConditionVersionID == "svip7-odds-rank-280" {
            return svip7RuntimeInput(rawGeneratedInput, enabled: currentConditionPackageEnabled)
        }
        guard selectedConditionVersionID == "svip5-current-snapshot" else { return rawGeneratedInput }
        return packageRuntimeInput(rawGeneratedInput, enabled: currentConditionPackageEnabled)
    }

    private var rawGeneratedInput: String { rawGeneratedInput(for: selectedConditionVersionID) }

    private func rawGeneratedInput(for selectedConditionVersionID: String) -> String {
        let mainMatches = currentCalculationMatchNumbers.joined(separator: ",")
        let extras = usesVIP6AutomaticMatchSelection
            ? "\(singleMatchInput):\(singleOutcomeInput)"
            : "\(effectiveFixedFullMatchInput):310|\(singleMatchInput):\(singleOutcomeInput)"
        let calculationScopeToken: String
        if isVIPConditionEnabled && usesVIP10FrontFiveRealSum {
            calculationScopeToken = "MCOUNT=5|CALCCOUNT=5|REALSUM=1|"
        } else if isVIPConditionEnabled && usesVIP11FrontFiveMappedSum {
            calculationScopeToken = "MCOUNT=5|SUMCOUNT=6|CALCCOUNT=5|"
        } else if isVIPConditionEnabled && selectedConditionVersionID == "vip9-front-five-m3-6" {
            calculationScopeToken = "MCOUNT=5|"
        } else {
            calculationScopeToken = ""
        }
        let customOddsProductCountToken = ["svip11-breakpoint-selection", "svip10-frozen-160", "svip9-dual-s", "svip8-current-three", "svip6-three-condition", "svip5-current-snapshot", "svip4-permutation-lowest-odds", "svip1-xs-current", "svip2-all-basic", "svip3-current-no-four", "vip12-probability-bottom20"].contains(selectedConditionVersionID)
            ? "HODDSPRODCOUNT=6|"
            : "HODDSPRODCOUNT=0|"
        let conditionScopeToken = calculationScopeToken
            + customOddsProductCountToken
            + (isVIPConditionEnabled && usesSVIPPermutationVersion
                ? "SVIP5DROP=0|TOP5SECOND=1|TOP5RELAX=1|FIVEWIDE=1|STRUCTRELAX=1|STRUCT3R=\(combinedThreeRRangeInput)|F6LOSS14ON=\(selectedConditionVersionID == "svip5-current-snapshot" && sixLossCount14Enabled ? 1 : 0)|F5R39ON=\(selectedConditionVersionID == "svip5-current-snapshot" && frontFiveR39Enabled ? 1 : 0)|F5NO000ON=\(selectedConditionVersionID == "svip5-current-snapshot" && frontFiveNoTripleLossEnabled ? 1 : 0)|F5ACTUALMRANGE=\(frontFiveActualMRangeInput)|STRUCT3ON=\(selectedConditionVersionID == "svip5-current-snapshot" && combinedThreeStructureEnabled ? 1 : 0)|F5LOSSRANGE=\(frontFiveLossCountRangeInput)|F5WINRANGE=\(frontFiveWinCountRangeInput)|F5WINON=\(selectedConditionVersionID == "svip5-current-snapshot" && frontFiveWinCountEnabled ? 1 : 0)|F5LOSS13ON=\(selectedConditionVersionID == "svip5-current-snapshot" && frontFiveLossCountEnabled ? 1 : 0)|F5NO111ON=\(selectedConditionVersionID == "svip5-current-snapshot" && frontFiveNoTripleDrawEnabled ? 1 : 0)|F5ACTUALM36ON=\(selectedConditionVersionID == "svip5-current-snapshot" && frontFiveActualMEnabled ? 1 : 0)|SVIP5FOURCAPON=\(selectedConditionVersionID == "svip5-current-snapshot" && svip5FourCountFilterEnabled ? 1 : 0)|MPERM=\(svip4MinimumDistinctMOrdersInput)|NO4LOWODDS=\(noFourPositionFilterEnabled && svip4NoFourSelection == "auto" ? 1 : 0)|"
                : "")
            + (frontThreeMaximumFourFilterEnabled ? "MAX4F3=1|" : "")
        let singleNoFourToken = usesVIP6AutomaticMatchSelection
            && !frontThreeMaximumFourFilterEnabled
            && !enabledNoFourPositionInputs.isEmpty
            ? "NO4SINGLE=1|"
            : ""
        return "\(mainMatches)|\(logicInput)|\(sumInput)|\(displacementInput)|\(varianceInput)|\(valueTwoMaximumInput)|\(transitionMinimumInput)|\(roughnessMaximumInput)|\(breakpointInput)|QDROP0|FINAL=\(finalReduction.rawValue)|SEED=\(finalReduction == .random ? randomSeedInput : "1")|MKTW=\(marketWeightPercent)|RATE=\(finalRemovalPercent)|OCTOLON=\(outcomeConditionToleranceEnabled && activeOutcomeConditionCount > 0 ? 1 : 0)|OCTOL=\(outcomeConditionToleranceInput)|ALLTOLON=\(allConditionsToleranceEnabled ? 1 : 0)|ALLTOL=\(allConditionsToleranceInput)|RUNS=\(consecutiveRunsEnabled ? 1 : 0)|NLRUN=\(nonLossRunInput)|NDRUN=\(nonDrawRunInput)|NWRUN=\(nonWinRunInput)|RUNTOL=\(consecutiveRunToleranceInput)|RUN2ON=\(secondaryConsecutiveRunsEnabled ? 1 : 0)|RUN2RANGE=\(secondaryConsecutiveRunRangeInput)|RUN2TOL=\(secondaryConsecutiveRunToleranceInput)|SAMERUNS=\(sameResultRunsEnabled ? 1 : 0)|WINRUN=\(winRunInput)|DRAWRUN=\(drawRunInput)|LOSSRUN=\(lossRunInput)|SAMERUNTOL=\(sameResultRunToleranceInput)|PROTECT11=\(protectConsecutiveDrawPair ? 1 : 0)|SPPRODON=\(spProductFilterEnabled ? 1 : 0)|SPPROD=\(spProductRangeInput)|HODDSPRODON=\(customHandicapOddsProductFilterEnabled ? 1 : 0)|HODDSPROD=\(customHandicapOddsProductMinimum)-\(customHandicapOddsProductMaximum)|HODDSSUMON=\(customHandicapOddsSumFilterEnabled ? 1 : 0)|HODDSSUM=\(customHandicapOddsSumMinimum)-\(customHandicapOddsSumMaximum)|PRIZEON=\(prizeRangeFilterEnabled ? 1 : 0)|PRIZE=\(estimatedPrizeRangeInput)|SPRISKON=\(spRiskFilterEnabled ? 1 : 0)|MAXSP=\(maximumSingleSPInput)|HIGHSPTH=\(highSPThresholdInput)|HIGHSPCOUNT=\(highSPCountRangeInput)|MINPROBON=\(minimumProbabilityFilterEnabled ? 1 : 0)|MINPROB=\(minimumSingleProbabilityInput)|JOINTPROBON=\(jointProbabilityFilterEnabled ? 1 : 0)|JOINTPROB=\(jointProbabilityRangeInput)|VIP12PROBON=\(isVIPConditionEnabled && usesVIP12ProbabilityReduction && vip12ProbabilityReductionEnabled ? 1 : 0)|SVIP1ODDSGUARDON=\(isVIPConditionEnabled && ["svip1-xs-current", "svip2-all-basic", "svip3-current-no-four"].contains(selectedConditionVersionID) && svip1CustomOddsGuardEnabled ? 1 : 0)|VIP16TOP200ON=\(isVIPConditionEnabled && selectedConditionVersionID == "vip16-probability-top200" ? 1 : 0)|VIP18TOP200ON=\(isVIPConditionEnabled && selectedConditionVersionID == "vip18-calibrated-upset-top200" ? 1 : 0)|VIP19CUSTOMTOP200ON=\(isVIPConditionEnabled && selectedConditionVersionID == "vip19-custom-odds-constitution-top200" ? 1 : 0)|GROUPON=\(groupFilterEnabled ? 1 : 0)|GROUPMODE=\(groupFilterMode.rawValue)|GFSUM=\(frontGroupOutcomeSumInput)|GBSUM=\(backGroupOutcomeSumInput)|GFSP=\(frontGroupSPProductInput)|GBSP=\(backGroupSPProductInput)|PRIZESTATON=\(prizeStatisticalConditionEnabled ? 1 : 0)|PRIZECOUNTON=0|U150ON=\(universal150CompressionEnabled ? 1 : 0)|U247ON=\(effectiveUniversal247ToleranceEnabled ? 1 : 0)|U247TH=\(effectiveUniversal247ToleranceThresholdInput)|V10TOP150ON=\(productSumV10Top150Enabled ? 1 : 0)|\(conditionScopeToken)\(singleNoFourToken)NO4=\(enabledNoFourPositionInputs.joined(separator: ","))|\(outcomeConditionInputTokens)\(extras)|MERGE3"
    }

    /// Mac批量重算和启动导入使用的条件Tab快照。
    /// 不读历史TXT，也不等待 SwiftUI @State 完成异步回填。
    private func persistedCurrentConditionInputForMaintenance(
        persistedValues: [String: String]? = nil
    ) -> String {
        let values = persistedValues
            ?? UserDefaults.standard.dictionary(forKey: inputDefaultsStorageKey) as? [String: String]
            ?? persistedInputValues
        return applyingConditionEditorSettings(
            to: basePersistedCurrentConditionInputForMaintenance(persistedValues: values), values: values)
    }

    private func basePersistedCurrentConditionInputForMaintenance(
        persistedValues: [String: String]? = nil
    ) -> String {
        let defaults = UserDefaults.standard
        guard let values = persistedValues
                ?? defaults.dictionary(forKey: inputDefaultsStorageKey) as? [String: String],
              !values.isEmpty else {
            return generatedInput
        }
        func value(_ key: String, _ fallback: String) -> String {
            values[key] ?? fallback
        }
        func flag(_ key: String, _ fallback: Bool) -> String {
            value(key, fallback ? "1" : "0") == "1" ? "1" : "0"
        }

        let persistedVersionID = value("selectedConditionVersionID", selectedConditionVersionID)
        let persistedUsesVIP6 = ["svip11-breakpoint-selection", "svip10-frozen-160", "svip9-dual-s", "svip8-current-three", "svip6-three-condition", "svip5-current-snapshot", "svip4-permutation-lowest-odds", "svip1-xs-current", "svip2-all-basic", "svip3-current-no-four", "vip6-automatic-odds", "vip7-enabled-only", "vip8-current-day", "vip9-front-five-m3-6", "vip10-front-five-real-sum", "vip11-front-five-mapped-sum", "vip12-probability-bottom20", "vip14-s15-18", "vip15-s15-20-single-no-four", "vip16-probability-top200", "vip18-calibrated-upset-top200", "vip19-custom-odds-constitution-top200"]
            .contains(persistedVersionID)
            || (persistedVersionID == "svip7-odds-rank-280" && flag("vipConditionsEnabled", vipConditionsEnabled) == "1")
        var matchValues = [
            value("match1Input", match1Input),
            value("match2Input", match2Input),
            value("match3Input", match3Input),
            value("match4Input", match4Input),
            value("match5Input", match5Input)
        ]
