            persistedUsesVIP6
                && flag("frontThreeMaximumFourFilterEnabled", frontThreeMaximumFourFilterEnabled) == "0"
                && !persistedNoFourPositions.isEmpty
                ? "NO4SINGLE=1"
                : nil,
            "NO4=\(persistedNoFourPositions.joined(separator: ","))"
        ].compactMap { $0 }
        fields.append(contentsOf: outcomeTokens)
        if !persistedUsesVIP6 {
