            return FilterConfig.appendingSVIP10AdditionalInput(baseInput, coldEnabled: value("svip10ColdCountEnabled", "1") != "0", coldRange: value("svip10ColdCountRangeInput", "0-2"), drawEnabled: value("svip10DrawCountEnabled", "0") == "1", drawRange: value("svip10DrawCountRangeInput", "0-3"), winLossSwitchEnabled: value("svip10WinLossSwitchEnabled", "1") != "0", highestDoubleProbabilityTopTwoEnabled: false, secondDoubleLowestProbabilityEnabled: false, fiveMatchMEnabled: value("svip10FiveMatchMEnabled", "1") != "0", fiveMatchMRange: value("svip10FiveMatchMRangeInput", "2-6"), frontFiveSameOutcomeRunMaximum2Enabled: value("svip10FrontFiveSameOutcomeRunMaximum2Enabled", "0") == "1", frontFiveReturnMaximum2Enabled: value("svip10FrontFiveReturnMaximum2Enabled", "1") != "0", frontFiveNoConsecutiveDrawEnabled: value("svip10FrontFiveNoConsecutiveDrawEnabled", "0") == "1", frontFiveValueThreeMaximum2Enabled: value("svip10FrontFiveValueThreeMaximum2Enabled", "0") == "1", sixMatchFavoriteCount1To4Enabled: value("svip10SixMatchFavoriteCount1To4Enabled", "1") != "0", sixMatchMinimumOddsProductEnabled: value("svip10SixMatchMinimumOddsProductEnabled", "1") != "0", sixMatchMinimumOddsProduct: value("svip10SixMatchMinimumOddsProductInput", "380"), sixMatchBreakpoint3To5Enabled: value("svip10SixMatchBreakpoint3To5Enabled", "1") != "0", topThreeProbabilityRecovery100Enabled: value("svip10TopThreeProbabilityRecovery100Enabled", "1") != "0", statisticalLineBudgetEnabled: value("svip10StatisticalLineBudgetEnabled", "0") == "1", probabilityMass60Enabled: value("svip10ProbabilityMass60Enabled", "1") != "0", calibratedDoubleSelectionEnabled: value("svip10CalibratedDoubleSelectionEnabled", "0") == "1", sixMatchBreakpointRange: value("svip10SixMatchBreakpointRangeInput", "2-5"), automaticDoublePairEnabled: false, judgmentFactors: [], allABCDSelectionEnabled: false, maximum105Enabled: false, frontTwoADEnabled: false, fixedFrontTwoDoublesEnabled: false, adDoublesWithinSixEnabled: false, adDoubleCountWithinSix: 1, automaticDoubleCount: 1)
